import{b as z,u as O,a as S,r as b,c as q,j as e,B as M,R as N}from"./index-DEIzKU81.js";import{P as E}from"./PageLayout-h1_uV0ck.js";import{R as C}from"./ResultDetail-CguwZ0-2.js";import{M as R}from"./Marks-FjgWgRE6.js";const B="1.0.1",U="2026-04-10",L=JSON.parse('[{"id":"outcomes-001","code":"001","description":{"en":"","ru":"<p><strong><i>Ваша община возвела надёжное поселение, служившее убежищем в холодное время года, и заложила основу для формирования местной культуры. С годами поселение разрослось, и некоторые жители стали оставаться в нём круглый год.</i></strong></p><p>На стене первобытной пещеры изобразите историю о неустрашимых поселенцах, включив в неё отметку укрытия [i] и отметку одного из регионов, где у вас есть поселение (например, Дивная долина [ii] или Поднебесная равнина [iii]). Постоянные обитатели ваших поселений могут оказать вам поддержку. Получите карту знаний «Укрепления» (ЗБ10).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<hold>"},{"label":"i","image":"<verdantvale>"},{"label":"iii","image":"<skyreachplateau>"}]},{"id":"outcomes-002","code":"002","description":{"en":"","ru":"<p><strong><i>Холодные солнечные лучи скользили по дрожащим листьям, но поселение уже было достроено и готово укрыть ваш народ от суровых морозов. И всё же беспокойство не покидало вас. В час, когда луна царила на небосводе, нечто огромное и непостижимое устремлялось к долине...</i></strong></p><p>В конце любого дня можете завершить текущее испытание. Затем добавьте <population><population>.<br>Освоившись в долине, ваш народ приобрёл новые навыки выживания. Ваша община получает следующие силы мантий: «Следопыт» (МА01), «Знаток секретов» (МА02), «Друг-наставник» (МА03), «Хранитель» (МА04). Запишите их в раздел «Силы мантий» на странице «Культура» в журнале. В начале каждого следующего испытания выбирайте по одной силе для каждого персонажа в соответствии с их мантиями, как описано в разделе «Силы мантий» на с. <rulebook>65</rulebook> правил игры. Затем совместно выберите один из следующих путей развития общины:<br><strong>А. Направьте свой народ на путь созидания, избавив его от страха перед неизвестностью.</strong> Добавьте <population> и <unrest><unrest>. На стене первобытной пещеры изобразите историю о сияющем солнце, включив в неё отметку <sun> и отметку региона, где вы построили поселение (например, Дивная долина [i] или Поднебесная равнина [ii]). Добавьте карту «Период затишья» (ИЯ01) к грядущим испытаниям. В начале следующего испытания добавьте к целям следующие карты: «Соберите припасы» (ЦА03), «Отыщите знамения» (ЦА07), «Разведите огонь» (ЦА08), «Пройдите по следам тайн» (ЦА11).<br><strong>Б. Объедините народ, чтобы противостоять таинственной угрозе.</strong> На стене первобытной пещеры изобразите историю о лунном дозоре, включив в неё отметку <moon> и отметку региона, где вы построили поселение (например, Дивная долина [i] или Поднебесная равнина [ii]). Добавьте карту «Вторжение» (ИА04) к грядущим испытаниям. В начале следующего испытания добавьте к целям следующие карты: «Соберите припасы» (ЦА03), «Отыщите знамения» (ЦА07), «Разведите огонь» (ЦА08).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<verdantvale>"},{"label":"ii","image":"<skyreachplateau>"}]},{"id":"outcomes-003","code":"003","description":{"en":"","ru":"<p><strong><i>Вы начали видеть закономерности в смене времён года и чередовании эпох…</i></strong></p><p>Посмотрите три верхние карты колоды событий (находящиеся под этой картой). Вы можете положить любое количество из них под низ колоды. Затем перемешайте колоду и положите оставшиеся карты на верх колоды (под эту карту) в любом порядке.</p>"},"repeatable":false},{"id":"outcomes-006","code":"006","description":{"en":"","ru":"<p><strong><i>Увернувшись от смертоносных рогов, вы взобрались на голову чудища и всмотрелись в янтарные омуты его глаз...</i></strong></p><p>Выберите и разыграйте одно:</p><p><strong>А. Померяйтесь выдержкой с чудищем.</strong>Проведите состязание: ваша <conviction> против <conviction> чудища. +2, если вы неукротимый, и +4, если у вас есть отметка другого чудища.<br><strong>Успех.</strong> Вы одержали верх. Разозлите чудище на 1. Оно сбегает.<br><strong>Провал.</strong> Вы почувствовали, как ваша жизненная сила начинает угасать. Отметьте одну клетку возраста на карте своего персонажа. Добавьте отметку этого чудища на сторону легенды карты своего персонажа.</p><p><strong>Б. Постарайтесь по-настоящему понять чудище.</strong>Проведите состязание: ваше <awareness> против <might> чудища. +2, если вы сосредоточенный, и +4, если у вас есть отметка этого чудища.<br><strong>Успех.</strong> Вы увидели вечный круговорот жизни и смерти — луна бесконечно догоняет солнце сквозь времена и эпохи. Сбросьте все свои <boost>. Чудище сбегает. Успокойте чудище на 3.<br><strong>Провал.</strong> Вы заглянули в око вечности и были ошеломлены увиденным. Отметьте одну клетку возраста на карте своего персонажа. Добавьте отметку этого чудища на сторону легенды карты своего персонажа. Получите черту «сосредоточенный».</p><br>Затем завершите встречу."},"repeatable":false},{"id":"outcomes-009","code":"009","description":{"en":"","ru":"<p><i><b>Вы скатились по каменной крошке и затаились под чудищем в надежде, что здесь оно вас не почует. Несколько томительных минут, пока чудище грохотало над вами, вы не смели поднять головы. Именно тогда, глядя в землю, вы заметили застрявший в ней предмет. Дождавшись, пока чудище уйдёт, вы вытащили находку. </b></i></p><p>Завершите встречу. Получите 1 сокровище этого чудища.</p>"},"repeatable":false},{"id":"outcomes-011","code":"011","description":{"en":"","ru":"<p><i><b>Таинственное мохнатое чудище казалось непобедимым, а его следы покрывал иней. Однако даже у такого колосса могли быть свои секреты. Наблюдая за его поведением, вы поняли, что существо уязвимее, чем можно было подумать. </b></i></p><p>Разыграйте первое, что можете:</p> <p><b>А. Наблюдая за исполинским вестником цикла, вы постигали новые истины о его природе.</b> Если у чудища есть назначенная неоткрытая карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале. <b><br>Б. Согласно преданиям, гигантское существо ступает по земле, оставляя за собой хрустальные озёра — следы его непостижимой воли. </b>Получите 1 сокровище этого чудища.</p>"},"repeatable":false},{"id":"outcomes-012","code":"012","description":{"en":"","ru":"<p><strong><i>Вы сделали первый робкий шаг по незнакомым прекрасным землям...</i></strong></p><p>На стене первобытной пещеры изобразите историю о шагах в неизвестность, включив в неё отметку открытия [i], отметку Звёздного моря [ii] и отметку подземного мира [iii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<discovery>"},{"label":"ii","image":"<starlitsea>"},{"label":"iii","image":"<underworld>"}]},{"id":"outcomes-015","code":"015","description":{"en":"","ru":"<p><strong><i>Уцепившись за густой мех на громадном подбородке чудища, вы протянули ему щедрый дар и затаили дыхание, в надежде, что чудище в благосклонном настроении — и что его великодушие окажется равным вашему...</i></strong></p><p>Выберите и разыграйте одно:</p><p><strong>А. Вы преподнесли весомый дар.</strong>Если значение нрава чудища не более 4, а в вашем инвентаре есть хотя бы 3 материала, сбросьте 3 из них. Если сделали это, успокойте чудище на 1. Затем, если все 3 сброшенных материала соответствуют текущим знамениям (см. ниже), получите 1 сокровище этого чудища:<br><cloud>— минеральные материалы<br><comet>— жетоны материалов меньшего размера.<br><moon>— животные материалы.<br><star>— жетоны материалов большего размера. <br><sun>— растительные материалы.<br></p><p><strong>Б. Вы преподнесли умиротворяющий дар.</strong> Если значение нрава чудища равно хотя бы 5, а в вашем инвентаре есть хотя бы 3 материала, сбросьте 3 из них. Если сделали это, успокойте чудище на 2.<br><strong>В. Вы не преподнесли ничего, рискуя разгневать чудище.</strong> Разозлите чудище на 1. Затем, если значение нрава чудища равно хотя бы 5, получите <minor_injury> и сбегите.</p><p>Затем завершите встречу.</p>"},"repeatable":false},{"id":"outcomes-016","code":"016","description":{"en":"","ru":"<p><strong><i>Поступь ходячего шпиля стирала леса в пыль, но всё же вы видели нечто, что, казалось, внушает чудищу страх. Это заставило вас задуматься: что за сердце бьётся под каменной кожей?</i></strong></p><p>Разыграйте первое, что можете:</p><p><strong>А. Немного понаблюдав, вы раскрыли одну из тайн этого величественного существа.</strong>Если у чудища есть назначенная неоткрытая карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><strong>Б. Истории вашего народа гласили, что чудище оставляет за собой огромные разломы в земле и в них легко добывать камень.</strong> Получите 2 сокровища этого чудища.</p>"},"repeatable":false},{"id":"outcomes-017","code":"017","description":{"en":"","ru":"<p><strong><i>Вы стояли на голове чудища, когда тень накрыла вас. Обернувшись, вы увидели исполинскую лапу, заслонившую небо. Со свистом рассекая воздух, она обрушилась на вас — и стало темно.</i></strong></p><p>Получите <minor_injury><minor_injury><minor_injury>. Если это заполняет всю шкалу здоровья персонажа, он умирает.<br>Если персонаж не умер, переместите его на случайный соседний участок местности — чудище отшвырнуло его.</p>"},"repeatable":false},{"id":"outcomes-018","code":"018","description":{"en":"","ru":"<p><strong><i>Встав на пути у возможных захватчиков, вы укротили чужую ярость и сумели разрешить конфликт миром. Терпение, проявленное в этот день, не будет забыто.</i></strong></p><p>Уберите <unrest><unrest>. На стене первобытной пещеры изобразите историю о бескровной победе, включив в неё отметку посредника.</p>"},"repeatable":false,"marks":[{"label":"","image":"<mediator>"}]},{"id":"outcomes-019","code":"019","description":{"en":"","ru":"<p><strong><i>Приближаясь к туше, вы ощутили смрад, от которого скрутило желудок, — дыхание самой смерти. Нужно быть осторожным, чтобы скверна этого места не коснулась вас.</i></strong></p><p>Проведите проверку <awareness>, чтобы сопротивляться болезни. +2, если вы удачливый, и +4, если у вас есть отметка ужаса [i] или отметка чумы [ii]. +4 к результату этой проверки, если сбросите 1 воду.<br><strong>11≥</strong>: Вам удалось избежать инфекции. Без эффекта.<br><strong>6-10</strong>: У вас запершило в горле. Получите <minor_disease>.<br><strong>1-5</strong>: Вас разобрал кашель. Получите <major_disease>, затем добавьте карту «Мор» (ИЯ03) к грядущим испытаниям, если только на стене первобытной пещеры не изображена отметка чумы.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<harrowing>"},{"label":"ii","image":"<plague>"}]},{"id":"outcomes-021","code":"021","description":{"en":"","ru":"<p><strong><i>Над деревьями возвышалось существо, словно сама долина ожила и обрела форму. Но, наблюдая за ним, вы поняли: даже оно не безупречно в своей силе. И, быть может, ваше открытие позволит сразиться с могучим чудищем на равных.</i></strong></p><p>Разыграйте первое, что можете:</p><p><strong>А. Наблюдая за исполинским вестником цикла, вы постигали новые истины о его природе.</strong> Если у чудища есть назначенная неоткрытая карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><strong>Б. Пути чудища были хорошо известны вашему народу. Двигаясь, оно сбрасывало похожие на корни щупальца, наполненные липкой смолой, которую вы могли собрать.</strong> Получите 2 сокровища этого чудища.</p>"},"repeatable":false},{"id":"outcomes-022","code":"022","description":{"en":"","ru":"<p><strong><i>Чудище настигло семя с неумолимостью урагана. Оно коснулось семени и начало вытягивать краски из зелёных побегов.</i></strong></p><p>Разыграйте первое, что можете:</p><p><strong>А. Наблюдайте, как семя тускнеет и покрывается пеплом.</strong> Если у вас есть цель «Взрастите саженец», немедленно достигните её. <br><strong>Б. Попробуйте вернуть семя.</strong> Поместите семя рядом с любой из главных развилок чудища. Пока семя находится на планшете чудища, вы не можете достигнуть цели «Взрастите саженец». После того как персонаж доберётся до этой развилки, он может поместить семя на любой участок местности, соседний с участком чудища.</p><p>Затем уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-023","code":"023","description":{"en":"","ru":"<p><strong><i>Меж суровых горных вершин вашему народу было непросто добыть всё необходимое, чтобы выжить в долине. Теперь, когда дыхание зимы всё сильнее ощущалось в осеннем воздухе, ваши люди столкнулись с трудным выбором.</i></strong></p><p>Завершите текущее испытание.<br>Добавьте карту «Пуская корни» (ИА02) к грядущим испытаниям.<br>Затем совместно выберите один из следующих путей развития общины:</p><p><strong>А. Вернитесь через пещеры до того, как их занесёт снегом.</strong> Добавьте <unrest><unrest>. Следуйте инструкциям на с. <rulebook>69</rulebook> правил игры, чтобы изобразить на стене первобытной пещеры историю о терпеливых путниках. Включите в неё отметку прибытия [i], отметку осторожности [ii] и отметку своего начального региона (например, Дивная долина [iii] или Поднебесная равнина [iv]). Затем каждый персонаж получает одну из двух черт на выбор игрока: «терпеливый» или «осторожный». <br><strong>Б. Останьтесь, чтобы пережить суровую зиму.</strong> Уберите <population><population>. Следуйте инструкциям на с. <rulebook>69</rulebook> правил игры, чтобы изобразить на стене первобытной пещеры историю о неумолимых небесах, включив в неё отметку прибытия [i], отметку льда [v] и отметку своего начального региона (например, Дивная долина [iii] или Поднебесная равнина [iv]). Затем каждый персонаж получает одну из двух черт на выбор игрока: «любознательный» или «мстительный».</p>"},"repeatable":false,"marks":[{"label":"i","image":"<arrival>"},{"label":"ii","image":"<caution>"},{"label":"iii","image":"<verdantvale>"},{"label":"iv","image":"<skyreachplateau>"},{"label":"v","image":"<ice>"}]},{"id":"outcomes-024","code":"024","description":{"en":"","ru":"<p><strong><i>В вашем сознании вспыхнула жуткая картина: огромные дымные челюсти сомкнулись вокруг вашего народа. Деревья в долине пылали, звери в страхе бежали от ужасающего пламени. Видение закружилось, подняло вас над землёй — теперь вы взирали на безмолвную долину, укрытую мёртвым пеплом.</i></strong></p><p>На стене первобытной пещеры изобразите историю о долине, покрытой пеплом, включив в неё отметку пламени, заключённую в отметку погибели [i].</p>"},"repeatable":false,"marks":[{"label":"i","image":{"image":"<doom>","overlay":{"image":"<blaze>","size":0.65,"x":0,"y":17,"rotate":0}}}]},{"id":"outcomes-025","code":"025","description":{"en":"","ru":"<p><strong>Маленькие зелёные побеги пробивались сквозь усыпанную пеплом почву, по которой прошло чудище. Вы задумались…</strong></p><p>Разыграйте первое, что можете:</p><p><strong>А. ...откуда оно пришло?</strong> Если на стене первобытной пещеры нет отметки Вулканических пустошей, то <outcome> 990.<br><strong>Б. ...как его поступь приносит и смерть, и возрождение?</strong> Если у чудища есть назначенная неоткрытая карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><strong>В. ...что привело его сюда?</strong> Поместите жетон тайны на соседний участок местности без персонажа, если возможно.</p>"},"repeatable":false,"marks":[{"label":"","image":"volcanic_wastes"}]},{"id":"outcomes-028","code":"028","description":{"en":"","ru":"<p><i><b>Вы бросились к щербатому лбу чудища, чтобы нанести точный оглушающий удар. Чудище содрогнулось и оступилось, его голова почти коснулась земли. Вы успели соскочить и остались в живых.</b></i></p> <p>Завершите встречу. Разозлите чудище на 1. Уменьшите все его <boost>.</p>"},"repeatable":false},{"id":"outcomes-029","code":"029","description":{"en":"","ru":"<p><strong><i>Семя покоилось глубоко в корневых туннелях. Вы вновь ступили в их темноту, чтобы спасти Сплетение, — на сей раз с ясным пониманием цели.</i></strong></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><strong><i>Внутри корневых туннелей земля будто давила на вас со всех сторон, а тьма казалась невыносимой.</i></strong></p><p><strong>Группа, угроза.</strong> Все персонажи в походе должны провести проверку <conviction>, чтобы продолжить путь. +2, если персонаж неукротимый, и +2, если у него есть предмет с <fire>.<br><b>≥12:</b> Вы уверенно продвигались вперёд. Продолжите поход.<br><b>7-11:</b> Страх заставил вас вздрагивать от каждого движения тени. Потеряйте <energy>. Продолжите поход.<br><b>1-6:</b> Вы поддались панике. Покиньте поход. Если все персонажи покинули поход, он окончился неудачно.</p><p><strong><i>Вы вновь оказались в полости с семенем и увидели перед собой гигантскую сферу. Её поверхность была гладкой, и вы чувствовали, как изнутри исходит тепло. Вам пришлось действовать крайне осторожно, чтобы извлечь её.</i></strong></p><p><strong>Защитник.</strong> Один из персонажей в походе должен провести проверку <dexterity>, чтобы высвободить семя. +2, если у него есть <dig>, +2, если у него есть <stoneworking>, и +2, если он <i>мудрый</i>.<br><b>≥11:</b> Вам удалось вытащить семя, не повредив его. Продолжите поход.<br><b>1-10:</b> Семя не поддалось — оно слишком крепко вросло. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><b><i>Теперь, когда семя было у вас, предстояло вынести эту громадину из туннелей.</b></i></p><p><b>Группа.</b> Все персонажи в походе должны провести проверку <might>, чтобы переместить семя. +2, если у персонажа есть «Верёвка», и +2, если он <i>изобретательный</i>.<br><b>≥14:</b> Все вместе, с огромным трудом, вы вынесли семя из туннелей. Завершите этот поход и достигните соответствующей цели.<br><b>1-13:</b> Вам не удалось сдвинуть семя с места. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-030","code":"030","description":{"en":"","ru":"<p><strong><i>Ваше поселение оставалось недостроенным, а по небу уже проносились тяжёлые тучи — предвестники грядущих страданий. Свет звёздных троп в вышине над вами потускнел и казался таким далёким...</i></strong></p><p>Завершите текущее испытание. Уберите <population> и добавьте <unrest>.</p><p><strong><i>Однако не всё было потеряно. Преодолев немало трудностей, ваш народ обрёл новые умения, которые помогут выжить.</i></strong></p><p>Ваша община получает следующие силы мантий: «Следопыт» (МА01), «Знаток секретов» (МА02), «Друг-наставник» (МА03), «Хранитель» (МА04). Запишите их в раздел «Силы мантий» на странице «Культура» в журнале. В начале каждого следующего испытания выбирайте по одной силе для каждого персонажа в соответствии с их мантиями, как описано в разделе «Силы мантий» на с. <rulebook>65</rulebook> правил игры.<br>Затем совместно выберите один из следующих путей развития общины:<br><strong>А. Продолжите строительство, несмотря на подступающие морозы.</strong> Уберите <population><population> и добавьте <unrest>, затем постройте поселение (не оплачивая его стоимость) в районе без требований для строительства (если таких районов нет, выбрать этот вариант нельзя). На стене первобытной пещеры изобразите историю о ледяной стойкости, включив в неё отметку и <cloud> отметку ужаса [i]. Добавьте карту «Праздник памяти» (ИА07) к грядущим испытаниям. В начале следующего испытания добавьте к целям следующие карты: «Соберите припасы» (ЦА03), «Отыщите знамения» (ЦА07), «Разведите огонь» (ЦА08), «Пройдите по следам тайн» (ЦА11).<br><strong>Б. Бросьте недостроенное поселение и отправьтесь по звёздной тропе к новому дому.</strong> Ваше поселение становится руинами (переверните накладку неактивной стороной вверх и укажите на карте поселения, что теперь это руины). На стене первобытной пещеры изобразите историю о надежде, что сулит горизонт, включив в неё отметку прибытия [ii] и отметку <star>. Добавьте карту «Прибежище» (ИА03) к грядущим испытаниям. В начале следующего испытания добавьте к целям следующие карты: «Соберите припасы» (ЦА03), «Отыщите знамения» (ЦА07), «Разведите огонь» (ЦА08), «Пройдите по следам тайн» (ЦА11).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<harrowing>"},{"label":"ii","image":"<arrival>"}]},{"id":"outcomes-031","code":"031","description":{"en":"","ru":"<p><strong><i>Чудище смотрело на вас, ожидая подношения, и вы начали рыться в своём мешке в поисках подходящего подарка...</i></strong></p><p>Выберите и разыграйте одно:</p><p> <strong>А. Сделайте подношение.</strong> Если в вашем инвентаре есть хотя бы 2 ресурса, сбросьте любые 2 из них, чтобы успокоить чудище на 1. Затем продолжите встречу.<br><strong>Б. Не давайте ничего.</strong> Разозлите чудище на 1. Затем продолжите встречу.</p>"},"repeatable":false},{"id":"outcomes-034","code":"034","description":{"en":"","ru":"<p><strong><i>Светящиеся споры грибов вспыхнули перед глазами, и в их пляске вы узрели луну — то растущую, то убывающую в исступлённом ритме. Вы вспомнили, как оступились во тьме и рухнули вниз. Очнувшись, вы увидели луну уже в полуденном небе, а голова пульсировала в такт последним отблескам исчезающего знамения.</i></strong></p><p>Завершите это действие спуска. Получите одну из присвоенных во время спуска наград, остальные верните в запас. Добавьте <lore><lore>.Затем поместите своего персонажа на случайный участок местности в регионе, где вы начали спуск. Выберите неисследованный участок, если возможно. Персонаж теряет <energy> из-за обезвоживания и пульсации в голове, если только не сбросит 1 воду.</p>"},"repeatable":false},{"id":"outcomes-035","code":"035","description":{"en":"","ru":"<p><strong><i>Смахивая белую пыль, вы наткнулись на древний окаменевший риф, по вашему мнению бывший когда‑то кораллом.</i></strong></p><p>Если все накладки коралловых зарослей находятся в долине, уберите одну из них на ваш выбор. Затем поместите неактивные коралловые заросли на ваш текущий участок местности. Добавьте карту «Встретьтесь с высшим разумом» (ЦВ11) к целям.</p>"},"repeatable":false},{"id":"outcomes-037","code":"037","description":{"en":"","ru":"<p><strong><i>Слова пророка просачивались по тайным тропам и достигали ваших ушей: его последователи говорили, что пророк отмечен небесным Скитальцем. Комета — благоговейно шептали последователи — явится в великом столпе чудесного света и создаст новый мир таким, как предсказывал пророк. Готовясь к великому дню, адепты искали редкие сокровища, чтобы умилостивить Скитальца и ускорить его пришествие.</i></strong></p><p>Добавьте карту «Отыщите знаки кометы» (ЦВ03) к целям.</p>"},"repeatable":false},{"id":"outcomes-039","code":"039","description":{"en":"","ru":"<p><strong><i>Раздался рёв, и небеса воспылали над вами. Воздух вздрогнул, и небо разверзлось.</i></strong></p><p>Добавьте карту «Падение небес» (ИВ04) к грядущим испытаниям.</p>"},"repeatable":false},{"id":"outcomes-045","code":"045","description":{"en":"","ru":"<p><strong><i>Ваши люди трудились до изнеможения в попытках перекроить землю, но она отказывалась поддаваться. Там, где вы выкорчёвывали деревья, прорастали новые побеги. Ваши запасы семян загнивали, не дождавшись посадки. В конце концов, ваш народ оставил эту затею, вернувшись к более надёжным способам выживания.</i></strong></p><p>Завершите текущее испытание.<br>Добавьте <unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю об увядшем урожае, включив в неё отметку расколотой земли [i] и отметку травничества [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<brokenearth>"},{"label":"ii","image":"<herbalism>"}]},{"id":"outcomes-046","code":"046","description":{"en":"","ru":"<p><strong><i>Чудище потянулось к семени с каким‑то необъяснимым любопытством. Медленно, с нежностью оно подняло семя, что не вязалось с громадными каменными лапами. Вас пробрала дрожь. Семя на миг озарилось блеском. Чудище обернулось к вам, и в его холодном взоре скользнуло... понимание? Оно указало вдаль, обозначая путь.</i></strong></p><p>Разыграйте первое, что можете:<br><strong>А. Смотрите в изумлении, как семя каменеет.</strong> Если цель «Разомкните круг» в игре и ещё не достигнута, добавьте 1 лунную кровь на её карту.<br><strong>Б. Последуйте туда, куда указало чудище.</strong> Каждый персонаж получает <major_boost> к <awareness>.</p><p>Затем уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-048","code":"048","description":{"en":"","ru":"<p><strong><i>В подземных глубинах бережно хранились семена вашей общины. Однажды они снова прорастут.</i></strong></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о побеге в подземелье, включив в неё отметку подземного мира. Все ваши поселения становятся руинами. Затем, если не осталось накладок поселений, уберите из долины одну из них по вашему выбору. Постройте новое поселение, не тратя <energy> . Поместите его на любой участок, выбрав участок местности с пещерой или пропастью, если возможно. В строке «Категория» на карте этого поселения напишите «Подземное». Добавьте карту «Презрение земли» (ИВ06) к грядущим испытаниям. Когда начнёте испытание «Презрение земли», сразу же достигните цели «Укротите мятеж».</p>"},"repeatable":false,"marks":[{"label":"","image":"<underworld>"}]},{"id":"outcomes-049","code":"049","description":{"en":"","ru":"<p><strong><i>Вы взобрались на исполинское лицо чудища, стараясь не попасть под вихрь камней. У вас появился шанс нанести удар по его крепкой маске.</i></strong></p><p>Выберите и разыграйте одно:<br><strong>А. Ударьте чудище.</strong> Завершите встречу. Разозлите чудище на 2. Чудище сбегает.<br><strong>Б. Установите контакт с чудищем.</strong> Получите 2 сокровища этого чудища, затем продолжите встречу.</p>"},"repeatable":false},{"id":"outcomes-052","code":"052","description":{"en":"","ru":"<p><strong><i>Когда напряжение от старых распрей достигло предела, некоторые решили уйти, оставив после себя лишь сказания…</i> </strong></p><p>    На стене первобытной пещеры изобразите историю об исчезнувших, включив в неё отметку раскола [i]. Уберите <population><population>. Затем совместно выберите один из следующих путей развития общины:<br><strong>А. Предупредите будущие поколения об угрозе извне.</strong> Запишите «Отдыхать на участке местности, соседнем хотя бы с одним участком с жетоном тайны» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у общины её нет. Добавьте <unrest><unrest>. На стене первобытной пещеры  изобразите историю о мрачном предостережении, включв в неё отметку раскола [i] и отметку табу [ii].<br><strong>Б. Сохраните надежду на воссоединение.</strong> Добавьте <unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о заветном возвращении, включив в неё отметку посредника [iii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<schism>"},{"label":"ii","image":"<taboo>"},{"label":"iii","image":"<mediator>"}]},{"id":"outcomes-059","code":"059","description":{"en":"","ru":"<p><strong><i>Пробираясь во тьме, вы наткнулись на нечто похожее на высохшую кость. Она казалась древней, но по‑прежнему крепкой</i>.</strong></p><p>Проведите проверку <might>, чтобы попытаться вырвать кости из земли. +2, если вы <i>мудрый</i>, +2, если у вас есть <grind>, и +2, если у вас есть «Трость».</p><p><b>≥14:</b> Вам удалось вытащить странные кости и изучить их. Они напомнили вам кости существ из долины. Получите 2 кости. Добавьте <lore><lore>.<br><b>9-13:</b> Кости ломались и трещали, когда вы пытались их извлечь. Добавьте <lore>. <br><b>1-8:</b> Кости просто рассыʼпались, оставив вас в недоумении. Без эффекта.</p>"},"repeatable":false},{"id":"outcomes-061","code":"061","description":{"en":"","ru":"<p><strong><i>Облака клубились у ваших стоп, когда вы смотрели вниз со шпиля на голове чудища . Отсюда взору открывалась вся долина до самых её скалистых стен.</i></strong></p><p>Посмотрите 2 верхние карты колоды пути. Можете положить любые из них под низ колоды. Вы и это чудище получаете по <minor_boost> к <awareness>. Затем, если значение нрава этого чудища не более 4, завершите встречу: оно наклоняет рог, приглашая вас спуститься. В противном случае потеряйте <energy><energy>, если только у вас нет «Верёвки».</p>"},"repeatable":false},{"id":"outcomes-065","code":"065","description":{"en":"","ru":"<p><strong><i>Вы спускались по корневым туннелям, не догадываясь, какие ужасы поджидают вас в этом странном отражении Сплетения...</i></strong></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><b><i>В туннелях ощущалась вся тяжесть земли и корней, нависающих сверху.</b></i><br><b>Группа, угроза.</b> Все персонажи в походе должны провести проверку <conviction>, чтобы продолжить путь. +2, если у персонажа есть предмет с <fire>, и +2, если он <i>неукротимый</i>.<br><b>≥12:</b> Вы уверенно продвигались вперёд. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>7-11:</b> Страх заставил вас вздрагивать от каждого движения тени. Потеряйте <energy>. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-6:</b> Вы поддались панике и сбежали из туннеля. Покиньте поход. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><b><i>Повернув за угол, вы оказались в гнезде ядовитых подземных хищников. Вам предстояло бороться за свою жизнь!</i></b><br><b>Группа, угроза.</b> Все персонажи в походе должны провести проверку <might> или <dexterity>, чтобы сразиться. +2, если персонаж мстительный, и +4, если у него есть смесь.<br><b>≥11:</b> Вы сумели пробиться. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-10:</b> Изжаленная кожа начала болезненно опухать. Получите <minor_injury> и <major_disease>. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy>, чтобы провести проверку ещё раз.<br></p><p><b><i>В непроглядной мгле вы наткнулись на преграду. Из‑за толщи грунта доносился знакомый смрад гнили, куда более резкий и зловещий, чем тот, что ощущался на поверхности. Чтобы добраться до источника разложения, предстояло прорваться сквозь барьер.</i></b><br><b>Защитник, угроза.</b> Один из персонажей в походе должен провести проверку <awareness>, чтобы найти правильное место для раскопок. +4, если у него есть <dig>, +4, если у него есть <resourceful>, и +2, если он <i>изобретательный</i>.<br><b>≥12:</b> Вы нашли нужное место и разрушили земляной барьер. Завершите поход и достигните соответствующей цели.<br><b>6-11:</b> Туннель содрогнулся, предвещая беду. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy>, чтобы провести проверку ещё раз.<br><b>1-5:</b> Туннель обрушился! Поход окончился неудачно, и каждый персонаж в походе получает <major_injury><major_injury><major_injury>."},"repeatable":false},{"id":"outcomes-068","code":"068","description":{"en":"","ru":"<p><b><i>Вы заметили, что комета тесно связана с кораллом: её движение по небу предвещало подъёмы и спады кораллового  роста. Удивительнее всего было то, что коралл, похоже, не мог повлиять на обитателей подземного мира, хотя он пронизывал самые его глубины. Вы чувствовали, что держите в руках ключ к разгадке, но полная картина ускользала от вас.</i></b></p><p>На стене первобытной пещеры изобразите историю о коралле и комете, включив в неё  отметку <comet>, отметку коралла [i] и отметку почерневшего неба [ii]. Ваша община получает  силу мантии «Сторож коралла» (МА17).<br>Если сейчас эра 3, добавьте карту «Остановите заросли» (ЦВ02) к целям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<coral>"},{"label":"ii","image":"<blackenedsky>"}]},{"id":"outcomes-072","code":"072","description":{"en":"","ru":"<p><b><i>Вам снился камень, проламывающий великую чашу небес. В видении глиняные осколки обрушивались вниз, оставляя борозды в земле и поднимая тучи пыли. Растения чернели и увядали, а животные оседали грудами выбеленных костей.</i></b></p><p>В конце любого дня можете завершить текущее испытание. Затем добавьте <unrest>.<br>На стене первобытной пещеры изобразите историю о разрушительном видении, включив в неё отметку <comet> и отметку несчастья. Добавьте карту «Час приготовлений» (ИВ03) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"","image":"<misfortune>"}]},{"id":"outcomes-073","code":"073","description":{"en":"","ru":"<p><i><b>Вы взобрались на шею чудища — она тянулась к облакам, как громадный мост. Вас бросало, словно лист на ветру, но вы удержались, вцепившись в каменистую кожу, когда существо пришло в движение.</b></i></p><p>Выберите и разыграйте одно:</p><p><b>А. Бросьте приманку. </b>Сбросьте 1 сокровище чудища и потратьте <lore>, чтобы завершить встречу. Затем переместите чудище и своего персонажа на любой участок местности в этом же регионе (не берите карту пути).<br><b>Б. Держитесь изо всех сил.</b> Завершите встречу. Чудище сбегает. Поместите своего персонажа на участок местности, куда сбежало чудище (не берите карту пути).<br><b>В. Легко соскользните.</b> Если у вас есть отметка этого чудища, получите одно сокровище этого чудища и завершите встречу. Чудище сбегает.</p>"},"repeatable":false},{"id":"outcomes-074","code":"074","description":{"en":"","ru":"<p><i><b>Многие внимали речам странного пророка, и ваши усилия опровергнуть их были тщетны. Влекомые его мрачным видением, они ушли в дальние пределы долины и исчезли из вашей истории, когда зимний снег укрыл их следы. К весне судьба этих людей оставалась неведомой, и страх проникал в сердца вашего поредевшего народа…</b></i></p><p>Завершите текущее испытание.<br>Уберите <population><population><population> и добавьте <unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю об утерянной вере, включив в неё отметку тайны [i] и отметку раскола [ii]. Добавьте карту «Тлеющие угли» (ИЯ05) к грядущим испытаниям (даже если это испытание было завершено ранее).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<mystery>"},{"label":"ii","image":"<schism>"}]},{"id":"outcomes-076","code":"076","description":{"en":"","ru":"<p><i><b>Под чёрным небом ваш народ не видел надежды на выживание. Единственный выход — покинуть эту долину, прежде чем она будет полностью поглощена кораллом...</b></i></p><p>Завершите текущее испытание.<br>Уберите 5 <population>. Переверните все неактивные коралловые заросли активной стороной вверх. Затем поместите все неразмещённые коралловые заросли активной стороной вверх на любые участки местности, выбирая участки без накладок, если возможно. Вы должны выбрать участок, соседний с другими коралловыми зарослями, если это возможно. Для каждых зарослей бросьте <1d6>, чтобы поместить их в соответствующий район: [1-2] А, [3-4] Б, [5-6] В. Затем добавьте карту «Исход» (ИЯ09) к грядущим испытаниям.</p>"},"repeatable":false},{"id":"outcomes-080","code":"080","description":{"en":"","ru":"<p><i><b>Чудище осело. Вы окунули своё оружие в едкую жижу, а затем стали наносить удары — снова и снова, пока не поняли, что сжимаете только треснувшую рукоять. Разбитый череп чудища стал мягким, как глина. Постепенно всё его тело размягчилось и растеклось бесформенной массой, просачиваясь в почву. Спустя несколько часов твердь начала содрогаться, сотрясая горы и пропасти. Но вскоре всё затихло — чудище вернулось в утробу земли, оставив на ней шрамы разломов как напоминание о его мощи.</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о поверженном древнем существе, включив в неё отметку боя [i] и отметку бодрствующего чудища, украшенную отметкой крови чудища [ii]. Добавьте отметку крови чудища [ii] на сторону легенды карты каждого персонажа, который участвовал в походе. Один из персонажей, участвовавших в походе, должен сбросить оружие, если возможно.<br>Поместите логово бодрствующего чудища неактивной стороной вверх на участок местности с чудищем. Затем, если остались неразмещённые накладки расколотых отпечатков, поместите их на случайные участки местности, соседние с неактивным логовом чудища. Для каждого отпечатка бросьте <1d6>, чтобы поместить отпечаток в соответствующий район: [1-2] А, [3-4] Б, [5-6] В. Если при этом вы должны поместить отпечаток в район с другой накладкой, замените её на расколотый отпечаток.<br>Затем завершите эру. См. с. 204, чтобы <era3>начать эру 3</era3>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<behemothsblood>"}]},{"id":"outcomes-083","code":"083","description":{"en":"","ru":"<p><i><b>Чудище наклонилось к семени и коснулось его когтем. Ледяная корочка покрыла оболочку прямо на ваших глазах. Чудище подняло замёрзшее семя и положило к себе на спину.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Позвольте чудищу унести семя.</b> Если цель «Разомкните круг» в игре и ещё не достигнута, достигните её немедленно.<br><b>Б. Попробуйте забрать семя.</b> Поместите семя рядом с любой из главных развилок чудища. Пока семя находится на планшете чудища, вы не можете достигнуть цели «Взрастите саженец». После того как персонаж доберётся до этой развилки, он может поместить семя на любой участок местности, соседний с участком чудища.</p><p>Затем уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-084","code":"084","description":{"en":"","ru":"<p><i><b>Вы вскарабкались на высокое гранитное чело чудища. Из его глубин доносился тихий гул, и вы ощутили, как на миг вас с исполином связало безмолвное единение.</b></i></p><p>Вы можете сбросить 1 сокровище чудища, чтобы успокоить его на 1. Если сделали это, выберите один из эффектов ниже, соответствующий текущему знамению:<br><cloud>— получите <minor_boost> к <might>.<br><moon>— получите <minor_boost> к <awareness><br><comet>— уменьшите любой недуг своего персонажа 1 раз.<br><star>— получите <minor_boost> к <dexterity>.<br><sun>— получите <minor_boost> к <conviction>.</p><p>Затем завершите встречу.</p>"},"repeatable":false},{"id":"outcomes-085","code":"085","description":{"en":"","ru":"<p><i><b>Сплотив враждующие стороны общей целью, вы положили конец расколу среди своего народа.</b></i></p><p>Добавьте <lore><lore><lore> и <population>. На стене первобытной пещеры изобразите историю о посреднике, включив в неё отметку посредника.</p>"},"repeatable":false,"marks":[{"label":"","image":"<mediator>"}]},{"id":"outcomes-086","code":"086","description":{"en":"","ru":"<p><i><b>С вершины громадного, похожего на маску лица чудища был виден почти весь горизонт. Краем глаза вы заметили танцующие тени — они будто предрекали то, что ещё только грядёт. Ваш разум соприкоснулся с разумом чудища.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Попробуйте противостоять разуму чудища всей своей волей, заставив чудище отступить. </b>Если <comet> или <sun> — текущее знамение, разозлите чудище на 1. Чудище сбегает.<br><b>Б. Поищите знания в разуме чудища. </b>Если <star> — текущее знамение, посмотрите 3 верхние карты колоды ночи или пути и положите любое количество из них под низ колоды.<br><b>В. Проследите за устремлённым вдаль взглядом чудища. </b>Если <cloud> или <moon> — текущее знамение, поместите жетон тайны на любой участок местности без персонажа.</p><p>Затем завершите встречу.</p>"},"repeatable":false},{"id":"outcomes-087","code":"087","description":{"en":"","ru":"<p><i><b>Встречи с чудищами помогли вашему народу обрести единство в отношении этих гигантов.</b></i></p><p>Уберите <unrest><unrest><unrest>. Затем разыграйте первое, что можете:<br><b>А. Ваш народ решил, что конфликт неизбежен, и начал провоцировать чудищ.</b> Если значения нрава всех чудищ равны хотя бы 6, добавьте карту «Непримиримая вражда» (ИБ03) к грядущим испытаниям. На стене первобытной пещеры изобразите историю о грядущем столкновении, включив в неё отметку чудища с активным логовом в долине и с самым высоким значением нрава, украшенную отметкой гнева [i] (см. раздел «Украшающие отметки» в правилах игры на с. <rulebook>70</rulebook>).<br><b>Б. Ваш народ понял, что можно мирно сосуществовать с чудищами. </b>Если значение нрава любого чудища не более 5 и значение <unrest> не более 14, добавьте карту «Единое видение» (ИБ07) к грядущим испытаниям. На стене первобытной пещеры изобразите историю о пути единения, включив в неё отметку чудища с активным логовом в долине и с самым низким значением нрава, а также отметку посредника [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<wrath>"},{"label":"ii","image":"<mediator>"}]},{"id":"outcomes-089","code":"089","description":{"en":"","ru":"<p><i><b>Вы вернулись к семени, сокрытому в глубине корневых туннелей. Сомнения ледяными пальцами сжимали ваше сердце, пока вы приближались.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><i><b>Тени в туннеле казались холоднее обычного. Вас тяготила ваша же цель.</b></i><br><b>Группа, угроза.</b> Все персонажи в походе должны провести проверку <conviction>, чтобы продолжить путь. +2, если у персонажа есть предмет с <fire> , +2, если персонаж <i>неукротимый</i>, и +4, если у него есть отметка изобилия.<br><b>≥12:</b>  Вы уверенно продвигались вперёд. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>7-11:</b>  Вы с трудом двигались вперёд, остро ощущая тяжесть Сплетения над головой. Потеряйте <energy>. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-6:</b>  Вас одолели сомнения, и вы повернули назад. Покиньте поход. Если все персонажи покинули поход, он окончился неудачно.</p><p><i><b>Вы пробрались в полость с семенем. Плотная оболочка защищала семя от чужого вмешательства, но вы были готовы идти до конца.</b></i><br><b>Защитник.</b> Один из персонажей в походе должен провести проверку <dexterity>, чтобы пробить отверстие к сердцевине семени. +2, если у этого персонажа есть <drill>, и +2, если он <i>хитрый</i>.<br><b>≥11:</b>  Вы раскололи оболочку без особого труда. Продолжите поход.<br>1-10  Оболочка не поддалась. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, что бы провести проверку ещё раз.</p><p><i><b>Один из принесённых вами материалов мог повлиять на семя.</b></i><br><b>Защитник.</b> Один из персонажей в походе должен сбросить редкий материал, а затем провести проверку <awareness>, чтобы нанести вещество на семя. +2, если персонаж <i>сосредоточенный</i>, и +6, если он сбросил лунную кровь.<br><b>≥14:</b>  По туннелям прошла дрожь. Завершите этот поход и достигните соответствующей цели.<br><b>1-13:</b>  Вам не удалось добиться успеха. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз. </p>"},"repeatable":false,"marks":[{"label":"","image":"<plenty>"}]},{"id":"outcomes-090","code":"090","description":{"en":"","ru":"<p><i><b>Вы стояли на спине чудища. Его костистый хребет пульсировал неожиданным теплом.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Вонзите своё оружие меж позвонков и узрите, как оно рассыпается от соприкосновения с чудищем. </b>Если в вашем инвентаре есть оружие, сбросьте 1 оружие. Завершите встречу. Разозлите чудище на 2. Чудище сбегает.<br><b>Б. Ударьте между позвонками кулаком и ощутите, как из вас уходит жизненная сила.</b> Отметьте одну клетку возраста на карте персонажа. Завершите встречу. Разозлите чудище на 2. Чудище сбегает. Добавьте отметку этого чудища на сторону легенды карты своего персонажа.<br><b>В. Коснитесь хребта, чтобы направить чудище.</b>Сбросьте все свои <boost>; если сбрасывать нечего, отметьте одну клетку возраста на карте своего персонажа. Завершите встречу. Чудище сбегает. Успокойте чудище на 1. Добавьте отметку этого чудища на сторону легенды карты своего персонажа.</p>"},"repeatable":false},{"id":"outcomes-092","code":"092","description":{"en":"","ru":"<p><i><b>Оглушительные шаги сотрясали долину. Вы обернулись и увидели ужасающее существо невообразимых размеров. Оно сминало всё на своём пути, и след его вёл от того места, где ваши старейшины вошли в долину. Огромное облако пыли клубилось над запечатанным навсегда проходом. Какой бы ни была дальнейшая судьба вашего народа, это чудище должно было сыграть в ней свою роль.</b></i></p><p>Верните в коробку карту цели «Пройдите по следам тайн» (ЦА11). Добавьте карту «Вторжение» (ИА04) к грядущим испытаниям.</p>"},"repeatable":false},{"id":"outcomes-093","code":"093","description":{"en":"","ru":"<p><i><b>Вы воззвали к прошлому своего народа, полному волнений и примирений, и рассказали о вспышках гнева, которые удалось погасить. Ваша история передавалась из уст в уста, принося с собой мир и единство.</b></i></p><p>Уберите <unrest><unrest><unrest>. Если значение <unrest> должно опуститься ниже 0, добавьте <lore> за каждое , которое не может быть убрано.</p>"},"repeatable":false},{"id":"outcomes-094","code":"094","description":{"en":"","ru":"<p><i><b>Неужели споры коралла в долину принёс Скиталец? Ваша голова шла кругом от этой мысли. Пока вы наблюдали, кусок кометы откололся и исчез за горизонтом. Осознание происходящего привело вас в ужас. Скиталец приближался, и времени на подготовку почти не осталось.</b></i></p><p>Добавьте карту «Час приготовлений» (ИВ03) к грядущим испытаниям.</p>"},"repeatable":false},{"id":"outcomes-095","code":"095","description":{"en":"","ru":"<p><i><b>Спина чудища сотрясалась при ходьбе, и острые гребни на его спине опасно раскачивались, пока вы пробирались между ними. Риск раззадорил вас, наполнив храбростью.</b></i></p><p>Добавьте <minor_boost> к <conviction>.</p>"},"repeatable":false},{"id":"outcomes-096","code":"096","description":{"en":"","ru":"<p><i><b>Чудище направилось к подножию пылающего горного склона, будто указывая вам единственный безопасный путь сквозь обжигающие облака и трескучие молнии, венчающие вершину.</b></i></p><p>Завершите текущее испытание.<br>На стене первобытной пещеры изобразите историю об одиноком проводнике, включив в неё отметку ЧД4 [ii], заключённую в отметку окончания [i]. Добавьте карту «Пеплопад» (ИЕ05) к грядущим испытаниям. Когда выберете его, добавьте карту «Заключите необычный союз» (ЦЕ06) к целям.</p>"},"repeatable":false,"marks":[{"label":"i","image":{"image":"<conclusion>","overlay":{"image":"<bh4>","size":0.65,"x":5,"y":0,"rotate":0}}}]},{"id":"outcomes-097","code":"097","description":{"en":"","ru":"<p><i><b>Хаос перерастал в насилие, отвлекал от важных целей и приводил ваш народ в замешательство. Ожесточённые сражения задели невинных жителей, разрушили здания и побеспокоили всех обитателей долины.</b></i></p><p>Разозлите каждое чудище на 2. Для каждого поселения бросьте <1d6>. +1 к результату за каждый жетон тайны на участке с поселением и на соседних участках, а также за каждый жетон следов или чудище на участке с поселением и на соседних участках. Затем разыграйте эффект для каждого поселения в зависимости от результата:<br><b>≥9:</b>  Во время очередной потасовки разлетелись горячие угли, и пламя охватило поселение. Поселение становится руинами. Добавьте <unrest><unrest>  и уберите <population><population>.<br><b>5-8:</b>  Одна из построек рухнула во время беспорядков. Разрушьте одно случайное сооружение в этом поселении, если только персонаж на этом участке местности не получит <major_injury><minor_injury><minor_injury>. Добавьте <unrest>.<br><b>3-4:</b>  Обстановка опасно накалилась, но в конце концов здравый смысл победил. Добавьте <unrest>.<br><b>1-2:</b>  В этом поселении беды не случилось, и напряжение немного ослабло. Уберите <unrest>.</p>"},"repeatable":false},{"id":"outcomes-098","code":"098","description":{"en":"","ru":"<p><i><b>Вы исследовали место падения, несмотря на беспокойство народа. В огромном тлеющем кратере один из вас бросил вызов кораллу и остановил его рост ценой собственной жизни. Однако могло оказаться, что люди не примут этого.</b></i></p><p>Завершите текущее испытание.</p><p>Затем разыграйте первое, что можете:<br><b>A. Ваш народ, слишком измученный бесконечными тяготами, чтобы протестовать, принял ваше решение — и так наступил хрупкий мир.</b> Если значение <unrest> не более 8, добавьте к грядущим испытаниям карту «Период затишья» (ИЯ01), даже если это испытание было завершено ранее, и карту «Презрение земли» (ИВ06).<br><b>Б. Ваш народ был разгневан вашими поступками. Вас изгнали из общины, несмотря на великое бедствие, угрожавшее миру. </b>Если значение <unrest> равно хотя бы 9, добавьте карту «Презрение человечества» (ИВ05) к грядущим испытаниям.</p>"},"repeatable":false},{"id":"outcomes-099","code":"099","description":{"en":"","ru":"<p><i><b>Стоя на голове чудища, вы занесли руку для последнего удара, но замерли в нерешительности. Убить великое существо, что пришло в долину вместе с вашими предками?.. Вы обмякли, и в этот момент чудище вздрогнуло. Вы упали на землю. Чудище нависло над вами, его раны сочились. Оно смотрело на вас по‑новому, словно признав ваше место в долине.</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest><unrest><unrest>. Установите значение нрава бодрствующего чудища на 2. На стене первобытной пещеры изобразите историю о разомкнутом круге, включив в неё отметку бодрствующего чудища, отметку осторожности [i] и отметку становления [ii]. Навсегда увеличьте <conviction> и <awareness> на 1 (не более чем до 7) каждого персонажа, оставшегося в походе на момент его завершения. Добавьте отметку чудища и отметку становления на сторону легенды карты каждого из этих персонажей.</p><p>Затем завершите эру. См. с. 204, чтобы <era3>начать эру 3</era3>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":"<growth>"}]},{"id":"outcomes-101","code":"101","description":{"en":"","ru":"<p><i><b>Вы раскрыли секрет укрощения чудища. Это неожиданное открытие позволило вам сдержать невероятную мощь исполинского существа, а позже позволит грядущим поколениям выстроить с чудищем новые отношения. Но будут ли потомки распоряжаться мудро этим знанием? Или власть над гигантом посеет семена высокомерия и заставит ваших преемников забыть об уважении к своему месту в этом огромном мире?</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о секрете чудища, включив в неё отметку бодрствующего чудища и отметку открытия.<br>Добавьте карты «Праздник памяти» (ИА07) и «Предостережение чудища» (ИА10) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"","image":"<discovery>"}]},{"id":"outcomes-107","code":"107","description":{"en":"","ru":"<p><i><b>Вы занимали высокое положение среди своего народа, но проблемы, с которыми вам довелось столкнуться, привели к вашему изгнанию... </b></i></p><p>Завершите текущее испытание.</p><p>Уберите <unrest><unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о восхождении к власти, включив в неё отметку ужаса [i] и отметку мятежа [ii]. Добавьте карту «Презрение земли» (ИВ06) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<harrowing>"},{"label":"ii","image":"<rebellion>"}]},{"id":"outcomes-108","code":"108","description":{"en":"","ru":"<p><i><b>Вы создали вечный памятник прошлым поколениям. Уход за этим местом стал важной задачей для вашего народа.</b></i></p><p>На стене первобытной пещеры изобразите историю о письменах, включив в неё отметку летописца. Получите карту знаний «Легенды» (ЗБ15) и карту знаний «Символы» (ЗБ17). Ваша община получает силу мантии «Глашатай легенд» (МА11).</p>"},"repeatable":false,"marks":[{"label":"","image":"<scribe>"}]},{"id":"outcomes-109","code":"109","description":{"en":"","ru":"<p><i><b>История вашего народа по‑прежнему передавалась из уст в уста. Вы делали всё возможное, чтобы помнить деяния предков, и каждое поколение стремилось сохранить связь с прошлым. И всё же какие‑то истины неизбежно терялись, ускользая сквозь трещины человеческой памяти.</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о далёких днях, включив в неё отметку тайны. Получите карту знаний «Легенды» (ЗБ15). Ваша община получает силу мантии «Глашатай легенд» (МА11).<br>Возьмите 2 случайные карты из колоды легенд. Эти легенды забыты. Верните их в коробку — ваша община больше не может их использовать.</p>"},"repeatable":false,"marks":[{"label":"","image":"<mystery>"}]},{"id":"outcomes-111","code":"111","description":{"en":"","ru":"<p><i><b>Во время раскопок вы нашли перламутровый осколок, совсем не похожий на камни, с которыми вам приходилось работать. Он был легче и пористее, чем обычно, и крошился под кончиками пальцев. Но вдруг был способ извлечь его, не повредив?</b></i></p><p>Вы можете провести проверку <might>, чтобы вытащить осколок из стены. +2, если вы <i>неукротимый</i>, +2, если у вас есть <comet>, и +4, если у вас есть отметка  или отметка коралла.<br><b>≥12:</b>  Получите 2 мёртвых коралла.<br><b>8-11:</b>  Получите 1 мёртвый коралл.<br><b>1-7:</b>  Осколок не поддался. Без эффекта.</p>"},"repeatable":false,"marks":[{"label":"","image":"<coral>"}]},{"id":"outcomes-112","code":"112","description":{"en":"","ru":"<p><i><b>Слухи из разных уголков долины начали складываться в единую картину: тут — примятая поляна, там — зияющий разлом в земле. Что‑то могущественное и опасное обитало на окраинах этого уединённого места. Казалось, оно пришло одновременно с вами. Ваша община встала перед выбором.</b></i></p><p>Совместно выберите один из следующих путей развития общины:<br><b>А. Подготовьтесь к возможной угрозе. </b>Добавьте <population>. Спроектируйте частокол (СР11), не тратя <lore>.<br><b>Б. Уйдите вглубь долины в поисках укрытия. </b>Добавьте карту «Пройдите по ледяному покрову» (ЦА06) к целям.</p>"},"repeatable":false},{"id":"outcomes-113","code":"113","description":{"en":"","ru":"<p><i><b>За многие поколения старое Сплетение увяло и умерло. Земля стала сухой и пыльной, когда цветущие джунгли уступили губительному заболеванию. Однако семя однажды даст всходы и превзойдёт своего родителя, создав новое Сплетение, в котором ваша община сможет процветать на протяжении бесчисленных поколений.</b></i></p><p>Добавьте <population><population><population> и уберите <unrest><unrest><unrest>.<br></p><p>На стене первобытной пещеры изобразите историю о возрождении Сплетения, включив в неё отметку Сплетения [i] и отметку тайны [ii]. Ваша община <b>выжила</b>.<br></p> <p>Поздравляем! Вы завершили кампанию «Наскальной истории»! Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!<br>Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. <rulebook>97</rulebook> или раздел «Бесконечный режим» на с. <rulebook>102</rulebook>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<tangle>"},{"label":"ii","image":"<mystery>"},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-114","code":"114","description":{"en":"","ru":"<p><i><b>Ведомое своими инстинктами, чудище завершило путь, вернулось в логово и погрузилось в покой.</b></i></p><p>Это чудище становится спящим. Затем разыграйте первое, что можете:<br><b>А. Если в долине есть одно или несколько других чудищ с активными логовами,</b> выберите случайное из них — оно становится бодрствующим. Поместите фигурку этого чудища на участок местности с его логовом и назначьте ему инстинкт (см. в правилах игры на с. <rulebook>75</rulebook>).<br><b>Б. Если в долине нет других чудищ с активными логовами,</b> положите 4 жетона следов на логово чудища, которое стало спящим. В конце каждого дня убирайте по 1 жетону. Когда на логове не останется жетонов следов, это чудище снова становится бодрствующим. В этом случае поместите фигурку этого чудища на участок местности с его логовом и назначьте ему инстинкт (см. в правилах игры на с. <rulebook>75</rulebook>).</p>"},"repeatable":false},{"id":"outcomes-116","code":"116","description":{"en":"","ru":"<p><i><b>Сменялись времена года, а разногласия только сильнее разделяли ваших людей, превращая их в непримиримых врагов. Когда недовольные ушли, забрав с собой сильных членов общины, обе стороны остались ослабленными и разобщёнными.</b></i></p><p>Завершите текущее испытание.</p><p>Уберите <population><population><population><population>. На стене первобытной пещеры изобразите историю о разрыве связей, включив в неё отметку раскола.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<schism>"}]},{"id":"outcomes-117","code":"117","description":{"en":"","ru":"<p><i><b>Ваше чутьё подсказывало, что некая сущность намеренно оставила это странное послание, — и вам казалось, что вы способны понять его…</b></i></p><p>Добавьте <lore> и получите <minor_boost> к любой характеристике. Если у вас есть отметка чудища, вместо этого добавьте <lore><lore><lore> и получите <major_boost> к любой характеристике.</p>"},"repeatable":false},{"id":"outcomes-119","code":"119","description":{"en":"","ru":"<p><i><b>Сухая трава занялась от вспышки молнии — и огонь уже грозился выйти из‑под контроля...</b></i></p><p>Добавьте карту «Остановите огонь» (ЦЯ20) к целям.</p>"},"repeatable":false},{"id":"outcomes-121","code":"121","description":{"en":"","ru":"<p><i><b>Возведённое вами поселение едва ли можно было назвать основательным, ведь оно состояло в основном из лёгких построек, которые несложно разобрать и перенести. Со временем ваши люди так приноровились к кочевому укладу, что теперь они могли следовать за дикими животными и собирать урожай в самых плодородных уголках долины, переходя от места к месту из года в год.</b></i></p><p>На стене первобытной пещеры изобразите историю о безграничных путях, включив в неё отметку каравана. Поселения вашего народа могут быть перемещены как в процессе испытаний, так и между ними. Получите карту знаний «Караваны» (ЗБ09).</p>"},"repeatable":false,"marks":[{"label":"","image":"<caravan>"}]},{"id":"outcomes-126","code":"126","description":{"en":"","ru":"<p><i><b>Загадка оставалась неразгаданной, и ваши люди невольно задумывались, что же кроется за пределами их восприятия.</b></i></p><p>Завершите текущее испытание.</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Примите, что есть вещи, непостижимые для человеческого разума. </b>Уберите  <unrest><unrest>. Добавьте отметку тайны [i] на сторону легенды карты каждого персонажа. На стене первобытной пещеры изобразите историю о непостижимом вопросе, включив в неё отметку бодрствующего чудища и отметку тайны [i].<br><b>Б. Никогда не прекращайте поиски ответов.</b>Навсегда увеличьте <awareness> каждого персонажа на 2 (не более чем до 7). Добавьте отметку становления [ii] на сторону легенды карты каждого персонажа. Запишите «Завершение испытания хотя бы с 1 жетоном тайны в долине» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет. На стене первобытной пещеры изобразите историю о бесконечном поиске, включив в неё отметку бодрствующего чудища и отметку становления [ii].</p><p>Завершите текущую эру. См. с. 196, чтобы <era2>начать эру 2</era2>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<mystery>"},{"label":"ii","image":"<growth>"}]},{"id":"outcomes-129","code":"129","description":{"en":"","ru":"<p><i><b>Вы отправились туда, где ужас вместе с тенями скользил по каждой поверхности. В звенящей тишине у пустующего логова чудища никто не осмеливался нарушить молчание. Что же ждало вас внутри? Оставалось только гадать…</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><b>Чудище должно было как‑то входить и выходить из этого логова, но его путь был покрыт тайной. Вам пришлось искать способ попасть внутрь.</b></p><p><b>Группа, чудо. </b>Все персонажи в походе должны провести проверку <awareness>, чтобы найти вход. +2 за каждый имеющийся у персонажа предмет для <i>исследования</i>, и +2, если персонаж <i>любознательный </i>или <i>отважный</i>.</p><p><b>≥12:</b>  Вы узнали о чудище нечто интересное. Добавьте <lore>. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-11:</b>  Вы не преуспели. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>В логове на каждом шагу вы натыкались на напоминания об исполинском обитателе сего места. Следы, отметины, запах — даже отголоски этого чудища устрашали. Вы должны были собраться с духом, чтобы продолжить!</b></i></p><p><b>Группа, угроза.</b> Все персонажи в походе должны провести проверку <conviction>, чтобы преодолеть страх. +2, если у персонажа есть <i>талисман</i>, и +2, если персонаж <i>неукротимый </i>или <i>мстительный</i>.</p><p><b>≥10:</b>  Вы преодолели невыносимое давление, искажающее ваше ощущение реальности. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-9:</b>  Вы растерялись перед доказательствами своей ничтожности в масштабах вселенной. Покиньте поход, затем сбегите. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><i><b>Внутри логова вы нашли небольшую вырытую в земле полость. Чудище, несомненно, создало это укрытие намеренно. Что оно могло прятать там?</b></i></p><p><b>Защитник, чудо.</b> Один из персонажей в походе должен провести проверку <dexterity>, чтобы прокрасться в логово. +2, если у него есть <i>накидка</i>, и +2, если этот персонаж <i>хитрый</i>.</p><p><b>≥13:</b>  Вы проскользнули внутрь. Завершите этот поход и достигните соответствующей цели.<br><b>1-12:</b>  Вы не смогли попасть внутрь и наделали много шума. Разозлите чудище на 1. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-130","code":"130","description":{"en":"","ru":"<p><i><b>Осенний холод крепчал, предвещая наступление ледяной зимы. Без надёжного крова над головой даже ранние заморозки ощущались особенно суровыми. Облака темнели на горизонте, скрывая высокое звёздное небо.</b></i></p><p>Завершите текущее испытание.</p><p>Уберите <population>. За время, проведённое в долине, ваш народ развил новые навыки выживания. Ваша община получает следующие силы мантий: «Следопыт» (МА01), «Знаток секретов» (МА02), «Друг-наставник» (МА03), «Хранитель» (МА04). Запишите их в раздел «Силы мантий» на странице «Культура» в журнале. В начале каждого следующего испытания выбирайте по одной силе для каждого персонажа в соответствии с их мантиями, как описано в разделе «Силы мантий» на с. <rulebook>65</rulebook> правил.</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>A. Призовите свой народ завершить начатые постройки любой ценой, несмотря на надвигающиеся штормовые облака. </b>Уберите <population> и добавьте <unrest>, затем постройте одно спроектированное сооружение в одном из своих поселений, не оплачивая его стоимость. Можете повторить это действие ещё 2 раза или меньше. На стене первобытной пещеры изобразите историю о закалённой решимости, включив в неё отметку <cloud> и отметку ужаса [i]. Добавьте карту «Праздник памяти» (ИА07) к грядущим испытаниям. Добавьте к целям следующие карты: «Соберите припасы» (ЦА03), «Отыщите знамения» (ЦА07), «Разведите огонь» (ЦА08), «Пройдите по следам тайн» (ЦА11).<br><b>Б. Сообщите своему народу, что вы отправитесь вслед за рекой звёздного света в лучшее пристанище.</b>Построенное вами поселение становится руинами (переверните накладку стороной руин вверх и укажите на карте поселения, что теперь это руины). На стене первобытной пещеры изобразите историю о надежде, что сулит горизонт, включив в неё отметку прибытия [ii] и отметку <star>. Добавьте карту «Прибежище» (ИА03) к грядущим испытаниям. Добавьте к целям следующие карты: «Соберите припасы» (ЦА03), «Отыщите знамения» (ЦА07), «Разведите огонь» (ЦА08), «Пройдите по следам тайн» (ЦА11).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<harrowing>"},{"label":"ii","image":"<arrival>"}]},{"id":"outcomes-132","code":"132","description":{"en":"","ru":"<p><i><b>Ваш народ знал, что Скиталец вскоре вернётся перерождённым, и восхищался его чудесным путешествием к солнцу. С нарастающим шумом и весельем люди радовались этому запредельному чуду.</b></i></p><p>Каждый персонаж получает <minor_boost> к любой характеристике. Вместо этого, если у персонажа есть предмет <i>коралла</i>, он может 2 раза уменьшить недуг или получить <major_boost> к любой характеристике.</p>"},"repeatable":false},{"id":"outcomes-134","code":"134","description":{"en":"","ru":"<p><i><b>В этой недавно обнаруженной части долины вы нашли лабиринт из каньонов и ям. Из трещин выходил пар, сохраняя тепло даже в самые холодные ночи.</b></i></p><p>Если в долине не более 1 накладки геотермального источника, поместите накладку геотермального источника на участок в последней добавленной основе местности, выбрав неисследованный участок без накладок, если возможно. Бросьте <1d6>, чтобы поместить геотермальный источник в соответствующий район: [1-2]  A, [3-4] Б, [5-6] В. Подробнее о геотермальных источниках см. на с. 210.</p>"},"repeatable":false},{"id":"outcomes-136","code":"136","description":{"en":"","ru":"<p><i><b>Ваш народ привык жить в Сплетении и рядом с ним, шагая по лианам под мерцающими тенями гигантских цветков. Эта земля, полная буйной растительности и неукротимого роста, давала вашему народу всё необходимое, и ваша община начала разрастаться. Вы ощущали всё более тесную связь с этим местом...</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Добавьте <population><population>. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Начните строить внутри Сплетения.</b>  Добавьте <population><population><population><population>. Вы можете поместить 1 поселение на участок Сплетения (не тратя энергию и ресурсы). На стене первобытной пещеры изобразите историю о даре Сплетения, включив в неё отметку Сплетения [i] и отметку изобилия [ii].<br><b>Б. Запретите строительство в Сплетении. </b>Запишите «Строительство поселений в Сплетении» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет. На стене первобытной пещеры изобразите историю о благоговейных жнецах, включив в неё отметку табу [iii] и отметку Сплетения [i].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<tangle>"},{"label":"ii","image":"<plenty>"},{"label":"iii","image":"<taboo>"}]},{"id":"outcomes-143","code":"143","description":{"en":"","ru":"<p><i><b>В глубине пещеры вы нашли отполированный камень, отражающий всё, словно озёрная гладь. Сначала вам показалось, что в отражении вы видите себя. Однако, присмотревшись, вы заметили, что это был человек, лишь похожий на вас, с едва уловимыми отличиями. Вы встретились взглядом с усталыми глазами незнакомца — и ваш разум захлестнуло видение. Вы пришли в себя рядом с осколками зеркального камня, а ваша голова гудела от немыслимого знания.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Даже когда видение угасло, пылающий след Странника остался в вашем сознании. </b>Если <comet> — текущее знамение, найдите карту цели ЦВ05. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описывать её другим игрокам в течение любого времени. Затем на стене первобытной пещеры изобразите историю о живом кратере, включив в неё отметку ЧД1 [i] и отметку <comet>, заключённую в отметку пророчества [ii].<br><b>Б. Вы вспомнили побелевшие кости, гремящие на иссушающем ветре. </b>Если <sun> — текущее знамение, найдите карту цели ЦЯ08. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описывать её другим игрокам в течение любого времени. Затем на стене первобытной пещеры изобразите историю о стремительной смерти, включив в неё отметку ЧД1 [i], отметку ужаса [iii] и отметку <sun>, заключённую в отметку пророчества [ii].<br><b>В. В сознании остался образ тёплой улыбки незнакомца. </b> Если  <star>— текущее знамение, найдите карту цели ЦЯ10. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описывать её другим игрокам в течение любого времени. Затем на стене первобытной пещеры изобразите историю о ещё не случившейся, но предсказанной встрече, включив в неё отметку ЧД1 [i] и отметку <star>, заключённую в отметку пророчества [ii].<br><b>Г. Всё ваше тело содрогнулось от силы видения. </b>Если <cloud> или <moon> — текущее знамение, найдите карту цели ЦЯ16. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описывать её другим игрокам в течение любого времени. Затем на стене первобытной пещеры изобразите историю о роковом столкновении, включив в неё отметку ЧД1 [i] и отметку <moon>, заключённую в отметку пророчества [ii].</p><p>В конце этого испытания завершите текущую эру. См. с. 196, чтобы <era2>начать эру 2<era2>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<bh1>"},{"label":"ii","image":"<prophecy>"},{"label":"iii","image":"<harrowing>"}]},{"id":"outcomes-147","code":"147","description":{"en":"","ru":"<p><i><b>Силой, хитростью или упорством — вы одолели чудище трижды. Когда рассвет прорезал тьму, вы увидели его у окраин диких земель. Оно было всё ещё необъятно и непостижимо, но теперь в его взгляде будто бы сквозила неуверенность. Чудище отступило к своему логову, а вы невольно задумались, как ваши столкновения с ним отзовутся в судьбе грядущих поколений.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Уберите <unrest>. На стене первобытной пещеры изобразите историю о великой битве, включив в неё отметку битвы [i] и отметку бодрствующего чудища, украшенную отметкой гнева [ii]. См. раздел «Украшающие отметки» в правилах игры на с. <rulebook>70</rulebook>.</p><p>Добавьте карты «Праздник памяти» (ИА07) и «Ночь бурь» (ИА09) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<wrath>"}]},{"id":"outcomes-149","code":"149","description":{"en":"","ru":"<p><i><b>Погружаясь глубже во тьму, вы ощущали, как стены становятся всё более липкими и влажными. Спустя какое‑то время вы поняли, что липким и влажным стало и ваше тело. Вас охватила лихорадка.</b></i></p><p>Проведите проверку <might>, чтобы сопротивляться болезни. +2, если вы <i>осторожный</i>, и +4, если у вас есть отметка чумы.<br><b>≥12:</b>  Вам удалось справиться с самыми тяжёлыми последствиями. Получите <minor_disease>.<br><b>6-11:</b>  Вы заболели. Получите <major_disease>.<br><b>1-5:</b>  Разыграйте исход как при 6-11, затем добавьте карту «Мор» (ИЯ03) к грядущим испытаниям, если на стене первобытной пещеры нет отметки чумы.</p>"},"repeatable":false,"marks":[{"label":"","image":"<plague>"}]},{"id":"outcomes-154","code":"154","description":{"en":"","ru":"<p><i><b>Пламя и дым извергались из огромного кратера на вершине горы. Молнии вспыхивали в тучах над вершиной. Вам нужно было спешить, чтобы запечатать гигантскую пасть, пока будущее вашего народа не оказалось погребено под пеплом.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><b><i>Гром сотрясал небо, а молнии рассекали воздух над краем кратера. Вам нужно было срочно найти укрытие!</i></b></p><p><b>Группа, погода. </b>Все персонажи в походе должны провести проверку <awareness>, чтобы найти укрытие. +2, если персонаж <i>осторожный</i>, и +6, если чудище помогает в походе.<br><b>≥10:</b>  Вы заметили выступ и успели укрыться под ним как раз в тот момент, когда молния обожгла землю выше по склону. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-9 : </b>Вас сбило с ног ударом молнии. Получите <major_injury>. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore><lore>, чтобы провести проверку ещё раз.</p><p><i><b>Из огненной пасти валил едкий дым, и вам предстояло пробиваться сквозь пелену пепла.</b></i></p><p><b>Группа, погода. </b>Все персонажи в походе должны провести проверку <might>. +2, если персонаж <i>отважный</i>, и +6, если чудище помогает в походе. Персонаж может сбросить 1 воду, чтобы добавить 4 к результату.<br><b>≥12:</b>  Вы не дали дыму проникнуть в лёгкие. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>8-11:</b>  Вы продолжили путь, но вдохнули обжигающий дым. Получите <major_disease>. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-7:</b>  Вы потерялись в дыму. Получите <major_disease> и <minor_disease>, затем покиньте поход. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><b><i>В самом сердце кратера кипела грозная магма — но, быть может, правильная жертва усмирила бы её гнев.</i></b></p><p><b>Защитник. </b>Один из персонажей в походе должен сбросить редкий материал либо предмет с ключевым словом «коралл», «лунная кровь», «шёлк» или «трофей», а затем провести проверку <dexterity>, чтобы бросить подношение в кипящее жерло. +2, если был сброшен предмет с ключевым словом «коралл», «лунная кровь» или «шёлк», +4, если был сброшен предмет с ключевым словом «трофей», +2, если персонаж <i>изобретательный</i>, и +6, если чудище помогает в походе.<br><b>≥14:</b>  Сверкнув, подношение погрузилось в магму, и гора начала дрожать, когда камень затвердел над кратером. Завершите этот поход и достигните соответствующей цели.<br><b>1-13:</b>  Брошенный предмет воспламенился, и расплавленный камень начал бурлить ещё яростнее. Каждый персонаж в походе получает <minor_injury>. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести</p>"},"repeatable":false},{"id":"outcomes-155","code":"155","description":{"en":"","ru":"<p><i><b>Вы стали лучше управляться с огнём и теперь, приложив усилия, научились высекать искры трением. Однако вы не переставали задумываться, как разжечь пламя ещё быстрее.</b></i></p><p>Получите карту знаний «Разведение огня» (ЗБ06). На стене первобытной пещеры изобразите историю о заботливо поддерживаемых углях, включив в неё отметку пламени. Спроектируйте костровую яму (СР02), не тратя <lore>. См. раздел «Проектирование сооружения» в правилах игры на с. <rulebook>34</rulebook>. Ваша община получает силу мантии «Сторож очага» (МА15). Добавьте карту «Изучите тайные тропы» (ЦА09) к целям.</p>"},"repeatable":false,"marks":[{"label":"","image":"<blaze>"}]},{"id":"outcomes-165","code":"165","description":{"en":"","ru":"<p><i><b>Могучая лапа чудища обрушилась, сокрушая метеорит, в котором покоилось сердце коралла. Гулкий звон катился по долине, пока коралловые стебли не обесцветились, став пепельно‑серыми. Долина ещё не залечила шрамы от удара, но с каждым днём жизнь возвращалась в прежнее русло. Под присмотром чудища ваша община снова начала расцветать.</b></i></p><p>Добавьте <population><population><population> и уберите <unrest><unrest><unrest>. Уберите накладку места падения. Переверните все коралловые заросли неактивной стороной вверх.</p><p>На стене первобытной пещеры изобразите историю о могучем победителе вне времени, включив в неё отметку коралла [i] и отметку этого чудища, заключённую в отметку окончания [ii]. Ваша община <b>выжила</b>.</p><p>Поздравляем! Вы завершили кампанию «Наскальной истории»! Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!</p><p>Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. <rulebook>97</rulebook> или раздел «Бесконечный режим» на с. <rulebook>102</rulebook>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<coral>"},{"label":"ii","image":"<conclusion>"},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-168","code":"168","description":{"en":"","ru":"<p><i><b>Человек рассказал о себе, делясь своей радостью, горем и утратами. В вашем сердце зародилось стремление возродить его историю в памяти вашего народа.</b></i></p><p>Добавьте  <lore><lore><lore>. Вы можете случайным образом выбрать карту легенды, забытую вашей общиной (которую вы вернули в коробку). Она снова становится одной из легенд вашей общины.</p>"},"repeatable":false},{"id":"outcomes-175","code":"175","description":{"en":"","ru":"<p><i><b>Вы вытащили из ртутного моря создание, которое прежде не встречали. У него была вздутая голова и несколько щупалец, которые извивались у вас в руках. Его большие глаза вопрошающе смотрели на вас.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Пожалейте существо и верните его в море.</b> Существо скользнуло обратно в воду. Добавьте <lore><lore>.<br><b>Б. Проверьте, пригодно ли оно в пищу. </b> Мясо оказалось жилистым, но насыщенным живительной влагой, хотя существо обитало в переменчивом и ядовитом море. Получите 2 дичи и 4 воды.</p>"},"repeatable":false},{"id":"outcomes-186","code":"186","description":{"en":"","ru":"<p><i><b>Когда тьма окутала землю, вы старались поддерживать нуждающихся пищей. Вам часто мешали люди, что в панике собирали ресурсы, даже когда те им были не нужны. Но всё же вам и вашему народу удалось справиться.</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest><unrest><unrest>. Добавьте карту «Переживите опасные налёты» (ЦЯ26) к целям. На стене первобытной пещеры изобразите историю о тёмных днях, включив в неё отметку почерневшего неба [i] и отметку мятежа [ii]. Затем совместно выберите один из следующих путей развития общины:<br><b>A. Поищите происхождение коралла в незнакомой ледяной земле. </b> Если на стене первобытной пещеры есть отметка Звёздного моря [iii], добавьте карту «Разговор со звёздами» (ИВ07) к гряду щим испытаниям.<br><b>Б. Сразитесь с защитником древности, который теперь служит кораллу. </b>Если на стене первобытной пещеры есть отметка коралла, заключённая в отметку окончания [iv], добавьте карту «Избранник кометы» (ИВ08) к грядущим испытаниям.<br><b>В. Отправьтесь на поиски логова своего древнего врага. </b>Если на стене первобытной пещеры есть отметка чудища с неактивным логовом, украшенная отметкой крови чудища [v], добавьте карту «Чудище кометы» (ИВ09) к грядущим испытаниям.<br><b>Г. Обратитесь к связи чудища с прошлым. </b>Если на стене первобытной пещеры есть отметка чудища, заключённая в отметку связи [vi], добавьте карту «Узы чудища» (ИВ10) к грядущим испытаниям. <br><b>Д. Сбегите из долины раз и навсегда. </b>Добавьте карту «Исход» (ИЯ09) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<blackenedsky>"},{"label":"ii","image":"<rebellion>"},{"label":"iii","image":"<starlitsea>"},{"label":"iv","image":{"image":"<conclusion>","overlay":{"image":"<coral>","size":0.85,"x":3,"y":5,"rotate":0}}},{"label":"v","image":"<behemothsblood>"},{"label":"vi","image":"<bond>"}]},{"id":"outcomes-188","code":"188","description":{"en":"","ru":"<p><i><b>Спускаясь под землю, вы зацепили рукой что‑то влажное и обнаружили лужу странной серебристой жидкости. Как бы ухитриться собрать это необычное вещество?</b></i></p><p>Можете провести проверку <awareness>, чтобы попытаться собрать скользкое вещество. +2, если вы <i>изобретательный</i>, +2, если у вас есть «Бурдюк», и +4, если у вас есть отметка лунной крови.<br><b>≥12:</b> Получите 2 лунные крови. <br><b>8-11:</b>  Получите 1 лунную кровь.<br><b>1-7 :</b> Вещество выскользнуло у вас из пальцев. Без эффекта. </p>"},"repeatable":false,"marks":[{"label":"","image":"<moonblood>"}]},{"id":"outcomes-193","code":"193","description":{"en":"","ru":"<p><i><b>По всей долине с пугающей скоростью начали разрастаться кораллы.</b></i></p><p>Поместите неактивные коралловые заросли на любой участок, выбрав участок без накладок, если возможно (поместите столько зарослей, сколько испытаний завершили в текущей эре до этого момента, но не более 3). Для каждых зарослей бросьте <1d6>, чтобы поместить их в соответствующий район: [1-2] А, [3-4] Б, [5-6] В. Если заросли должны быть помещены поверх другой накладки, перебросьте <1d6>.</p><p>Добавьте карту «Раскройте тайну коралла» (ЦБ08) к целям (если вы не достигли её ранее).<br>Затем разыграйте как можно больше из следующего:<br><b>А. Леса изменились из-за воздействия кораллов. </b>Если в долине есть хотя бы 1 участок Дивной долины, добавьте карты КЛ01–КЛ04 в колоду добычи припасов в лесу.<br><b>Б. В степи закипела странная новая жизнь. </b>Если в долине есть хотя бы 1 участок Поднебесной равнины, добавьте карты КС01–КС04 в колоду добычи припасов в степи.<br><b>В. Сплетение стало ещё более странным, чем прежде. </b> Если в долине есть хотя бы 1 участок Сплетения, добавьте карты КП01–КП04 в колоду добычи припасов на полянах (если возможно).<br><b>Г. Зловещие создания рыскали в ночи. </b>Добавьте карты НК01–НК02 в колоду ночи.<br><b>Д. Сама земля изменилась. </b>Добавьте карты ПК01–ПК03 в колоду пути.</p><p>На новых картах добычи припасов появляется новый бонусный ресурс — живой коралл.</p>"},"repeatable":false},{"id":"outcomes-194","code":"194","description":{"en":"","ru":"<p><i><b>Что‑то тёмное мелькнуло в толще воды, и вы метнулись, чтобы схватить это. К вашему ужасу, нечто схватило вас в ответ и утащило под воду. С трудом вынырнув, вы увидели, как добыча уходит на глубину.</b></i></p><p>Проведите проверку <conviction>, чтобы схватить и удержать существо. +2, если вы <i>отважный</i>, +4, если у вас есть предмет для <i>рыбалки</i>, и +2, если у вас есть отметка <star>.</p><p><b>≥13:</b>  Вы удержали добычу и вытащили её из воды. Это была огромная рыба со сверкающей чешуёй. Получите 4 рыбы. Ваша община получает силу мантии «Речной охотник» (МА06).<br><b>1-12:</b>  Вы утратили решимость. Сбросьте все предметы, которые вы использовали для рыбалки.</p>"},"repeatable":false},{"id":"outcomes-195","code":"195","description":{"en":"","ru":"<p><i><b>Возведённые вами шпили пали, а стены разрушились. Коралловые побеги мягко колыхались среди руин некогда процветавших поселений, а выбеленные кости торчали из‑под обломков рухнувших домов. Гнев пробудившегося чудища подверг испытанию ваш народ — и тот не выдержал.</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о древней мести, включив в неё отметку коралла [i] и отметку бодрствующего чудища, украшенную отметкой гнева [ii]. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Смиритесь с тем, что ваша история будет погребена вместе с народом. </b>Ваша кампания завершилась, а община <b>исчезла</b>. См. раздел «Конец кампании» на с. <rulebook>97</rulebook> правил игры. <br>Такой конец хоть и далёк от счастливого, но он всё же может послужить уроком для народов, которые заселят эту долину в будущем. Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!<br>Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. <rulebook>97</rulebook> или раздел «Бесконечный режим» на с. <rulebook>102</rulebook>.<br><b>Б. Отправьтесь в путь, чтобы избежать гибели. </b>Добавьте карту «Исход» (ИЯ09) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<coral>"},{"label":"ii","image":"<wrath>"}]},{"id":"outcomes-196","code":"196","description":{"en":"","ru":"<p><i><b>Силой оружия и ценой пролитой крови вы заставили предводителей мятежа отказаться от своих планов, вынудили их выбрать — бежать или погибнуть. Без своих вождей недовольные люди бросили попытки покинуть свои земли. Ваши жестокие действия оставили след в истории вашего народа, и последствия могут отразиться на будущих поколениях.</b></i></p><p>Уберите <population><population><population><population>. Добавьте <unrest><unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о суровом суде, включив в неё отметку битвы [i] и отметку раскола [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<schism>"}]},{"id":"outcomes-197","code":"197","description":{"en":"","ru":"<p><i><b>Даже представляя угрозу для чудища, вы не могли постичь природу этого существа…</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><b><i>Какие неведомые вам тайны знало чудище? Вы принялись оглядываться, пытаясь заметить приближающуюся опасность...</i></b></p><p><b>Чудище, защитник. </b>Один из персонажей в походе должен провести состязание, чтобы найти безопасный путь: его <awareness> против <dexterity> чудища. +2, если персонаж <i>неукротимый</i>.<br><b>Успех. </b>Вы вели остальных, скрывая приближающуюся группу от взгляда чудища. Продолжите поход.<br><b>Провал.</b> Взгляд чудища упал на вас, и ваша воля ослабла. Уменьшите все свои <boost>. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy>, чтобы провести состязание ещё раз.</p><p><i><b>Снежная буря накрыла вас, когда вы приблизились к чудищу. Руки примёрзли к оружию, а ледяной воздух разрывал ваши лёгкие.</b></i></p><p><b>Чудище, группа,</b> погода. Все персонажи в походе должны провести состязание, чтобы не пострадать: <might> или <conviction> против <conviction> чудища. +2, если у персонажа есть <i>одежда</i>, +2, если у него есть предмет с  <fire>, и +2, если он <i>осторожный</i>.<br><b>Успех. </b>Вы продолжили двигаться вперёд, несмотря на трудности. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>Провал.</b> Холод отнимал у вас силы. Покиньте поход или получите <major_disease> и <minor_disease>, а также уменьшите все свои <boost>. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><b><i>Когда вы оказались достаточно близко к чудищу, чтобы прикоснуться, оно слегка отодвинулось, следя за вами. Вы надеялись, что найденный символ поможет победить это чудище, но добраться до его панциря, чтобы нарисовать там символ, будет непросто!</i></b></p><p><b>Чудище, защитник. </b>Один из персонажей в походе должен провести состязание, чтобы сразиться: его <dexterity> против <awareness> чудища. +2, если у персонажа есть <i>оружие</i>, и +4, если у персонажа есть <i>трофей</i>.<br><b>Успех. </b>Оружием вы вырезали символ на панцире. Завершите этот поход и достигните соответствующей цели.<br><b>Провал. </b>Вы покрылись снегом и льдом, и ваше оружие сломалось. Сбросьте 1 оружие, если возможно. Поход окончился неудачно, если только любой персонаж в походе не получит <major_disease><major_disease> или не потратит <lore>, чтобы провести состязание ещё раз. </p>"},"repeatable":false},{"id":"outcomes-199","code":"199","description":{"en":"","ru":"<p><i><b>В суете подготовки и подачи такого богатого угощения у вас едва ли было время оценить реакцию людей на еду. Но когда огонь начал затухать, а разговоры умолкли, вы заметили, что люди скребут дно котелков, чтобы достать остатки. К утру все только и говорили, что об изобильном пиршестве.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем добавьте <population><population><population> и уберите <unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о роскошном пиршестве, включив в неё отметку пира [i] и отметку изобилия [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<feast>"},{"label":"ii","image":"<plenty>"}]},{"id":"outcomes-200","code":"200","description":{"en":"","ru":"<p><i><b>Найдя жизненно важные ресурсы, создав инструменты и подготовив место для укрытия, ваш народ обосновался в долине. Но до вас долетали слухи о тени, что поглощает луну, облаках кружащейся пыли вдали и о странных завываниях, что разносятся эхом в высоких горах.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Добавьте карту «Пуская корни» (ИА02) к грядущим испытаниям. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Сосредоточьтесь на исследовании долины. </b>Как описано на с. <rulebook>69</rulebook> правил игры, на стене первобытной пещеры изобразите историю о новых горизонтах, включив в неё отметку прибытия [i], отметку тайны [ii] и отметку своего начального региона (например, Дивная долина [iii] или Поднебесная равнина [iv]). Затем каждый персонаж получает одну из следующих черт по выбору игрока: «любознательный» или «осторожный». В начале следующего испытания, после подготовки, поместите по 1 жетону тайны на любые два неисследованных участка местности (см. раздел «Жетоны тайн» в правилах игры на с. <rulebook>60</rulebook>).<br><b>Б. Приложите усилия, чтобы накопить припасы на зиму. </b>Добавьте <population><population>. Как описано на с. <rulebook>69</rulebook> правил игры, на стене первобытной пещеры изобразите историю о стойких путниках, включив в неё отметку прибытия [i], отметку изобилия [v] и отметку своего начального региона (например, Дивная долина [iii] или Поднебесная равнина [iv]). Затем каждый персонаж получает одну из следующих черт по выбору игрока: «удачливый» или «терпеливый».</p><p>Сделав выбор, завершите это испытание, следуя инструкциям раздела «Завершение испытания» в правилах игры на с. <rulebook>95</rulebook>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<arrival>"},{"label":"ii","image":"<mystery>"},{"label":"iii","image":"<verdantvale>"},{"label":"iv","image":"<skyreachplateau>"},{"label":"v","image":"<plenty>"}]},{"id":"outcomes-202","code":"202","description":{"en":"","ru":"<p><i><b>Успех великой охоты подарил вашим людям уверенность в завтрашнем дне, позволив им процветать, осваивая охотничьи тропы долины.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Сосредоточьтесь на лесах. </b>Если в долине есть хотя бы 1 участок Дивной долины, уберите <unrest><unrest><unrest> и добавьте <population>. Затем на стене первобытной пещеры изобразите историю о лесном следопыте, включив в неё отметку охотника [i], отметку изобилия [ii] и отметку Дивной долины [iii]. Добавьте карту ДЛ14 в колоду добычи припасов в лесу, если возможно.<br><b>Б. Сосредоточьтесь на степи. </b>Если в долине есть хотя бы 1 участок Поднебесной равнины, уберите <unrest><unrest><unrest> и добавьте <population>. Затем на стене первобытной пещеры изобразите историю об охотнике на золотую траву,  включив в неё отметку охотника [i], отметку изобилия [ii] и отметку Поднебесной равнины [iv]. Добавьте карту ДС14 в колоду добычи припасов в степи, если возможно.<br><b>В. Сосредоточьтесь на Сплетении. </b>Если в долине есть хотя бы 1 участок Сплетения (и этот регион доступен), уберите <unrest><unrest><unrest> и добавьте <population>. Затем на стене первобытной пещеры изобразите историю об охотнике в тенях, включив в неё отметку охотника [i], отметку изобилия [ii] и отметку Сплетения [v]. Добавьте карту ДП14 в колоду добычи припасов на полянах.<br><b>Г. Кто зовёт себя охотником — пусть ест мясо, а не землю. </b>Добавьте <population><population><population>. На стене первобытной пещеры изобразите историю о славе охотника, включив в неё отметку охотника [i], отметку изобилия [ii] и отметку табу [vi]. Запишите «Есть коренья ночью» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет. Добавьте отметку охотника на сторону легенды карты каждого персонажа. Затем разыграйте как можно больше из следующего:<br><b>1.</b> Если в долине есть хотя бы 1 участок Дивной долины, добавьте карту ДЛ14 в колоду добычи припасов в лесу.<br><b>2.</b> Если в долине есть хотя бы 1 участок Поднебесной равнины, добавьте карту ДС14 в колоду добычи припасов в степи.<br><b>3.</b> Если в долине есть хотя бы 1 участок Сплетения (и этот регион доступен), добавьте карту ДП14 в колоду добычи припасов на полянах.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<hunter>"},{"label":"ii","image":"<plenty>"},{"label":"iii","image":"<verdantvale>"},{"label":"iv","image":"<skyreachplateau>"},{"label":"v","image":"<tangle>"}]},{"id":"outcomes-209","code":"209","description":{"en":"","ru":"<p><i><b>Сквозь клубы облаков, в вышине над горами, проступила земля.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Вам открылся совершенно новый вид на знакомые земли. </b>Если на стене первобытной пещеры есть отметка Поднебесной равнины [i] или у вас нет ещё не помещённых основ местности, добавьте <lore><lore><lore>.<br><b>Б. Вы попали на землю, полную чудес. </b>Если на стене первобытной пещеры нет отметки Поднебесной равнины [i] и у вас есть хотя бы 1 ещё не помещённая основа местности, откройте этот регион. На стене первобытной пещеры изобразите историю о земле, касающейся облаков, включив в неё отметку Поднебесной равнины [i] и отметку открытия [ii]. Затем расширьте долину, пройдя описанные ниже этапы.</p><p><b>Этап 1. </b>Добавьте новую основу местности в долину. Поместите её по соседству с участком местности с вашим персонажем, если возможно. Границы основы должны соседствовать с как можно большим количеством границ уже размещённых основ. Если есть несколько возможных позиций, выберите одну случайным образом.<br><b>Этап 2. </b>Положите в мешочек все неразмещённые участки Поднебесной равнины, кроме начального, и перемешайте. Затем по одному вытащите 3 участка и поместите их неисследованной стороной вверх в ячейки новой основы по направлению с севера на юг и с востока на запад.<br><b>Этап 3 (только для эры 1 и бесконечного режима).</b> Если в запасе есть хотя бы 1 непомещённая накладка ледника, бросьте <1d6> и поместите ледники по результату броска: [1-2] один ледник в район А одного из участков местности без накладки, [3-4] один ледник в район Б одного из участков местности без накладки, [5] разыграйте результаты 1-2 и 3-4, [6] бросьте <1d6> ещё раз и прочитайте один из исходов ниже, соответствующий результату броска. <br>[1-3] <outcome> 846, [4-5] <outcome> 134, [6] <outcome> 446.<br><b>Этап 4.</b> Замешайте карты ПП01–ПП06 в колоду пути и карты НП01–НП03 в колоду ночи, если возможно.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<skyreachplateau>"},{"label":"ii","image":"<discovery>"}]},{"id":"outcomes-210","code":"210","description":{"en":"","ru":"<p><i><b>Существо обрушилось на вас, и бой вспыхнул с неистовой силой — трудно было понять, сколько длилась эта схватка…</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Вспомните время триумфа над зверем. </b>Если вы <i>мстительный </i>или у вас есть отметка зверобоя [i], вы одолели подземное существо и оно пало. Добавьте 3 дичи, 1 ракушку и 1 клык к своим наградам. Продолжите это действие спуска.<br><b>Б. Вспомните путь в подземелье. </b>Если вы <i>хитрый</i>, и у вас есть отметка подземного мира [ii] или «Карта», после недолгой борьбы вы скользнули в знакомый туннель и сбежали. Вы можете <exit> или продолжить это действие спуска.<br><b>В. Прогоните зверя. </b>После ожесточённой битвы существо отступило и скрылось в темноте. Потеряйте <energy> и получите <major_injury>. Продолжите это действие спуска.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<beastslayer>"},{"label":"ii","image":"<underworld>"}]},{"id":"outcomes-211","code":"211","description":{"en":"","ru":"<p><i><b>Вы вернулись на поверхность, бережно прижимая к груди хрупкий гриб. В последующие дни вы доставили его во все свои поселения — и недуг, терзавший ваш народ, постепенно отступил.</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о милосердии грота, включив в неё отметку чумы [i] и отметку подземного мира [ii]. Ваша община получает силу мантии «Лекарь» (МА14).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<plague>"},{"label":"ii","image":"<underworld>"}]},{"id":"outcomes-212","code":"212","description":{"en":"","ru":"<p><i><b>Вы сделали ещё один шаг и неожиданно погрузились на глубину. Течение подхватило вас, унося по подземным потокам, которые, должно быть, пролегали под долиной. Из бурной воды перед вами появился камень, затем всё потемнело. Когда вы очнулись, начало смеркаться, голова болела, но над вами простиралось небо.</b></i></p><p>Получите <major_injury> и потеряйте <energy><energy>. Завершите это действие спуска и потеряйте все полученные награды. Поместите своего персонажа на любой участок местности, выбрав участок с озером, рекой или болотом, если возможно.</p>"},"repeatable":false},{"id":"outcomes-214","code":"214","description":{"en":"","ru":"<p><i><b>Путь к кратеру просто не мог быть лёгким...</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Подкрадитесь к кратеру незаметно. </b>Если у общины есть табу, которое активируется в месте падения, то <outcome> 502. <br><b>Б. Подойдите к кратеру открыто. </b> <outcome> 622.</p>"},"repeatable":false},{"id":"outcomes-218","code":"218","description":{"en":"","ru":"<p><i><b>От туши исходила такая невыносимая вонь, что у вас закружилась голова и вам пришлось опереться на останки, чтобы устоять на ногах. Но рука скользнула по вязкой жидкости, которая сочилась из трупа. </b></i></p>Получите <major_disease><minor_disease>. Если на стене первобытной пещеры есть отметка чумы, добавьте <lore>. В противном случае добавьте карту «Мор» (ИЯ03) к грядущим испытаниям.<p></p>"},"repeatable":false,"marks":[{"label":"","image":"<plague>"}]},{"id":"outcomes-219","code":"219","description":{"en":"","ru":"<p><i><b>Мерцающие туманы, покрывающие долину, порой обманывали ваши чувства. Вы всмотрелись в туман и увидели...</b></i></p><p>Разыграйте первое, что можете:<br><b>А. …необычную границу местности. </b>Если исследуемый вами участок местности граничит с другим регионом, в котором есть хотя бы один неисследованный участок местности, поменяйте местами участок, который вы исследуете, и любой неисследованный участок из того региона. Если это условие возможно для нескольких регионов, выберите один из них.<br><b>Б. …изменившийся ландшафт. </b>Если есть хотя бы 2 ещё не помещённых участка местности (кроме начального), принадлежащих тому же региону, что и исследуемый вами участок, выберите случайный участок из непомещённых и замените им участок местности, который вы исследуете.<br><b>В. …загадочное происшествие. </b>Поместите жетон тайны на исследуемый вами участок местности и немедленно разгадайте тайну.</p>"},"repeatable":false},{"id":"outcomes-222","code":"222","description":{"en":"","ru":"<p><i><b>На дне озера вы потянулись к странной жидкости. Несмотря на воду вокруг, она оставалась отделённой, словно её удерживала невидимая рука.</b></i></p><p>Проведите проверку <conviction>, чтобы дотянуться до жидкости. +2, если вы <i>сосредоточенный</i>, и +4, если у вас есть отметка лунной крови.<br><b>≥11:</b>  Вы решительно зачерпнули жидкость рукой и собрали её. Получите 2 лунные крови.<br><b>8-10:</b>  Жидкость ускользала, и вы ощутили, как пальцы начинают неметь. Получите 1 лунную кровь. Получите <minor_injury>. <br><b>1-7:</b>  Вы вздрогнули, когда жидкость сомкнулась вокруг вас, утаскивая всё глубже и глубже. <outcome> 899.</p>"},"repeatable":false,"marks":[{"label":"","image":"<moonblood>"}]},{"id":"outcomes-223","code":"223","description":{"en":"","ru":"<p><i><b>В подземном озере нечто схватило вас за ногу и потянуло на глубину.</b></i></p><p>Проведите проверку <might>, чтобы вырваться. +2, если вы <i>хитрый</i>, и +4, если у вас есть отметка зверобоя.<br><b>≥12:</b>  Вы вырвались из лап существа. Продолжите это действие спуска. Добавьте <lore><lore>.<br><b>6-11:</b>  Вас унесло подземным течением, и в конце концов вы выбрались на берег реки неподалёку. Завершите это действие спуска. Поместите своего персонажа на случайный участок местности в регионе, где вы начали спуск. Выберите участок с озером, рекой или болотом, если возможно.<br><b>1-5:</b>  Разыграйте исход как при [6-11], затем получите <major_injury>.</p>"},"repeatable":false,"marks":[{"label":"","image":"<beastslayer>"}]},{"id":"outcomes-224","code":"224","description":{"en":"","ru":"<p><i><b>Шли годы, и символ, что вы избрали для своего народа, стал неотделим от вашего имени. Он был зна́ком дружелюбия на землях, где вы часто бывали, и приметой того, что дом близко, среди диких просторов. Под этим счастливым знаком вы ощущали покой и благосклонность судьбы.</b></i></p><p>Уберите <unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о найденном символе, включив в неё отметку знамения, изображённую на жетоне тайны на карте цели «Сотворите миф» (ЦБ10). Ваша община получает силу мантии «Ткач преданий» (МА12).</p>"},"repeatable":false},{"id":"outcomes-227","code":"227","description":{"en":"","ru":"<p><i><b>Следуя за мерцающей звездой, вы нашли путь в ещё не исследованный уголок долины.</b></i></p><p>На стене первобытной пещеры изобразите историю о пути, проложенном звёздами, включив в неё отметку своего текущего региона, отметку открытия и отметку <star>. Затем расширьте долину, пройдя описанные ниже этапы.</p><p><b>Этап 1. </b>Добавьте новую основу местности в долину. Поместите её по соседству с участком местности с вашим персонажем, если возможно. Границы основы должны соседствовать с как можно большим количеством границ уже размещённых основ. Если есть несколько возможных позиций, выберите одну случайным образом. <br><b>Этап 2. </b>Положите в мешочек все неразмещённые участки местности региона, в котором вы находитесь, кроме начального, и перемешайте. Затем по одному вытащите 3 участка и поместите их неисследованной стороной вверх в ячейки новой основы по направлению с севера на юг и с востока на запад.<br><b>Этап 3 (только для эры 1 и бесконечного режима).</b> Если в запасе есть хотя бы 1 непомещённая накладка ледника, бросьте <1d6> и поместите ледники по результату броска: [1-2] один ледник в район А одного из участков местности без накладки, [3-4] один ледник в район Б одного из участков местности без накладки, [5] разыграйте результаты [1-2] и [3-4], [6] бросьте <1d6> ещё раз и прочитайте один из исходов ниже, соответствующий результату броска.<br>[1-3] <outcome> 846, [4-5] <outcome> 134, [6] <outcome> 446.</p><p>Наконец, верните в коробку карту «Ярчайшая из искр» (ПН03).</p>"},"repeatable":false,"marks":[{"label":"","image":"<discovery>"}]},{"id":"outcomes-228","code":"228","description":{"en":"","ru":"<p><i><b>Вы пробрались через ледяную землю, чтобы обнаружить... </b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><i><b>Логово чудища было обрывом с крутыми краями и уходило глубоко в ледяную землю. Вам нужно было спуститься, расчищая себе путь.</b></i></p><p><b>Защитник, угроза. </b>Один из персонажей в походе должен провести проверку <dexterity>, чтобы расчистить путь. +2, если у персонажа есть <stoneworking>, и +2 за каждый предмет для <i>исследования </i>у этого персонажа.<br><b>≥10:</b>  Вы проложили безопасный путь для других. Продолжите поход.<br><b>1-9:</b>  Ожидая на краю бездны, все замёрзли. Каждый персонаж уменьшает одно из своих усилений. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy>, чтобы провести проверку ещё раз.</p><p><b><i>Тусклые синие туманы вились вокруг вас. Ледяной спуск становился всё холоднее, и воздух казался камнями в лёгких. </i></b></p><p><b>Группа, погода. </b>Все персонажи в походе должны провести проверку <might> или <conviction>, чтобы выдержать холод. +2, если у персонажа есть предмет с <fire>, и +2, если у него есть <i>одежда</i>.<br><b>≥10:</b>  Вы справились с холодом тумана. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-9: </b> Вы начали замерзать. Получите <major_injury><major_injury>, если не уменьшите все свои усиления. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><i><b>На дне расселины вы нашли странный знак. Он мерцал и менялся, перетекая из одной формы в другую — и тогда вы поняли: перед вами сама сущность чудища. В этом знаке была заключена сила, способная обратить чудище в прах… если найдётся тот, кто сумеет его воспроизвести.</b></i></p><p><b>Чудище, защитник. </b>Один из персонажей в походе должен провести проверку <awareness>, чтобы изучить знак. +4, если в журнале записан хотя бы один секрет этого чудища.<br><b>≥10:</b>  Изменчивость линий была подобна танцу теней в свете костра, однако вы сумели удержать символ в своём сознании. Завершите этот поход и достигните соответствующей цели.<br><b>1-9:</b>  У вас задёргался глаз, и вы заметили струйку крови, стекающую из носа. Знак, извиваясь, с боем вырвался из вашего разума, прежде чем вы успели его запомнить. Получите <major_injury>, если только не уменьшите усиление. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-229","code":"229","description":{"en":"","ru":"<p><i><b>Коралл оставался чем‑то непостижимым. Боялись ли вы его, ненавидели или презирали — ваш разум был не в силах его воспринять. Он распространился по долине подобно приливу, унося ваших людей с земель их предков, не заботясь о вашем мимолётном существовании.</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о непостижимом знаке, включив в неё отметку <comet>, отметку несчастья [i] и отметку Звёздного моря [ii].<br>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Смиритесь с тем, что ваша цивилизация исчезнет, и вы вместе с ней.</b> Завершите кампанию. Ваша община <b>исчезла</b>. См. раздел «Конец кампании» в правилах игры на с. <rulebook>97</rulebook>. Такой конец хоть и далёк от счастливого, но он всё же может послужить уроком для народов, которые заселят эту долину в будущем. Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!<br>Чтобы продолжить играть в  «Наскальную историю», см.  в  правилах игры раздел «Начало следующих кампаний» на с. <rulebook>97</rulebook> или раздел «Бесконечный режим» на с. <rulebook>102</rulebook>.<br><b>Б. Сражайтесь за выживание из последних сил.</b> Добавьте карту «Исход» (ИЯ09) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<misfortune>"},{"label":"ii","image":"<starlitsea>"},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-231","code":"231","description":{"en":"","ru":"<p><i><b>С годами величественные растения Сплетения увяли, его водные пути заросли илом, а могучие лианы стали разлагаться. В самом сердце этих джунглей поселилась гниль, постепенно поглощая их жизненную силу. </b></i></p><p>Каждое поселение в регионе Сплетения становится руинами. Уберите <population><population> за каждое поселение, которое стало руинами таким образом. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Запретите надолго оставаться в Сплетении. </b>Запишите «Отдых на участке местности в Сплетении» в  раздел «Табу» на странице «Культура» в  журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет. Добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю о запретной долине, включив в неё отметку табу [i] и отметку Сплетения [ii].<br><b>Б. Осмельтесь столкнуться с расползающейся гнилью. </b>Уберите <population><population><population>. На стене первобытной пещеры изобразите историю о распространяющемся разложении, включив в неё от метку чумы [iii] и отметку Сплетения [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<taboo>"},{"label":"ii","image":"<tangle>"},{"label":"iii","image":"<plague>"}]},{"id":"outcomes-234","code":"234","description":{"en":"","ru":"<p><i><b>На окраине одного из поселений вы услышали крики ужаса и увидели, как жители спасаются бегством. Коралловый защитник шагал к деревне. Только вы могли преградить ему путь.</b></i></p><p>Проведите состязание, чтобы сразиться: ваша <conviction> против <dexterity> кораллового защитника. +2 к вашему результату, если у вас есть предмет <i>лунной крови</i>. +4 к результату кораллового защитника за каждый соседний участок местности с активными коралловыми зарослями.<br><b>Успех. </b>Вы сцепились с коралловым защитником, уводя его подальше от поселения. Когда вы швырнули его обратно в заросли, коралловые ветви обвили его, утаскивая в безопасное место. Добавьте <major_boost> к <awareness>.<br><b>Провал. </b>Ваша кожа, сожжённая спорами, которые окружали плоть кораллового защитника, начала гореть и пузыриться. Получите <major_disease>,<major_injury>  и <minor_injury>.</p>"},"repeatable":false},{"id":"outcomes-235","code":"235","description":{"en":"","ru":"<p><i><b>Вы увидели мелких насекомых — это их стрекотание издалека можно было принять за речь. Эти покрытые панцирями существа были хороши на вкус, но вы также знали, что они часто прячут среди корней кустарников занятные вещицы.</b></i></p><p>Разыграйте одно:<br><b>А. Вы нашли большой кусок мяса, который, казалось, всё ещё был съедобен.</b> Получите 2 дичи. <br><b>Б. Вы нашли клубок растительных волокон.</b> Получите 2 волокна.<br><b>В. Вы нашли осколок зуба хищника.</b> Получите 1 клык.</p>"},"repeatable":false},{"id":"outcomes-236","code":"236","description":{"en":"","ru":"<p><i><b>В темноте воздух становился удушающим, и ваши чувства начали затуманиваться. Вы тряхнули головой и ощутили острую боль. Вы не могли оставаться здесь.</b></i></p><p>Проведите проверку <awareness>, чтобы найти путь в безопасное место. +2, если вы <i>удачливый</i>, и +2, если у вас есть отметка подземного мира.<br><b>≥12:</b>  Вам удалось благополучно покинуть пещеру. Получите <lore>.<br><b>8-11:</b>  Кашляя и задыхаясь, вы всё же смогли выбраться из пещеры. Получите <minor_disease>.<br><b>1-7:</b>  Вы заблудились, и в конце концов тьма пещеры завладела вами. Вы пришли в себя вдалеке от пещеры, в окружении странных следов на песке. Получите <major_disease> и <minor_disease>. Сбегите. Поместите жетон тайны на участок местности, с которого вы сбежали.</p>"},"repeatable":false,"marks":[{"label":"","image":"<underworld>"}]},{"id":"outcomes-237","code":"237","description":{"en":"","ru":"<p><i><b>Разбираясь в причинах конфликта, вы выяснили, с чего всё началось. Хищник убил жителя вашей деревни. Одни пришли к выводу, что этих существ необходимо истребить. Другие сочли их священными — ведь звери испытывали на прочность решимость вашего народа остаться в этом суровом краю.</b></i></p><p>Совместно выберите один из следующих путей развития общины:<br><b>А. Объявите охоту на хищников. </b>Добавьте <population><population>. На стене первобытной пещеры изобразите историю об истреблении, включив в неё отметку зверобоя [i]. Разыграйте как можно больше из следующего:<br>1. Если в долине есть хотя бы 1 участок местности Дивной долины, добавьте карту ДЛ14 в колоду добычи припасов в лесу.<br>2. Если в долине есть хотя бы 1 участок местности Поднебесной равнины, добавьте карту ДС14 в колоду добычи припасов в степи.<br>3. Если в долине есть хотя бы 1 участок местности Сплетения (и этот регион доступен), добавьте карту ДП14 в колоду добычи припасов на полянах.<br><b>Б. Подчеркните значимость этих существ для вашей культуры.</b> Добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю о священных зверях, включив в неё отметку осторожности [ii] и отметку охотника [iii]. Запишите «Сражение с хищником на участке без поселения» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<beastslayer>"},{"label":"ii","image":"<caution>"},{"label":"iii","image":"<hunter>"}]},{"id":"outcomes-238","code":"238","description":{"en":"","ru":"<p><i><b>Изучив коралл, вы сделали важное открытие, которое помогло бы защитить ваш народ. Споры коралла обжигали лёгкие тех, кто их вдыхал, но кристаллы лунной крови обеспечивали какую‑никакую защиту. Облака спор расступились, когда вы приблизились.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем добавьте 5 <unrest>. На стене первобытной пещеры изобразите историю о странном целебном средстве, включив в неё отметку коралла [i] и отметку лунной крови [ii]. Добавьте карту «Падение небес» (ИВ04) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<coral>"},{"label":"ii","image":"<moonblood>"}]},{"id":"outcomes-239","code":"239","description":{"en":"","ru":"<p><i><b>Лёд проломился, и вы рухнули в сияющую холодную воду. Погружаясь в бездну, вы успели заметить, что жидкость мерцает, словно лунный свет...</b></i></p><p>Добавьте отметку лунной крови на сторону легенды своего персонажа, затем верните в коробку карту своего персонажа. Создайте нового персонажа, как если бы прежний умер. Верните в коробку карту «Проход в подземелье» (ПН10) и добавьте карту «Облик на глубине» (ПЗ02) в колоду пути.</p>"},"repeatable":false,"marks":[{"label":"","image":"<moonblood>"}]},{"id":"outcomes-244","code":"244","description":{"en":"","ru":"<p><i><b>Ваш отчаянный побег через перевал увенчался успехом как раз, когда зубы зимы вгрызлись в долину. Нельзя было сказать, куда этот путь приведёт ваш народ. Но ваши потомки выживут, и их история продолжится на этой земле, за пределами долины ваших предков. Возможно, когда‑нибудь они вернутся в долину, чтобы попытать свои силы в её испытаниях.</b></i></p><p>На стене первобытной пещеры изобразите историю об исходе, включив в неё отметку исхода. Завершите кампанию. Ваша община <b>исчезла</b>. См. раздел «Конец кампании» в правилах игры на с. <rulebook>97</rulebook>.<br>Однако не вся надежда утрачена, поскольку знания, добытые вашим народом, передаются новым поколениям! Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. <rulebook>97</rulebook> или раздел «Бесконечный режим» на с. <rulebook>102</rulebook>.<br>Когда вы начнёте новую кампанию, можете добавить любое количество забытых карт легенд в свою новую общину в качестве легенд. Вы также можете перенести любые сведения со страниц «Культура» и «Рецепты» из старого журнала в новый.</p>"},"repeatable":false,"marks":[{"label":"","image":"<exodus>"}]},{"id":"outcomes-245","code":"245","description":{"en":"","ru":"<p><i><b>Среди вашего народа зародился культ почитателей чудища как вестника космических сил, лежащих в основе мироздания. Кто‑то видел в нём голос предков, кто‑то — дыхание творца, кто‑то — равновесие звёзд. Ваши люди стали считать чудище проводником этой силы и верили, что умиротворить его значит сохранить порядок вещей. Вам предстояло принять собственное решение по этому поводу.</b></i></p><p>Завершите текущее испытание.</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Присоединитесь к растущему движению.</b> Уберите <unrest><unrest>. На стене первобытной пещеры изобразите историю о космическом проводнике, включив в неё отметку бодрствующего чудища, заключённую в отметку связи [i]. Ваша община получает силу мантии «Говорящий с чудищами» (MA18).<br><b>Б. Выступите за свободный выбор пути. </b>Добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю о множестве путей, включив в неё отметку бодрствующего чудища, отметку посредника [ii] и отметку летописца [iii].<br><b>В. Изгоните последователей чудища. </b>Добавьте <unrest><unrest><unrest> и уберите <population><population><population><population>. На стене первобытной пещеры изобразите историю о вере, преданной забвению, включив в неё отметку бодрствующего чудища, отметку раскола [iv] и отметку гнева [v].</p><p>Завершите текущую эру. См. с. 196, чтобы <era2>начать эру 2</era2>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<bond>"},{"label":"ii","image":"<mediator>"},{"label":"iii","image":"<scribe>"},{"label":"iv","image":"<schism>"},{"label":"v","image":"<wrath>"}]},{"id":"outcomes-248","code":"248","description":{"en":"","ru":"<p><i><b>С яростью, рождённой множеством мелких ран, чудище обрушилось на ваши поселения. Оно растоптало деревянные и каменные постройки, будто они были из хвороста и песка. Отомстив, оно ушло, оставив вашу общину в руинах.</b></i></p><p>Завершите текущее испытание. На стене первобытной пещеры изобразите историю о мести, включив в неё отметку бодрствующего чудища, украшенную отметкой гнева [i]. Уберите 5 <population>. В каждом из своих поселений случайным образом выберите два сооружения и разрушьте их.</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Поклянитесь отомстить. </b>Каждый персонаж получает черту «мстительный». Добавьте карту «Преодоление вечности» (ИБ08) к грядущим испытаниям.<br><b>Б. Смиритесь с наказанием чудища. </b>Каждый персонаж получает черту «терпеливый». Добавьте карту «Единое видение» (ИБ07) к грядущим испытаниям.<br><b>В. Найдите укрытие в тёмных недрах под могучей поступью чудища. </b>Если на стене первобытной пещеры есть отметка подземного мира [ii], добавьте карту «Странники подземелий» (ИБ09) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<wrath>"},{"label":"ii","image":"<underworld>"}]},{"id":"outcomes-249","code":"249","description":{"en":"","ru":"<p><i><b>Ваши мышцы горели, тело разрывалось — но вы повалили кораллового защитника. Он попытался подняться, но вы собрали остаток сил и метнулись вперёд, нанося последний удар. Коралловое сердце в его груди затрепетало — и раскололось. По долине прокатился звон. Коралловые поля отозвались на этот звук — и затихли, превращаясь в мёртвые серые стебли. Тело кораллового защитника постигла та же участь: оно окаменело, став странным памятником этому дню.</b></i></p><p><b><i>Следующие годы были благоприятны для вашего народа, и вы смогли заселить всю долину. Однако Скиталец по‑прежнему пылал над головами, и ваши потомки всё чаще задумывались, какие ужасы он всё ещё может принести...</i></b></p><p>Добавьте <population><population><population> и уберите <unrest><unrest><unrest>. Переверните все коралловые заросли неактивной стороной вверх.</p><p>На стене первобытной пещеры изобразите историю о падении кораллового защитника, включив в неё отметку <comet>, отметку битвы [i] и отметку коралла, заключённую в отметку окончания [ii]. Ваша община <b>выжила</b>.<br>Поздравляем! Вы завершили кампанию «Наскальной истории»! Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!</p><p>Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. <rulebook>97</rulebook> или раздел «Бесконечный режим» на с. <rulebook>102</rulebook>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":{"image":"<conclusion>","overlay":{"image":"<coral>","size":0.85,"x":3,"y":5,"rotate":0}}},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-255","code":"255","description":{"en":"","ru":"<p><i><b>Вы сражались с двойником не один час, и никто не мог одержать верх. Наконец, схватив камень, вы ударили им своего противника и отправили в беспамятство. Потеряв сознание от изнеможения, вы очнулись в одиночестве. Что это было за существо? Кто вы?.. Который из вас?</b></i></p><p>Потеряйте <energy><energy>. По очереди, для каждой из характеристик своего персонажа, бросьте <1d6>, затем навсегда измените значение этой характеристики на результат броска. После одного из таких бросков можете перевернуть <1d6> на противоположную грань перед тем, как записать новое значение характеристики. На стене первобытной пещеры изобразите историю о неизвестном, включив в неё отметку тайны. Затем верните в коробку карту «Иной» (ПН08).</p>"},"repeatable":false,"marks":[{"label":"","image":"<mystery>"}]},{"id":"outcomes-268","code":"268","description":{"en":"","ru":"<p><i><b>То, что поначалу выглядело как обычная драка, оказалось организованным нападением — и целью были вы! Вам предстояло сразиться за свою жизнь. </b></i></p><p>Проведите проверку <might> или <dexterity>, чтобы сразиться. +2 за каждое <i>оружие</i>, находящееся в вашей <hand>, и +2, если вы <i>мстительный</i>. <br><b>≥10:</b>  Вы вырвались! Сбегите на соседний участок местности.<br><b>6-9:</b>  Вам с трудом удалось вырваться. Получите <major_injury>.<br><b>1-5:</b>  Вы получили тяжёлые раны в бою. Получите <major_injury><major_injury><minor_injury>.</p><p>Затем добавьте карту «Переживите опасные налёты» (ЦЯ26) к целям.</p>"},"repeatable":false},{"id":"outcomes-274","code":"274","description":{"en":"","ru":"<p><i><b>Охота обернулась дурным знамением, и эта неудача тревожила сердца вашего народа. Однако эту оплошность ещё можно было исправить — обряд великой охоты продолжался.</b></i></p><p>Добавьте <unrest><unrest>. Каждый персонаж уменьшает все свои <boost> один раз. На стене первобытной пещеры изобразите историю о недобром обряде, включив в неё отметку охотника [i] и отметку несчастья [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<hunter>"},{"label":"ii","image":"<misfortune>"}]},{"id":"outcomes-276","code":"276","description":{"en":"","ru":"<p><i><b>Вашему народу не удалось превзойти охотников с севера, и в последующие годы эти хищники продолжали теснить вас.</b></i></p><p>Завершите текущее испытание.</p><p>Уберите <population> и добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю о ледяных клыках, включив в неё отметку ужаса. Добавьте карту «Царство хищника» (ПН06) в колоду пути, если возможно.</p>"},"repeatable":false,"marks":[{"label":"","image":"<harrowing>"}]},{"id":"outcomes-279","code":"279","description":{"en":"","ru":"<p><i><b>Какие бы секреты ни хранило это чудище, они мирно покоились в его могиле. Вы нашли артефакт его былой мощи.</b></i></p><p>Завершите текущее испытание.</p><p>Получите 1 сокровище этого чудища. На стене первобытной пещеры изобразите историю о древней мистической силе, включив в неё отметку этого чудища, украшенную отметкой тайны.</p>"},"repeatable":false,"marks":[{"label":"","image":"<mystery>"}]},{"id":"outcomes-283","code":"283","description":{"en":"","ru":"<p><i><b>Вы наконец‑то выбрались из реки в месте, где ваш народ никогда прежде не бывал…</b></i></p><p>На стене первобытной пещеры изобразите историю об объятиях реки, включив в неё отметку текущего региона и отметку <star>. Затем расширьте долину, пройдя описанные ниже этапы.<br><b>Этап 1. </b>Добавьте новую основу местности в долину. Поместите её по соседству с участком местности со своим персонажем, если возможно. Границы основы должны соседствовать с как можно большим количеством границ уже размещённых основ. Если есть несколько возможных позиций, выберите одну случайным образом.<br><b>Этап 2. </b>Положите в мешочек все неразмещённые участки местности региона, в котором вы находитесь, и перемешайте. Затем по одному вытащите 3 участка и поместите их неисследованной стороной вверх в ячейки новой основы по направлению с севера на юг и с востока на запад.<br><b>Этап 3 (только для эры 1 и бесконечного режима). </b> Если в запасе есть хотя бы 1 непомещённая накладка ледника,  бросьте <1d6> и поместите ледники по результату броска: [1-2] один ледник в район А одного из участков местности без накладки, [3-4] один ледник в район Б одного из участков местности без накладки, [5] разыграйте результаты 1-2 и 3-4, [6] бросьте <1d6> ещё раз и прочитайте один из исходов ниже, соответствующий результату броска.<br>[1-3] <outcome> 846, [4-5] <outcome> 134, [6] <outcome> 446.</p><p>Затем поместите своего персонажа на случайный участок в только что помещённой основе и исследуйте его.</p>"},"repeatable":false},{"id":"outcomes-287","code":"287","description":{"en":"","ru":"<p><i><b>Эти спокойные дни дали вам возможность подготовиться к суровым зимам, что непременно наступят вновь.</b></i></p><p>Совместно выберите один из следующих путей развития общины:<br><b>А. Накопите ресурсы.</b> Добавьте карту «Соберите припасы» (ЦА03) к целям.<br><b>Б. Вырастите злаки. </b>Добавьте карту «Измените ландшафт» (ЦА16) к целям. Достигнув её, на стене первобытной пещеры изобразите историю о возделывании, включив в неё отметку возделывания [i].<br><b>В. Посейте семена грядущего урожая. </b>Если на стене первобытной пещеры есть отметка возделывания [i], добавьте карту «Вспашите поле» (ЦБ06) к целям.<br><b>Г. Взрастите общую культуру. </b>Если на стене первобытной пещеры есть отметка песнопевца [ii] или летописца [iii], добавьте карту «Отыщите символ» (ЦБ09) к целям.<br><b>Д. Возведите великую цитадель. </b>Если на стене первобытной пещеры есть отметка возделывания [i], добавьте карту «Разровняйте землю» (ЦБ14) к целям.<br><b>Е. Отправьтесь на поиски пути к Звёздному морю. </b>Если на стене первобытной пещеры есть отметка Звёздного моря [iv], добавьте карту «Исследуйте тайну луны» (ЦЯ13) к целям. <br><b>Ж. Исследуйте скрытый мир. </b>Если на стене первобытной пещеры есть отметка подземного мира [v], добавьте карту «Отправьтесь в путешествие к теням» (ЦЯ23) к целям.</p><p>Затем можете потратить 6 <lore>, чтобы выбрать и разыграть другой эффект из этого списка. Повторите это сколько угодно раз.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<cultivation>"},{"label":"ii","image":"<songweaver>"},{"label":"iii","image":"<scribe>"},{"label":"iv","image":"<starlitsea>"},{"label":"v","image":"<underworld>"}]},{"id":"outcomes-290","code":"290","description":{"en":"","ru":"<p><i><b>Внезапная гроза сделала пребывание на равнине крайне опасным!</b></i></p><p>Проведите проверку <awareness>, чтобы угадать путь молнии. +2, если вы <i>сосредоточенный</i>, и +2, если у вас есть «Карта».<br><b>≥12:</b>  Вы помчались к небольшой рытвине, замеченной ранее, и с изумлением наблюдали, как ярость небес обрушивается на землю вокруг вас. Поместите <fire> на свой участок местности.<br><b>8-11:</b>  Вы почувствовали, как вокруг сгущается электричество, и бросились ничком на землю. Получите <minor_injury>.<br><b>1-7:</b>  Рядом с вами ударила молния. Получите <major_injury><major_injury>.</p>"},"repeatable":false},{"id":"outcomes-291","code":"291","description":{"en":"","ru":"<p><i><b>Чрезмерная охота разорила звериные тропы в землях, где жил ваш народ. Добычи становилось всё меньше, и животные не успевали размножиться. Перед вашей общиной встал трудный выбор…</b></i></p><p>Совместно выберите один из следующих путей развития общины:<br><b>А. Продолжите охотиться несмотря на трудности.</b> Уберите <population><population><population>. Разыграйте как можно больше из следующего:<br>1. Если в долине есть хотя бы 1 участок Дивной долины, верните в коробку карту ДЛ03 из колоды добычи припасов в лесу.<br>2. Если в долине есть хотя бы 1 участок Поднебесной равнины, верните в коробку карту ДС09 из колоды добычи припасов в степи.<br>3. Если в долине есть хотя бы 1 участок Ураганных холмов, верните в коробку карту ДД04 из колоды добычи припасов в джунглях.<br>4. Если в долине есть хотя бы 1 участок Сплетения (и этот регион доступен), верните в коробку карту ДП04 из колоды добычи припасов на полянах.<br><b>Б. Ограничьте убийство диких животных. </b>Добавьте <unrest><unrest>.<br><b>В. Пересмотрите прежние взгляды на питание. </b>Если у вас есть табу на поедание растений (злаки, орехи или коренья), зачеркните или сотрите это табу и добавьте <unrest><unrest><unrest>.</p>"},"repeatable":false},{"id":"outcomes-292","code":"292","description":{"en":"","ru":"<p><i><b>Вражда нарастала. Повсюду случались стычки. Вы понимали, что если не принять немедленных мер, община расколется у самого основания.</b></i></p><p>Если уровень <unrest> 6 или ниже, он становится равным 7. Если в эту эру вы ещё не достигли цели «Погасите искры» (ЦЯ21), добавьте её к целям. В противном случае уберите <population><population>.</p>"},"repeatable":false},{"id":"outcomes-293","code":"293","description":{"en":"","ru":"<p><i><b>Оглушённое чудище обрушилось на землю. Его каменный лик казался лишённым человеческих чувств, но глухой гул, исходящий от него, звучал почти как печаль. Вы поняли, что не способны убить такое создание — как бы ни были горьки прежние схватки. Несколько ударов сердца вы выжидали, пока чудище решит, что делать дальше. Наконец, с трудом поднявшись, оно не стало нападать снова — лишь тяжело застонало и вернулось в своё логово.</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest><unrest><unrest>. Установите значение нрава бодрствующего чудища на «2». На стене первобытной пещеры изобразите историю о разомкнутом круге, включив в неё отметку бодрствующего чудища, отметку осторожности [i] и отметку становления [ii].<br>Навсегда увеличьте <conviction> и <awareness>  каждого персонажа, участвовавшего в этом походе на момент его завершения, на 1 (не более чем до 7). Добавьте отметку бодрствующего чудища и отметку становления [ii] на сторону легенды карты каждого из этих персонажей.</p><p>Затем завершите эру. См. с. 204, чтобы <era3>начать эру 3</era3>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":"<growth>"}]},{"id":"outcomes-299","code":"299","description":{"en":"","ru":"<p><i><b>Раздвинув свисающие лианы, вы сделали первые шаги в густые влажные заросли. Сквозь необъятный полог благоухающих цветов просачивался рассеянный свет.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Проскользните в знакомую тень по нехоженому туннелю. </b>Если на стене первобытной пещеры есть отметка Сплетения, поместите своего персонажа на любой участок местности Сплетения, затем добавьте <lore><lore><lore>.<br><b>Б. Исследуйте этот регион громадных цветов. </b>Если у вас есть хотя бы 1 неразмещённая основа местности, на стене первобытной пещеры изобразите историю о парящих цветах, включив в неё отметку открытия [ii] и отметку Сплетения [i]. Добавьте карту «Под навесом» (ИЖ01) к грядущим испытаниям. Затем расширьте долину, пройдя описанные ниже этапы.<br><b>Этап 1. </b>Добавьте новую основу местности в долину. Поместите её по соседству с участком местности с вашим персонажем, если возможно. Границы основы должны соседствовать с как можно большим количеством границ уже размещённых основ. Если есть несколько возможных позиций, выберите одну случайным образом.<br><b>Этап 2.</b> Положите в мешочек все неразмещённые участки Сплетения, кроме начального, и перемешайте. Затем по одному вытащите 3 участка и поместите их неисследованной стороной вверх в ячейки новой основы по направлению с севера на юг и с востока на запад.<br><b>Этап 3.</b> Замешайте карты ПС01–ПС06 в колоду пути и карты НС01–НС03 в колоду ночи, если возможно.<br><b>В. Странные джунгли временно раскинулись в этих местах, открыв путь, который прежде преграждали горы. </b> Если у вас нет неразмещённых основ местности, поместите случайный участок Сплетения рядом со своим участком (не в ячейку основы  местности), а затем поместите своего персонажа на него. До конца текущего испытания считайте этот участок частью региона Сплетения (см. с. 4 правил дополнения «Природа зверя»). Завершив испытание, верните в коробку этот участок местности вместе с жетонами и накладками на нём. Персонажи, которые находились на убранном участке, умирают.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<tangle>"},{"label":"ii","image":"<discovery>"}]},{"id":"outcomes-300","code":"300","description":{"en":"","ru":"<p><i><b>Вы нанесли удар по голове чудища и пронзили его лоб своим отравленным оружием. На мгновение показалось, что существо не ощутило боли. Но затем яд начал действовать, и чудище рухнуло с оглушительным грохотом. Его исполинский лик покрылся трещинами, а из тела хлынула бурлящая слизь. Она растеклась и пропитала почву, превратив её в почерневшее месиво. В предсмертном всплеске ярости побеги чудища взметнулись из земли и обратили в пыль близлежащие постройки. Когда лианы стали ломкими настолько, что рассыпались, существо окончательно исчезло.</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о поверженном древнем существе, включив в неё отметку битвы [i] и отметку бодрствующего чудища, украшенную отметкой крови чудища [ii]. Добавьте отметку крови чудища [ii] на сторону легенды каждой карты персонажа, участвовавшего в походе. Один из персонажей, участвовавших в походе, должен сбросить оружие, если возможно. <br>Поместите логово бодрствующего чудища неактивной стороной вверх на участок местности с чудищем. Затем, если остались неразмещённые накладки скрученных отпечатков, поместите их на случайные участки местности, соседние с неактивным логовом чудища. Для каждого отпечатка бросьте <1d6>, чтобы поместить в соответствующий район: [1-2] А, [3-4] Б, [5-6] В. Если при этом вы должны поместить отпечаток в район с другой накладкой, замените её на скрученный отпечаток.</p><p>Затем завершите текущую эру. См. с. 204, чтобы <era3>начать эру 3</era3>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<behemothsblood>"}]},{"id":"outcomes-302","code":"302","description":{"en":"","ru":"<p><i><b>Любопытство и восхищение миром определяли воззрения вашего народа, и вы устремились к новым знаниям о долине, которую называли домом.</b></i></p><p>Совместно выберите один из следующих путей развития общины:<br><b>А. Исследуйте открытый регион. </b>Если у вас есть хотя бы 1 неразмещённая основа местности, и в долине есть хотя бы 1 регион с 3 размещёнными и 3 неразмещёнными участками, выберите 1 из таких регионов. Добавьте 1 новую основу местности в долину так, чтобы она соприкасалась с выбранным регионом как можно большим количеством сторон. Затем возьмите 3 случайных участка этого региона и поместите их неисследованной стороной вверх в пустые ячейки новой основы местности по направлению с севера на юг и с востока на запад.<br><b>Б. Бросьте вызов ледяным стенам. </b>Если в долине нет накладки ледяного купола (ОБ01а), добавьте карту «Пройдите по ледяному покрову» (ЦA06) к целям.<br><b>В. Изучите знамения. </b>Добавьте карту «Прочтите, что начертано в небесах» (ЦA24) к целям.<br><b>Г. Отыщите новый регион. </b>Если на стене первобытной пещеры есть отметка ледника [i], выберите одну из следующих карт и добавьте её к целям: «Отправьтесь за зубчатый край» (ЦЯ04), «Отправьтесь в подземный мир» (ЦЯ05), «Отправьтесь в сокрытые земли» (ЦЯ28), «Найдите луч света» (ЦЕ02) или «Найдите Сплетение» (ЦЖ01).<br><b>Д. Отыщите потерянных родственников. </b>Если на стене первобытной пещеры есть отметка раскола [ii], добавьте карту «Установите контакт» (ЦЯ10) к целям.<br><b>Е. Найдите ответы в прошлом. </b>Если в долине есть руины, получите карту знаний «Раскопки» (ЗБ12), добавьте карты «Отыщите спрятанные сокровища» (ЦЯ30) и «Восстановите руины» (ЦЯ22) к целям.<br><b>Ж. Изучите гробницу древнего чудища. </b>Если в долине есть неактивное логово чудища, добавьте карту «Осмотрите могилу» (ЦЯ14) к целям.</p><p>Затем можете потратить 6 <lore>, чтобы выбрать другой эффект из этого списка и разыграть его. Повторите это сколько угодно раз.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<glacier>"},{"label":"ii","image":"<schism>"}]},{"id":"outcomes-303","code":"303","description":{"en":"","ru":"<p><i><b>В коралловых зарослях вы обнаружили...</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><b><i>Коралловые отростки, что качались у вас под ногами, складывались в странный узор. Комета светила всё ярче, и казалось, что путь перед вами становился яснее.</i></b></p><p><b>Защитник, коралл.</b> Один из персонажей в походе должен провести проверку <awareness>, чтобы изучить узор. +4, если <comet>— текущее знамение.<br><b>≥11:</b> Вы были уверены, что мерцающий свет манил вас вглубь зарослей. Продолжите поход.<br><b>1-10:</b> Вы заблудились среди зарослей, и удушающие споры начали разъедать ваши лёгкие. Поход окончился неудачно, если только любой персонаж в походе не получит <minor_disease> или не потратит <lore>, чтобы провести проверку ещё раз.</p><p><b><i>Продвигаясь вглубь зарослей, вы вдруг ощутили на себе взгляд. Это были существа, что мелькали среди качающихся кораллов. И они были голодны.</i></b></p><p><b>Коралл, группа, угроза. </b>Все персонажи в походе должны провести проверку <dexterity>, чтобы отогнать существ. +2, если у персонажа есть предмет с <fire>.<br><b>≥9:</b> Вы сдержали существ на расстоянии. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-8:</b> Вас укусило существо, которое вы даже не успели увидеть, и вновь скрылось в кораллах, ожидая, пока вы лишитесь сил. Получите <minor_injury> и <major_disease>. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><b><i>Вы добрались до места, которое казалось центром зарослей. Огромный коралловый стебель возвышался  над остальными.</i></b></p><p><b>Защитник, коралл, чудо. </b>Один из персонажей в походе должен провести проверку <conviction>, чтобы подойти к стеблю. +4, если у него есть предмет <i>коралла </i>или <i>лунной крови</i>, и +4, если <comet>— текущее знамение.<br><b>≥12:</b> Вы подошли к стеблю, и он раскрылся, нежно прикоснувшись к вашему лицу. Вдруг все заросли начали увядать. Переверните коралловые заросли неактивной стороной вверх. Затем добавьте отметку коралла на сторону легенды карты своего персонажа. Завершите этот поход и достигните соответствующей цели.<br><b>1-11:</b> Никто не решился подойти. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы попытаться снова.</p>"},"repeatable":false,"marks":[{"label":"","image":"<coral>"}]},{"id":"outcomes-309","code":"309","description":{"en":"","ru":"<p><i><b>Вы выявили корень проблемы и устранили его, что позволило жителям долины вновь зажить в согласии.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Установите значение <unrest> на «0». На стене первобытной пещеры изобразите историю о процветающем спокойствии, включив в неё отметку посредника.</p>"},"repeatable":false,"marks":[{"label":"","image":"<mediator>"}]},{"id":"outcomes-310","code":"310","description":{"en":"","ru":"<p><i><b>Вы обнаружили, что некоторые члены вашей общины тайно запасали ресурсы и отказывались делиться ими в трудные времена.</b></i></p><p>Совместно выберите один из следующих путей развития общины:<br><b>А. Принудительно распределите ресурсы, изгнав тех, кто отказывается делиться.</b> Уберите <population><population><population>. На стене первобытной пещеры изобразите историю об изгнании, включив в неё отметку раскола [i].<br><b>Б. Не перераспределяйте ресурсы. </b>Добавьте <unrest><unrest><unrest> и уберите <population>. Добавьте карту «Ворчание у костра» (НО01) в колоду ночи, если возможно. На стене первобытной пещеры изобразите историю о муках голода, включив в неё отметку ужаса [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<schism>"},{"label":"ii","image":"<harrowing>"}]},{"id":"outcomes-311","code":"311","description":{"en":"","ru":"<p><i><b>Без поселений ваш народ сдался на милость воющих ветров и леденящих ночей. Потери росли, и община очутилась на грани бедствия. Более того, начали появляться странные знамения: в небе ярко пылала сверкающая комета, а следы неведомого чудища, что бродило по долине, сложно было не замечать…</b></i></p><p>Завершите текущее испытание. </p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Продолжите борьбу за выживание в долине. </b>Уберите <population><population><population> и добавьте <unrest><unrest>. Несмотря на потери, ваш народ обрёл новые знания, которые могут оказаться решающими в борьбе за выживание. Ваша община получает следующие силы мантий: «Следопыт» (MA01), «Знаток секретов» (MA02), «Друг-наставник» (MA03), «Хранитель» (MA04). Запишите их в раздел «Силы мантий» на странице «Культура» в журнале. В начале каждого последующего испытания выбирайте одну силу для каждого персонажа, основываясь на его мантии, как описано в разделе «Силы мантий» на с. <rulebook>65</rulebook> правил. На стене первобытной пещеры изобразите историю о мрачных скитаниях, включив в неё отметку <comet> и отметку ужаса [i]. Добавьте карту «Вторжение» (ИA04) к грядущим испытаниям.<br><b>Б. Покиньте долину в надежде, что ваши потомки однажды вернутся. </b>На стене первобытной пещеры изобразите историю о горьком отступлении, включив в неё отметку исхода [ii] и отметку ужаса [i]. Завершите кампанию. Ваша община <b>исчезла</b>. См. раздел «Конец кампании» в правилах игры на с. <rulebook>97</rulebook>.<br>Однако не вся надежда утрачена, поскольку знания, добытые вашим народом, передаются новым поколениям! Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. <rulebook>97</rulebook> или раздел «Бесконечный режим» на с. <rulebook>102</rulebook>. Когда начнёте новую кампанию, можете добавить любое количество забытых карт легенд в свою новую общину. Вы также можете перенести любые сведения со страниц «Культура» и «Рецепты» из старого журнала в новый.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<harrowing>"},{"label":"ii","image":"<exodus>"}]},{"id":"outcomes-312","code":"312","description":{"en":"","ru":"<p><i><b>Вы словно протянули руку к луне и разомкнули круг смерти и возрождения Сплетения. Со временем оно вернулось к прежнему состоянию, а гниль осталась лишь в далёком прошлом. Но где‑то в укромном месте семя Сплетения всё ещё дремало, дожидаясь момента, когда вы ослабите хватку и цикл сможет повториться.</b></i></p><p>Добавьте <population><population><population> и уберите <unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о сохранении Сплетения, включив в неё отметку лунной крови [i] и отметку Сплетения [ii]. Ваша община <b>выжила</b>.</p><p>Поздравляем! Вы завершили кампанию «Наскальной истории»! Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!</p><p>Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. <rulebook>97</rulebook> или раздел «Бесконечный режим» на с. <rulebook>102</rulebook>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<moonblood>"},{"label":"ii","image":"<tangle>"},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-317","code":"317","description":{"en":"","ru":"<p><i><b>Вдруг что‑то зашевелилось в вашей сумке — вы вздрогнули и уронили её, рассыпав все материалы. Вы заметили, как выпавший из сумки коралл, извиваясь, пополз к засохшим зарослям. С изумлением и страхом вы наблюдали, как живой коралл слился с мёртвыми ветвями — и те зацвели.</b></i></p><p>Переверните накладку коралловых зарослей активной стороной вверх. Затем уменьшите каждый из своих недугов дважды и добавьте <lore><lore>.</p>"},"repeatable":false},{"id":"outcomes-319","code":"319","description":{"en":"","ru":"<p><i><b>Хищник рухнул на вас, придавив к земле. Его жвалы дёрнулись, затем свет в его глазах погас — и он испустил дух.</b></i></p><p>Получите 3 дичи, 1 ракушку и 1 клык. Добавьте карту «Пройдите испытание охотника» (ЦA05) к целям.</p>"},"repeatable":false},{"id":"outcomes-321","code":"321","description":{"en":"","ru":"<p><i><b>Впереди виднелось нечто неожиданное. Кажется, это…</b></i></p><p>Случайным образом выберите один из неисследованных участков местности по соседству со своим, выбрав участок без накладок, если возможно. Затем разыграйте первое, что можете:<br><b>А. …необычная граница местности. </b>Если выбранный участок местности граничит с другим регионом, в котором есть хотя бы 1 неисследованный участок, поменяйте местами выбранный участок и любой неисследованный участок из того региона. Поместите оба участка неисследованной стороной вверх. Если это условие выполняется для нескольких регионов, выберите один.<br><b>Б. …руины, о которых не рассказывали ваши предки. </b>Если на стене первобытной пещеры есть отметка раскола и у вас есть хотя бы 1 неиспользованная накладка поселения, поместите её стороной руин вверх в любой район, где нет накладки, неисследованного участка.<br><b>В. …странные трещины и расселины. </b>Если есть хотя бы 1 неиспользованная накладка геотермальных источников, поместите её неактивной стороной вверх в любой район, где нет накладки, неисследованного участка (подробнее о геотермальных источниках см. на с. 210).<br><b>Г. …огромная ледяная стена. </b>Если есть хотя бы 1 неиспользованная накладка ледника, поместите её в любой район, где нет накладки, неисследованного участка.<br><b>Д. …некое таинственное явление. </b>Поместите жетон тайны на выбранный участок местности.</p>"},"repeatable":false,"marks":[{"label":"","image":"<schism>"}]},{"id":"outcomes-323","code":"323","description":{"en":"","ru":"<p><i><b>Чудище бесстрастно наблюдало за вами…</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><i><b>…а ваше сердце пронизывал страх. Это существо возвышалось над деревьями — неужели его можно одолеть?</b></i></p><p><b>Чудище, защитник.</b> Один из персонажей в походе должен провести состязание, чтобы первым пойти в атаку: его <conviction> против <dexterity> чудища. +2, если этот персонаж <i>неукротимый</i>.<br><b>Успех. </b>Вы воспряли духом, и остальные последовали за вами. Продолжите поход.<br><b>Провал. </b>Ваша решимость испарилась. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy>, что бы провести проверку ещё раз.</p><p><b><i>Чудище издало рёв, обрушило каменный кулак на землю, и на вас полетели тяжёлые глыбы.</i></b></p><p><b>Чудище, группа, угроза. </b>Все персонажи в походе должны провести состязание, чтобы избежать урона: <might> или <awareness> против <awareness> чудища. +2, если у персонажа есть <i>одежда</i>, и +2, если он <i>осторожный</i>.<br><b>Успех. </b>Вы смогли увернуться от летящих глыб. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>Провал. </b>Вас задело камнем. Покиньте поход либо получите <major_injury> и уменьшите все свои усиления. Если все персонажи покинули поход, он окончился неудачно.</p><p><i><b>Пока кулак чудища оставался на земле, вы успели взобраться по нему. Прицельный удар по макушке мог бы повалить исполина, но кто из вас похвастается такой безошибочной точностью?</b></i></p><p><b>Чудище, защитник. </b>Один из персонажей в походе должен провести состязание, чтобы сразиться: его <might> или <dexterity> против <might> чудища. +2, если у этого персонажа есть <i>оружие</i>, и +4, если у него есть <i>трофей</i>.<br><b>Успех. </b>Вы нанесли удар именно туда, куда было нужно. Завершите этот поход и достигните соответствующей цели.<br>Провал. Ваше оружие отскочило от каменной головы чудища, и существо небрежно сбросило вас лапой, будто отмахиваясь от насекомого. Получите <major_injury><major_injury><minor_injury>. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-327","code":"327","description":{"en":"","ru":"<p><i><b>В долине ваша община росла и процветала. Однако растущее население хоть и давало некоторые преимущества, но при этом требовало больше ресурсов для своего существования.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Вы собирали много ресурсов, и это сказывалось на долине. </b>Если хотя бы на 3 участках местности есть жетоны истощения, добавьте <activity><activity>.<br><b>Б. Ваши действия слегка нарушали равновесие в долине. </b>Добавьте <activity>.</p>"},"repeatable":false},{"id":"outcomes-329","code":"329","description":{"en":"","ru":"<p><i><b>В общине рос страх перед чужаками, о которых ходили тревожные слухи. Если не связаться с теми людьми, рассказы о возможной угрозе могут стать ещё более мрачными…</b></i></p><p>Добавьте <unrest><unrest><unrest>. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Запретите выходить за пределы поселений ночью.</b> Запишите «Отдыхать на участках без убежища или поселения» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет. На стене первобытной пещеры изобразите историю о пугающих ночах, включив в неё отметку <moon> и отметку табу.<br><b>Б. Направьте энергию своих людей на строительство защитных сооружений.</b> Если вы спроектировали частокол (СР11) или сторожевую башню (СР19), добавьте любое из этих сооружений в каждое из своих поселений, где нет таких сооружений (не тратя <energy> и ресурсы). Если в поселении уже построено максимальное количество сооружений, разрушьте случайное из них, чтобы построить новое.<br><b>В. Успокойте людей, заверив, что вы хорошо подготовлены. </b>Если в каждом из ваших поселений есть частокол или сторожевая башня, уберите <unrest>.</p>"},"repeatable":false,"marks":[{"label":"","image":"<taboo>"}]},{"id":"outcomes-331","code":"331","description":{"en":"","ru":"<p><i><b>Когда последние лучи солнца словно исчезли в огромной невидимой пасти, ваш народ в ужасе обратился к вам…</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Увековечьте это событие в истории. </b>Потратьте <lore><lore><lore>. Затем на стене первобытной пещеры изобразите историю о возвращении солнца, включив в неё отметку <moon> и отметку <sun>. <br><b>Б. Призовите людей укрыться. </b>Уберите <unrest><unrest>.</p>"},"repeatable":false},{"id":"outcomes-332","code":"332","description":{"en":"","ru":"<p><i><b>То, что вы игнорировали жалобы своего народа, превратило проблему в настоящую катастрофу. Небольшая ссора переросла в драку, и вскоре пролилась кровь. Зачинщиков вы изгнали, но они успели причинить вред.</b></i></p><p>Завершите текущее испытание.</p><p>Уберите <population><population><population><population>. Разрушьте 2 случайных сооружения в каждом поселении. Если после этого в поселении не осталось ни одного сооружения, оно становится руинами. </p><p>На стене первобытной пещеры изобразите историю о кровавом расколе, включив в неё отметку битвы [i] и отметку раскола [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<schism>"}]},{"id":"outcomes-333","code":"333","description":{"en":"","ru":"<p><i><b>Не сумев обосноваться в долине, слишком много людей потерялось из‑за обильных снегопадов. Чтобы выжить, вашему народу предстояло пойти на отчаянные меры.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Покиньте долину. </b>Если вы проходите кампанию, уберите все грядущие испытания, затем добавьте карту «Исход» (ИЯ09) к грядущим испытаниям.<br><b>Б. Отправьтесь на поиски людей, зная, что вернётесь нескоро. </b>Если вы играете в бесконечном режиме, найдите в колоде событий карту «Утраченные легенды» (БР10) и отложите её. Перемешайте колоду событий и положите карту «Утраченные легенды» на верх колоды событий. Добавьте 12 <population>. Уберите все руины, затем все поселения становятся руинами.</p>"},"repeatable":false},{"id":"outcomes-339","code":"339","description":{"en":"","ru":"<p><i><b>Вся долина наполнилась раскатами грохота, в небо поднялись облака пыли, а затем наступила тишина. Видимо, источник разрушения находился там, откуда вы пришли в долину.</b></i></p><p>Если на стене первобытной пещеры есть отметка тайны, добавьте <lore><lore><lore>. Затем катастрофическое появление чудища изменяет долину. Пройдите описанные ниже этапы.</p><p><b>Этап 1. Чудище разрушило проход, через который вы вошли в долину. </b>Переверните начальный участок местности. Также переверните все накладки на этом участке неактивной стороной вверх (например, если на этом участке было поселение, оно становится руинами).<br><b>Этап 2. Из облака пыли появилось гигантское существо. </b>Если у одного или нескольких чудищ ещё нет логова в долине, выберите любое из этих чудищ (если возможно, выберите то чудище, отметка которого есть на стене первобытной пещеры). Это чудище появляется в долине (см. раздел «Появление чудища» в правилах игры на с. <rulebook>74</rulebook>).<br><b>Этап 3. Чудище заняло логово. </b>Поместите активное логово этого чудища на начальный участок местности. Бросьте <1d6>, чтобы поместить логово в соответствующий район: [1-3] А, [4-6] В. Если в этом районе есть другая накладка (например, руины), замените её логовом. Если у этого чудища уже есть неактивное логово, переверните его активной стороной вверх.<br><b>Этап 4. Оглушительный удар разрушил старые пути, зато открыл новые, ведущие вглубь долины. </b>Если в долине не более 2 основ местности, пройдите следующие шаги по порядку, чтобы расширить долину.<br><b>Шаг 1.</b> Добавьте новую основу местности в долину. Поместите её по соседству с любым участком местности с хотя бы 2 открытыми границами. Границы основы должны соседствовать с как можно большим количеством границ уже размещённых основ. Если есть несколько возможных позиций, поместите её в самую северную из них.<br><b>Шаг 2. </b>Положите в мешочек все неразмещённые участки начального региона и перемешайте их. Затем по одному вытащите 3 участка и поместите их неисследованной стороной вверх в ячейки новой основы по направлению с севера на юг и с востока на запад. <br><b>Шаг 3 (только для эры 1 и бесконечного режима). </b>Если в запасе есть хотя бы 1 непомещённая накладка ледника, бросьте <1d6> и поместите ледники по результату броска: [1-2] один ледник в район А одного из участков местности без накладки, [3-4] один ледник в район Б одного из участков местности без накладки, [5] разыграйте результаты 1-2 и 3-4, [6] бросьте <1d6> ещё раз и прочитайте один из исходов ниже, соответствующий результату броска.<br>[1-3] <outcome> 846, [4-5] <outcome> 134, [6] <outcome> 446.</p>"},"repeatable":false},{"id":"outcomes-342","code":"342","description":{"en":"","ru":"<p><i><b>Благодаря кулинарным экспериментам вы обратили внимание на новые ингредиенты, которые могли бы придать вашим блюдам пикантности и обогатить их вкус. </b></i></p><p>Получите карту знаний «Готовка» (ЗЕ01). Разыграйте как можно больше из следующего:<br><b>А. Вы заметили, что птицы и насекомые часто вьют гнёзда на лесных деревьях. </b>Добавьте карты EЛ01–ЕЛ03 в колоду добычи припасов в лесу.<br><b>Б. Хотя деревья в степи встречались реже, чем в лесу, птицы и насекомые всё равно находили здесь места для гнёзд. </b>Добавьте карты EС01–ЕС03 в колоду добычи припасов в степи.<br><b>В. В Сплетении обитало множество крылатых существ, вьющих гнёзда. </b>Если вы используете дополнение «Природа зверя», добавьте карты EП01–ЕП03 в колоду добычи припасов на полянах.</p>"},"repeatable":false},{"id":"outcomes-347","code":"347","description":{"en":"","ru":"<p><i><b>Вы вернулись из тёмных глубин в залитые солнцем земли. Воодушевившись вашим успехом, община смогла последовать примеру и начать спускаться под землю.</b></i></p><p>Теперь община может исследовать подземный мир долины. Получите карту знаний «Спуск» (ЗБ07). Подробнее см. в разделе «Спуск» на с. <rulebook>82</rulebook> правил игры. На стене первобытной пещеры изобразите историю о преодолённых глубинах, включив в неё отметку подземного мира.</p>"},"repeatable":false,"marks":[{"label":"","image":"<underworld>"}]},{"id":"outcomes-348","code":"348","description":{"en":"","ru":"<p><i><b>Исследования коралла привели вас в ещё большее замешательство. Должна была существовать какая‑то закономерность, но она пока ускользала от вас. </b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest><unrest><unrest>. Добавьте карту «Падение небес» (ИВ04) к грядущим испытаниям.<br>Затем разыграйте как можно больше из следующего:<br><b>А. Из-за кораллов преобразились леса. </b>Если в долине есть хотя бы 1 участок Дивной долины, добавьте карты КЛ01–КЛ04 в колоду добычи припасов в лесу.<br><b>Б. В степи закипела странная новая жизнь.</b> Если в долине есть хотя бы 1 участок Поднебесной равнины, добавьте карты КC01–КС04 в колоду добычи припасов в степи.<br><b>В. Сплетение стало ещё более таинственным, чем прежде. </b>Если в долине есть хотя бы один 1 участок Сплетения, добавьте карты КП01–КП04 в колоду добычи припасов на полянах, если возможно.<br><b>Г. Зловещие создания начали рыскать в ночи. </b>Добавьте карты НК01 и НК02 в колоду ночи.<br><b>Д. Сама земля изменилась. </b>Добавьте карту ПЕ04 в колоду пути.</p><p>На новых картах добычи припасов появляется новый бонусный ресурс — живой коралл.</p>"},"repeatable":false},{"id":"outcomes-349","code":"349","description":{"en":"","ru":"<p><i><b>В логове вы пробирались через высохшие листья и древние лианы, пока не нашли зал, поросший перламутровыми цветами. Когда вы прикоснулись к одному из них, бутон раскрылся и ваш разум наполнился видением. Что это было? Событие из прошлого? Предсказание будущего? Или пророчество, которое можно предотвратить?</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Вам показалось, что цветок раскрылся настолько, что затмил всю землю. </b>Если <comet> или <cloud> — текущее знамение, найдите карту цели ЦВ02. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описать её другим игрокам. Затем на стене первобытной пещеры изобразите историю о распространившихся изменениях, включив в неё отметку ЧД2 [i] и отметку <comet>, заключённую в отметку пророчества [iii].<br><b>Б. Где-то в глубине вашего разума струилась вода, пока вы искали спасения в темноте.</b> Если <sun> — текущее знамение, найдите карту цели ЦЯ09. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описать её другим игрокам. Затем на стене первобытной пещеры изобразите историю о чудотворном исцелении, включив в неё отметку ЧД2 [i], отметку ужаса [ii] и отметку  <sun>, заключённую в отметку пророчества [iii].<br><b>В. Когда видение рассеялось, вы ощутили мощный прилив сил.</b> Если <star> — текущее знамение, найдите карту цели ЦЯ07. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описать её другим игрокам. Затем на стене первобытной пещеры изобразите историю о ещё не пролитой крови, включив в неё отметку ЧД2 [i] и отметку <star>, заключённую в отметку пророчества [iii].<br><b>Г. Пока вы не очнулись, вас трясло от напряжения и было трудно дышать. </b>Если <moon> — текущее знамение, найдите карту цели ЦЯ17. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описать её другим игрокам. Затем на стене первобытной пещеры изобразите историю об отчаянном союзе, включив в неё отметку ЧД2 [i] и отметку <moon>, заключённую в отметку пророчества [iii].</p><p>В конце текущего испытания завершите эру. См. с. 196, чтобы <era2>начать эру 2</era2>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<bh2>"},{"label":"ii","image":"<harrowing>"},{"label":"iii","image":"<prophecy>"}]},{"id":"outcomes-353","code":"353","description":{"en":"","ru":"<p><i><b>Открытый участок стены пещеры словно манил вас оставить на ней след.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Оставьте отметку на стене. </b>Если на этой карте спуска не более 2 отметок знамений, добавьте отметку текущего знамения на пустое пространство на карте. <br><b>Б. Изучите отметки в поисках подсказок о том, какие испытания ждут вас в тёмном подземном мире. </b>Если на этой карте спуска уже есть хотя бы 3 отметки знамений, разыграйте эффект, соответствующий одной из этих отметок, как указано ниже:<br><cloud> — получите <major_boost> к <might>.<br><star>— получите <major_boost> к <dexterity>.<br><moon>— получите <major_boost> к <awareness>.<br><sun>— получите <major_boost> к <conviction>.<br><comet>— уменьшите один из своих недугов дважды.<br><b>В. Узнайте больше об истории долины. </b> Если на этой карте спуска есть хотя бы 1 отметка знамения, добавьте <lore> за каждую отметку на этой карте.</p>"},"repeatable":false},{"id":"outcomes-358","code":"358","description":{"en":"","ru":"<p><i><b>Вы создавали высеченные из камня памятники, чтобы сохранить память о прошлом и чтобы ваш народ мог гордиться этими великими творениями ещё много поколений.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем уберите <unrest><unrest>. На стене первобытной пещеры изобразите историю о памятниках из камня, включив в неё отметку летописца. Получите карты знаний «Легенды» (ЗБ15) и «Символы» (ЗБ17), если у вас их ещё нет.</p>"},"repeatable":false,"marks":[{"label":"","image":"<scribe>"}]},{"id":"outcomes-363","code":"363","description":{"en":"","ru":"<p><i><b>Земля словно завращалась у вас под ногами, когда бугор превратился в лапу существа, стряхнувшего с себя вековой сон. Вы обратились в бегство, а оглянувшись, увидели, что земля хоть и легла вновь на место, но разлом остался…</b></i></p><p>Каждый персонаж на вашем участке местности сбегает. Затем разыграйте первое, что можете:<br><b>А. Чудище вырвалось из своего древнего логова, вновь преисполненное ярости.</b> Если сейчас эра 2 или эра 3 и на стене первобытной пещеры есть отметка расколотой земли, переверните логово чудища на участке местности, с которого вы бежали (или на соседнем с ним), активной стороной вверх. Это чудище появляется в долине (см. раздел «Появление чудища» в правилах игры на с. <rulebook>74</rulebook>). Затем, если в долине есть ещё одно активное логово, добавьте карту «Битва титанов» (ИЯ08) к грядущим испытаниям.<br><b>Б. Грохот постепенно утих.</b> Поместите жетон тайны на участок местности, с которого вы сбежали.</p>"},"repeatable":false,"marks":[{"label":"","image":"<brokenearth>"}]},{"id":"outcomes-372","code":"372","description":{"en":"","ru":"<p><i><b>Знамения поведали вам, что чудище глубоко связано с жизнью этого мира. Его поступь меняет саму землю, и, если верить знамениям, вы можете предсказать его желания.</b></i></p><p>Завершите текущее испытание.</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Проявите почтение к чудищу. </b>Уберите <unrest><unrest>. Успокойте бодрствующее чудище на 3. На стене первобытной пещеры изобразите историю о священной связи, включив в неё отметку бодрствующего чудища, заключённую в отметку связи [i]. Добавьте отметку этого чудища на сторону легенды карты каждого персонажа. Ваша община получает силу мантии «Говорящий с чудищами» (MA18).<br><b>Б. Объясните людям, что чудище приходит в ярость, когда кто-то нарушает запрет. </b>Если на стене первобытной пещеры есть отметка табу [ii], уберите 6 <unrest>. На стене первобытной пещеры изобразите историю о древнем законе, включив в неё отметку бодрствующего чудища и отметку табу, заключённую в отметку связи [i].<br><b>В. Увековечьте путь чудища для будущих поколений. </b>Если на стене первобытной пещеры есть отметка летописца [iii] или отметка песнопевца [iv], добавьте <population><population>. Успокойте бодрствующее чудище на 1. На стене первобытной пещеры изобразите историю о вестнике дикой природы, включив в неё отметку бодрствующего чудища и отметку летописца [iii] или отметку песнопевца [iv] (выберите ту, которая уже есть на стене).</p><p>Затем завершите текущую эру. См. с. 196, чтобы <era2>начать эру 2</era2>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<bond>"},{"label":"ii","image":"<taboo>"},{"label":"iii","image":"<scribe>"},{"label":"iv","image":"<songweaver>"}]},{"id":"outcomes-378","code":"378","description":{"en":"","ru":"<p><i><b>Ваши поля процветали, и вы собрали богатый урожай до наступления зимы. Годы спустя ваш народ продолжил развиваться, а община достигла небывалых размеров.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем добавьте <population><population><population><population>. На стене первобытной пещеры изобразите историю о меняющих землю, включив в неё отметку расколотой земли [i], отметку изобилия [ii] и отметку возделывания [iii]. Ваша община получает силу мантии «Строитель» (MA16). Добавьте карты «Период затишья» (ИЯ01), даже если вы уже завершили это испытание ранее, и «Цитадель» (ИБ10) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<brokenearth>"},{"label":"ii","image":"<cultivation>"},{"label":"iii","image":"<plenty>"}]},{"id":"outcomes-382","code":"382","description":{"en":"","ru":"<p><i><b>Появление кометы изменило долину, но ваш народ сумел приспособиться к новым опасностям и лишениям. Однако гнев от этих перемен продолжал бурлить в сердцах людей… </b></i></p><p>Добавьте <unrest><unrest><unrest>. Затем разыграйте первое, что можете:<br><b>А. Ваши усилия приняли, но неохотно. </b>Если значение <unrest> равно 12 или меньше, добавьте к грядущим испытаниям карту «Презрение земли» (ИВ06).<br><b>Б. В этом бедствии обвинили вас. </b>Добавьте карту «Презрение человечества» (ИВ05) к грядущим испытаниям.</p>"},"repeatable":false},{"id":"outcomes-386","code":"386","description":{"en":"","ru":"<p><i><b>Вы отправились в гробницу чудища, уходя всё глубже... </b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><b><i>Снаружи не было видно, как попасть в древнее логово. Вам пришлось искать путь внутрь.</i></b></p><p><b>Защитник, чудо. </b>Один из персонажей в походе должен провести проверку <awareness>, чтобы отыскать проход. +1 за каждый предмет для <i>исследования </i>у любого участника похода, +2, если выбранный персонаж <i>сосредоточенный</i>, и +4, если в журнале записан хотя бы 1 секрет этого чудища.<br><b>≥10:</b>  Вы нашли путь внутрь логова. Продолжите поход.<br><b>1-9:</b>  Логово осталось неприступным. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy>, что бы провести проверку ещё раз.</p><p><i><b>Вы проскользнули в расщелину и вдруг услышали рычание. Здесь устроили логово хищники. У вас был шанс прогнать их до того, как они нападут.</b></i></p><p><b>Защитник, угроза. </b>Один из персонажей в походе должен провести проверку <might> или <conviction>, чтобы прогнать зверей. +2, если у него есть предмет с <fire>, +2, если у него есть <i>оружие</i>, и +2, если он <i>мстительный</i>.<br><b>≥11:</b>  Вы обрушились на хищников с яростью, превосходящей их собственную, и прогнали их. Продолжите поход.<br><b>1-10:</b>  Хищники напали на вас. Каждый персонаж в походе должен встретиться с хищником. Если персонаж решит сбежать, он покидает поход. Если все персонажи покинули поход, он окончился неудачно.</p><p><b><i>Окутанные тьмой, вы приблизились к узкому выступу над пропастью. Пришлось идти осторожно, чтобы не сорваться. </i></b></p><p><b>Чудище, защитник, угроза. </b>Один из персонажей в походе должен провести проверку <dexterity>, чтобы пройти через пропасть. +2, если у него есть предмет с <fire>, и +2 за каждое сброшенное им сокровище этого чудища (не более +6).<br><b>≥14:</b>  Сквозь тьму пробивался свет, открывающий взору нечто... неожиданное. Завершите этот поход и достигните соответствую щей цели.<br><b>1-13:</b>  Всепоглощающая тьма взяла верх, и вы отступили. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-388","code":"388","description":{"en":"","ru":"<p><i><b>Ваш народ перешёл на редкий рацион, основой которого стали не мясо и не овощи. Вам предстояло решить, следовать ли этой необычной диете дальше или искать более привычные источники пропитания.</b></i></p><p>Совместно выберите один из следующих путей развития общины:<br><b>А. Оставьте необычные продукты основой рациона. </b>Если на карте цели есть хотя бы 1 жетон мёда, спроектируйте улей (СЕ04), не тратя <lore>. Если на карте цели есть хотя бы 1 жетон яйца, спроектируйте курятник (СЕ05), не тратя <lore>.<br><b>Б. Сосредоточьтесь на растительных продуктах.</b> Если на карте цели есть хотя бы 1 жетон овощей, добавьте <lore><lore><lore>, затем добавьте карту «Освой те травничество» (ЦA04) к целям.<br><b>В. Сделайте охоту приоритетной. </b>Если на карте цели есть хотя бы 1 жетон мяса, добавьте <lore><lore><lore>, затем добавьте карту «Пройдите испытание охотника» (ЦA05) к целям.</p>"},"repeatable":false},{"id":"outcomes-391","code":"391","description":{"en":"","ru":"<p><i><b>Во тьме вы заметили сверкающие глаза хищника. Существо бросилось вперёд — и вам пришлось защищаться.</b></i></p><p>Проведите встречу с хищником (см. раздел «Встреча с хищником» в правилах игры на с. <rulebook>48</rulebook>). +2, если вы выбрали сражение и у вас есть «Факел». Если вы решили отступить, при результате [1-9] потеряйте все свои награды.</p>"},"repeatable":false},{"id":"outcomes-392","code":"392","description":{"en":"","ru":"<p><i><b>Приложив немалые усилия и проявив терпение, вам удалось усмирить гнев чудища. С протяжным стоном существо вернулось в своё логово. Стало ли это столкновение уроком для вашего народа или, наоборот, придало людям смелости?</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю об усмирении, включив в неё отметку бодрствующего чудища и отметку посредника. Добавьте карту «Единое видение» (ИБ07) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"","image":"<mediator>"}]},{"id":"outcomes-393","code":"393","description":{"en":"","ru":"<p><i><b>Эхо вымершего чудища звучало сквозь века. Его поступь гремела лишь в преданиях вашего народа, а в тени огромного кургана резвились дети. Но с каждым годом рассказы о страхе перед чудищем становились всё мрачнее, и ваш народ начинал опасаться, что оно может вернуться…</b></i></p><p>Добавьте <unrest><unrest>. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Запретите приближаться к зловещей гробнице. </b>Если в долине есть неактивное логово, запишите «Отдыхать на участке местности с неактивным логовом чудища» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет. Добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю об устрашающей могиле, включив в неё отметку чудища с неактивным логовом и отметку табу.<br><b>Б. Отправьте смельчака в логово. </b>Если в долине есть неактивное логово, выберите любое из них. Один из персонажей должен провести проверку <conviction>. При результате [≥10] уберите <unrest><unrest><unrest> и добавьте отметку этого чудища на сторону легенды карты выбранного персонажа. При любом другом результате легенда этого персонажа будет забыта в начале следующей эры (см. раздел «Забытые легенды» в правилах игры на с. <rulebook>72</rulebook>).<br><b>В. А стоило ли вообще обращать внимание на эти слухи? Они больше походили на суеверия.</b> Если в долине нет неактивного логова, без эффекта.</p>"},"repeatable":false,"marks":[{"label":"","image":"<taboo>"}]},{"id":"outcomes-394","code":"394","description":{"en":"","ru":"<p><i><b>Вам не удалось выкопать семя Сплетения. Судьба великого леса была предрешена, и земля вокруг него начала чахнуть. Спустя года долина стала пустынной и засушливой. Чтобы выжить, вашему народу пришлось покинуть земли предков.</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о погибшем саде, включив в неё отметку ужаса [i], отметку несчастья [ii] и отметку Сплетения [iii]. Добавьте карту «Исход» (ИЯ09) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<harrowing>"},{"label":"ii","image":"<misfortune>"},{"label":"iii","image":"<tangle>"}]},{"id":"outcomes-398","code":"398","description":{"en":"","ru":"<p><i><b>Сквозь кожу червя вы ощущали влажную землю. Вы скользили, прогрызая корни и двигаясь за кисловатым привкусом гнили. Смерть коснулась необъятного зелёного мира над вами, и время пира приближалось… Вы пробудились в ужасе и смятении.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. В вашем сне не было никакого смысла. Хотя… нет, не может этого быть! </b>Если на стене первобытной пещеры есть отметка погибели, уменьшите все свои усиления и получите <lore> за каждое такое уменьшение. <br><b>Б. Вы были уверены, что это не сон, а предвестие рока, обрушившегося на родные земли. </b>На стене первобытной пещеры изобразите историю о подточенных корнях, включив в неё отметку расколотой земли, заключённую в отметку погибели. Затем верните в коробку карту «Корни мироздания» (НС03).</p>"},"repeatable":false,"marks":[{"label":"","image":{"image":"<doom>","overlay":{"image":"<brokenearth>","size":0.55,"x":-2,"y":20,"rotate":0}}}]},{"id":"outcomes-400","code":"400","description":{"en":"","ru":"<p><i><b>Вдали от своих домов, сломленные ужасным бременем изгнания, ваши люди затерялись в легендах…</b></i></p><p>Завершите текущее испытание.</p><p>Все персонажи становятся легендами. На стене первобытной пещеры изобразите историю о презираемых героях, включив в неё отметку коралла [i] и отметку несчастья [ii]. Добавьте к грядущим испытаниям карту «Презрение земли» (ИВ06).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<coral>"},{"label":"ii","image":"<misfortune>"}]},{"id":"outcomes-402","code":"402","description":{"en":"","ru":"<p><i><b>Вы знали, что такие залежи мусора стоит исследовать, тем более что они явно несвежие, а значит, владельца не было поблизости. Перебрав содержимое логова, вы нашли кое‑что полезное. Было видно, что существо питалось разнообразно.</b></i></p><p>Выберите одно:<br><b>А. Хищник, похоже, предпочитал охотиться на птиц. </b>Получите 2 пера.<br><b>Б. От съеденного зверя остался только кусок кожи. </b>Получите 1 шкуру.<br><b>В. Вам оставалось лишь надеяться, что обглоданные кости не принадлежали кому-то, кого вы знали. </b>Получите 1 кость.</p>"},"repeatable":false},{"id":"outcomes-403","code":"403","description":{"en":"","ru":"<p><i><b>Корни этого чудища простирались вглубь долины. В какой‑то момент на месте его следов начали появляться новые побеги. Они извивались, переплетались и превращались в колючие заросли. Эти места были опасны, но там было много пищи как для дичи, так и для хищников.</b></i></p><p>Уберите все накладки скрученных отпечатков из долины, затем поместите накладку скрученного отпечатка активной стороной вверх на каждый участок местности с жетоном следов. Каждый раз выбирайте район с озером, болотом или рекой и без накладки, если возможно. Подробнее о скрученном отпечатке см. на с. 212.</p><p>Затем уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-406","code":"406","description":{"en":"","ru":"<p><i><b>Вы вообразили человека и так живо описали его, что остальные у костра почувствовали, будто знают его лично. Со временем этот образ, созданный вашим разумом, стал легендой на века.</b></i></p><p>Следуя указаниям на с. <rulebook>6</rulebook> правил игры, создайте новую карту персонажа, которую после добавите в легенды общины. Вы можете выбрать, будет он молодым или пожилым. Затем выберите и разыграйте одно:<br><b>А. Наделите легендарного персонажа собственными сильными или слабыми сторонами, чтобы он сильнее казался настоящим. </b>Замените значение одной из характеристик нового персонажа на значение такой же своей характеристики.<br><b>Б. Припишите вымышленному образу поступок, отражающий вас.</b> Добавьте одну из своих отметок на сторону легенды карты нового персонажа.<br><b>В. Привнесите частичку своей личности в выдуманного персонажа. </b>Добавьте персонажу одну из своих черт.</p><p>Затем отметьте клетку рядом со словом «легенда» на карте нового персонажа и добавьте эту карту в легенды общины.</p>"},"repeatable":false},{"id":"outcomes-407","code":"407","description":{"en":"","ru":"<p><b><i>Вы изучили поражённый регион и обнаружили, что болезнь Сплетения проникала глубоко в корни, делая их узловатыми. Вы срезали столько этих странных наростов, сколько смогли, и хватка заразы, казалось, ослабла. Однако может настать день, когда гниль вернётся, и тогда придётся отправиться вглубь, чтобы найти источник заразы. Пока же вам оставалось лишь ждать и надеяться, что Сплетение восстановится.</i></b></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем уберите <unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о побеждённой гнили, включив в неё отметку Сплетения [i] и отметку расколотой земли, заключённую в отметку погибели [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<tangle>"},{"label":"ii","image":{"image":"<doom>","overlay":{"image":"<brokenearth>","size":0.55,"x":-2,"y":20,"rotate":0}}}]},{"id":"outcomes-409","code":"409","description":{"en":"","ru":"<p><i><b>Чудище отпрянуло от света, касание которого заставляло кожу чудища таять, словно лёд. В агонии существо отступало всё дальше, оставляя за собой огромные лужи из жидкой плоти. В одной из этих луж вы нашли необычный камень. </b></i></p><p>Завершите встречу. Разозлите чудище на 1. Чудище сбегает. Затем, если у персонажа, животного-компаньона или в <i>сооружении-хранилище</i> есть предмет со словом «расколотый» в названии, получите 2 сокровища этого чудища; в противном случае получите карту предмета «Расколотый камень» (ВЩ88).</p>"},"repeatable":false},{"id":"outcomes-410","code":"410","description":{"en":"","ru":"<p><i><b>Чудище вернулось к своему громадному сверкающему дереву. Когда оно ступило в полую расщелину в древесине, свет угас.</b></i></p><p>Завершите текущее испытание. На стене первобытной пещеры изобразите историю о спящем огне, включив в неё отметку ЧД4 и отметку <star>. Переверните логово ЧД4 неактивной стороной вверх. В начале следующего испытания каждое другое чудище становится спящим. Добавьте карту «Пеплопад» (ИЕ05) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"","image":"<bh4>"}]},{"id":"outcomes-411","code":"411","description":{"en":"","ru":"<p><i><b>Изучая место, где чудище оставило ледяную борозду в земле, вы нашли предметы, явно созданные человеком.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Истолкуйте значение предмета. </b>Если у чудища есть назначенная неоткрытая карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br>Б. Заберите одну из реликвий. Получите карту знаний «Раскопки» (ЗБ12). Затем можете выполнить действие раскопок, не тратя <energy>. Если у вас есть отметка реликвии, можете также добавить 1 лунную кровь или 1 шёлк в мешочек для раскопок.</p>"},"repeatable":false,"marks":[{"label":"","image":"<relic>"}]},{"id":"outcomes-414","code":"414","description":{"en":"","ru":"<p><i><b>Болезнь распространилась, без пощады накрыв ваши поселения.</b></i></p><p>Для каждого участка местности со вспышкой болезни бросьте <1d6>. +2, если в этом поселении есть мусорная яма.<br><b>1-3:</b>  Уберите <population><population>. Каждый персонаж на этом участке местности получает <major_disease>. <br><b>4-5:</b>  Уберите <population>. Каждый персонаж на этом участке местности получает <major_disease>.<br><b>6:</b>  Каждый персонаж на этом участке местности получает <minor_disease>.<br><b>≥7:</b>  Без эффекта.</p>"},"repeatable":false},{"id":"outcomes-415","code":"415","description":{"en":"","ru":"<p><i><b>Чудище с большим интересом ожидало подношения, низко склонив голову.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Предложите чудищу изящное изделие.</b> Если у вас есть обработанный материал или предмет в инвентаре, сбросьте 1 любой обработанный материал или предмет. Завершите встречу. Успокойте чудище на 1. Затем, если у любого персонажа, животного-компаньона или в сооружении-хранилище есть предмет со словом «радужный» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Радужная кожа» (ВЩ89).<br><b>Б. Поройтесь в кармане в поисках чего-нибудь для подношения. </b>Если у вас есть материал в инвентаре, сбросьте 1 любой материал и получите 1 волокно. Затем завершите встречу.<br><b>В. Ничего не предлагайте. Завершите встречу. </b>Разозлите чудище на 2.</p>"},"repeatable":false},{"id":"outcomes-416","code":"416","description":{"en":"","ru":"<p><i><b>Хрупкий кусок кожи чудища лежал на солнце, медленно рассыпаясь в пыль. Казалось, внутри него что‑то есть…</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Поразмышляйте о значении залитого солнцем камня.</b> Если у чудища есть назначенная неоткрытая карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><b>Б. Разбейте камень. </b>Получите 2 глины. Если у вас есть <stoneworking>, вместо этого получите 1 ракушку.</p>"},"repeatable":false},{"id":"outcomes-417","code":"417","description":{"en":"","ru":"<p><i><b>Над вами нависла лапа чудища. Но под светом солнца в его каменной коже стали появляться большие трещины. Вы проскользнули в одну из них, дождались, пока лапа сдвинется, а затем благополучно спустились на землю.</b></i></p><p>Завершите встречу. Получите <minor_boost> к <dexterity>.</p>"},"repeatable":false},{"id":"outcomes-418","code":"418","description":{"en":"","ru":"<p><i><b>Недовольство давно нависало над вашим народом, словно грозовая туча. Теперь же буря обрушилась… Начались распри и сражения, разорвались узы, пролилась кровь. А когда столкновения утихли, победителей не оказалось. Человеческие потери были слишком велики, чтобы их вынести, и между враждующими сторонами установилось хрупкое перемирие. Однако жестокость то и дело продолжала сотрясать прежде мирную долину, а грозовые тучи взаимных обвинений и жажды мести так и не рассеялись.</b></i></p><p>Установите значение <unrest> на 10. Уберите 8 <population>. На стене первобытной пещеры изобразите историю о кровавых днях, включив в неё отметку битвы [i] и отметку ужаса [ii]. Добавьте карту «Беспрестанное насилие» (ПР06) в колоду пути и карту «Открытая враждебность» (НО02) в колоду ночи.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<harrowing>"}]},{"id":"outcomes-420","code":"420","description":{"en":"","ru":"<p><i><b>Под землёй вы обнаружили огромное семя. Неужели из него и проросло само Сплетение? Вы с благоговением взирали на великий круговорот жизни. </b></i></p><p>Добавьте <lore><lore><lore><lore>.</p>"},"repeatable":false},{"id":"outcomes-421","code":"421","description":{"en":"","ru":"<p><i><b>Разглядывая следы корней чудища, вы заметили, что они аккуратно огибают участок обожжённой земли.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Поразмышляйте об этом обугленном участке земли. </b>Если у чудища есть назначенная неоткрытая карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><b>Б. Возродите пламя, чтобы отпугнуть чудище. </b>Уменьшите любое усиление чудища. Если у вас есть предмет с <fire> или на вашем участке местности есть <fire>, уменьшите все усиления чудища.</p>"},"repeatable":false},{"id":"outcomes-422","code":"422","description":{"en":"","ru":"<p><i><b>Следы чудища горели неестественным пламенем, иссушая растения и отпугивая зверей.</b></i></p><p>Поместите жетон истощения на каждый участок местности с жетоном следов. Каждый персонаж на участке с жетоном следов получает <minor_disease>. Затем уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-423","code":"423","description":{"en":"","ru":"<p><i><b>Вы услышали, как вода струится по склону ледника, а вдали шелестят ветви. Где‑то там, должно быть, раскинулся лес.</b></i></p><p>Добавьте <lore><lore><lore>. Добавьте к целям карту «Отправьтесь в подземный мир» (ЦЯ05).</p>"},"repeatable":false},{"id":"outcomes-424","code":"424","description":{"en":"","ru":"<p><i><b>Ценой пота и крови вы вынесли семя Сплетения на поверхность.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о семени Сплетения, включив в неё отметку становления [i] и отметку Сплетения [ii]. Добавьте карту «Новый расцвет» (ИЖ05) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<growth>"},{"label":"ii","image":"<tangle>"}]},{"id":"outcomes-425","code":"425","description":{"en":"","ru":"<p><i><b>Там, где были пепельные следы чудища, расцвела жизнь.</b></i></p><p>Уберите все жетоны истощения с участков местности с жетонами следов и поместите по 1 жетону тайны на каждый из этих участков. Затем уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-426","code":"426","description":{"en":"","ru":"<p><i><b>Вы спустились в огромный грот. Услышав плеск воды, вы направились к подземному озеру, берег которого освещался ледяным сиянием.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><b><i>Этот грот хоть и казался защищённым от кораллов, но это вовсе не означало, что здесь нет других опасностей. </i></b></p><p><b>Защитник, угроза. </b>Один из персонажей в походе должен провести проверку <awareness>, чтобы распознать угрозу. +1 за каждый его предмет для <i>исследования</i>, +2, если у него есть предмет с <fire>, и +2, если он <i>осторожный</i>.<br><b>≥10:</b>  Вы убедились, что здесь безопасно. Продолжите поход.<br><b>1-9:</b> Во тьме всё ещё могли скрываться опасности. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Основать даже небольшое поселение под землёй — задача не из лёгких. Для начала вам придётся прорубить вентиляционные шахты, чтобы зажечь огонь.</b></i></p><p><b>Защитник. </b>Один из персонажей в походе должен провести проверку <might>, чтобы копать. +2, если у него есть <dig>, +2, если у него есть <stoneworking>, а также +2 за каждое сброшенное из его инвентаря дерево (не более +6).<br><b>≥12:</b>  Вы перестроили грот под свои нужды. Продолжите поход.<br><b>1-11:</b>  Вам не удалось создать условия для жизни под землёй. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Вам предстояло отметить путь к подземному убежищу, чтобы ваши люди могли жить там постоянно. </b></i></p><p><b>Защитник. </b>Один из персонажей в походе должен провести проверку <awareness>, чтобы оставить метки, ведущие в грот. +4, если у него есть отметка летописца [i], +2, если у него есть отметка изобилия [ii], +4, если у него есть «Карта», и +2, если он <i>любознательный</i>.<br><b>≥12:</b>  По вашим меткам люди смогут безопасно добраться до грота. Завершите этот поход и достигните соответствующей цели. <br><b>1-11:</b>  Вам не удалось создать понятную систему меток. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<scribe>"},{"label":"ii","image":"<plenty>"}]},{"id":"outcomes-428","code":"428","description":{"en":"","ru":"<p><i><b>Вы заметили мелкие трещины на лбу чудища. Видимо, там, куда попадал свет, его кожа становилась хрупкой...</b></i></p><p>Выберите и разыграйте одно: <br><b>А. От ваших мощных ударов трещины превратились в глубокие разломы. Большой кусок головы чудища откололся и с грохотом рухнул на землю. </b>Если <sun>— текущее знамение или у вас есть <stoneworking>, завершите встречу. Разозлите чудище на 1. Чудище сбегает. Затем, если у любого персонажа, животного-компаньона или в сооружении-хранилище есть предмет со словом «разрушительный» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Разрушительный осколок» (ВЩ85).<br><b>Б. Вы на мгновение потеряли хватку, и чудище сбросило вас с головы.</b> Получите <minor_injury>. Завершите встречу и сбегите.</p>"},"repeatable":false},{"id":"outcomes-430","code":"430","description":{"en":"","ru":"<p><i><b>Вы с волнением подняли глаза от котлов с едой, чтобы увидеть, как принимают угощение. Люди у костра ворчали, без особого энтузиазма ковыряясь в мисках. Никто не просил добавки.</b></i></p><p>Завершите текущее испытание.</p><p>Если цель «Приготовьте главное блюдо» не выполнена, добавьте <unrest><unrest><unrest>(уменьшите добавленное таким образом недовольство на 1 за каждое блюдо, которое вы приготовили в этой партии).<br>Если цель «Сделайте запасы» не выполнена, добавьте <unrest><unrest><unrest><unrest>(уменьшите добавленное таким образом недовольство на 1 за каждые 2 жетона на этой карте цели, округляя в большую сторону).</p>"},"repeatable":false},{"id":"outcomes-431","code":"431","description":{"en":"","ru":"<p><i><b>Чудище смотрело на вас, ожидая подношения. Вы пришли подготовленными?</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Преподнесите чудищу дар. </b>Если у вас есть обработанный материал или предмет в инвентаре, сбросьте 1 обработанный материал или предмет. Успокойте чудище на 1.<br><b>Б. Не преподносите дар. </b>Разозлите чудище на 1.</p><p>Затем продолжите встречу.</p>"},"repeatable":false},{"id":"outcomes-432","code":"432","description":{"en":"","ru":"<p><i><b>Течение унесло вас вниз по реке, неумолимо швыряя из стороны в сторону. Куда вас вынесет — кто знает? Ваша судьба была во власти воды.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Вас унесло в неисследованные земли.</b> Если у вашего участка местности хотя бы  2 открытые соседние границы, а также если есть хотя бы 1 ещё не помещённая основа местности и хотя бы 3 ещё не помещённых участка вашего текущего региона (не считая начального участка, если применимо), то <outcome> 283.<br><b>Б. Вас унесло в неожиданном направлении. </b>Если хотя бы на 1 соседнем участке местности есть озеро, река или болото, переместите туда персонажа, выбрав участок случайным образом.<br><b>В. Вы попали в преграду на реке.</b> Потеряйте <energy><energy>. Получите 1 дерево и 1 волокно.</p>"},"repeatable":false},{"id":"outcomes-434","code":"434","description":{"en":"","ru":"<p><i><b>Свет кометы привёл вас к одинокому коралловому отростку. Он подрагивал, словно вторя вашему дыханию. </b></i></p><p>Проведите проверку <conviction>, чтобы узнать больше о долине. +2, если вы <i>любознательный</i>, и +2, если у вас есть отметка коралла.<br><b>≥11:</b>  Вы протянули руку и коснулись коралла — он дрогнул, а затем стал блёкнуть. Получите 1 мёртвый коралл. Затем можете добавить <lore> или вместо этого потратить <lore> и уменьшить один из своих недугов. <br><b>7-10:</b>  Вы нерешительно потянулись к кораллу, и он отпрянул. Добавьте <lore>.<br><b>1-6:</b>  Вы поспешно удалились. Без эффекта.</p>"},"repeatable":false,"marks":[{"label":"","image":"<coral>"}]},{"id":"outcomes-438","code":"438","description":{"en":"","ru":"<p><i><b>Сквозь туман вы увидели их: огромные, величественные шагающие хребты. Они двигались над едким маревом, неся на своих спинах последние островки жизни.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. С осторожностью отправьтесь в этот край. </b>Если на стене первобытной пещеры есть отметка тумана [i], поместите своего персонажа на любой участок Ураганных холмов, где есть хотя бы 1 шагающий хребет. Затем добавьте <lore><lore><lore>.<br><b>Б. Исследуйте эту землю ужасных вихрей. </b>Если у вас есть хотя бы 2 неразмещённые основы местности, на стене первобытной пещеры изобразите историю о бурлящем тумане, включив в неё отметку <cloud>, отметку тумана [i] и отметку открытия [ii]. Добавьте к целям карту «Пройдите сквозь туман» (ЦЯ25). Затем подготовьте регион Ураганных холмов, как описано на с. 214.<br><b>В. Похоже, жгучий туман распространился на другие земли и на время сделал их опасными.</b> Если у вас нет неразмещённых основ местности, поместите случайный участок Ураганных холмов рядом со своим участком (не в ячейку основы местности), а затем поместите своего персонажа на него. До конца текущего испытания считайте этот участок частью региона Ураганных холмов (см. подробнее на с. 214). Завершив испытание, верните в коробку этот участок местности вместе с жетонами и накладками на нём. Персонажи, которые находились на убранном участке, умирают.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<mist>"},{"label":"ii","image":"<discovery>"}]},{"id":"outcomes-439","code":"439","description":{"en":"","ru":"<p><i><b>Оставалась лишь одна надежда: провести народ через перевал и покинуть долину. Вы собрались с силами и повели людей за собой, чтобы спастись из сжимающейся вокруг вас ледяной хватки зимы.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><i><b>Когда вы приблизились к перевалу, пошёл снег. Конечности занемели, а белое покрывало всё плотнее укрывало долину. </b></i></p><p><b>Группа, погода. </b>Все персонажи в походе должны провести проверку <might>, чтобы справиться с холодом. +2, если у персонажа есть <i>одежда</i>, +2, если у него есть предмет с <fire>, и +2, если он <i>неукротимый</i>.<br><b>≥11:</b>  Вы проложили путь сквозь глубокий снег, и за вами смогли последовать другие. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-10:</b>  Зима крепко сжала вас в своих объятиях — вы спотыкались и с трудом удерживались на ногах, пробираясь сквозь снег. Получите <major_disease> и <minor_disease>. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore><lore>, чтобы провести проверку ещё раз. Если поход окончился неудачно при таком результате, поместите на свой участок неудачный выход (<minor_boost>).</p><p><b><i>Надежда гасла, людей охватил страх. Кто‑то должен был вдохновить их!</i></b></p><p><b>Защитник. </b>Один из персонажей в походе должен провести проверку <conviction>, чтобы воодушевить людей. +1 за каждого персонажа в походе, у которого есть карта легенды, и +4, если цель «Сделайте запасы» достигнута в течение этого испытания.<br><b>≥13:</b>  Вы рассказали о своих свершениях и о предках, чьи истории вы несёте с собой. Воодушевившись, люди вновь обрели силы. Продолжите поход.<br><b>1-12:</b>  Ваши слова утонули в снегу, и люди повернули назад. Поход окончился неудачно. Поместите на свой участок неудачный выход (<minor_boost>).</p><p><b><i>Вдруг вас охватила леденящая дрожь — вы увидели, как огромный пласт снега сорвался с перевала, грозя погрести вас под собой и отрезать путь к спасению!</i></b></p><p><b>Группа, угроза. </b>Все персонажи в походе должны провести проверку <dexterity> или <awareness>, чтобы избежать снежной лавины. +2, если у персонажа есть предмет для <i>исследования</i>, +2, если персонаж <i>осторожный</i>, и +6, если цель «Воззовите к чудищу» достигнута в течение этого испытания. Также персонаж может получить одну или несколько <major_injury>, чтобы добавить 1 к результату за каждую (не более +4; персонаж не может добровольно стать недееспособным таким способом).<br><b>≥13:</b>  Вы бежали, не оглядываясь, пока за вами гналась снежная буря. Вдруг вам показалось, будто кто-то позади вас сдерживает лавину. Неужели это было чудище? Или предки? А может, сама долина? Времени, чтобы оглянуться, не было… Если хотя бы один персонаж получил этот результат, завершите этот поход и достигните соответствующей цели.<br><b>1-12:</b>  Вы оказались погребены под снегом и навеки остались в долине. Ваш персонаж умирает и становится легендой. Если все персонажи получили этот результат, то <outcome> 475.</p>"},"repeatable":false},{"id":"outcomes-440","code":"440","description":{"en":"","ru":"<p><i><b>Когда сменялись эры, чума охватила ваши земли, наводя ужас на людей.</b></i></p><p>На стене первобытной пещеры изобразите историю о годах несчастья, включив в неё отметку ужаса [i] и отметку чумы [ii]. Уберите <population><population>. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Справьтесь с чумой. </b>Бросьте <1d6> и уберите столько <population>, сколько выпало на <1d6>.<br><b>Б. Побудите общину построить санитарные сооружения. </b>Если вы спроектировали мусорную яму, постройте по одному такому сооружению в каждом из поселений, где его ещё нет, не тратя <energy> и ресурсы. Если в поселении достигнуто максимальное количество сооружений, разрушьте 1 случайное сооружение в таком поселении, чтобы построить мусорную яму. Добавьте <unrest><unrest>.<br><b>В. Выживите благодаря подготовке. </b>Если в каждом поселении есть мусорная яма, без эффекта.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<harrowing>"},{"label":"ii","image":"<plague>"}]},{"id":"outcomes-442","code":"442","description":{"en":"","ru":"<p><i><b>Среди первобытных камней и костей древних чудищ вы увидели, как сменялись поколения Сплетения — расцветали, умирали, а затем расцветали вновь. Вы узрели великое семя. Было ли это дитя Сплетения?</b></i></p><p>Получите <major_boost> к <conviction> и добавьте <lore><lore><lore>.</p>"},"repeatable":false},{"id":"outcomes-443","code":"443","description":{"en":"","ru":"<p><i><b>Вы с трудом прошли сквозь клубящуюся пыль у логова чудища. </b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><b><i>Круглые насыпи, образующие каменное жилище чудища, было непросто пробить. Быть может, если найти подходящие точки для удара, вам удастся пробраться внутрь.</i></b></p><p><b>Защитник, чудо.</b> Один из персонажей в походе должен провести проверку <awareness>, чтобы пробить стену. +2, если у него есть <stoneworking>, и +2 за каждый его предмет для <i>исследования</i>.<br><b>≥10:</b>  Вы ударили по тонкому участку стены, и вам открылась сеть полых проходов. Продолжите поход.<br><b>1-9:</b>  Вы не смогли пробить вход в стене. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><b><i>В узких туннелях вас всё сильнее охватывал страх.</i></b></p><p><b>Группа, угроза. </b>Все персонажи в походе должны провести проверку <conviction>, чтобы сохранить спокойствие. +2, если у персонажа есть предмет с <fire>, и +2, если персонаж <i>неукротимый</i>. <br><b>≥10:</b>  Вы твёрдо шли к цели. Продолжите поход.<br><b>1-9:</b>  Вас охватила паника, и вы стали отступать. Если все персонажи получили этот результат, поход окончился неудачно. </p><p><i><b>Извилистые туннели привели вас к полости с озером из разъедающей кислоты. Вероятно, именно с её помощью чудище прокладывало себе ходы. Если так, то, возможно, эта жидкость сможет пробить и его неуязвимую каменную кожу — нужно только пропитать оружие кислотой.</b></i></p><p><b>Защитник, угроза. </b>Один из персонажей в походе должен провести проверку <dexterity>, чтобы собрать немного жидкости. +4, если в журнале записан хотя бы 1 секрет этого чудища.<br><b>≥10:</b>  Вам удалось собрать немного едкой жижи. Завершите этот поход и достигните соответствующей цели.<br><b>1-9:</b>  Ваша рука неловко дёрнулась, и немного кислоты попало на кожу. Получите <major_injury><major_injury>. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-445","code":"445","description":{"en":"","ru":"<p><i><b>Вы замахнулись, но оружие дрогнуло в вашей руке. Это существо несло в себе жизнь и смерть. Если вы были в силах его убить — имели ли вы на это право? Прервёт ли его смерть круговороты времён года и судеб? Станет ли убийство этого ужасного, но совершенного существа вашей собственной западнёй — каплей янтаря, навеки заключившей муху? Под тяжестью этих мыслей сознание покинуло вас. А когда вы очнулись, то увидели, что ваше оружие превратилось в яркий цветущий побег. Чудище исчезло. Вы знали: оно всё ещё наблюдает за вами. Но в его скрытом взгляде не чувствовалось злобы.</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest><unrest><unrest>. Установите значение нрава чудища на 2. На стене первобытной пещеры изобразите историю о нарушенном круговороте, включив в неё отметку бодрствующего чудища, отметку осторожности [i] и отметку становления [ii]. Навсегда увеличьте <conviction> и <awareness> на 1 (не более чем до 7) каждого персонажа, участвовавшего в этом походе на момент его завершения. Также добавьте отметку бодрствующего чудища и отметку становления [ii] на сторону легенды карт этих персонажей. Если у персонажа, завершившего последнее испытание этого похода, есть <i>оружие </i>и ни у одного персонажа, животного-компаньона или в сооружении-<i>хранилище</i> нет предмета со словом «живой» в названии, этот персонаж должен сбросить <i>оружие </i>и получить карту предмета «Живой росток» (ВЩ90).</p><p>Затем завершите текущую эру. См. с. 204, чтобы <era3>начать эру 3.</era3></p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":"<growth>"}]},{"id":"outcomes-446","code":"446","description":{"en":"","ru":"<p><i><b>В тумане долины возвышался огромный монолит. Какое бы существо ни обитало в этом странном сооружении, оно покинуло его много солнц и лун назад. </b></i></p><p>Разыграйте первое, что можете:<br><b>А. Застыньте в изумлении перед гигантской гробницей. </b>Если есть хотя бы 1 непомещённая накладка логова, поместите случайное логово неактивной стороной вверх на любой участок только что добавленной основы местности. Бросьте <1d6>, чтобы поместить логово в соответствующий район: [1-2] А, [3-4] Б, [5-6] В. Логово должно быть помещено в район без накладок. Подробнее о логовах чудищ см. на с. 211–212. На стене первобытной пещеры изобразите историю о древней гробнице, включив в неё отметку чудища, чьё логово вы поместили, и отметку открытия.<br><b>Б. Придите в ужас, не в силах смотреть на древний обелиск, рассекающий туман. </b>Поместите жетоны тайны на только что добавленную основу местности — по 1 жетону на каждый участок без персонажа. Затем сбегите на случайный участок, не находящийся на только что добавленной основе местности.</p>"},"repeatable":false,"marks":[{"label":"","image":"<discovery>"}]},{"id":"outcomes-447","code":"447","description":{"en":"","ru":"<p><i><b>Во тьме под долиной раздавалось эхо множества шагов. Ваш народ освоил подземные врата, и путешествия между поселениями отныне не представляли труда. Быстрое и безопасное передвижение позволило знаниям и культуре расцвести, ведь расстояние между частями общины теперь не имело большого значения.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о раскопанных путях, включив в неё отметку расколотой земли [i] и отметку подземного мира [ii].</p><p>В конце этого испытания завершите текущую эру. См. с. 204, чтобы <era3>начать эру 3</era3>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<brokenearth>"},{"label":"ii","image":"<underworld>"}]},{"id":"outcomes-448","code":"448","description":{"en":"","ru":"<p><i><b>Лунный свет сделал вас мишенью для крупной хищной птицы. Она устремилась к вам, готовясь схватить как добычу!</b></i></p><p>Проведите проверку <conviction>, чтобы устоять. +2, если вы <i>неукротимый</i>, и +2, если у вас есть предмет с <fire>.<br><b>≥12:</b>  Вы смотрели прямо на птицу, и в последний миг она резко свернула в сторону, осыпав вас перьями. Получите 2 пера.<br><b>8-11:</b>  Птица пронеслась мимо, но порыв ветра от её крыльев едва не сбросил вас с горного склона. Если у вас есть «Скальный крюк» или «Трость», без эффекта. В противном случае получите <major_injury>.<br><b>1-7:</b>  Птица схватила вас и унесла в небо. Вы яростно вырывались, но её хватка оставалась крепкой. Наконец она сбросила вас в гнездо, и вы выбрались оттуда, пока она пробуждала ото сна своё голодное потомство. Потеряйте <energy> и получите <major_injury>. Затем переместите своего персонажа на случайный неисследованный участок местности, если возможно, и исследуйте его. В противном случае переместите персонажа на любой участок местности, выбрав участок с горами, если возможно.</p>"},"repeatable":false},{"id":"outcomes-449","code":"449","description":{"en":"","ru":"<p><i><b>Вы поднесли свет к огромному лику чудища — и его маска треснула. Вы просунули руку внутрь разлома и что‑то нащупали. Из трещины хлынула жидкость, и чудище сбросило вас со своей массивной головы. Вы рухнули на землю. Очнувшись, вы лежали в разлитой жидкости, сжимая в руке нечто странное.</b></i></p><p>Разозлите чудище на 1. Завершите встречу. Чудище сбегает. Получите <major_injury>.</p><p>Затем, если у любого персонажа, животного-компаньона или в сооружении-хранилище есть предмет со словом «симбиотический» в названии, получите 2 дичи. В противном случае получите карту предмета «Симбиотическое яйцо» (ВЩ93).</p>"},"repeatable":false},{"id":"outcomes-452","code":"452","description":{"en":"","ru":"<p><i><b>Постоянно вступая в схватки с новыми хищниками, вы заставили этих созданий уважать силу человека. В долине установилось хрупкое перемирие.</b></i></p><p>В конце этого дня можете завершить текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о сломанных клыках, включив в неё отметку зверобоя.</p>"},"repeatable":false,"marks":[{"label":"","image":"<beastslayer>"}]},{"id":"outcomes-461","code":"461","description":{"en":"","ru":"<p><i><b>Чем выше вы взбирались по громадному рогу чудища, тем более хрупкой становилась поверхность. Когда под вашей рукой откололся кусок рога, вы обнаружили нечто неожиданное...</b></i></p><p>Завершите встречу. Разозлите чудище на 1. Чудище сбегает. Затем, если у любого персонажа, животного-компаньона или в сооружении-<i>хранилище </i>есть предмет со словом «тёмный» в названии, получите 2 сокровища этого чудища; в противном случае получите карту предмета «Тёмный шар» (ВЩ92).</p>"},"repeatable":false},{"id":"outcomes-473","code":"473","description":{"en":"","ru":"<p><i><b>На свету движения чудища становились вялыми и скованными, словно на него давил огромный груз. Существо медленно отходило прочь, пока оцепенение не завладело им. </b></i></p><p>Завершите встречу. Успокойте чудище на 1. Чудище сбегает.</p>"},"repeatable":false},{"id":"outcomes-475","code":"475","description":{"en":"","ru":"<p><i><b>Ваш народ отчаянно искал путь к спасению, осматривая каждый уступ и проход в надежде найти выход из долины, но всё было тщетно. Когда на долину опустилась последняя зима, история вашего народа утихла и эхо её растворилось в ветре и снегах.</b></i></p><p>Завершите кампанию. Ваша община <b>исчезла</b>. См. раздел «Конец кампании» в правилах игры на с. <rulebook>97</rulebook>.</p><p>Такой конец хоть и далёк от счастливого, но он всё же может послужить уроком для народов, которые заселят эту долину в будущем. Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!</p><p>Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. <rulebook>97</rulebook> или раздел «Бесконечный режим» на с. <rulebook>102</rulebook>.</p>"},"repeatable":false,"marks":[{"label":"","image":"<qrcode>"}]},{"id":"outcomes-478","code":"478","description":{"en":"","ru":"<p><i><b>Осколок прорвался сквозь покров облаков, превращая огромные небесные глыбы в туман. Когда он врезался в землю, раздался оглушительный треск, поваливший деревья и расколовший горы. Среди разрушения вы увидели, как начинают расползаться коралловые побеги. Затем видение исчезло.</b></i></p><p>Поместите неактивные коралловые заросли на любой участок местности, выбрав неисследованный участок без накладок, если возможно. Бросьте <1d6>, чтобы поместить заросли в соответствующий район: [1-2] A, [3-4] Б, [5-6] В. Поместите жетон тайны на этот участок, если на нём нет персонажа. Затем верните в коробку карту «Расходящиеся пути» (НЭ01).</p>"},"repeatable":false},{"id":"outcomes-481","code":"481","description":{"en":"","ru":"<p><i><b>Когда последние следы цивилизации исчезли под кораллами, вы перестали узнавать ваш народ. Вы могли присоединиться к тем, кто шёл за избранником кометы, или сбежать и слиться с дикой природой. Но то, что вы когда‑то знали, исчезло навсегда.</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о непостижимом будущем, включив в неё отметку коралла [i] и отметку несчастья [ii]. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Примите объятия кометы.</b> Завершите кампанию. Ваша община исчезла. См. раздел «Конец кампании» в правилах игры на с. <rulebook>97</rulebook>.<br>Такой конец хоть и далёк от счастливого, но он всё же может послужить уроком для народов, которые заселят эту долину в будущем. Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом! Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. <rulebook>97</rulebook> или раздел «Бесконечный режим» на с. <rulebook>102</rulebook>.<br><b>Б. Останьтесь собой любой ценой. </b>Добавьте к грядущим испытаниям карту «Исход» (ИЯ09).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<coral>"},{"label":"ii","image":"<misfortune>"},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-482","code":"482","description":{"en":"","ru":"<p><i><b>Ваш народ оказался на самой грани из‑за голода. Это время лишений надолго останется в памяти общины.</b></i></p><p>Завершите текущее испытание.</p><p>Уберите <population><population>. На стене первобытной пещеры изобразите историю о страшном годе, включив в неё отметку ужаса. Добавьте карту «Ворчание у костра» (НО01) в колоду ночи, если возможно.</p>"},"repeatable":false,"marks":[{"label":"","image":"<harrowing>"}]},{"id":"outcomes-484","code":"484","description":{"en":"","ru":"<p><i><b>Находясь на вершине головы чудища, вы заметили, что его каменная кожа стала хрупкой и потрескалась под палящим солнцем. Вы могли бы попытаться залатать трещины, чтобы облегчить страдания существа. </b></i></p><p>Завершите встречу. Затем можете сбросить 2 сокровища этого чудища, чтобы успокоить его на 1.</p>"},"repeatable":false},{"id":"outcomes-485","code":"485","description":{"en":"","ru":"<p><i><b>Когда одна эра сменяла другую, чудище обрушило на вас свою месть. Оно разорило одно из ваших поселений и обратило людей в бегство, разогнав их по всей долине. Следующие поколения выросли в страхе перед затмевавшим небо чудищем…</b></i></p><p>Выберите чудище с активным логовом и с самым высоким значением нрава. На стене первобытной пещеры изобразите историю о пугающих временах, включив в неё отметку ужаса [i] и отметку этого чудища, украшенную отметкой гнева [ii]. Случайное поселение становится руинами. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Встретьте чудище с оружием. </b>Бросьте <1d6> и уберите столько <population>, сколько выпало на <1d6>.<br><b>Б. Запретите своему народу вмешиваться в дела чудищ. </b>Запишите «Отдыхать на участке с активным логовом чудища» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет. Добавьте <unrest><unrest>. Добавьте отметку табу [iii] к только что изображённой истории.<br><b>В. Покиньте регион, где обитает чудище.</b> Каждое поселение в регионе с логовом чудища становится руинами.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<harrowing>"},{"label":"ii","image":"<wrath>"},{"label":"iii","image":"<taboo>"}]},{"id":"outcomes-486","code":"486","description":{"en":"","ru":"<p><i><b>Вы соскользнули по белой пряди чудища, демонстрируя ему занятный предмет. Чудище с живым интересом наблюдало за вами. Откуда‑то из глубины его шерстяного покрова вдруг появилась диковинная вещь — чудище предлагало обмен.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Заключите обмен. </b>Если у вас в инвентаре есть обработанный материал или предмет, сбросьте 1 обработанный материал или предмет, чтобы завершить встречу. Успокойте чудище на 1. Затем, если у любого персонажа, животного-компаньона или в сооружении-<i>хранилище </i>есть предмет со словом «симбиотический» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Симбиотическое яйцо» (ВЩ93).<br><b>Б. Откажитесь от обмена. </b>Завершите встречу. Разозлите чудище на 2.</p>"},"repeatable":false},{"id":"outcomes-490","code":"490","description":{"en":"","ru":"<p><i><b>Ваши поиски источника чёрного следа в небе завершились лишь досадой, когда вы добрались до края долины. Вскоре дым рассеялся, превратившись в воспоминание. Быть может, вашим потомкам удастся раскрыть то, что ускользнуло от вас…</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о клубящемся дыме, включив в неё отметку <cloud> и отметку тайны.</p>"},"repeatable":false,"marks":[{"label":"","image":"<mystery>"}]},{"id":"outcomes-491","code":"491","description":{"en":"","ru":"<p><i><b>Вы поймали странное существо с мягким телом и множеством конечностей и в его желудке нашли нечто похожее на орудие. Видимо, существо проглотило его. Кем же было сделано это орудие? Жителем деревни или каким‑то чужаком?</b></i></p><p>Получите предмет «Костяной нож» (ВЩ01). Запишите его код (Красный 2344) на странице «Рецепты» в журнале.</p>"},"repeatable":false},{"id":"outcomes-492","code":"492","description":{"en":"","ru":"<p><i><b>Ваши попытки усмирить чудище окончательно потерпели неудачу. Его ответный удар обрушился словно буря, уничтожив величайшие творения вашего народа и разрушив все надежды, что вы питали…</b></i></p><p>Уберите <population> за каждый жетон на карте «Дайте отпор чудищу». Затем на стене первобытной пещеры изобразите историю о вечном гневе, включив в неё отметку бодрствующего чудища, украшенную отметкой гнева [i]. </p><p>Поочерёдно для каждого из поселений совместно выберите один из следующих вариантов и разыграйте его:<br><b>А. Сражайтесь до конца. </b>Бросьте <1d6>. Разрушьте столько любых сооружений в поселении и уберите столько <population>, какой результат выпал на  <1d6>.<br><b>Б. Бегите от чудища. </b>Поселение становится руинами. Уберите <population><population><population>.<br><b>В. Отвлеките чудище подношением, пока ваш народ спасается бегством. </b>Если на стене первобытной пещеры есть отметка изобилия [ii] и в журнале записано хотя бы 2 секрета этого чудища, поселение становится руинами. Этот вариант можно выбрать только один раз.</p><p>Затем завершите текущие испытание и эру. См. с. 204, чтобы <era3>начать эру 3</era3>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<wrath>"},{"label":"ii","image":"<plenty>"}]},{"id":"outcomes-493","code":"493","description":{"en":"","ru":"<p><i><b>Вы столкнулись с чужаками. Когда вы подошли, они жестами велели вам остановиться. Чтобы наладить более тесные отношения, придётся завоевать их доверие.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><i><b>Обитатели лагеря казались вам настороженными. Кто‑то должен был первым прервать тишину.</b></i></p><p><b>Защитник. </b>Один из персонажей в походе должен провести проверку <conviction> или <awareness>, чтобы поприветствовать незнакомцев. +2, если он <i>терпеливый</i>, и +2 за каждый жетон еды, который он сбросит из своего инвентаря (не более +4).<br><b>≥12:</b>  Незнакомцы тепло ответили на ваше приветствие. Продолжите поход.<br><b>1-11:</b>  Напряжение ничуть не спало. Добавьте <unrest>. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Вы произвели хорошее первое впечатление на незнакомцев и подошли к костру. Обитатели лагеря говорили на языке, который был вам знаком, но всё же не до конца понятен. Чтобы сохранить расположение незнакомцев, вам нужно было узнать их обычаи.</b></i></p><p>Группа. Все персонажи в походе должны провести проверку <awareness>, чтобы найти общий язык. +2, если у персонажа есть карта легенды, и +4, если у него есть <music>.<br><b>≥11:</b>  Вы узнали, что между вашим народом и этими чужаками много общего. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-10:</b>  Видимо, ваши народы разошлись в очень далёком прошлом, потому что вы нашли мало общего. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не сбросит карту легенды или не потратит <lore><lore><lore>, чтобы провести проверку ещё раз.</p><p><i><b>Вы почувствовали себя комфортно среди чужаков, но знакомство всё ещё было слишком поверхностным. Чтобы вас пригласили в дом, нужно было преподнести дар, который показал бы ваши добрые намерения.</b></i></p><p><b>Защитник. </b>Один из персонажей в походе должен провести проверку <conviction> и сбросить предмет или материал, чтобы преподнести дар. +2, если персонаж изобретательный. Также +2, если он сбросит предмет, либо +4, если сбросит редкий материал.<br><b>≥12:</b>  Чужаки ответили вам щедрым подарком. Положите 1 коралл, 1 лунную кровь и 1 шёлк в мешочек, затем достаньте один материал из мешочка и получите его в необработанном виде. Завершите этот поход и достигните соответствующей цели.<br><b>1-11:</b>  Чужаки, похоже, остались равнодушны к вашему дару. Добавьте <unrest><unrest>. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-494","code":"494","description":{"en":"","ru":"<p><i><b>Люди заболевали повсюду, словно болезнь передвигалась теми же тропами, по которым ваш народ ходил между поселениями.</b></i></p><p>За каждый участок местности с поселением бросьте <1d6>. +2, если в поселении есть мусорная яма.<br><b>1-2:</b>  Поместите вспышку болезни на этот участок местности. Затем каждый персонаж на этом участке получает <major_disease>. <br><b>3-4:</b>  Поместите вспышку болезни на этот участок местности.<br><b>≥5:</b>  Без эффекта.</p>"},"repeatable":false},{"id":"outcomes-495","code":"495","description":{"en":"","ru":"<p><i><b>Вы лавировали среди опасных шипов на спине чудища, чтобы добраться до его гривы. Оказавшись на вершине панциря, вы с удивлением заметили, что голова чудища склонилась прямо к вам и вы оказались с ним лицом к лицу. Нужно было быстро решать, какой дар вы готовы предложить…</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Отдайте обработанный материал. </b>Сбросьте 1 обработанный материал, чтобы получить <major_boost> к любой характеристике.<br><b>Б. Достаньте со дна сумы потрёпанные лоскуты меха и волокон. </b>Разозлите чудище на 1.</p><p>Затем завершите встречу.</p>"},"repeatable":false},{"id":"outcomes-497","code":"497","description":{"en":"","ru":"<p><i><b>Вы не были уверены, что это может значить, но понимали, что ничего хорошего это не сулит.</b></i></p><p>Добавьте карту «Падение небес» (ИВ04) к грядущим испытаниям.</p>"},"repeatable":false},{"id":"outcomes-498","code":"498","description":{"en":"","ru":"<p><i><b>Чудище, что рыскало по долине, становилось всё смелее.</b></i></p><p>Каждое бодрствующее чудище получает <major_boost> ко всем своим характеристикам.</p>"},"repeatable":false},{"id":"outcomes-499","code":"499","description":{"en":"","ru":"<p><i><b>Чудище завершило раскопки и, похоже, было довольно результатом. Там, где оно копало, образовался ледяной вал. </b></i></p><p>Поместите накладку ледяного отпечатка активной стороной вверх на любой участок местности с жетоном следов. Выберите район без накладки, но с пропастью, если возможно. См. правила ледяного отпечатка на с. 212.</p><p>Затем уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-502","code":"502","description":{"en":"","ru":"<p><i><b>Всего лишь мысль о кратере отпугивала ваших людей от места падения. Чтобы чувствовать себя в безопасности, вам приходилось держаться подальше от паникёров на своём пути к кратеру…</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>). </p><p><i><b>Дозорные были уже совсем близко, но возможно, вам удастся найти укрытие, чтобы спрятаться от них…</b></i></p><p><b>Группа, угроза.</b> Все персонажи в походе должны провести проверку <dexterity>, чтобы уйти от преследователей. +4, если на соседнем с персонажами участке местности есть пещера или пропасть, +2, если у персонажа есть <i>накидка</i>, и +2, если он <i>хитрый</i>.<br><b>≥12:</b>  Вы избежали столкновения с дозорными. Получите <minor_boost> к  <conviction>. Затем продолжите этот поход: <outcome> 622.<br><b>10-11:</b>  Дозорные преследовали вас какое-то время, пока не сбились со следа. Добавьте <unrest>. Затем продолжите этот поход: <outcome> 622.<br><b>1-9:</b>  Вы сцепились с преследователями, прежде чем вырваться на свободу. Получите <major_injury>, затем добавьте <unrest><unrest>. Покиньте поход и сбегите. Если все персонажи получили этот результат, поход окончился неудачно.</p>"},"repeatable":false},{"id":"outcomes-503","code":"503","description":{"en":"","ru":"<p><i><b>Вы знали, что эти вибрации исходят из странного подземного мира долины и предвещают появление новых коралловых зарослей. Обыскивая окрестности, вы нашли перламутровый отросток и быстро срезали его, пока тот был спящим.</b></i></p><p>Получите 1 мёртвый коралл. Если на стене первобытной пещеры есть отметка коралла, вместо этого получите 2 мёртвых коралла.</p>"},"repeatable":false,"marks":[{"label":"","image":"<coral>"}]},{"id":"outcomes-504","code":"504","description":{"en":"","ru":"<p><i><b>Громадное чудище появилось в долине.</b></i></p><p>Выберите случайное чудище, у которого нет логова в долине. На стене первобытной пещеры изобразите историю о великом появлении, включив в неё отметку этого чудища. Затем это чудище появляется в долине и становится бодрствующим (см. раздел «Появление чудища» в правилах игры на с. <rulebook>74</rulebook>). Поместите его логово активной стороной вверх на участок местности без накладки и с его предпочитаемой особенностью местности, если возможно.</p>"},"repeatable":false},{"id":"outcomes-505","code":"505","description":{"en":"","ru":"<p><i><b>Это был труд не одного поколения: пусть вы и начали это дело, но довести его до конца предстояло уже вашим потомкам. Растения, выбранные вами, расцвели в долине небольшими островками, и год за годом их становилось всё больше.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Сосредоточьтесь на изучении лесов. </b>Если в долине есть хотя бы 1 участок Дивной долины, добавьте <population><population><population>. Затем на стене первобытной пещеры изобразите историю о резцах по дереву, включив в неё отметку травничества [iii], отметку изобилия [iv] и отметку Дивной долины [i]. Добавьте карту ДЛ13 в колоду добычи припасов в лесу, если возможно.<br><b>Б. Сосредоточьтесь на изучении степей. </b>Если в долине есть хотя бы 1 участок Поднебесной равнины, добавьте <population><population><population>. Затем на стене первобытной пещеры изобразите историю о хранителях равнин, включив в неё отметку травничества [iii], отметку изобилия [iv] и отметку Поднебесной равнины [ii]. Добавьте карту ДС13 в колоду добычи припасов в степи, если возможно.<br><b>В. Сосредоточьтесь на изучении Сплетения (если доступно). </b>Если в долине есть хотя бы 1 участок Сплетения, добавьте <population><population><population>. Затем на стене первобытной пещеры изобразите историю о цветущих лугах, включив в неё отметку травничества [iii], отметку изобилия [iv] и отметку Сплетения [v]. Добавьте карту ДП13 в колоду добычи припасов на полянах, если возможно.<br><b>Г. Откажитесь от красного мяса. </b>Добавьте <population><population><population><population>. На стене первобытной пещеры изобразите историю об обещании земли, включив в неё отметку травничества [iii], отметку изобилия [iv] и отметку табу [vi]. Запишите «Есть дичь ночью» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет. Добавьте отметку травничества на сторону легенды карты каждого персонажа. Затем разыграйте как можно больше из следующего:<br>1. Если в долине есть хотя бы 1 участок Дивной долины, добавьте карту ДЛ13 в колоду добычи припасов в лесу.<br>2. Если в долине есть хотя бы 1 участок Поднебесной равнины, добавьте карту ДС13 в колоду добычи припасов в степи<br>3. Если в долине есть хотя бы 1 участок Сплетения, добавьте карту ДП13 в колоду добычи припасов на полянах.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<verdantvale>"},{"label":"ii","image":"<skyreachplateau>"},{"label":"iii","image":"<herbalism>"},{"label":"iv","image":"<plenty>"},{"label":"v","image":"<tangle>"},{"label":"vi","image":"<taboo>"}]},{"id":"outcomes-506","code":"506","description":{"en":"","ru":"<p><i><b>Чудище сосредоточилось на раскатах грома.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Поднимите шум, чтобы напугать чудище. </b>Если у вас есть <music>, завершите встречу. Разозлите чудище на 2. Чудище сбегает.<br><b>Б. Затаите дыхание. </b>Если ваше значение <conviction>  равно хотя бы 3, завершите встречу. Затем, если у персонажа, животного-компаньона или в сооружении-хранилище есть предмет со словом «пламенный» в названии, получите 2 сокровища этого чудища; в противном случае получите карту предмета «Пламенная кровь» (ВЩ99).<br><b>В. Поспешно отступите. </b>Завершите встречу и сбегите.</p>"},"repeatable":false},{"id":"outcomes-508","code":"508","description":{"en":"","ru":"<p><i><b>Вашему народу не удалось обосноваться в долине, и без постоянного пристанища вам предстояло пережить суровую зиму. Но возможно, для вас в этих землях ещё таилась надежда.</b></i></p><p>Завершите текущее испытание.</p><p>Уберите <population><population><population>. Добавьте карту «Прибежище» (ИA03) к грядущим испытаниям.</p>"},"repeatable":false},{"id":"outcomes-509","code":"509","description":{"en":"","ru":"<p><i><b>Стоя под неистовствующим чудищем, вы сыграли умиротворяющую мелодию. Чудище склонило голову — его любопытству не было предела. Впитывая звуки вашей музыки, оно успокоилось и отступило. Когда оно уходило прочь, огромный бутон, оторвавшийся от тела чудища, опустился и раскрылся перед вами — в его лепестках скрывалось нечто неожиданное.</b></i></p><p>Завершите встречу. Успокойте чудище на 1. Чудище сбегает. Затем, если у персонажа, животного-компаньона или в сооружении-<i>хранилище </i>есть предмет со словом «шепчущий» в названии, получите 2 сокровища этого чудища; в противном случае получите карту предмета «Шепчущие нити» (ВЩ87).</p>"},"repeatable":false},{"id":"outcomes-511","code":"511","description":{"en":"","ru":"<p><i><b>Чудище оставило за собой извилистую цепочку спиральных борозд на земле. Наблюдая за этим петляющим узором, вы начали задумываться: не записывает ли оно что‑то своими следами?..</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Изучите странный след. </b>Если у чудища есть неоткрытая назначенная карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><b>Б. Найдите в этом узоре следы истории своего народа.</b> Получите карту знаний «Легенды» (ЗБ15), если у вас её нет, и возьмите 1 карту легенды. Если у вас уже есть карта легенды, вместо этого можете выбрать легенду из забытых вашей общиной, добавить одну из её отметок на сторону легенды карты своего персонажа и вернуть эту карту в колоду легенд.</p>"},"repeatable":false},{"id":"outcomes-512","code":"512","description":{"en":"","ru":"<p><i><b>Череда неудач во время великой охоты заставила ваш народ задуматься о том, сможет ли община пережить ближайшую зиму. Хоть урожая и хватило бы, чтобы прокормить людей, надвигающиеся холода заставляли людей сомневаться в этом.</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о неудавшейся охоте, включив в неё отметку несчастья.</p>"},"repeatable":false,"marks":[{"label":"","image":"<misfortune>"}]},{"id":"outcomes-514","code":"514","description":{"en":"","ru":"<p><i><b>Легенда согласилась взвалить на свои плечи ваши невзгоды и вновь выйти в мир, чтобы встретиться с великим испытанием лицом к лицу. Однако за это придётся заплатить: вы исчезнете в тумане времён.</b></i></p><p>Выберите карту легенды и перепишите с неё все сведения на карту нового персонажа, не отмечая клетку легенды. Затем отметьте клетку легенды на карте своего персонажа и замените карту своего персонажа на только что созданную.</p>"},"repeatable":false},{"id":"outcomes-515","code":"515","description":{"en":"","ru":"<p><i><b>Вы начали говорить и заметили, как вздрагивает шерсть на теле чудища, пока оно успокаивается. Когда вы закончили свой рассказ, несколько волосков чудища слегка коснулись вас, давая понять, что оно уразумело ваши намерения.</b></i></p><p>Успокойте чудище на 1. Получите <major_boost> к двум любым характеристикам. Затем завершите встречу.</p>"},"repeatable":false},{"id":"outcomes-516","code":"516","description":{"en":"","ru":"<p><i><b>В глубокой расселине в земле угадывалось место, где чудище склонилось, внимая какому‑то непостижимому зову.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Присмотритесь к глубокой расселине. </b>Если у чудища есть неоткрытая назначенная карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><b>Б. Постучите по земле, чтобы подать сигнал чудищу. </b>Чудище получает <minor_boost> к любой характеристике. Если на вашем участке местности есть <shelter>, вместо этого чудище получает <major_boost> к любой характеристике.</p>"},"repeatable":false},{"id":"outcomes-517","code":"517","description":{"en":"","ru":"<p><i><b>Тяжёлая лапа чудища обрушилась на вас, разом погрузив мир в непроглядную мглу. Когда вы пришли в себя, вокруг не было видно ни зги. Из стен, окружавших вас, доносился звук крошащихся камней. Вы поняли, что находились внутри чудища, и немедля начали искать в темноте хоть что‑то, что сможет помочь вам выбраться. Каменный пол под вами слабо вибрировал, и вы последовали за нарастающими толчками, исходящими от него, пока не нащупали мягкую гладкую поверхность. Вы вцепились в неё и, собравшись с силами, вырвали её из стены. Раздался громовой рёв, волна от которого вышвырнула вас из пасти чудища на землю. Вы потеряли сознание, а очнувшись, обнаружили, что всё ещё сжимаете в руке какой‑то странный материал…</b></i></p><p>Завершите встречу. Разозлите чудище на 1. Чудище сбегает. Затем, если у персонажа, животного-компаньона или в сооружении-<i>хранилище </i>есть предмет со словом «тёмный» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Тёмный шар» (ВЩ92).</p>"},"repeatable":false},{"id":"outcomes-521","code":"521","description":{"en":"","ru":"<p><i><b>Трещина в земле, оставленная чудищем, осторожно огибала одно‑единственное дерево. У его подножия была слышна птичья трель, лёгкая и певучая, словно возносившаяся к небесам. Неужели чудище пощадило этих птиц ради их песни?</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Понаблюдайте за узором переплетений. </b>Если у чудища есть неоткрытая назначенная карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><b>Б. Вслушайтесь в птичью песню, пытаясь понять поступок чудища. </b>Добавьте <minor_boost> к <awareness>. Если у вас есть <music>, вместо этого добавьте <major_boost> к <awareness>. Добавьте отметку песнопевца на сторону легенды карты своего персонажа.</p>"},"repeatable":false,"marks":[{"label":"","image":"<songweaver>"}]},{"id":"outcomes-525","code":"525","description":{"en":"","ru":"<p><i><b>Чудище стремительно бежало отсюда — там, где его копыта рассекали землю, оставались глубокие и скошенные следы.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Пройдите по следам и узнайте, почему оно так спешило. </b>Если у чудища есть неоткрытая назначенная карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><b>Б. Вглядитесь в следы. </b>Если <cloud>— текущее знамение, получите 3 воды и <minor_boost> к <dexterity> или <awareness>.</p>"},"repeatable":false},{"id":"outcomes-528","code":"528","description":{"en":"","ru":"<p><i><b>Взобравшись на темя чудища, вы постучали по рогам — существо повернулось, будто пытаясь найти что‑то невидимое у себя за спиной…</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Продолжите ритмично стучать, направляя чудище в одну сторону. </b>Завершите встречу. Чудище сбегает. Можете переместить своего персонажа на участок местности, куда сбежало чудище (не берите карту пути). Затем разозлите чудище на 2, если на участке местности, на который вы переместились, нет <shelter>.<br><b>Б. Соскользните в безопасное место, как только чудище отвлечётся. </b>Завершите встречу. Чудище сбегает. Затем разозлите чудище на 1, если на вашем участке местности нет <shelter>.</p>"},"repeatable":false},{"id":"outcomes-531","code":"531","description":{"en":"","ru":"<p><i><b>Чудище смотрело на вас — и вам оставалось лишь надеяться, что оно не увидит в вас добычу. Зная, что его успокаивают воспоминания, вы начали рассказывать историю…</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Поведайте легенду. </b>Если у вас есть карта легенды, сбросьте её, чтобы завершить встречу. Успокойте чудище на 1. Затем, если у персонажа, животного-компаньона или в сооружении-хранилище есть предмет со словом «шепчущий» в названии, получите 1 сокровище чудища; в противном случае получите карту предмета «Шепчущие нити» (ВЩ87).<br><b>Б. Сочините новую историю. </b>Если у вас есть усиление <awareness> или <conviction>, уменьшите это усиление, чтобы завершить встречу. <br><b>В. Промолчите. </b>Завершите встречу. Разозлите чудище на 1.</p>"},"repeatable":false},{"id":"outcomes-544","code":"544","description":{"en":"","ru":"<p><i><b>Ваши несгибаемая воля и упорство помогали добывать ресурсы, даже когда влияние коралла крепло. И чем больше вы работали, тем безопаснее становились земли для вашего народа.</b></i></p><p>На стене первобытной пещеры изобразите историю о стойкости, включив в неё отметку коралла [i] и отметку открытия [ii]. Разыграйте как можно больше из следующего:<br><b>А. Научитесь скользить меж деревьев, будто тень. </b>Если в долине есть хотя бы 1 участок Дивной долины, верните в коробку карту ДЛ06 из колоды добычи припасов в лесу.<br><b>Б. Прокрадитесь по степи, низко пригибаясь к траве, оставшись незамеченным. </b>Если в долине есть хотя бы 1 участок Поднебесной равнины, верните в коробку карту ДС06 из колоды добычи припасов в степи.<br><b>В. Проскользите по высокому пологу Сплетения, избегая страшных опасностей. </b>Если в долине есть хотя бы 1 участок Сплетения, верните в коробку карту ДП06 из колоды добычи припасов на полянах.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<coral>"},{"label":"ii","image":"<discovery>"}]},{"id":"outcomes-549","code":"549","description":{"en":"","ru":"<p><i><b>Вы сыграли зачаровывающую мелодию, и чудище последовало за вами. Даже когда вы перестали играть, оно продолжало двигаться следом, весело покачиваясь и сокрушая деревья и холмы своей тяжёлой поступью.</b></i></p><p>Завершите встречу. Успокойте чудище на 1. Чудище сбегает.</p>"},"repeatable":false},{"id":"outcomes-552","code":"552","description":{"en":"","ru":"<p><i><b>Когда вы оказывали помощь раненному в бою, вы узнали нечто пугающее: у некоторых людей из вашей общины кровь светилась странным коралловым сиянием. Одни считали, что эти люди прокляты, а другие верили, что это — благословение Скитальца.</b></i></p><p>Совместно выберите один из следующих путей развития общины:<br><b>А. Примите отмеченных кораллом. </b>Добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю о благословении Скитальца, включив в неё отметку <comet> и отметку коралла [i].<br>Б. Изгоните отмеченных кораллом. Уберите <population><population>. На стене первобытной пещеры изобразите историю о преданном доверии, включив в неё отметку раскола [ii]. Запишите «Обрабатывать коралл на участке с поселением» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<coral>"},{"label":"ii","image":"<schism>"}]},{"id":"outcomes-556","code":"556","description":{"en":"","ru":"<p><i><b>Вы вонзили оружие в бок великого создания, и янтарный свет хлынул из раны, обволакивая вас, словно смола, стекающая по дереву. Существо издало безжизненный, леденящий кровь вопль и рухнуло. Его огромное сверкающее око пронзало вас взглядом, пока свет в нём не угас. Поднимаясь на ноги перед гигантским телом, вы увидели, что все деревья, цветы и растения вокруг исчезли — осталась одна лишь зола.</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о поверженном древнем существе, включив в неё отметку битвы [i] и отметку бодрствующего чудища, украшенную отметкой крови чудища [ii]. Добавьте отметку крови чудища [ii] на сторону легенды карт персонажей, участвовавших в этом походе. Один из этих персонажей должен сбросить оружие, если возможно.</p><p>Затем игрок, чей персонаж прошёл финальную проверку похода, должен вычеркнуть клетку легенды и все неотмеченные клетки возраста на карте этого персонажа. Этот персонаж больше не стареет. Если он умирает во время испытания, каждый раз возвращайте его карту в число доступных персонажей в начале следующего испытания. Добавьте отметку поверженного чудища на сторону легенды карты этого персонажа.</p><p>Поместите логово бодрствующего чудища неактивной стороной вверх на участок местности с чудищем. Затем, если остались неразмещённые накладки обжигающих отпечатков, поместите их на случайные участки местности, соседние с неактивным логовом чудища. Для каждого отпечатка бросьте <1d6>, чтобы поместить отпечаток в соответствующий район: [1-2] А, [3-4] Б, [5-6] В. Если при этом вы должны поместить отпечаток в район с другой накладкой, замените её на обжигающий отпечаток.</p><p>Затем завершите текущую эру. См. с. 204, чтобы <era3>начать эру 3</era3>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<behemothsblood>"}]},{"id":"outcomes-558","code":"558","description":{"en":"","ru":"<p><i><b>Ваши попытки наладить отношения с незнакомцами ни к чему не привели. Некоторые люди вашей общины считали, что так даже лучше, но другие опасались, что эта встреча может быть предвестием куда более серьёзных распрей…</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю об исчезнувших, включив в неё отметку тайны [i] и отметку раскола [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"Mystery"},{"label":"ii","image":"<schism>"}]},{"id":"outcomes-560","code":"560","description":{"en":"","ru":"<p><i><b>Вы мчались навстречу великой битве, и ваше сердце сжималось от страха. Вы знали, что нужно сделать, чтобы склонить чашу весов. Пока вокруг рассыпались холмы и сминались леса, вы искали в себе храбрость, чтобы бросить вызов такой непостижимой мощи.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><i><b>Приближаясь к неистовствующим титанам, вы видели, как огромные глыбы земли взмывали в небо.</b></i></p><p><b>Чудище, группа, угроза. </b>Все персонажи в походе должны провести состязание, чтобы избежать урона: <dexterity> против меньшего из значений <might> двух чудищ. +2, если у персонажа есть <i>одежда</i>, и +2, если он <i>осторожный</i>.<br><b>Успех. </b>Вы пробрались сквозь опасность невредимыми. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>Провал. </b>Вас растоптали бы, если бы вы не отступили! Покиньте поход или получите <major_injury><major_injury>. Если все персонажи покинули поход, он окончился неудачно.</p><p><i><b>Когда вы выбрались из пекла боя, всё вокруг казалось стихшим — лишь сбивающий с ног рёв сражающихся чудищ разносился вокруг. Чтобы переломить ход битвы, вам нужно было взобраться на возвышенность!</b></i></p><p>Защитник, чудо. Один из персонажей в походе должен провести состязание, чтобы найти подходящую точку обзора: его <awareness> против меньшего из значений <conviction> двух чудищ. +4, если на участке местности с этим персонажем есть морена или гора, и +2, если персонаж <i>отважный</i>.<br><b>Успех. </b>Вы заметили подходящее место и повели группу наверх. Продолжите поход.<br><b>Провал. </b>Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><b><i>С возвышения вы могли бы прыгнуть на спину одного из чудищ и нанести удар, чтобы временно отвлечь его и дать преимущество другому. Настал ваш момент: воспользуетесь ли вы им?</i></b></p><p><b>Чудище, группа. </b>Все персонажи в походе должны провести состязание, чтобы прыгнуть: <conviction> против большего из значений <dexterity> двух чудищ. +2, если у персонажа есть хотя бы 1 сокровище любого из чудищ, и +2, если он <i>неукротимый</i>.<br><b>Успех. </b>Вы запрыгнули на спину чудища и поспешили нанести отвлекающий удар. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>Провал. </b>Вам стало страшно при одной лишь мысли о прыжке. Покиньте поход либо потратьте <energy> или <lore>, чтобы провести проверку ещё раз. Если все персонажи покинули поход, он окончился неудачно.</p><p><b><i>Вы достигли того, что казалось уязвимой точкой; по крайней мере, на любом другом существе она выглядела бы так. Вы должны были нанести удар изо всех сил!</i></b></p><p><b>Чудище, защитник. </b>Один из персонажей в походе должен выбрать чудище для атаки, а затем провести состязание, чтобы сразиться: его <might> или <dexterity> против <might> выбранного чудища. +2, если у персонажа есть оружие, и +2, если он <i>мстительный</i>.<br><b>Успех. </b>Ваш удар с ужасающей силой обрушился на чудище. Завершите этот поход и достигните соответствующей цели.<br><b>Провал. </b>Ваше оружие отскочило, не нанеся урона. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-561","code":"561","description":{"en":"","ru":"<p><i><b>Острое чутьё чудища позволяло ему улавливать перемены вокруг. Постучав по его рогу, вы сумели направить его в другую сторону.</b></i></p><p>Завершите встречу. Переместите персонажа и это чудище на один и тот же соседний участок местности (не берите карту пути).</p>"},"repeatable":false},{"id":"outcomes-562","code":"562","description":{"en":"","ru":"<p><i><b>Стоило вам положить материал в чашу, как внезапно её будто что‑то выдернуло из вашего поля зрения — и она исчезла в ближайшем дереве. Спустилась ещё одна чаша, в которой лежал другой материал. Возможно, вы обменялись с существом, живущим в дереве? Едва вы начали искать это существо, как услышали лишь назойливое щёлканье, которое медленно растворилось в густой листве. Мгновение спустя что‑то скользнуло прочь с вершины дерева и исчезло за краем хребта. Как странно… Вы вернулись к чаше, чтобы забрать свои вещи.</b></i></p><p>Если вы сбросили шёлк или плетёный шёлк, получите 1 живой коралл и 1 лунную кровь. В противном случае получите 2 плетёных шёлка.</p>"},"repeatable":false},{"id":"outcomes-565","code":"565","description":{"en":"","ru":"<p><i><b>С отчаянным рёвом чудище исчезло под разрастающимся кораллом. Избавившись от последнего громадного препятствия на своём пути, коралл вскоре распространился как пожар, захватив долину целиком.</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о заре гибели, включив в неё отметку бодрствующего чудища, украшенную отметкой коралла [i], и отметку ужаса [ii]. </p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Останьтесь с телом чудища, пока коралл разрастается по всей долине. </b>Завершите кампанию. Ваша община <b>исчезла</b>.<br>См. раздел «Конец кампании» в правилах игры на с. <rulebook>97</rulebook>.<br>Такой конец хоть и далёк от счастливого, но он всё же может послужить уроком для народов, которые заселят эту долину в будущем. Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом! Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. <rulebook>97</rulebook> или раздел «Бесконечный режим» на с. <rulebook>102</rulebook>.<br><b>Б. Покиньте своего древнего спутника, чтобы продолжить его историю в других землях. </b>Добавьте к грядущим испытаниям карту «Исход» (ИЯ09).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<coral>"},{"label":"ii","image":"<harrowing>"},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-571","code":"571","description":{"en":"","ru":"<p><i><b>Скиталец пронёсся по небу и исчез в свете солнца. Спустя какое‑то время он вырвался из солнечного сияния, лучась пламенем и жаром.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Запечатлейте это событие. </b>Потратьте <lore><lore><lore>, чтобы на стене первобытной пещеры изобразить историю о возрождении коралла, включив в неё отметку коралла и отметку <sun>.<br><b>Б. Внимательно понаблюдайте, чтобы узнать что-то новое о мироздании. </b>Добавьте <lore><lore>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<coral>"}]},{"id":"outcomes-572","code":"572","description":{"en":"","ru":"<p><i><b>В клубящемся облаке спор вы заметили кораллового защитника. Древнее создание шагало сквозь сверкающий туман, который расступился, когда вы бросились врагу наперерез. </b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><i><b>Парящие частицы коралла превратились в крошечные обжигающие искры, как только вы приблизились. Там, где они вас касались, кожа покрывалась волдырями и лопалась.</b></i></p><p><b>Коралл, группа, угроза. </b>Все персонажи в походе должны провести проверку <conviction>, чтобы продолжить наступление. +2, если у персонажа есть <i>одежда</i>, +4, если у него есть «Талисман из лунной крови», и +2, если он <i>неукротимый</i>.<br><b>≥12:</b>  Вы стиснули зубы и продолжили наступление, несмотря на боль. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-11:</b>  Споры обожгли вас, и вы закричали от боли. Покиньте поход или получите <major_disease> и <minor_disease>. Если все персонажи покинули поход, он окончился неудачно, если только любой персонаж в походе не потратит <energy>, чтобы провести проверку ещё раз.</p><p><b><i>Коралловый защитник сжал руку в кулак. Из земли вокруг вырвались отростки живого коралла и попытались схватить вас, будто повинуясь воле защитника.</i></b></p><p><b>Коралл, группа. </b>Все персонажи в походе должны провести проверку <dexterity>, чтобы увернуться. +2, если у персонажа есть  <cut>(или +4, если у него есть предмет <i>лунной крови </i>с <cut>). Также +4, если у персонажа есть «Талисман из лунной крови», и +2, если он <i>удачливый</i>.<br><b>≥12:</b>  Вы увернулись от устремившихся к вам кораллов и сделали прыжок в сторону кораллового защитника. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-11:</b>  Кораллы схватили вас, выбив из сил. Покиньте поход или получите <major_injury><major_injury>. Если все персонажи покинули поход, он окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><b><i>Стоя перед коралловым защитником, вы понимали, что у вас есть лишь мгновение, чтобы нанести удар!</i></b></p><p><b>Коралл, защитник. </b>Один из персонажей в походе должен провести проверку <might>, чтобы сразиться. +2, если у персонажа есть <i>оружие из лунной крови</i>, +4, если у него есть<i> оружие-трофей</i>, и +2, если он <i>мстительный</i>.<br><b>≥13:</b>  Ваш удар достиг цели. Завершите этот поход и достигните соответствующей цели.<br><b>9-12:</b>  Ваш удар не достиг цели, но вы увидели возможность для ещё одной атаки. Разыграйте исход как при [1-8], если только любой персонаж в походе не потратит <energy> или <lore>, чтобы провести проверку ещё раз.<br><b>1-8:</b>  Защитник с лёгкостью уклонился от вашего удара. Вернитесь ко второй вылазке этого похода.</p>"},"repeatable":false},{"id":"outcomes-573","code":"573","description":{"en":"","ru":"<p><i><b>Ваша песня была лихой и неистовой: чудище всё больше и больше раздражалось, пытаясь угнаться за ней. В конце концов оно выбилось из сил и ушло, оставив после себя клочок мха. Вы решили осмотреть его поближе — вдруг вы найдёте в нём что‑то необычное?</b></i></p><p>Завершите встречу. Разозлите чудище на 1. Чудище сбегает.</p><p>Затем, если у персонажа, животного- компаньона или в сооружении-хранилище есть предмет со словом «мерцающий» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Мерцающий мох» (ВЩ86).</p>"},"repeatable":false},{"id":"outcomes-575","code":"575","description":{"en":"","ru":"<p><i><b>Ваши частые встречи с чудищем раскрыли скрытые истины о его природе. Да, оно было могущественным, но в то же время было тесно связано с окружающим миром. Его сила далеко превосходила мощь любого человека, но и она не была безграничной. Чем бы ни было это чудище, вы верили: оно сыграет важную роль в будущем вашего народа.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Посоветуйте своему народу обходить стороной логова чудищ.</b> Уберите <unrest>. Успокойте бодрствующее чудище на 2. На стене первобытной пещеры изобразите историю о могучем соседе, включив в неё отметку бодрствующего чудища, отметку осторожности [i] и отметку табу [iv]. Запишите «Отдыхать на участке местности с логовом чудища» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет.<br><b>Б. Соберите ресурсы рядом с отпечатком чудища. </b>Добавьте <population><population><population>. Разозлите бодрствующее чудище на 3. На стене первобытной пещеры изобразите историю о дарах разрушителя земли, включив в неё отметку бодрствующего чудища, отметку расколотой земли [ii], отметку тайны [vii] и отметку изобилия [iii].<br><b>В. Провозгласите, что чудище — посланник богов, следящий за соблюдением табу. </b>Если на стене первобытной пещеры есть отметка табу [iv], уберите 6<unrest>. На стене первобытной пещеры изобразите историю о древнем законе, включив в неё отметку бодрствующего чудища, отметку тайны [vii] и отметку табу, заключённую в отметку связи [v].<br><b>Г. Запишите передвижения чудища для будущих поколений. </b>Добавьте <population><population>. Успокойте чудище на 1. На стене первобытной пещеры изобразите историю о вестнике дикой природы, включив в неё отметку бодрствующего чудища и отметку летописца [vi].</p><p>В конце этого испытания завершите текущую эру. См. с. 196, чтобы <era2>начать эру 2</era2>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":"<brokenearth>"},{"label":"iii","image":"<plenty>"},{"label":"iv","image":"<taboo>"},{"label":"v","image":{"image":"<bond>","overlay":{"image":"<taboo>","size":0.4,"x":7,"y":10,"rotate":0}}},{"label":"vi","image":"<scribe>"},{"label":"vii","image":"<mystery>"}]},{"id":"outcomes-582","code":"582","description":{"en":"","ru":"<p><i><b>Ваша охота совпала со знамениями, предвещая изобилие в грядущем году. Конечно, впереди было ещё много работы, чтобы подготовиться к продолжению великой охоты.</b></i></p><p>Уберите <unrest>. Каждый персонаж получает <minor_boost> к <dexterity> или <conviction>. На стене первобытной пещеры изобразите историю об удачной охоте, включив в неё отметки всех знамений, которые вы нашли на картах добычи припасов во время достижения цели «Выйдите на охоту под светом знамения», и отметку охотника.</p>"},"repeatable":false,"marks":[{"label":"","image":"<hunter>"}]},{"id":"outcomes-584","code":"584","description":{"en":"","ru":"<p><i><b>На каменной брови чудища вы заметили жёсткий мох, растущий в трещинах.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Сорвите немного мха и заставьте чудище вздрогнуть. </b>Завершите встречу. Разозлите чудище на 1. Получите 3 волокна.<br><b>Б. Срежьте мерцающий кусок мха, который вы заметили.</b> Если у вас есть <cut>, завершите встречу. Затем, если у персонажа, животного-компаньона или в сооружении-хранилище есть предмет со словом «мерцающий» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Мерцающий мох» (ВЩ86).<br><b>В. Соскользните по мху, чтобы сбежать. </b>Завершите встречу. Получите <minor_boost> к <dexterity>.</p>"},"repeatable":false},{"id":"outcomes-586","code":"586","description":{"en":"","ru":"<p><i><b>Сидя в гриве чудища, вы поняли, что оно хочет услышать рассказ о вашем народе. Пока вы говорили, волоски на его теле колыхались, будто впитывая каждое слово. Когда вы закончили рассказ, чудище бережно спустило вас с себя, а потом мгновенно зарылось в землю.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Поведайте древнюю быль. </b>Если у вас есть карта легенды, сбросьте её, чтобы завершить встречу. Успокойте чудище на 1. Затем, если у персонажа, животного-компаньона или в сооружении-хранилище есть предмет со словом «симбиотический» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Симбиотическое яйцо» (ВЩ93).<br><b>Б. Придумайте какую-нибудь чушь в надежде, что она будет убедительной.</b> Завершите встречу. Разозлите чудище на 1. Получите 1 солнечный камень.</p>"},"repeatable":false},{"id":"outcomes-588","code":"588","description":{"en":"","ru":"<p><i><b>Свершив своё жуткое дело, чудище с грохотом умчалось прочь, оставив за собой след разрушений.</b></i></p><p>До конца текущего испытания (или события в бесконечном режиме), когда вы перемещаетесь на участок местности с логовом этого чудища или с одной из накладок этого чудища, помещайте на этот участок местности жетон истощения.</p><p>Уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-590","code":"590","description":{"en":"","ru":"<p><i><b>С раскатом грома сияние чудища словно померкло. Вы протянули руку, чтобы коснуться его огромного хребта…</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Осторожно положите ладонь на хребет и ощутите тёплое течение жизни внутри.</b> Успокойте чудище на 2. Можете заменить его инстинкт на «Вернуться в забытьё» (ЧК20). Затем, если <cloud>— текущее знамение, сотрите или зачеркните одну отметку в клетке возраста на карте персонажа.<br><b>Б. Схватите хребет изо всех сил. Завершите встречу.</b> Разозлите чудище на 1. Чудище сбегает.</p>"},"repeatable":false},{"id":"outcomes-591","code":"591","description":{"en":"","ru":"<p><i><b>Как неукротимая буря, чудище обрушилось на ваши поселения, заставив ваш народ спасаться бегством. Вам негде было спрятаться от его ярости. </b></i></p><p>Завершите текущее испытание.</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Займите оборону и защитите свои поселения. </b>Уберите <population><population><population><population>. За каждое своё поселение бросьте <1d6> и разыграйте эффект по результату броска: [1-2] это поселение становится руинами, [3-5] разрушьте 2 случайных сооружения в этом поселении, [6] уберите <population>. Навсегда увеличьте <conviction> каждого персонажа на 2 (не более чем до 7). Добавьте отметку становления [iv] на сторону легенды карты каждого персонажа. Затем на стене первобытной пещеры изобразите историю о несчастных днях, включив в неё отметку битвы [i] и отметку бодрствующего чудища, украшенную отметкой гнева [iii].<br><b>Б. Сбегите прочь от ярости чудища. </b>Добавьте <unrest><unrest><unrest>. Каждое из ваших поселений становится руинами. На стене первобытной пещеры изобразите историю об отчаянном бегстве, включив в неё отметку расколотой земли [ii] и отметку бодрствующего чудища, украшенную отметкой гнева [iii].</p><p>Затем завершите текущую эру. См. с. 196, чтобы <era2>начать эру 2</era2>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<brokenearth>"},{"label":"iii","image":"<wrath>"},{"label":"iv","image":"<growth>"}]},{"id":"outcomes-592","code":"592","description":{"en":"","ru":"<p><i><b>Ваши поиски начались в огромной пещере. Кораллы заполнили часть полости, но даже они держались подальше от шипящей трещины, рассекающей пол…</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><i><b>Вы стояли на краю шипящей трещины. Кто‑то должен был спуститься вниз.</b></i></p><p><b>Защитник, чудо.</b> Один из персонажей в походе должен провести проверку <conviction>, чтобы забраться внутрь трещины. +2, если у персонажа есть предмет с <fire>, +2, если он <i>отважный</i>, и +1 за каждый его предмет для <i>исследования</i>.<br><b>≥11:</b>  Вы с уверенностью залезли в трещину. Продолжите поход.<br><b>1-10:</b>  У вас сдали нервы. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><b><i>Стены внутри трещины были скользкими, как мокрый камень, и острыми, как вулканическое стекло. Спуск становился опасным: на каждом выступе можно было сильно порезаться.</i></b></p><p><b>Группа, угроза.</b> Все персонажи в походе должны провести проверку <dexterity>, чтобы безопасно спуститься. +2, если у персонажа есть <i>одежда</i>, +2 за каждый его предмет для <i>исследования </i>и +2, если он <i>осторожный</i>.<br><b>≥10:</b>  Вы спустились без происшествий. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-9:</b>  Вы сильно поцарапались. Покиньте поход или получите <major_injury> и <minor_injury>. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><i><b>Острые выступы на стенах, похоже, были кристаллизованной лунной кровью, что пузырилась в яме на дне и выбрасывала едкий пар в воздух. На дне трещины не было следов кораллов. Видимо, лунная кровь их отпугивала. В жидкой форме её здесь было немного, но возможно, вы могли бы собрать хотя бы небольшой образец.</b></i></p><p><b>Защитник, чудо. </b>Один из персонажей в походе должен провести проверку <awareness>, чтобы безопасно собрать лунную кровь. +2, если у персонажа есть предмет с <fire>, +2, если у него есть отметка лунной крови, и +2, если он изобретательный. Также +4, если персонаж сбросит 1 воду.<br><b>≥13:</b>  Вы собрали хороший образец. Получите 3 лунные крови. Завершите этот поход и достигните соответствующей цели.<br><b>9-12:</b>  Вам не удалось собрать много жидкости, но этого было вполне достаточно. Получите 1 лунную кровь. Завершите этот поход и достигните соответствующей цели.<br><b>1-8:</b>  Едкие пары не дали вам сосредоточиться. Поход окончился неудачно, если только любой персонаж в походе не получит <major_disease> или не потратит <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false,"marks":[{"label":"","image":"<moonblood>"}]},{"id":"outcomes-593","code":"593","description":{"en":"","ru":"<p><i><b>Вы внимательно изучили звёзды и разгадали их узоры. Даже передвижения чудища оказались вписанными в великий космический замысел.</b></i></p><p>Ваша община получает силу мантии «Говорящий с чудищами» (MA18).</p>"},"repeatable":false},{"id":"outcomes-594","code":"594","description":{"en":"","ru":"<p><i><b>Перед вашим внутренним взором предстал раскинувшийся под вами полог леса. Неужели вы стояли на вершине огромной горы? Мир рванулся вперёд, и гром ваших шагов сотряс полог. Вы приняли облик существа немыслимых размеров, ведомого первобытными инстинктами. Деревья разлетались, словно листья, когда вы ступали по лесу. Миг спустя вы очнулись в холодном поту, с мрачной, тревожащей душу уверенностью: где‑то очень далеко это чудище целеустремлённо продолжало свой путь…</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Свяжитесь с незнакомым разумом.</b> Выберите случайное чудище, отметки которого нет на стене первобытной пещеры. На стене первобытной пещеры изобразите историю о древнейшем разуме, включив в неё отметку этого чудища и отметку тайны. Добавьте <activity><activity><activity> и получите <major_boost> к <might>.<br><b>Б. Найдите информацию об этом чудище.</b> Потратьте <lore><lore><lore> или добавьте <activity><activity>, чтобы выбрать чудище с активным логовом в долине. Перемешайте его неоткрытые карты секретов, затем откройте одну из них (см. раздел «Секреты» в правилах игры на с. <rulebook>81</rulebook>).</p>"},"repeatable":false,"marks":[{"label":"","image":"<mystery>"}]},{"id":"outcomes-595","code":"595","description":{"en":"","ru":"<p><i><b>Вскарабкавшись на острые шипы, вы прошептали что‑то себе под нос. Чудище замерло, вытянув шею, будто прислушиваясь. Когда оно перестало двигаться, вы легко смогли подняться выше.</b></i></p><p>Можете сбросить карту легенды, чтобы успокоить чудище на 1. Затем продолжите эту встречу.</p>"},"repeatable":false},{"id":"outcomes-596","code":"596","description":{"en":"","ru":"<p><i><b>Вы обошли все Вулканические пустоши в поисках каждого знамения и по пути увидели знаки. Облака пара вырывались из трещин в земле, обжигая всё вокруг. Магма пылала, словно солнце. Искры разлетались с вершины горящей горы, как хаотичные звёзды. Гнев горы нарастал, подбираясь к какому‑то, пока неведомому пиковому моменту. Даже равнодушное пепельное чудище, обитавшее в этом регионе, казалось, тоже чувствовало надвигающееся бедствие и мерило шагами подножие горы…</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем добавьте карту «Извержение» (ИЕ04) к грядущим испытаниям. На стене первобытной пещеры изобразите историю о гневе горы, включив в неё отметку пламени [ii] и отметку почерневшего неба [i]. Наконец, разыграйте первое, что можете:<br><b>А. Пепельное чудище направилось к Вулканическим пустошам. </b>Если на стене первобытной пещеры есть отметка ЧД4 [iii], переместите его логово на случайный участок Вулканических пустошей. Бросьте <1d6>, чтобы поместить логово в соответствующий район: [1-2] А, [3-4] Б, [5-6] В.<br><b>Б. Пепельное чудище прибыло в долину. </b>Подготовьте ЧД4 (см. раздел «Появление чудища» в правилах игры на с. <rulebook>74</rulebook>). Поместите его логово на случайный участок Вулканических пустошей. Бросьте <1d6>, чтобы поместить логово в соответствующий район: [1-2] А, [3-4] Б, [5-6] В.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<blackenedsky>"},{"label":"ii","image":"<blaze>"},{"label":"iii","image":"<bh4>"}]},{"id":"outcomes-597","code":"597","description":{"en":"","ru":"<p><i><b>За тёмным поворотом показалось несколько фигур. Их угрожающий вид стал ещё мрачнее, когда вы услышали их бормотание о гибели и разрушении. Вы испугались, что эта встреча может перерасти в столкновение. </b></i></p><p>Проведите проверку <might> или <dexterity>, чтобы сразиться. +2, если вы <i>мстительный</i>, и +4, если у вас есть отметка битвы.<br><b>≥10:</b>  Когда враждебная группа набросилась на вас, вы разогнали их хорошо поставленными ударами. Они скрылись во мраке. Уберите жетон тайны, поместив его на карту «Выживите в растущем хаосе», затем добавьте <lore>.<br><b>7-9:</b>  Чужаки набросились на вас, но вам удалось отбиться, хоть вы и получили несколько порезов и ушибов. Получите <minor_injury>. Переместите жетон тайны на другой участок местности, выбрав ближайший участок без персонажа, если возможно.<br><b>1-6:</b>  Противники атаковали вас, осыпая ударами и проклятиями. Получите <major_injury><major_injury>. Переместите жетон тайны на другой участок местности, выбрав соседний с поселением участок без персонажа, если возможно.</p>"},"repeatable":false,"marks":[{"label":"","image":"<battle>"}]},{"id":"outcomes-599","code":"599","description":{"en":"","ru":"<p><i><b>Набравшись смелости, вы запечатали пасть пламени. Дым рассеялся, а магма остыла. Ярость земли осталась лишь в памяти вашего народа, который отныне стал процветать в долине.</b></i></p><p>На стене первобытной пещеры изобразите историю о запечатанных вратах, включив в неё отметку пламени [i] и отметку Вулканических пустошей [ii]. Ваша община <b>выжила</b>.</p><p>Поздравляем! Вы завершили кампанию «Наскальной истории»! Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!</p><p>Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. <rulebook>97</rulebook> или раздел «Бесконечный режим» на с. <rulebook>102</rulebook>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<blaze>"},{"label":"ii","image":"<volcanic_wastes>"},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-606","code":"606","description":{"en":"","ru":"<p><i><b>Чудище пристально вгляделось в символ, который вы ему показали...</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Начертите символ на лбу чудища. </b>Завершите встречу. Успокойте чудище на 1. Чудище сбегает. Можете убрать жетон направления и все жетоны следов этого чудища, а затем заменить его текущий инстинкт на «Нести возрождение» (ЧЕ05).<br><b>Б. Сотрите символ. </b>Завершите встречу. Разозлите чудище на 2. Чудище сбегает. </p>"},"repeatable":false},{"id":"outcomes-609","code":"609","description":{"en":"","ru":"<p><i><b>Угрозами и убеждениями вы заставили мятежную группу отступить, и в долине воцарился шаткий мир. Хоть вам больше и не грозила опасность, что могла унести множество жизней, некоторые ваши люди всё же исчезли в ночи, а посиделки у костра всё чаще наполнялись недовольными возгласами.</b></i></p><p>Добавьте <unrest><unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о расселении, включив в неё отметку раскола. Добавьте карту «Ворчание у костра» (НО01) в колоду ночи, если возможно.</p>"},"repeatable":false,"marks":[{"label":"","image":"<schism>"}]},{"id":"outcomes-612","code":"612","description":{"en":"","ru":"<p><i><b>В глубинах логова вы обнаружили скрученный костяной стебель, на вершине которого распустился мертвенно‑бледный цветок. Замерцавший пламенем бутон раскрылся и обрушил на вас видение. Когда вы пришли в себя, логово было заполнено пеплом, а странный стебель исчез. То, что вы увидели, уже давным‑давно свершилось? Или только грядёт? А может быть, видение было одновременно и воспоминанием, и пророчеством?</b></i></p><p>Найдите карту цели ЦЕ07. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описать её другим игрокам. Затем на стене первобытной пещеры изобразите историю о волне перемен, включив в неё отметку ЧД4 [i] и отметку <cloud>, заключённую в отметку пророчества [ii].</p><p>В конце текущего испытания завершите эру. См. с. 196, чтобы <era2>начать эру 2</era2>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<bh4>"},{"label":"ii","image":"<prophecy>"}]},{"id":"outcomes-614","code":"614","description":{"en":"","ru":"<p><i><b>Ваши люди внимали каждому слову, пока ваш рассказ оживлял великих героев прошлого вместе с испытаниями и трудностями, через которые они прошли.</b></i></p><p>Уберите <unrest><unrest>, затем выберите и разыграйте одно:<br><b>А. Восславьте героя прошлого.</b> Выберите карту легенды без отметки становления, затем увеличьте любую её характеристику на 2 (не более чем до 8). Добавьте отметку становления на сторону легенды этой карты.<br><b>Б. Соотнесите всё происходящее с уроками прошлого. </b>Выберите карту легенды, затем выберите одну черту, которая есть у вашего персонажа, но отсутствует на этой карте. Добавьте эту черту на карту легенды.<br><b>В. В деталях поведайте историю об испытаниях героя. </b>Выберите карту легенды, затем на стене первобытной пещеры выберите отметку, которой ещё нет на этой карте. Добавьте эту отметку на эту карту легенды. </p><p>Затем верните в коробку карту «Ворчание у костра» (НО01).</p>"},"repeatable":false,"marks":[{"label":"","image":"<growth>"}]},{"id":"outcomes-618","code":"618","description":{"en":"","ru":"<p><i><b>Ваш разум запел в унисон с кораллом. Вы ощутили, как вода плескалась у ваших ног в долине далеко внизу. Вы ощутили мягкий свет далёких звёзд, не скрытых облаками. Вы ощутили ползущие по коже крошечные ножки из дюжины иных миров. И вы ощутили, как коралл признал в вас существо, способное мыслить и чувствовать.<br>Когда вы вернулись в долину, вы увидели, что коралл отступил к зарослям вокруг кратера. Хоть жизнь в долине и изменилась, одно вы могли сказать точно — коралл больше не будет разрастаться. Вы научили свой народ общаться с кораллом — и чудеса за пределами звёзд открылись вам…</b></i></p><p>Добавьте <population><population><population> и уберите <unrest><unrest><unrest>. Уберите все накладки коралловых зарослей, не соседствующие с местом падения, затем переверните оставшиеся в долине накладки коралловых зарослей неактивной стороной вверх.</p><p>На стене первобытной пещеры изобразите историю о связи вне времени, включив в неё отметку Звёздного моря [i] и отметку коралла, заключённую в отметку окончания [ii]. Ваша община <b>выжила</b>. Получите карту знаний «Вовне» (ЗБ20).</p><p>Поздравляем! Вы завершили кампанию «Наскальной истории»! Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!</p><p>Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. <rulebook>97</rulebook> или раздел «Бесконечный режим» на с. <rulebook>102</rulebook>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<starlitsea>"},{"label":"ii","image":{"image":"<conclusion>","overlay":{"image":"<coral>","size":0.85,"x":3,"y":5,"rotate":0}}},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-622","code":"622","description":{"en":"","ru":"<p><i><b>Вы направились к кратеру…</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><i><b>Вы увидели край кратера. Он был зазубренным, а окружающие его камни превратились в стекло от силы удара. Спускаться предстояло с большой осторожностью.</b></i></p><p>Группа. Все персонажи в походе должны провести проверку <awareness>, чтобы безопасно спуститься. +1 за каждый предмет для <i>исследования</i>, который есть у персонажа, и +2, если персонаж <i>отважный</i>.<br><b>≥11:</b>  Вы благополучно спустились. Продолжите поход.<br><b>1-10:</b>  Вы скатились по склону, сильно порезавшись о зазубренное стекло. Получите <major_injury> и <minor_injury>. Продолжите поход.</p><p><i><b>Вы подошли к лежащему посередине кратера огромному камню, который упал в долину. Около камня мягко покачивались коралловые отростки, двигаясь в ритме неслышной вам мелодии. А по самому камню змеилась вверх глубокая трещина. Вам показалось, что внутри камня было что‑то спрятано. Но что именно?</b></i></p><p><b>Коралл, группа.</b> Все персонажи в походе должны провести проверку <might>, чтобы протиснуться внутрь. +2, если у персонажа есть отметка коралла.<br><b>≥11:</b>  Вы протиснулись в расщелину. Внутри вы обнаружили, что камень полый — он был оболочкой, которая окружала подвешенное коралловое сердце, бившееся у вас над головой. Продолжите поход.<br><b>1-10:</b>  Вы начали кашлять и задыхаться, когда коралловые споры заполнили ваши лёгкие. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не получит <major_disease> или не потратит <lore>, чтобы провести проверку ещё раз.</p><p><b><i>Гул великого сердца звал вас из темноты. Кто‑то должен был подойти к сердцу и поговорить с ним… </i></b></p><p>Выберите персонажа в этом походе. Добавьте отметку коралла на сторону легенды карты этого персонажа, затем этот персонаж становится легендой.<br>Завершите этот поход и достигните соответствующей цели.</p>"},"repeatable":false,"marks":[{"label":"","image":"<coral>"}]},{"id":"outcomes-624","code":"624","description":{"en":"","ru":"<p><i><b>Вы заплутали в самом сердце коралловых зарослей. Звон разрывал ваш рассудок и скручивал мир в узлы. Вы наткнулись на светящийся коралловый отросток.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Возьмите светящийся шар.</b> Получите 3 живых коралла. Затем, если в долине есть хотя бы 1 накладка неактивных коралловых зарослей, переверните любую из них.<br><b>Б. Свяжитесь с кораллом. </b>Перед вашим внутренним взором мелькнуло место, связанное с этими зарослями. Поместите жетон тайны на другой участок местности, выбрав участок с коралловыми зарослями, если возможно.<br><b>В. Усыпите коралл. </b>Сбросьте 1 лунную кровь, чтобы перевернуть любые активные коралловые заросли.</p>"},"repeatable":false},{"id":"outcomes-625","code":"625","description":{"en":"","ru":"<p><i><b>Пузырчатые следы чудища разветвлялись и складывались в узор, напоминающий лист. Неужели это великое создание творило искусство ради удовольствия?.. Неужели оно танцевало?</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Изучите детали узора. </b>Если у чудища есть неоткрытая назначенная карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><b>Б. Осмотрите узор издалека. </b>Если у вас есть карта легенды хотя бы с 2 отметками, можете сбросить эту карту, чтобы добавить одну из этих отметок на сторону легенды карты своего персонажа.</p>"},"repeatable":false},{"id":"outcomes-635","code":"635","description":{"en":"","ru":"<p><i><b>Собравшись с силами, вы отогнали коралловых хищников. Когда этих вестников коралла стало меньше, часть зарослей затихла и замерла.</b></i></p><p>Выберите не более 2 накладок активных коралловых зарослей и переверните их.</p>"},"repeatable":false},{"id":"outcomes-640","code":"640","description":{"en":"","ru":"<p><i><b>Вы взобрались на огромные иссохшие ледяные пласты. Стоя под самым небом, глядя в глазницы гигантского черепа, вы… </b></i></p><p>Получите карту знаний «Переход через ледники» (ЗБ14). На стене первобытной пещеры изобразите историю о ледяном восхождении, включив в неё отметку своего начального региона, отметку ледника [i] и отметку открытия [ii]. Затем разыграйте первое, что можете:<br><b>А. …увидели землю, тронутую облаками, отражающимися на гладкой поверхности черепа. </b>Если ваш начальный регион — Дивная долина, то <outcome> 984.<br><b>Б. …услышали шёпот ветра в деревьях сразу за ледником.</b> Если ваш начальный регион — Поднебесная равнина, то <outcome> 423.<br><b>В. …заметили нечто поистине неожиданное. </b><outcome> 928.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<glacier>"},{"label":"ii","image":"<discovery>"}]},{"id":"outcomes-642","code":"642","description":{"en":"","ru":"<p><i><b>Чудище завершило свои таинственные поиски. Что же оно пыталось найти?</b></i></p><p>Поместите жетон тайны на каждый участок местности с жетоном следов.</p><p>Затем уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-644","code":"644","description":{"en":"","ru":"<p><i><b>Свет выхватил из темноты тушу животного. Казалось, она пролежала здесь недолго, так что, вероятно, вы могли бы разделать её.</b></i></p><p>Проведите проверку <might>, чтобы вытащить тушу. +2, если вы <i>изобретательный</i>, и +2, если у вас есть <cut>.<br><b>≥13:</b>  Вы вытянули тушу из-под недавнего каменного обвала. Получите 2 дичи, 1 кость и 1 шкуру.<br><b>9-12:</b>  Вам удалось оторвать кусок туши. Получите 1 дичь и 1 шкуру.<br><b>1-8:</b>  Вы расшатали морену, и вокруг посыпались камни. Получите <minor_injury>. </p>"},"repeatable":false},{"id":"outcomes-652","code":"652","description":{"en":"","ru":"<p><i><b>На долину обрушился ливень такой силы, что скапливающаяся вода начала переливаться через край пропасти, грозя превратить её в реку!</b></i></p><p>Проведите проверку <dexterity>, чтобы взобраться на край. +2, если вы <i>отважный</i>, и +2, если у вас есть «Скальный крюк».<br><b>≥12:</b>  Вы отчаянно взобрались по стене пропасти в безопасное место. Получите 1 воду.<br><b>8-11:</b>  Поток сбил вас с ног, но вам удалось ухватиться за свисающий куст и убраться подальше от стремительно прибывающей воды. Получите <minor_injury>.<br><b>1-7:</b>  Течение унесло вас. Получите <major_injury>, потеряйте 1 случайный предмет и сбегите на случайный соседний участок местности.</p>"},"repeatable":false},{"id":"outcomes-654","code":"654","description":{"en":"","ru":"<p><i><b>Когда вы потянулись к воде, из глубины вдруг показалась рука. Кто‑то пытался выбраться на поверхность и вместе с этим утянуть вас на дно.</b></i></p><p>Найдите в коробке карту молодого или пожилого персонажа (но не легенду) с отметкой лунной крови [ii], если возможно. На стене первобытной пещеры изобразите историю о замёрзшем, включив в неё отметку лунной крови [ii] и отметку тайны [i].</p><p>Верните в коробку карту «Облик на глубине» (ПЗ02). Затем разыграйте первое, что можете:<br><b>А. Отбейтесь от древнего создания. </b>Если и ваша <might>, и ваша <conviction> больше, чем у выбранного персонажа, вам удалось вырваться. Получите <major_injury> и добавьте <lore><lore>. Верните в коробку карту выбранного персонажа.<br><b>Б. Уйдите под поверхность. </b>Замените карту своего текущего персонажа этой картой персонажа. Добавьте отметку лунной крови [ii] на сторону легенды карты своего предыдущего персонажа, затем верните её в коробку. В конце испытания ваш новый персонаж станет доступным, а предыдущий останется в коробке.<br><b>В. Вы потрясли головой, пытаясь отбросить наваждение, и поняли, что вам всё это лишь показалось. </b>Без эффекта</p>"},"repeatable":false,"marks":[{"label":"i","image":"<mystery>"},{"label":"ii","image":"<moonblood>"}]},{"id":"outcomes-658","code":"658","description":{"en":"","ru":"<p><i><b>Вы почти закончили выцарапывать отметку на панцире чудища. Могучим последним взмахом вы завершили символ. Чудище застыло, словно окаменев. Затем панцирь взорвался, будто волна, разбившаяся о берег, — всё тело существа, казалось, обратилось в жидкость. Кровь чудища хлынула наружу — синяя и кристальная, а остатки панциря растаяли, как весенняя изморозь. Потоки ледяной жидкости пронеслись мимо вас, просочились по земле и потекли обратно в логово чудища. Там, где пролилась эта кровь, земля замёрзла, словно в разгар суровой зимы.</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о поверженном древнем существе, включив в неё отметку битвы [i] и отметку бодрствующего чудища, украшенную отметкой крови чудища [ii]. Добавьте отметку крови чудища [ii] на сторону легенды карт персонажей, участвовавших в этом походе. Один из этих персонажей должен сбросить оружие, если возможно.</p><p>Поместите логово бодрствующего чудища неактивной стороной вверх на участок местности с чудищем. Затем, если остались неразмещённые накладки ледяных отпечатков, поместите их на случайные участки местности, соседние с неактивным логовом чудища. Для каждого отпечатка бросьте <1d6>, чтобы поместить отпечаток в соответствующий район: [1-2] А, [3-4] Б, [5-6] В. Если при этом вы должны поместить отпечаток в район с другой накладкой, замените её на ледяной отпечаток.</p><p>Затем завершите текущую эру. См. с. 204, чтобы <era3>начать эру 3</era3>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<behemothsblood>"}]},{"id":"outcomes-667","code":"667","description":{"en":"","ru":"<p><i><b>Удушающий дым распространился по всему небу. В последующие дни воздух стал горьким, а земля — мёртвой. Для вашего народа оставалось лишь два пути: бежать из этих мест или держаться до последнего.</b></i></p><p>Завершите текущее испытание.</p><p>Бросьте <1d6> и уберите столько <population>, сколько выпало на <1d6>. Затем, если значение <population> равно 0, то <outcome> 966. В противном случае совместно выберите один из следующих путей развития общины:<br><b>А. Держитесь до последнего. </b>Добавьте к грядущим испытаниям карту «Пеплопад» (ИЕ05).<br><b>Б. Найдите выход из долины. </b>Добавьте к грядущим испытаниям карту «Исход» (ИЯ09).</p>"},"repeatable":false},{"id":"outcomes-671","code":"671","description":{"en":"","ru":"<p><i><b>Раздав свои припасы, вы добились преданности людей и успокоили их. Хоть некоторые соплеменники, понадеявшиеся на сытые годы, и решили после этого остаться в общине, зимой им пришлось затянуть пояса.</b></i></p><p>Завершите текущее испытание.</p><p>Уберите 5<population>. На стене первобытной пещеры изобразите историю о влиянии, включив в неё отметку осторожности [i] и отметку ужаса [ii].</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>A. Отыщите истоки коралла в незнакомой ледяной земле. </b>Если на стене первобытной пещеры есть отметка Звёздного моря [iii], добавьте карту «Разговор со звёздами» (ИВ07) к грядущим испытаниям.<br><b>Б. Сразитесь с защитником древности, который ныне служит кораллу. </b>Если на стене первобытной пещеры есть отметка коралла, заключённая в отметку окончания [iv], добавьте карту «Избранник кометы» (ИВ08) к грядущим испытаниям.<br><b>В. Отправьтесь на поиски логова своего древнего врага. </b>Если на стене первобытной пещеры есть отметка чудища с неактивным логовом, украшенная отметкой крови чудища [v], добавьте карту «Чудище кометы» (ИВ09) к грядущим испытаниям.<br><b>Г. Вспомните о связи чудища с прошлым. </b>Если на стене первобытной пещеры есть отметка чудища с активным логовом в долине, заключённая в отметку связи [vi], добавьте карту «Узы чудища» (ИВ10) к грядущим испытаниям.<br><b>Д. Покиньте долину раз и навсегда. </b>Уберите все остальные грядущие испытания и добавьте к грядущим испытаниям карту «Исход» (ИЯ09).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":"<harrowing>"},{"label":"iii","image":"<starlitsea>"},{"label":"iv","image":{"image":"<conclusion>","overlay":{"image":"<coral>","size":0.85,"x":3,"y":5,"rotate":0}}},{"label":"v","image":"<behemothsblood>"},{"label":"vi","image":"<bond>"}]},{"id":"outcomes-675","code":"675","description":{"en":"","ru":"<p><i><b>Хворь обрушилась на ваши поселения. Не зная, как бороться с этой бестелесной смертью, ваши люди изо всех сил пытались выжить. Это удавалось не сильнейшим и не молодым — а тем, кому повезло.</b></i></p><p>Завершите текущее испытание.</p><p>Уберите 6 <population>. На стене первобытной пещеры изобразите историю о распространяющейся смерти, включив в неё отметку ужаса [i] и отметку чумы [ii]. Бросьте <1d6> за каждого персонажа и разыграйте эффект по результату броска: [1-2] этот персонаж умирает, [3-6] без эффекта.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<harrowing>"},{"label":"ii","image":"<plague>"}]},{"id":"outcomes-676","code":"676","description":{"en":"","ru":"<p><i><b>С оглушительным грохотом один исполин поверг другого наземь и издал такой рёв, словно был намерен бросить вызов недосягаемым высотам неба...</b></i></p><p>Разыграйте состязание между <might> двух бодрствующих чудищ. +2 к результату чудища за каждый его жетон следов на карте «Узрите великую битву». Затем, если на стене первобытной пещеры нет отметки проигравшего чудища, заключённой в отметку связи [i], уберите <population><population> за каждый жетон следов этого чудища на карте «Узрите великую битву».</p><p>Завершите текущее испытание. На стене первобытной пещеры изобразите историю о схватке гигантов, включив в неё отметки каждого бодрствующего чудища и отметку расколотой земли [ii]. Переверните логово проигравшего чудища неактивной стороной вверх.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<bond>"},{"label":"ii","image":"<brokenearth>"}]},{"id":"outcomes-677","code":"677","description":{"en":"","ru":"<p><i><b>Вы протянули руку, чтобы коснуться странной жидкости.</b></i></p><p>Проведите проверку <conviction>, чтобы зачерпнуть жидкость. +2, если вы <i>сосредоточенный</i>, и +4, если у вас есть отметка лунной крови.<br><b>≥10:</b>  Получите 1 лунную кровь.<br><b>7-9:</b>  Холодное вещество выскользнуло сквозь пальцы. Потеряйте <energy>. <br><b>1-6:</b> <outcome>899.</p>"},"repeatable":false,"marks":[{"label":"","image":"<moonblood>"}]},{"id":"outcomes-682","code":"682","description":{"en":"","ru":"<p><i><b>Внутри останков древнего чудища вы нашли странное сокровище. Вы взяли его в руки и ощутили, как через всё тело волной пронеслась ужасающая сила.</b></i></p><p>В зависимости от чудища, неактивное логово которого вы исследовали, отложите соответствующие карты предметов из колоды предметов (не рассматривая их лицевые стороны). Затем, если у персонажа, животного-компаньона или в сооружении-<i>хранилище</i> есть <i>трофейные </i>предметы с такими же словами в названиях (например, «симбиотический» или «разрушительный»), верните в колоду такие отложенные карты.</p><p><div><bh1><span>: ВЩ85, ВЩ86</span></div><br><div><bh2><span>: ВЩ87, ВЩ88</span></div><br><div><bh3><span>:ВЩ92, ВЩ93</span></div><br><div><bh4><span>: ВЩ99, ВЩ100</span></div></p><p>Перемешайте отложенные карты, возьмите из них одну случайную, а остальные верните в колоду.<br>На стене первобытной пещеры изобразите историю о древнем трофее, включив в неё отметку чудища, логово которого вы исследовали, и отметку реликвии [i].</p>"},"repeatable":false,"marks":[{"label":"","image":"<bh1>"},{"label":"","image":"<bh2>"},{"label":"","image":"<bh3>"},{"label":"","image":"<bh4>"},{"label":"i","image":"<relic>"}]},{"id":"outcomes-686","code":"686","description":{"en":"","ru":"<p><i><b>Под лаской солнечных лучей пробудился к жизни росток, потянувшись нежными зелёными побегами к окружающему миру в поисках живительной силы. Если его не подкармливать и не поливать, он зачахнет, как и другие растения Сплетения.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><b><i>Великое семя из корневых туннелей оказалось не просто огромным — оно, похоже, обладало необычными свойствами и нуждалось в особом уходе. Чтобы понять, как с ним обойтись, вам пришлось вспомнить всё, что вы знаете о Сплетении.</i></b></p><p><b>Защитник. </b>Один из персонажей в походе должен провести проверку <awareness>, чтобы изучить семя. +2, если этот персонаж <i>сосредоточенный</i>, и +4, если у него есть отметка Сплетения. Также +4, если персонаж потратит <lore>.<br><b>≥12:</b>  Изучив семя, вы увидели, что его побеги тянутся к земле. Вероятно, лучше всего было бы его закопать, как того требовал естественный порядок вещей. Продолжите поход.<br><b>1-11:</b>  Вы зашли в тупик. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><b><i>Вы принялись закапывать семя в питательную почву.</i></b></p><p><b>Группа. </b>Все персонажи в походе должны провести проверку <might>, чтобы вспахать землю. +2, если у персонажа есть <chop>, +2, если у него есть <dig>, и +2, если он <i>изобретательный</i>. Также +4, если персонаж сбросит 1 растительный материал.<br><b>≥11:</b>  Вы закопали семя в рыхлую землю. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-10:</b>  Работа с землёй — не конёк вашей общины. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore><lore>, чтобы провести проверку ещё раз.</p><p><b><i>Поместив семя в насыпь из земли и растительности, вы полили его, чтобы оно быстрее росло.</i></b></p><p><b>Защитник.</b> Один из персонажей в походе должен провести проверку <dexterity>, чтобы полить семя. +2, если у этого персонажа есть <dig>, и +2, если он <i>мудрый</i>. Также +2, если он сбросит 1 воду. Если у этого персонажа есть <grind>, он может сбросить 1 кость, шкуру или жилы, чтобы добавить 6 к результату.<br><b>≥15:</b>  Вы напоили росток. Завершите этот поход и достигните соответствующей цели.<br>1-14  Ваши усилия не принесли результата. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-688","code":"688","description":{"en":"","ru":"<p><i><b>Ропот перерос в крики, а затем вспыхнул рёвом ярости. В любой момент могла начаться кровавая потасовка.</b></i></p><p>Добавьте карту «Открытая враждебность» (НО02) в колоду ночи, если возможно. В противном случае уберите <population>.</p>"},"repeatable":false},{"id":"outcomes-690","code":"690","description":{"en":"","ru":"<p><i><b>Вы прошлись по узору на спине чудища, и оно замерло…</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Попробуйте направить чудище. </b>Завершите встречу. Чудище сбегает 2 раза. Переместите своего персонажа на участок местности, куда оно сбежало.<br><b>Б. Прогоните чудище. </b>Завершите встречу. Разозлите чудище на 1. Чудище сбегает 3 раза.</p>"},"repeatable":false},{"id":"outcomes-691","code":"691","description":{"en":"","ru":"<p><i><b>Ваши отчаянные попытки принесли плоды. Мороз объял семя, и оно начало погружаться в спячку от ледяного прикосновения. Возможно, Сплетение всё же не было обречено на погибель!</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о ледяном спасении, включив в неё отметку <moon>, заключённую в отметку окончания.</p><p>Добавьте карту «Новый расцвет» (ИЖ05) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"","image":{"image":"<conclusion>","overlay":{"image":"<moon>","size":0.8,"x":3,"y":2,"rotate":0}}}]},{"id":"outcomes-692","code":"692","description":{"en":"","ru":"<p><i><b>Вы раздвинули вьющиеся лианы и обнаружили нечто интересное…</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><b><i>По земле тянулась странная борозда. Клубок каменных щупалец, оставленных чудищем, запечатывал проход. Что же скрывалось за ним?</i></b></p><p><b>Защитник, чудо. </b>Один из персонажей в походе должен провести проверку <might>, чтобы разрушить каменную печать. +2, если у этого персонажа есть <stoneworking>, и +2 за каждый его предмет для <i>исследования</i>.<br><b>≥11:</b>  Вы прорвались сквозь печать. Продолжите поход.<br>1-10  Ваши инструменты лишь отскакивали от каменных лоз. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy> или <lore>, чтобы провести проверку ещё раз.</p><p><b><i>Как только вы разрушили печать, наружу просочились едкие испарения. Видимо, чудище пыталось сдержать вещество, что поднималось из глубин земли.</i></b></p><p><b>Группа, угроза.</b> Все персонажи в походе должны провести проверку <awareness>, чтобы оставаться настороже. +2, если у персонажа есть предмет с <fire>.<br><b>≥10:</b>  Вы сделали шаг назад, когда плотное облако ядовитого пара медленно рассеялось, иссушая листья на своём пути. Продолжите поход.<br><b>1-9:</b>  Получите <major_disease>. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><b><i>Вы подошли к мутной булькающей луже. Вам казалось, будто в ней был яд, что извергся из самых недр земли. </i></b></p><p><b>Защитник, угроза. </b>Один из персонажей в походе должен провести проверку <conviction>, чтобы окунуть оружие в бурлящую жижу. +4, если в журнале записан хотя бы 1 секрет этого чудища.<br><b>≥12:</b>  Вы опустили оружие в жидкость, и оно зашипело, исказилось и превратилось в орудие, способное повергнуть великого зверя. Завершите этот поход и достигните соответствующей цели.<br><b>1-11:</b>  У вас не хватило духу подойти к луже, и вы отступили прочь. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-693","code":"693","description":{"en":"","ru":"<p><i><b>Вы решили пройтись вдоль лиан. Чем дальше вы забредали, тем гуще и плотнее становились заросли. В конце концов вы добрались до настоящей стены из растений, через которую, казалось, невозможно было пробраться. Вы задались вопросом, действительно ли она неприступна, как кажется.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>). </p><p><i><b>Стена из лиан казалась непроходимой, но вы решили прорубить себе путь…</b></i></p><p><b>Группа.</b> Все персонажи в походе должны провести проверку <might>, чтобы прорубить проход. +2, если у персонажа есть <cut>, +4, если у него есть <chop>, и +2, если он <i>мстительный</i>.<br><b>≥13:</b>  Вы прорубили себе путь сквозь зелёные баррикады и открыли проход. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-12:</b>  На месте каждой лианы, которую вы срубали, словно вырастали две новые. Неужели их становилось больше? Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore><lore>, чтобы провести проверку ещё раз.</p><p><i><b>Вы прорвались сквозь стену лиан и тут же оказались в болоте. Пробираясь по топям среди корней огромного растения, вы с ужасом осознали, что начали тонуть!</b></i></p><p><b>Группа, угроза. </b>Все персонажи в походе должны провести проверку <awareness>, чтобы не утонуть в мутном болоте. +2, если у персонажа есть «Верёвка» или «Трость», и +2, если он <i>осторожный</i>.<br><b>≥11:</b>  Вы нашли твёрдое место среди корней и выбрались из трясины. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-10:</b>  Вы барахтались, пока грязь поднималась всё выше. Получите <major_injury><major_injury>. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore><lore>, чтобы провести проверку ещё раз.</p><p><i><b>Поняв, что почва больше не уходит из‑под ног, вы посмотрели наверх и увидели восхитительный мягкий свет, пробивающийся сквозь густой полог. Не успели вы насладиться картиной, как из грёз вас вырвал низкий рык: вы наткнулись на логово голодных хищников!</b></i></p><p><b>Группа, угроза. </b>Каждый персонаж в походе должен провести встречу с хищником (см. раздел «Встреча с хищником» в правилах игры на с. 48), используя приведённые ниже результаты проверки вместо обычных. +2, если у персонажа есть предмет с <fire> или если на его участке местности есть <fire>. Если персонаж решил отступить, он разыгрывает стандартные результаты, а затем покидает поход. Если все персонажи покинули поход, он окончился неудачно.<br><b>≥12:</b>  Вы заставили существ отступить. Если хотя бы один персонаж получил этот результат, завершите этот поход и достигните соответствующей цели.<br><b>1-11:</b>  Хищники нанесли вам тяжёлые раны. Получите <major_injury> и <minor_injury>. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-694","code":"694","description":{"en":"","ru":"<p><i><b>Вы смогли выстоять в суровую пору, отыскивая любые возможности для выживания, вопреки всем невзгодам.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем добавьте <population><population><population>. На стене первобытной пещеры изобразите историю о нелегко доставшейся награде, включив в неё отметку изобилия.</p>"},"repeatable":false,"marks":[{"label":"","image":"<plenty>"}]},{"id":"outcomes-697","code":"697","description":{"en":"","ru":"<p><i><b>Вы ползли на животе через огромное молочно‑белое пространство. А облака и вода медленно кружились под вами.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><i><b>Вихри сознания потоком кружились вокруг вас. Каждый раз, когда вы протягивали руку к этому потоку, вам являлись новое видение и новое место.</b></i></p><p><b>Защитник, сон. </b>Один из персонажей в походе должен провести проверку <conviction>, чтобы посмотреть на мир глазами коралла. +2, если у этого персонажа есть предмет <i>коралла</i>, и +2, если этот персонаж <i>любознательный</i>. Также +2 за каждый <i>живой коралл</i>, который сбросит этот персонаж.<br><b>≥11:</b>  Ваш разум расширился, когда вы увидели неведомые места. Красная, продуваемая ветрами равнина… Спиральные чёрные водоёмы, усеянные звёздами… Продолжите поход.<br><b>1-10:</b>  Вы не смогли познать то, что наполнило ваш разум. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Водоворот разума коралла казался непреодолимым. Но в его недрах кружились знакомые мысли. Возможно, вы могли бы ухватиться за одну из них, как за корягу во время наводнения, чтобы выбраться.</b></i></p><p><b>Защитник, сон. </b>Один из персонажей в походе должен провести проверку <awareness>, чтобы найти связующую нить. +2, если у этого персонажа есть <music>, +4, если у него есть отметка песнопевца [i], и +2, если персонаж <i>удачливый</i>. Также +2 за каждый живой коралл, который сбросит этот персонаж.<br><b>≥12:</b>  Вы нашли связующую нить, за которую можно было потянуть, и разум коралла, похоже, откликнулся. Продолжите поход. <br><b>1-11:</b>  Вы безуспешно пытались найти хоть что-то, что могло бы вас сроднить с таким всеобъемлющим и странным существом. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy> или <lore>, чтобы провести проверку ещё раз.</p><p><b><i>Ваш островок разума колыхался на гребнях океана сознания, готовый в любой миг исчезнуть в его глубинах. </i></b></p><p><b>Защитник, сон. </b>Один из персонажей в походе должен провести проверку <conviction>, чтобы передать послание о мирном сосуществовании. +4, если у этого персонажа есть отметка коралла [ii], +2, если у персонажа есть <music>, и +2, если персонаж <i>сосредоточенный</i>. Также +2 за каждый живой коралл, который сбросит этот персонаж.<br><b>≥13:</b>  Коралловые усики скрутились, образовав лицо, похожее на ваше. Ваш разум словно стал общим, и вы увидели себя глазами коралла — маленьким, странным и хрупким существом. Завершите этот поход и достигните соответствующей цели. <br><b>1-12:</b>  Кораллы откликнулись, беспорядочно задёргав усиками. Но вы ощутили замешательство, увидев ответ на своё послание. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<songweaver>"},{"label":"ii","image":"<coral>"}]},{"id":"outcomes-699","code":"699","description":{"en":"","ru":"<p><i><b>Вы стояли на краю пропасти, внутри которой можно было отыскать путь в незнакомый зелёный мир. Если вы сможете попасть туда, то об этом наверняка будут складывать легенды ваши потомки.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><b><i>Край пропасти был коварен, и даже спуск в его извилистые проходы стал достойным испытанием. </i></b></p><p>Защитник, чудо. Один из персонажей в походе должен провести проверку <dexterity>, чтобы найти путь в пропасть. +4, если у этого персонажа есть отметка подземного мира [i], и +2, если персонаж <i>изобретательный</i>.<br><b>≥10:</b>  Вы с лёгкостью спустились вниз. Продолжите поход.<br><b>1-9:</b>  Первая же платформа, на которую вы ступили, провалилась под вашим весом, и вы поспешно вернулись наверх. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore><lore>, чтобы провести проверку ещё раз.</p><p><i><b>В прохладной тьме пропасти каждый звук действовал на нервы, из‑за чего вся группа чувствовала себя неуверенно. </b></i></p><p><b>Группа, угроза. </b>Все персонажи в походе должны провести проверку <conviction>, чтобы не побояться темноты. +2, если у персонажа есть предмет с <fire>, +2, если персонаж любознательный, и +4, если у него есть отметка тайны [ii].<br><b>≥11:</b>  Вы окликнули остальных, и знакомый звук вашего голоса стал для всех спасательным кругом в океане тьмы. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-10:</b>  Ваши нервы дрогнули, и паника начала захлёстывать вас. Потеряйте <energy><energy>. Если все персонажи получили этот результат, поход окончился неудачно. </p><p><i><b>Извилистые коридоры ущелья переплелись у вас в голове. Вам нужно было распутать этот клубок и вновь найти дорогу,  чтобы достичь земель впереди.</b></i></p><p><b>Защитник, угроза. </b>Один из персонажей в походе должен провести проверку <awareness>, чтобы проложить путь через проходы. +2, если у этого персонажа есть «Карта», +2, если он <i>терпеливый</i>, и +4, если у него есть отметка прибытия [iii].<br><b>≥10:</b>  Вы нашли дорогу. Завершите этот поход и достигните соответствующей цели.<br><b>1-9:</b>  Заблудившись окончательно, вы вышли на поверхность только через несколько часов вдали от того места, куда направлялись. Покиньте поход и сбегите, затем потеряйте <energy><energy>. Другой персонаж в походе должен провести эту проверку. Если все персонажи получили этот результат, поход окончился неудачно.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<underworld>"},{"label":"ii","image":"<mystery>"},{"label":"iii","image":"<arrival>"}]},{"id":"outcomes-701","code":"701","description":{"en":"","ru":"<p><i><b>Вы не могли не вздрогнуть от мысли о произошедшем с одним из вас в глубинах и о том, что это может предвещать…</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю о пропавшем, включив в неё отметку тайны [i] и отметку коралла, заключённую в отметку окончания [ii]. Добавьте к грядущим испытаниям карту «Презрение земли» (ИВ06).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<mystery>"},{"label":"ii","image":{"image":"<conclusion>","overlay":{"image":"<coral>","size":0.85,"x":3,"y":5,"rotate":0}}}]},{"id":"outcomes-703","code":"703","description":{"en":"","ru":"<p><i><b>Вам не удалось сбежать или отвлечь подземное существо, и теперь вам придётся сражаться, чтобы выжить.</b></i></p><p>Вы должны провести проверку <might>, чтобы сразиться. +2, если вы <i>мстительный</i>. <br><b>≥13:</b> <outcome> 210.<br><b>8-12:</b>  Вы отогнали существо, но оно успело вас ранить. Получите <major_injury> и потеряйте <energy><energy>.<br><b>1-7:</b>  В схватке вы получили рану и потеряли всё, что добыли во время спуска. Разыграйте исход как при [8-12], затем потеряйте все свои награды. Получите черту «мстительный».</p>"},"repeatable":false},{"id":"outcomes-704","code":"704","description":{"en":"","ru":"<p><i><b>Вы принялись восстанавливать руины. Заставить людей вновь здесь обустроиться казалось непосильной задачей, но вы верили, что это возможно.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><b><i>В руинах часто скрывались опасные существа, и кто‑то должен был их выманить.</i></b></p><p><b>Защитник, угроза.</b> Один из персонажей в походе должен провести проверку <awareness>, чтобы обыскать руины в поисках угрозы. +2, если этот персонаж <i>осторожный</i>, и +2, если у него есть предмет для <i>исследования</i>. <br><b>≥11:</b>  Вы прогнали всех опасных животных из руин. Продолжите поход.<br><b>1-10:</b>  В руинах вас ранило опасное существо. Получите <major_injury>. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy> или <lore>, чтобы провести проверку ещё раз.</p><p><b><i>Фундаменты многих сооружений растрескались, их нужно было аккуратно восстановить.</i></b></p><p><b>Защитник. </b>Один из персонажей в походе должен провести проверку <dexterity>, чтобы восстановить фундаменты. +2, если у этого персонажа есть <stoneworking>. Также +3 за каждую глину и +1 за каждый другой минеральный материал, которые сбросит этот персонаж (можно сбросить не более 3 минеральных материалов, включая глину).<br><b>≥12:</b>  Вы восстановили фундаменты сооружений в поселении. Продолжите поход.<br><b>1-11:</b>  Ваших умений оказалось недостаточно, чтобы восстановить сильно повреждённый фундамент. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз. </p><p><i><b>Чтобы сделать руины пригодными для жилья, нужно было не только укрепить фундаменты. Вам предстояло провести различные ремонтные работы и убраться, чтобы ваши люди вновь могли называть это место домом.</b></i></p><p><b>Защитник. </b>Один из персонажей в походе должен провести проверку <conviction>, чтобы создать подходящую обстановку. +4, если у этого персонажа есть «Метла», и +4, если у него есть отметка укрытия. Также +2 за каждое дерево, которое сбросит этот персонаж (не более +8).<br><b>≥14:</b>  Вы будете счастливы назвать это место домом! Переверните накладку руин. Создайте новую карту поселения. Выберите до 2 сооружений, записанных на карте руин, и запишите их на новой карте. Завершите этот поход.<br><b>10-13:</b>  Вам удалось восстановить поселение, но сооружения оказались непригодны для ремонта. Переверните накладку руин. Создайте новую карту поселения без сооружений. Завершите этот поход.<br><b>1-9:</b>  Восстановление поселения потребовало куда больших усилий, чем вы предполагали. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false,"marks":[{"label":"","image":"<hold>"}]},{"id":"outcomes-706","code":"706","description":{"en":"","ru":"<p><i><b>Когда вы стояли на голове чудища, оно с жадностью пыталось взглянуть на пламя, которое вы подняли над собой.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Преподнесите огонь. </b>Если у вас есть предмет с  <fire> или на вашем участке местности есть <fire>, сбросьте этот жетон, чтобы завершить встречу. Успокойте чудище на 1. Чудище сбегает. Затем, если у персонажа, животного- компаньона или в сооружении-<i>хранилище </i>есть предмет со словом «поглощающий» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Поглощающий камень» (ВЩ100).<br><b>Б. Доведите чудище до неистовства, размахивая пламенем. </b>Завершите встречу. Разозлите чудище на 1. Чудище сбегает. Уберите жетон направления и все жетоны следов этого чудища, затем замените его текущий инстинкт на «Нести гибель» (ЧЕ04).</p>"},"repeatable":false},{"id":"outcomes-708","code":"708","description":{"en":"","ru":"<p><i><b>Покормить чудище оказалось отличной идеей. Хоть его огромная туша никак не могла насытиться вашими жалкими подношениями, оно, похоже, было не прочь ими полакомиться. Поутру недалеко от деревни вы обнаружили странные сокровища: растения, которые вы никогда не видели, и сверкающие камни из неведомых глубин. Будущие поколения смогут воспользоваться этими необычайными дарами и, возможно, попытаются отблагодарить чудище новыми подношениями. Со временем чудище могло бы стать объектом поклонения для вашего народа.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о почтении, включив в неё отметку бодрствующего чудища и отметку пира. Добавьте карты «Праздник памяти» (ИA07) и «Сумрак долины» (ИA08) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"","image":"<feast>"}]},{"id":"outcomes-709","code":"709","description":{"en":"","ru":"<p><i><b>Корни чудища вращались и вспахивали землю вокруг, а вы уворачивались от них. Голова чудища тянулась к облакам, словно оно искало воду. Утолить его жажду было невозможно, но вода явно действовала на него. Когда корни у ваших ног с жадностью потянулись к влаге, из переплетения лоз внезапно проросла диковинная пища.</b></i></p><p>Завершите встречу. Получите 3 любых овоща.</p>"},"repeatable":false},{"id":"outcomes-711","code":"711","description":{"en":"","ru":"<p><i><b>Чудище устремилось к центру кратера, а вы пытались не отставать. В небесах нависала комета, исторгая струи спор, что тянулись к упавшему осколку. Их воссоединение грозило уничтожить долину, поэтому времени на размышления не было.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><i><b>Оболочка осколка кометы состояла из мёртвого коралла — прочного, как камень. Нужно было её как‑то сломать. Чудище рычало и рвалось вперёд, готовое действовать.</b></i></p><p><b>Чудище, защитник, коралл. </b>Один из персонажей в походе должен провести проверку <conviction>, чтобы подстегнуть чудище. +2, если у этого персонажа есть <i>талисман</i>, +2, если у персонажа есть <i>трофей</i>, и +2, если персонаж <i>мудрый</i>. Добавьте значение <might> или <conviction> чудища к результату.<br><b>≥20:</b>  Чудище с лёгкостью разбило оболочку. Продолжите поход.<br><b>1-19:</b>  Оболочка треснула, но выдержала удар. Уменьшите все усиления чудища. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Споры опускались вниз, наполняя воздух удушающей завесой. Они липли к коже чудища, обжигая её в местах соприкосновения.</b></i></p><p><b>Чудище, коралл, группа, угроза. </b>Все персонажи в походе должны провести проверку <dexterity>, чтобы помочь чудищу. +2, если у персонажа есть «Метла», и +2, если он <i>изобретательный</i>. Также +4, если персонаж сбросит 1 лунную кровь.<br><b>≥12:</b>  Вам удалось стряхнуть споры с чудища, и оно с новыми силами бросилось в атаку. Продолжите поход.<br><b>1-11:</b>  Вы не смогли помочь чудищу. Получите <major_disease>. Уменьшите все усиления чудища. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Великое сердце коралла билось внутри оболочки, теперь открытой всем ветрам. Споры сгущались в воздухе, обжигая вас и чудище.</b></i></p><p><b>Чудище, защитник, коралл, угроза. </b>Один из персонажей в походе должен провести проверку <awareness>, чтобы направить чудище. +2 за каждый предмет <i>лунной крови</i> всех персонажей в походе и +4, если выбранный персонаж <i>сосредоточенный</i>. Добавьте значение <awareness> или <dexterity> чудища к результату.<br><b>≥22:</b>  Чудище нанесло последний удар. Завершите этот поход и достигните соответствующей цели.<br><b>1-21:</b>  Удар чудища был недостаточно силён. Каждый персонаж получает <major_disease>. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-713","code":"713","description":{"en":"","ru":"<p><i><b>Несмотря на то что вы очень долго исследовали Сплетение, его тайны так и не открылись вам. Ваш народ начал считать это место — с его мерцающими тенями и непредсказуемыми зверями — опасным. Взрослые, чтобы отвадить детей от прогулок по Сплетению, пугали тех ужасными рассказами об этом месте.</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest><unrest>. Затем совместно выберите один из следующих путей развития общины: <br><b>А. Остерегайтесь тенистых полян. </b>Добавьте <unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о скрытых во мраке листьях, включив в неё отметку осторожности [i] и отметку Сплетения [ii].<br><b>Б. Запретите прогулки среди шелестящих листьев. </b>Уберите <unrest><unrest>. Запишите «Совершать действия, добавляющие жетоны истощения в Сплетение» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет. На стене первобытной пещеры изобразите историю о хищном лесе, включив в неё отметку табу [iii] и отметку Сплетения [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":"<tangle>"},{"label":"iii","image":"<taboo>"}]},{"id":"outcomes-716","code":"716","description":{"en":"","ru":"<p><i><b>Чудище проглотило огромный ком земли, с наслаждением его перед этим прожевав.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Поройтесь в пережёванных камнях в поисках чего-нибудь важного. </b>Если у чудища есть неоткрытая назначенная карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><b>Б. Оставьте камень, чтобы приманить чудище. </b>Сбросьте 1 минеральный материал, чтобы получить <minor_boost> к <awareness>, затем успокойте чудище на 1.<br><b>В. Возьмите камень из кучи. </b>Получите 1 любой обработанный минеральный материал.</p>"},"repeatable":false},{"id":"outcomes-717","code":"717","description":{"en":"","ru":"<p><i><b>Чудище схватило вас могучей лапой, когда вы забрались на самую вершину его парящего венца. Вы повисли над его огромной пастью, перемалывающей камни. В сумке вы нащупали камень, который, возможно, станет вашим спасением!</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Швырните чудищу камень. </b>Если в вашем инвентаре есть минеральный материал, сбросьте хотя бы 1, чтобы завершить встречу. Успокойте чудище на 1 за каждый материал, который вы сбросите. <br><b>Б. Упадите.</b> Завершите встречу. Получите <major_injury><major_injury>.</p>"},"repeatable":false},{"id":"outcomes-719","code":"719","description":{"en":"","ru":"<p><i><b>Ваши надежды оправдались: великая цитадель возвышалась над долиной многие годы. Ваша община процветала в тени этого изваяния, созданного человеческими руками, и история города неразрывно вплелась в историю вашего народа.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Уберите 5 <unrest>, добавьте <population><population><population><population>. На стене первобытной пещеры изобразите историю о возвышающемся городе, включив в неё отметку региона, где вы построили Город, и отметку Города.</p><p>В конце этого испытания завершите текущую эру. См. с. 204, чтобы <era3>начать эру 3</era3>.</p>"},"repeatable":false,"marks":[{"label":"","image":"<city>"}]},{"id":"outcomes-721","code":"721","description":{"en":"","ru":"<p><i><b>С каждым шагом поднимая всё больше и больше пыли, вы пришли туда, где не осталось ни капли влаги. Илистая земля трескалась под вашими ногами. </b></i></p><p>Выберите и разыграйте одно:<br><b>А. Изучите высохшую землю.</b> Если у чудища есть неоткрытая назначенная карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><b>Б. Полейте пыль, заставив траву стремительно прорасти. </b>Получите 1 волокно. Можете сбросить 1 воду, чтобы дополнительно получить 2 коренья.</p>"},"repeatable":false},{"id":"outcomes-723","code":"723","description":{"en":"","ru":"<p><i><b>Песни, созданные вами, стали частью культуры вашего народа — они объединили прошлое, настоящее и будущее.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем на стене первобытной пещеры изобразите историю о ткачах песен, включив в неё отметку песнопевца. Получите карты знаний «Легенды» (ЗБ15) и «Песни» (ЗБ16), если у вас их нет. Ваша община получает силу мантии «Глашатай легенд» (MA11).</p>"},"repeatable":false,"marks":[{"label":"","image":"<songweaver>"}]},{"id":"outcomes-724","code":"724","description":{"en":"","ru":"<p><i><b>Чудище поглощало всю воду в долине, и с каждым днём живительной влаги становилось всё меньше. Земля покрывалась трещинами, ваши губы сохли — на вас опустилась настоящая засуха.</b></i></p><p>До конца этого испытания каждый персонаж может получать не более 1 воды в день.<br>Уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-725","code":"725","description":{"en":"","ru":"<p><i><b>Тонкий слой пепла покрыл следы чудища. Они всё ещё тлели.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Вглядитесь в горизонт, чтобы понять, куда направлялось чудище, и, возможно, узнать его намерения. </b>Если у чудища есть неоткрытая назначенная карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><b>Б. Используйте тлеющий пепел. </b>Если у вас есть предмет, на который можно поместить <fire>, можете добавить на него <fire>. <br><b>В. Молча уйдите прочь.</b> Завершите встречу.</p>"},"repeatable":false},{"id":"outcomes-726","code":"726","description":{"en":"","ru":"<p><i><b>Вы почти закончили наносить отметку — в узоре царапин на панцире не хватало всего одного штриха. Вы знали: он положил бы конец чудищу. Но в этот миг желание сражаться покинуло вас. Это была бы не великая победа, а просто окончание жизни — и вы почувствовали всю тяжесть такого выбора. Вы отступили и выпустили оружие из рук. Чудище посмотрело на вас, но ледяные ветра стихли, и оно не сделало ни единого движения, чтобы атаковать.</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest><unrest><unrest>. Установите значение нрава бодрствующего чудища на 2. На стене первобытной пещеры изобразите историю о разорванном круге, включив в неё отметку бодрствующего чудища, отметку осторожности [i] и отметку становления [ii]. Навсегда увеличьте <conviction> и <awareness> каждого персонажа, участвовавшего в этом походе на момент его завершения, на 1 (не более чем до 7). Добавьте отметку бодрствующего чудища и отметку становления [ii] на сторону легенды карт каждого из этих персонажей.</p><p>Затем завершите текущую эру. См. с. 204, чтобы <era3>начать эру 3</era3>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":"<growth>"}]},{"id":"outcomes-727","code":"727","description":{"en":"","ru":"<p><i><b>Ваши попытки понять природу заразы Сплетения не принесли плодов и не развеяли тревоги вашего народа. С годами это место медленно угасало: здешняя земля, покрываясь умирающей зеленью, принимала иной облик.</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest>. Все поселения в регионе Сплетения становятся руинами. Уберите <population><population> за каждое поселение, ставшее руинами таким образом. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Запретите надолго оставаться в Сплетении. </b>Запишите «Отдыхать на участке Сплетения» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет. Добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю о запретной долине, включив в неё отметку Сплетения [i] и отметку табу [ii].<br><b>Б. Рискните и дайте отпор расползающейся гнили. </b>Уберите <population><population><population>. На стене первобытной пещеры изобразите историю о распространяющемся гниении, включив в неё отметку ужаса [iii] и отметку Сплетения [i].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<tangle>"},{"label":"ii","image":"<taboo>"},{"label":"iii","image":"<harrowing>"}]},{"id":"outcomes-728","code":"728","description":{"en":"","ru":"<p><i><b>Вы вскарабкались на челюсть чудища и повисли на ней. Вы поняли, что, хоть чудище и не видит вас, оно почуяло ваше присутствие, когда поменяло позу. Вы знали, что сможете привлечь внимание исполина, если используете камень, который всё это время был у вас с собой.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Отведите чудище на каменный пир.</b> Если на соседнем участке есть особенности местности, где можно добывать ископаемые, выберите одну из них, чтобы завершить встречу. Переместите своего персонажа и чудище на этот участок местности (не берите карту пути). Затем, если у персонажа, животного-компаньона или в сооружении-хранилище есть предмет со словом «расколотый» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Расколотый камень» (ВЩ88).<br><b>Б. Бросьте каменное угощение. </b>Сбросьте 1 минерал, чтобы завершить встречу. Чудище сбегает. Успокойте чудище на 1.<br><b>В. Позвольте чудищу смахнуть вас. </b>Завершите встречу. Получите <major_injury>. </p>"},"repeatable":false},{"id":"outcomes-729","code":"729","description":{"en":"","ru":"<p><i><b>Ваш народ активно взялся за строительство сооружений.</b></i></p><p>Бросьте <1d6> и спроектируйте сооружение по результату броска, не тратя <lore>: [1-2] соломенная хижина (СР01), [3] дождесборник (СР15), [4] корзины для хранения (СР03), [5] мусорная яма (СР05), [6] жёрнов (СР08).</p><p>Затем постройте это сооружение в поселении, где меньше всего сооружений, не тратя <energy> и ресурсы.</p>"},"repeatable":false},{"id":"outcomes-731","code":"731","description":{"en":"","ru":"<p><i><b>Жёсткий контроль за едой позволил сохранить жизни. Но бремя решений, кому жить, а кому умирать, оказалось слишком тяжёлым для одного человека.</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю о контроле, включив в неё отметку осторожности [i] и отметку несчастья [ii]. Затем совместно выберите один из следующих путей развития общины:<br><b>A. Отыщите истоки коралла в далёкой земле под звёздами.</b> Если на стене первобытной пещеры есть отметка Звёздного моря [iii], добавьте карту «Разговор со звёздами» (ИВ07) к грядущим испытаниям.<br><b>Б. Сразитесь с защитником древности, который ныне служит кораллу.</b> Если на стене первобытной пещеры есть отметка коралла, заключённая в отметку окончания [iv], добавьте карту «Избранник кометы» (ИВ08) к грядущим испытаниям.<br><b>В. Отправьтесь на поиски логова своего древнего врага. </b>Если на стене первобытной пещеры есть отметка чудища с неактивным логовом, украшенная отметкой крови чудища [v], добавьте карту «Чудище кометы» (ИВ09) к грядущим испытаниям.<br><b>Г. Вспомните о связи чудища с прошлым.</b> Если на стене первобытной пещеры есть отметка чудища с активным логовом в долине, заключённая в отметку связи [vi], добавьте карту «Узы чудища» (ИВ10) к грядущим испытаниям.<br><b>Д. Покиньте долину раз и навсегда. </b>Добавьте к грядущим испытаниям карту «Исход» (ИЯ09).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":"<misfortune>"},{"label":"iii","image":"<starlitsea>"},{"label":"iv","image":{"image":"<conclusion>","overlay":{"image":"<coral>","size":0.85,"x":3,"y":5,"rotate":0}}},{"label":"v","image":"<behemothsblood>"},{"label":"vi","image":"<bond>"}]},{"id":"outcomes-732","code":"732","description":{"en":"","ru":"<p><i><b>Вы не смогли удержаться на плаву, и течение утащило вас под воду. Вас мотало и кружило в бурлящем потоке, вы пере стали понимать, где вы, и каждую секунду боролись за глоток воздуха. Когда, наконец, вы пришли в себя, вы оказались в ручье где‑то в другой части долины. </b></i></p><p>Получите <major_injury> и <minor_disease>. Завершите действие спуска и потеряйте все награды, которые присвоили. Переместите своего персонажа на другой участок местности, выбрав участок с озером, рекой или болотом, если возможно.</p>"},"repeatable":false},{"id":"outcomes-733","code":"733","description":{"en":"","ru":"<p><i><b>Когда отзвуки разрушения стихли, а пыль опустилась обратно на землю, буйство чудища подошло к концу.</b></i></p><p>За каждый участок местности с поселением, где находится жетон следов, бросьте <1d6>. +1, если значение нрава чудища не более 5.</p><p>Затем разыграйте эффект в зависимости от результата:<br><b>1-2:</b>  Чудище сровняло поселение с землёй. Поселение становится руинами. Бросьте <1d6> и уберите столько <population>, сколько выпало на <1d6>.<br><b>3-4:</b>  Чудище проломило заграждения на окраине. Разрушьте 2 случайных сооружения в этом поселении. Уберите <population><population>. <br><b>5-6:</b>  Чудище повредило постройку и напугало жителей. Разрушьте 1 случайное сооружение в этом поселении. Добавьте <unrest>. </p><p>Затем уберите жетон направления и все жетоны следов этого чудища. Эта карта инстинкта остаётся назначенной этому чудищу.</p>"},"repeatable":false},{"id":"outcomes-736","code":"736","description":{"en":"","ru":"<p><i><b>Вы знали, что чудище в этих местах оставляет на своём пути ценные для него ресурсы. Вы могли бы собрать эти ресурсы или оставить рядом с ними такой же, чтобы передать чудищу послание.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Принесите подношение, чтобы усмирить чудище.</b> Сбросьте 1 сокровище чудища, чтобы успокоить чудище на 2. <br><b>Б. Заберите ресурс. </b>Получите 1 сокровище чудища.</p>"},"repeatable":false},{"id":"outcomes-743","code":"743","description":{"en":"","ru":"<p><i><b>Своим ударом ваш народ навлёк на себя гнев чудища. Теперь оно обрушилось на вас с яростью раненого божества. </b></i></p><p>Когда чудище активируется в следующую фазу чудищ, вместо того чтобы следовать своему инстинкту, оно проводит проверку <dexterity>, чтобы ступать к ближайшему участку местности с персонажем. +3, если значение нрава чудища равно хотя бы 6.<br><b>≥16:</b>  Чудище 3 раза ступает к тому участку. <br><b>12-15:</b>  Чудище 2 раза ступает к тому участку. <br><b>1-11:</b>  Чудище 1 раз ступает к тому участку, затем получает <minor_boost> ко всем характеристикам.</p><p>Затем, если чудище вошло на участок местности с одним или несколькими персонажами, выберите одного из этих персонажей — он должен провести встречу с чудищем. Кроме того, если оно вошло на участок местности с поселением, добавьте <unrest><unrest> и разрушьте 1 случайное сооружение в этом поселении.</p>"},"repeatable":false},{"id":"outcomes-744","code":"744","description":{"en":"","ru":"<p><i><b>Вы увидели далёкое место, окутанное вуалью неизвестности. Вы встрепенулись, чтобы очнуться, и…</b></i></p><p>Разыграйте первое, что можете:<br><b>А. ...сон вырвался из вашего разума, устремившись в долину. </b>Если у вас есть хотя бы 1 неразмещённая основа местности и в долине есть хотя бы 1 регион с хотя бы 1 размещённым участком местности и 3 или более неразмещёнными участками (кроме начального), случайным образом выберите 1 из таких регионов. Затем расширьте долину, пройдя описанные ниже этапы. <br><b>Этап 1. </b>Добавьте новую основу местности в долину. Поместите её по соседству с любым участком местности на ваш выбор — если возможно, с участком региона, который был выбран ранее. Границы основы должны соседствовать с как можно большим количеством границ уже помещённых основ. Если есть несколько возможных позиций, выберите одну случайным образом.<br><b>Этап 2. </b>Положите все неразмещённые участки местности выбранного региона в мешочек и перемешайте. Затем по одному вытащите 3 участка и поместите их неисследованной стороной вверх в ячейки новой основы по направлению с севера на юг и с востока на запад.<br><b>Этап 3 (только для эры 1 и бесконечного режима). </b>Если в запасе есть хотя бы 1 не помещённая накладка ледника, бросьте <1d6> и поместите ледники по результату броска: [1-2] один ледник в район А одного из участков местности без накладки, [3-4] один ледник в район Б одного из участков местности без накладки, [5] разыграйте результаты 1-2 и 3-4, [6] бросьте <1d6> ещё раз и прочитайте один из исходов ниже, соответствующий результату броска.<br>[1-2] <outcome> 846, [3-5] <outcome> 134, [6] <outcome>  446.<br>Затем верните в коробку карту «Недостижимая мечта» (НН07).<br><b>Б. ...сон рассеялся, как утренний туман, оставив лишь влажные отблески на краю вашего разума. </b>Добавьте <lore><lore>.</p>"},"repeatable":false},{"id":"outcomes-749","code":"749","description":{"en":"","ru":"<p><i><b>Вы плеснули водой в огромный лик чудища. И, словно в ответ, из него хлынул мощный поток, что унёс вас прочь. Когда вы пришли в себя, вы обнаружили, что сжимаете в руке странный предмет.</b></i></p><p>Завершите встречу. Разозлите чудище на 1. Переместите своего персонажа на соседний участок местности, выбрав участок с озером, рекой или болотом, если возможно (не берите карту пути).</p><p>Затем, если у персонажа, животного-компаньона или в сооружении-хранилище есть предмет со словом «мерцающий» в названии, получите 2 волокна; в противном случае получите карту предмета «Мерцающий мох» (ВЩ86).</p>"},"repeatable":false},{"id":"outcomes-754","code":"754","description":{"en":"","ru":"<p><i><b>Несмотря на все ваши усилия, семя Сплетения так и не смогло прижиться. Побег высох и затвердел, пока зараза пожирала остатки его родителя. Быть может, когда‑ нибудь, после великого наводнения или пожара, семя Сплетения пробудится вновь, но пока величие этих цветочных джунглей оставалось лишь в песнях и рассказах вашего народа. Поколения сменились, долина высохла, земля ещё сильнее покрылась трещинами, и ваш народ был вынужден искать новое убежище, оставив себе от Сплетения лишь воспоминания.</b></i></p><p>На стене первобытной пещеры изобразите историю о потрескавшейся земле, включив в неё отметку исхода [i] и отметку Сплетения [ii]. Замените начальный участок Сплетения на начальный участок местности другого региона, если возможно. Затем замените как можно больше других участков Сплетения на случайные участки этого региона, поместив их неисследованной стороной вверх. Ваша община <b>исчезла</b>.</p><p>Такой конец хоть и далёк от счастливого, но он всё же может послужить уроком для народов, которые заселят эту долину в будущем. Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!</p><p>Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. <rulebook>97</rulebook> или раздел «Бесконечный режим» на с. <rulebook>102</rulebook>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<exodus>"},{"label":"ii","image":"<tangle>"},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-755","code":"755","description":{"en":"","ru":"<p><i><b>Поверив слухам, которые твердили, что путь вам укажут клочки необычного облака, вы отправились на поиски земли жгучих туманов и ходячих холмов.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><i><b>Облако — это могущественное знамение.</b></i></p><p><b>Защитник, погода.</b> Один из персонажей в походе должен провести проверку <awareness>, чтобы истолковать знак. +2, если у этого персонажа есть <i>талисман</i>, и +2, если персонаж <i>сосредоточенный</i>.<br><b>≥10:</b>  Вы поняли, куда вас направляли облачные лоскуты. Продолжите поход.<br><b>1-9:</b>  Вы не смогли разобрать этот знак. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Путешествуя под знаком облака, вы добрались до необычного прохода в долине. Растения там были покрыты неестественными шероховатостями, а почва была сухой. Когда вы вошли в проход, вас окутали и обожгли странные испарения.</b></i></p><p><b>Группа, погода. </b>Все персонажи в походе должны провести проверку <might>, чтобы обойти туманные испарения стороной. +2, если у персонажа есть предмет для <i>исследования</i>, и +2, если персонаж <i>осторожный</i>.<br><b>≥12:</b>  Вы пробрались сквозь испарения, отделавшись лёгким испугом. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-11:</b>  Покиньте поход или получите <major_disease><major_disease>. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><i><b>Марево сгущалось. Пробираясь вперёд, вы сначала услышали затяжной грохочущий скрежет. Затем туман чуть рассеялся, и вы увидели, как склон холма медленной величавой поступью двигается в вашем направлении.</b></i></p><p><b>Защитник, чудо.</b> Один из персонажей в походе должен провести проверку <conviction>, чтобы взобраться на шагающий хребет. +2, если у этого персонажа есть «Верёвка», +2, если у него есть «Скальный крюк», +2, если у него есть <stoneworking>, и +2, если он <i>отважный</i>. <br><b>≥13:</b>  Вы взобрались на спину создания и обнаружили там маленький мир, укрывшийся на его огромных плечах. Завершите этот поход и достигните соответствующей цели.<br><b>1-12:</b>  Вы дрогнули. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-761","code":"761","description":{"en":"","ru":"<p><i><b>С вершины рога чудища вы увидели…</b></i></p><p>Выберите и разыграйте одно:<br><b>А. …большие залежи камня, которым чудище могло полакомиться. </b>Если на вашем участке есть особенности местности, где можно добывать ископаемые, выберите одну из них, чтобы завершить встречу. Выполните действие добычи ископаемых на этой особенности местности, не тратя <energy>. Успокойте чудище на 2.<br><b>Б. …лишь привычный пейзаж: ваши попытки что-то обнаружить, похоже, были бессмысленными и лишь разозлили чудище.</b> Завершите встречу. Разозлите чудище на 1.<br><b>В. …место, куда можно было безопасно спрыгнуть. </b>Завершите встречу. Потратьте <lore>, чтобы получить <minor_boost> к <conviction>.</p>"},"repeatable":false},{"id":"outcomes-764","code":"764","description":{"en":"","ru":"<p><i><b>Людей в вашей общине стало так много, что земля уже не могла их выдержать. Даже в самых крупных поселениях не хватало свободных жилищ. Мусор стал скапливаться так быстро, что это грозило распространением болезней. </b></i></p><p>Добавьте <activity><activity>. Если в долине не более 3 поселений, добавьте <unrest><unrest><unrest>. Каждый персонаж на участке местности с поселением, в котором нет мусорной ямы, получает <major_disease>. Затем, если на стене первобытной пещеры есть отметка чумы, добавьте <lore>. В противном случае добавьте карту «Мор» (ИЯ03) к грядущим испытаниям.</p><p>В конце ночи положите жетон истощения на каждый участок местности с поселением.</p>"},"repeatable":false,"marks":[{"label":"","image":"<plague>"}]},{"id":"outcomes-765","code":"765","description":{"en":"","ru":"<p><i><b>Вас затянуло в бурный поток. Тёмная вода захватила ваш разум и заполнила лёгкие. Очнувшись, вы почувствовали, как вода омывает ваши ноги. Солнце уже клонилось к горизонту.</b></i></p><p>Получите <major_injury> и потеряйте <energy>. Затем <exit>, переместив своего персонажа на другой участок местности, выбрав участок с озером, рекой или болотом, если возможно. Если персонаж <i>отважный </i>или <i>удачливый</i>, добавьте <lore><lore>.</p>"},"repeatable":false},{"id":"outcomes-766","code":"766","description":{"en":"","ru":"<p><i><b>Глубоко внутри глыбы замёрзшей лунной крови вы увидели силуэт, похожий на человеческий, — неведомо когда он был пленён таинственным инеем. Вы заметили, что из затвердевшего светящегося камня торчала сумка, явно принадлежащая этому существу.</b></i></p><p>Можете провести раскопки, не тратя <energy> и добавив 1 дополнительную лунную кровь в мешочек.</p>"},"repeatable":false},{"id":"outcomes-772","code":"772","description":{"en":"","ru":"<p><i><b>В течение года вы заприметили несколько разных знаков, но ни один из них так и не стал символом вашей общины.</b></i></p><p>Добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю о множестве знаков, включив в неё отметку раскола.</p><p>Затем завершите текущее испытание и текущую эру. См. с. 204, чтобы <era3>начать эру 3</era3>.</p>"},"repeatable":false,"marks":[{"label":"","image":"<schism>"}]},{"id":"outcomes-773","code":"773","description":{"en":"","ru":"<p><i><b>Вы брызнули водой на спину чудища, и из опалового камня на его шее начали пробиваться ростки. Вы сорвали один ярко‑зелёный побег, из‑за чего чудище резко остановилось. Вы скатились с его бока, как с горы, и рухнули оземь. Когда вы пришли в себя, то обнаружили, что чудище давно ушло, но сорванный росток всё ещё был у вас в руке.</b></i></p><p>Завершите встречу. Успокойте чудище на 1. Получите <major_injury>. Затем, если у персонажа, животного-компаньона или в сооружении-<i>хранилище </i>есть предмет со словом «живой» в названии, получите 2 волокна; в противном случае получите карту предмета «Живой росток» (ВЩ90).</p>"},"repeatable":false},{"id":"outcomes-774","code":"774","description":{"en":"","ru":"<p><i><b>Когда ваш народ расселился по долине, культурное единство стало особенно важным. Вы стали искать способы построить мосты доверия и укрепить духовные связи между людьми. </b></i></p><p>Совместно выберите один из следующих путей развития общины:<br><b>А. Разберитесь со старыми ранами и обидами.</b> Добавьте карту «Погасите искры» (ЦЯ21) к целям.<br><b>Б. Объявите охоту на легендарную добычу. </b>Добавьте карту «Выйдите на охоту под светом знамения» (ЦA17) к целям. <br><b>В. Гордо поведайте свою историю. </b>Добавьте карту «Сложите песни и сказания» (ЦA21) к целям.<br><b>Г. Начертите знаки культуры для будущих поколений. </b>Добавьте карту «Увековечьте в камне» (ЦA20) к целям.<br><b>Д. Начните развивать общие верования. </b>Если на стене первобытной пещеры есть отметка песнопевца [i] или отметка летописца [ii], добавьте карту «Отыщите символ» (ЦБ09) к целям.</p><p>Затем можете потратить 6 <lore>, чтобы выбрать другой эффект из этого списка и разыграть его. Повторите это сколько угодно раз.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<songweaver>"},{"label":"ii","image":"<scribe>"}]},{"id":"outcomes-776","code":"776","description":{"en":"","ru":"<p><i><b>Чтобы разузнать об истоках болезни, распространившейся в Сплетении, вы должны были самостоятельно изучить поражённые участки. Вы начали свои поиски на увядающей поляне. </b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><i><b>Лианы на поляне безжизненно повисли, а их кора была туго натянута. Возможно, вы могли бы получить новые сведения, срезав больше образцов.</b></i></p><p><b>Защитник.</b> Один из персонажей в походе должен провести проверку <dexterity>, чтобы взять образцы лиан. +2, если у этого персонажа есть <cut>, и +2, если он <i>любознательный</i>. Также +1 за каждый жетон на карте цели «Соберите образцы листвы» или +6, если эта цель выполнена.<br><b>≥14:</b>  Вы заметили, как лианы чахли у корней. Продолжите поход.<br><b>1-13:</b>  Вам не удалось найти ничего интересного. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Вы начали изучать корневую систему больших растений Сплетения, раскапывая землю в поисках подземного узла. </b></i></p><p><b>Группа.</b> Все персонажи в походе должны провести проверку <might>, чтобы откопать корни. +2, если у персонажа есть <dig>, и +2, если он <i>изобретательный</i>.<br><b>≥10:</b>  Вы откопали скрученные корни. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-9:</b>  Вы вскопали рыхлую почву, но ничего не нашли. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Вам нужно было внимательно изучить корни изнутри, но пробиться сквозь их плотную оболочку оказалось непросто. </b></i></p><p><b>Защитник.</b> Один из персонажей в походе должен провести проверку <awareness>, чтобы изучить корни. +2, если у этого персонажа есть <chop>, и +2, если он <i>сосредоточенный</i>. Также +1 за каждый жетон на карте цели «Соберите образцы листвы» или +6, если эта цель выполнена. <br><b>≥15:</b>  Вы прорубили корни и увидели скопление сочащихся ядом наростов. Они наверняка были симптомом порчи — неужели её источник находился ещё глубже под землёй? Завершите этот поход и достигните соответствующей цели.<br><b>1-14:</b>  Эта задача оказалась для вас нерешаемой. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-777","code":"777","description":{"en":"","ru":"<p><i><b>С рассветом вы увидели то, чего больше всего опасались: чудище брело к вашей деревне. То ли в гневе, то ли по неведению оно разрушило часть ваших сооружений и обратило ваш народ в бегство.</b></i></p><p>Завершите текущее испытание.</p><p>Уберите 6 <population>. На стене первобытной пещеры изобразите историю о страшном часе, включив в неё отметку бодрствующего чудища, украшенную отметкой гнева. Добавьте карту «Сумрак долины» (ИА08) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"","image":"<wrath>"}]},{"id":"outcomes-783","code":"783","description":{"en":"","ru":"<p><i><b>Вы узнали, что часть вашего народа считает, что чудище нужно обязательно выследить и покончить с ним навсегда.</b></i></p><p>Совместно выберите один из следующих путей развития общины:<br><b>А. Согласитесь охотиться на чудище. </b>Уберите <unrest><unrest><unrest>. Выберите чудище с самым высоким значением нрава и разозлите его на 3. Добавьте карту «Ночь бурь» (ИA09) к грядущим испытаниям.<br><b>Б. Запретите приближаться к чудищам.</b> Уберите <unrest><unrest><unrest>. Успокойте каждое чудище на 3. Запишите «Перемещаться на участок с бодрствующим чудищем» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет.<br><b>В. Убедите свой народ, что мирное сосуществование возможно.</b> Один из персонажей должен провести проверку <conviction>, чтобы разрядить обстановку. +2, если этот персонаж <i>мудрый</i>, +2, если у него есть отметка посредника, и +4, если у него есть отметка чудища с самым высоким значением нрава.<br><b>≥11:</b>  Вы ясно дали понять, к чему приведёт план охоты. Уберите <unrest><unrest><unrest>. Успокойте каждое чудище на 1.<br><b>9-10:</b>  Хоть вам и удалось убедить свой народ, кто-то остался недоволен. Добавьте <unrest><unrest><unrest>.<br><b>1-8:</b>  Группа людей не послушала вас и отправилась на битву с чудищем. Добавьте <unrest><unrest><unrest>. Разозлите каждое чудище на 3. Добавьте карту «Ночь бурь» (ИA09) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"","image":"<mediator>"}]},{"id":"outcomes-784","code":"784","description":{"en":"","ru":"<p><i><b>Вы знали, что чудище питается отборными камнями. Порывшись в своей сумке, вы попытались найти что‑то, что утолит его голод.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Накормите чудище отборным каменным лакомством.</b> Сбросьте 1 минерал, чтобы завершить встречу. Успокойте чудище на 1. Затем, если у персонажа, животного-компаньона или в сооружении-хранилище есть предмет со словом «сочащийся» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Сочащийся камень» (ВЩ91).<br><b>Б. Разочаруйте великого пожирателя камней.</b> Разозлите чудище на 1, затем завершите встречу.</p>"},"repeatable":false},{"id":"outcomes-785","code":"785","description":{"en":"","ru":"<p><i><b>Перед вами стояло безмолвное чудище — его огромная корона бросала вызов небу. Кто вы, чтобы противостоять созданию, чей каждый шаг возвещал огненную гибель и возрождение из пепла?</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><i><b>Приблизившись, вы почувствовали, как янтарный свет, льющийся от чудища, лишает вас сил для решительного рывка… </b></i></p><p><b>Чудище, группа, угроза. </b>Все персонажи в походе должны провести состязание, чтобы увидеть путь сквозь губительный свет: <awareness> против <conviction> чудища. +2, если у персонажа есть предмет коралла или предмет <i>лунной крови</i>, и +2, если персонаж <i>терпеливый</i>.<br><b>Успех.</b> Вы нашли путь сквозь свет. Продолжите поход.<br><b>Провал.</b> Свет истощил вас. Уменьшите все свои усиления дважды. Продолжите поход.</p><p><i><b>Чудище отступило, как только вы его настигли, быстро окружив вашу группу раскалёнными следами. Теперь вам нужно было ловко уклониться от огня, чтобы поймать чудище.</b></i></p><p><b>Чудище, группа, угроза. </b>Все персонажи в походе должны провести состязание, чтобы уклониться от огня: <dexterity> против <might> чудища. +2, если у персонажа есть <i>накидка</i>, и +2, если персонаж <i>хитрый</i>.<br><b>Успех. </b>Вы прорвались сквозь огненную завесу невредимыми. Если хотя бы один персонаж получил этот результат, продолжите поход. <br><b>Провал.</b> Получите <major_injury>, чтобы провести проверку ещё раз, или покиньте поход. Если все персонажи покинули поход, он окончился неудачно.</p><p><i><b>Вы добрались до чудища и стали взбираться на его покрытые шипами бока, что требовало нечеловеческих усилий.</b></i></p><p><b>Чудище, защитник. </b>Один из персонажей в походе должен провести состязание, чтобы взобраться: его <might> против <awareness> чудища. +2, если у этого персонажа есть «Верёвка», +2, если у него есть «Трость», +2, если у него есть <stoneworking>, и +2, если он <i>мстительный</i>.<br><b>Успех.</b> Вы цеплялись за уступы, с каждым движением теряя последние силы. Вы должны покинуть поход или навсегда уменьшить значение своей <conviction> либо <awareness> на 1. Другой персонаж в походе должен провести эту проверку. Если все персонажи покинули поход, он окончился неудачно. В противном случае продолжите поход.<br><b>Провал. </b>Вы не смогли удержаться на чудище. Получите <major_injury><major_injury> и покиньте поход. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><i><b>Оказавшись на чудище, вы сжали в кулаке бусину из янтаря. Сам воздух взвыл, а кожа начала слезать с вашей руки, когда вы вонзили камень в могучую грудь чудища.</b></i></p><p><b>Чудище, защитник. </b>Один из персонажей в походе должен провести состязание, чтобы выдержать боль: его <conviction> против <dexterity> чудища. +2, если у этого персонажа есть <i>талисман</i>, +4, если у него есть <i>трофей</i>, и +2, если персонаж <i>неукротимый</i>.<br><b>Успех. </b>Вы вонзили бусину глубоко в светящееся янтарём сердце чудища. Навсегда уменьшите значение своей <might> или <dexterity> на 1. Завершите этот поход и достигните соответствующей цели.<br><b>Провал.</b> Отметьте одну клетку возраста на карте персонажа. Если таким образом будет отмечена клетка легенды, персонаж немедленно умирает. Затем поход заканчивается неудачно, если только любой живой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-790","code":"790","description":{"en":"","ru":"<p><i><b>Чудище повернуло свою массивную голову, чтобы взглянуть на вас, пока вы стояли на его спине. Оно не отводило глаз от пламени.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Скормите пламя чудищу. Завершите встречу.</b> Чудище сбегает дважды. Уберите по одному жетону истощения с каждого участка местности, на который оно переместилось во время бегства.<br><b>Б. Потушите пламя. Завершите встречу. </b>Разозлите чудище на 2. Затем, если у персонажа, животного-компаньона или в сооружении-хранилище есть предмет со словом «поглощающий» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Поглощающий камень» (ВЩ100).</p>"},"repeatable":false},{"id":"outcomes-797","code":"797","description":{"en":"","ru":"<p><i><b>Вы сразились с чудищем и в конце концов оттеснили его обратно в логово. Существо скрылось внутри — и его не видели многие сезоны…</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Возрадуйтесь победе над чудищем.</b> Уберите <unrest><unrest>. На стене первобытной пещеры изобразите историю о конце бури, включив в неё отметку бодрствующего чудища, украшенную отметкой гнева [i].<br><b>Б. Сохраните огонь на случай, если чудище вернётся.</b> Если на стене первобытной пещеры есть отметка пламени, добавьте <population><population>. На стене первобытной пещеры изобразите историю о присягнувших огню стражах, включив в неё отметку пламени, заключённую в отметку связи [ii].</p><p>Завершите текущую эру. См. с. 196, чтобы <era2>начать эру 2</era2>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<wrath>"},{"label":"ii","image":{"image":"<bond>","overlay":{"image":"<blaze>","size":0.6,"x":5,"y":12,"rotate":0}}}]},{"id":"outcomes-801","code":"801","description":{"en":"","ru":"<p><i><b>Ваш пир запомнится на долгие годы.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем уберите <unrest><unrest><unrest><unrest> и добавьте <population><population>. На стене первобытной пещеры изобразите историю об осеннем изобилии, включив в неё отметку пира [i] и отметку изобилия [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<feast>"},{"label":"ii","image":"<plenty>"}]},{"id":"outcomes-811","code":"811","description":{"en":"","ru":"<p><i><b>Рядом с глубокой бороздой, оставленной чудищем, вы заметили куски коралла, которые оно аккуратно обошло стороной.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Проследите, как изменился путь. </b>Если у чудища есть неоткрытая назначенная карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><b>Б. Соберите коралловые осколки. </b>Получите 1 мёртвый коралл. Если у вас есть хотя бы 1 живой коралл или предмет <i>коралла</i>, вместо этого получите 1 живой коралл.</p>"},"repeatable":false},{"id":"outcomes-813","code":"813","description":{"en":"","ru":"<p><i><b>Вы изучили чудище и поняли, что, несмотря на свою силу, оно — живое существо, как и вы. Оно сновало по долине не просто так, а разыскивало ресурсы, необходимые для выживания. Познав его, ваш народ стал видеть в нём могущественную силу природы, достойную уважения. К тому же оно подняло наверх из глубин земли скрытые редкие ресурсы, которые вы могли использовать себе во благо.</b></i></p><p>Завершите текущее испытание.</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Посоветуйте людям своей общины избегать путей чудища. </b>Уберите <unrest>. Успокойте бодрствующее чудище на 2. На стене первобытной пещеры изобразите историю о могучем соседе, включив в неё отметку бодрствующего чудища, отметку осторожности [i] и отметку табу [iv]. Запишите «Отдыхать на участке с отпечатком чудища» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет.<br><b>Б. Воспользуйтесь разрушающими движениями чудища, чтобы добыть больше драгоценной серебристой жидкости. </b>Если на стене первобытной пещеры есть отметка лунной крови, добавьте <population><population><population>. Разозлите бодрствующее чудище на 3. На стене первобытной пещеры изобразите историю о даре лунной крови, включив в неё отметку бодрствующего чудища, отметку тайны [v] и отметку лунной крови, заключённую в отметку связи [ii].<br><b>В. Воспользуйтесь разрушительным отпечатком чудища, чтобы лучше исследовать тайны, скрытые под долиной. </b>Если на стене первобытной пещеры есть отметка подземного мира, добавьте <population><population><population>. Разозлите бодрствующее чудище на 3. На стене первобытной пещеры изобразите историю о раскрытых глубинах, включив в неё отметку бодрствующего чудища, отметку тайны [v] и отметку подземного мира, заключённую в отметку связи [iii].</p><p>Затем завершите текущую эру. См. с. 196, чтобы <era2>начать эру 2</era2>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":{"image":"<bond>","overlay":{"image":"<moonblood>","size":0.4,"x":5,"y":12,"rotate":0}}},{"label":"iii","image":{"image":"<bond>","overlay":{"image":"<underworld>","size":0.6,"x":4,"y":12,"rotate":0}}},{"label":"iv","image":"<taboo>"},{"label":"v","image":"<mystery>"}]},{"id":"outcomes-814","code":"814","description":{"en":"","ru":"<p><i><b>Налётчики, уверовавшие в свою неуязвимость, бросились в бой, но ваши отвага и мощь сломили их. Много крови было пролито впустую, однако время смуты миновало.</b></i></p><p>Уберите <population><population><population> и уберите 6 <unrest>. На стене первобытной пещеры изобразите историю о затихших, включив в неё отметку битвы [i] и отметку ужаса [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<harrowing>"}]},{"id":"outcomes-815","code":"815","description":{"en":"","ru":"<p><i><b>Чудище с интересом глядело на вас, явно чего‑то выжидая. Вы знали, что оно не выносит коралл, но вам было любопытно, что произойдёт, если вы всё же предложите его чудищу…</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Предложите коралловую безделушку. </b>Если в вашем инвентаре есть живой коралл или предмет коралла, сбросьте 1 такой материал или предмет, чтобы завершить встречу. Разозлите чудище на 3. Чудище сбегает. Затем, если у персонажа, животного-компаньона или в сооружении-<i>хранилище </i>есть предмет со словом «расколотый» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Расколотый камень» (ВЩ88).<br><b>Б. Предложите более безопасный дар.</b> Если в вашем инвентаре есть обработанный материал или предмет, сбросьте 1 обработанный материал или предмет, чтобы завершить встречу. Успокойте чудище на 1. Получите 1 сокровище этого чудища. <br><b>В. Быстро отступите, ничего не предложив.</b> Завершите встречу. Разозлите чудище на 2.</p>"},"repeatable":false},{"id":"outcomes-816","code":"816","description":{"en":"","ru":"<p><i><b>Небо раскололось с пронзительным рёвом. Вы посмотрели наверх и увидели в образовавшемся там зияющем разрыве Скитальца. Кусок камня оторвался от него и устремился вниз, в долину. Внезапная тишина ненадолго оборвала рёв, а затем вас швырнуло наземь громогласной волной вселенского разрушения.</b></i></p><p><b>Это невообразимое столкновение навсегда изменило долину. </b>Пройдите описанные ниже этапы в указанном порядке.<br><b>Этап 1. Всё в месте падения мгновенно испарилось. </b>Уберите все накладки с любого участка в долине, выбрав участок с коралловыми зарослями, если возможно, и поместите поверх него накладку места падения (ОБ01б). Каждый персонаж на этом участке местности становится легендой — создайте новых персонажей им на замену.<br><b>Этап 2. Ударная волна разрушила окрестности. </b>Уберите все накладки с каждого участка местности, соседнего с местом падения. Если таким образом должно быть убрано логово чудища, вместо этого переверните его неактивной стороной вверх (чудище с неактивным логовом не может стать бодрствующим). Каждый персонаж на этих участках получает <major_injury><major_injury><major_injury>.<br><b>Этап 3. Разрушение распространилось ещё дальше. </b>Переверните все накладки неактивной стороной вверх на каждом участке местности, соседнем с хотя бы одним участком, который соседствует с местом падения. Если логово чудища должно стать неактивным таким образом, вместо этого разозлите это чудище на результат броска <1d6>. Каждый персонаж на этих участках получает <major_injury> и  <minor_injury>.<br><b>Этап 4. Ветер и падающие обломки могли угрожать всей долине.</b> Персонажи на каждом другом участке местности в регионе с местом падения и в каждом соседнем регионе получают <major_injury> и <minor_injury>, если на их участке нет <shelter>. Затем, если на затронутом участке местности есть поселение, разрушьте в нём 2 случайных сооружения.<br><b>Этап 5. Коралловые заросли начали стремительно распространяться от места падения. </b>Если возможно, поочерёдно поместите неразмещённые накладки коралловых зарослей на соседние с местом падения участки местности, на которых нет ни одной накладки. Бросьте <1d6>, чтобы поместить накладку в соответствующий район: [1-2] А, [3-4] Б, [5-6] В.<br><b>Этап 6. Неожиданные превращения изменили саму природу долины.</b> Разыграйте как можно больше из следующего:<br><b>А. Леса начали меняться странным образом. </b>Если в долине есть хотя бы 1 участок Дивной долины, добавьте карту КЛ02 в колоду добычи припасов в лесу.<br><b>Б. В степной траве начали попадаться загадочные стебли.</b> Если в долине есть хотя бы 1 участок Поднебесной равнины, добавьте карту КС02 в колоду добычи припасов в степи.<br><b>В. Даже в необычном Сплетении появилось нечто чуждое. </b>Если в долине есть хотя бы 1 участок Сплетения, добавьте карту КП02 в колоду добычи припасов на полянах.<br><b>Этап 7. Чем больше распространялся хаос, тем больше паниковал и впадал в отчаяние ваш народ.</b>Совместно выберите один из следующих путей развития общины:<br><b>А. Свыкнитесь с обстоятельствами. </b>Добавьте <unrest><unrest> и уберите <population><population><population>. Добавьте карту «Выживите в растущем хаосе» (ЦВ01) к целям.<br><b>Б. Заставьте людей избегать места падения.</b> Если на стене первобытной пещеры есть отметка осторожности [i], запишите «Перемещаться в место падения» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет.<br><b>В. Найдите убежище в глубинах.</b> Если на стене первобытной пещеры есть отметка тайны [ii] и отметка подземного мира [iii], добавьте карту «Укройтесь под землёй» (ЦВ10) к целям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":"<mystery>"},{"label":"iii","image":"<underworld>"}]},{"id":"outcomes-817","code":"817","description":{"en":"","ru":"<p><i><b>Когда вы приблизились к логову чудища, то обнаружили, что вход в логово опутан щупальцами коралла. Великое создание оказалось в ловушке внутри, а ведь на него вы возлагали свои надежды.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><b><i>Коралл вокруг логова, казалось, заснул и стал подобен каменной преграде. Придётся её пробить!</i></b></p><p>Коралл, группа. Все персонажи в походе должны провести проверку <might>, чтобы проломить барьер. +2, если у персонажа есть <strike>, +4, если у него есть <stoneworking>, и +2, если он <i>изобретательный</i>.<br><b>≥12:</b>  Вы раскололи коралл, и он обрушился, открыв проход — достаточно широкий, чтобы вы смогли попасть внутрь логова. Продолжите поход.<br><b>1-11:</b>  Вы выбились из сил. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy>, чтобы провести проверку ещё раз.</p><p><i><b>В самом сердце логова вы нашли чудище, опутанное живыми коралловыми щупальцами — толстыми, как лианы, и прочными, как жилы.</b></i></p><p><b>Чудище, коралл, группа.</b> Все персонажи в походе должны провести проверку <dexterity>, чтобы освободить чудище. +2, если у персонажа есть <cut>, +4, если у него есть предмет лунной крови с <cut>, и +2, если он <i>мудрый</i>.<br><b>≥13:</b>  Вы перерезали достаточно щупалец, чтобы освободить одну из конечностей чудища, и оно поднялось на ноги, разрывая оставшиеся путы. Продолжите поход.<br>1-12  Несмотря на ваши усилия, прочные коралловые щупальца отрастали почти с той же скоростью, с какой вы их срезали. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не получит <major_injury> или не потратит <lore><lore>, чтобы провести проверку ещё раз.</p><p><i><b>Чудище освободилось от пут, и тут же его охватила слепая ярость. Вам нужно было направить гнев чудища в нужное русло, пока оно не выбрало вас своей целью.</b></i></p><p><b>Чудище, защитник, коралл. </b>Один из персонажей в походе должен провести проверку <conviction>, чтобы успокоить чудище. +4, если в журнале записан хотя бы один секрет этого чудища, +2, если этот персонаж <i>сосредоточенный</i>, +4, если значение нрава чудища не более 5. Также +2 за каждое сброшенное выбранным персонажем сокровище чудища (не более +6).<br><b>≥14:</b>  Чудище посмотрело вам в глаза и успокоилось. Завершите этот поход и достигните соответствующей цели.<br><b>9-13:</b>  Поход окончился неудачно, если только любой персонаж в походе не потратит или , чтобы провести проверку ещё раз.<br><b>1-8:</b>  Чудище в агонии обрушило на вас обломки логова. Получите <major_injury><major_injury>, затем разыграйте исход как при [9-13].</p>"},"repeatable":false},{"id":"outcomes-818","code":"818","description":{"en":"","ru":"<p><i><b>Ваш народ привык каждый сезон переезжать с места на место, что позволяло ему охотиться и рыбачить, не истощая природные ресурсы.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Добавьте карту «Период затишья» (ИЯ01) к грядущим испытаниям (даже если вы завершали ранее это испытание).</p><p>Затем на стене первобытной пещеры изобразите историю о сезонном переселении, включив в неё отметку каравана [i], отметку охотника [ii] и отметку изобилия [iii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caravan>"},{"label":"ii","image":"<hunter>"},{"label":"iii","image":"<plenty>"}]},{"id":"outcomes-821","code":"821","description":{"en":"","ru":"<p><i><b>Выбранный вами символ сплотил людей. Спустя много лет он стал олицетворением неповторимости вашей культуры.</b></i></p><p>В конце любого дня можете завершить текущее испытание. </p><p>Затем уберите <unrest><unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю об объединяющем знаке, включив в неё отметку посредника [i] и отметку знамения с открытого жетона на карте цели «Сотворите миф», заключённую в отметку связи [ii]. Также добавьте отметку этого знамения на сторону легенды карт персонажей. После чего разыграйте эффект в зависимости от знамения:<br><b>А. Грозовая туча стала символом силы вашей культуры.</b> Если знамение — <cloud>, каждый персонаж получает черту «неукротимый». Каждый персонаж, на стороне легенды карты которого нет отметки становления [iv], навсегда увеличивает <might> на 1 (не более чем до 7), а затем получает отметку становления.<br><b>Б. Скиталец стал символом несгибаемости и приспособляемости вашего народа. </b>Если знамение — <comet>, каждый персонаж получает черту «изобретательный». Каждый персонаж, на стороне легенды карты которого нет отметки становления [iv], навсегда увеличивает одну из своих самых низких характеристик на 3 (не более чем до 8), а затем получает отметки коралла [iii] и становления.<br><b>В. Таинственная луна заняла видное место в культуре вашего народа. </b>Если знамение — <moon>, каждый персонаж получает черту «мудрый». Каждый персонаж, на стороне легенды карты которого нет отметки становления [iv], навсегда увеличивает <awareness> на 1 (не более чем до 7), а затем получает отметку становления.<br><b>Г. Животворящее солнце стало символом вашего народа. </b>Если знамение — <sun>, каждый персонаж получает черту «отважный». Каждый персонаж, на стороне легенды карты которого нет отметки становления (iv), навсегда увеличивает <conviction> на 1 (не более чем до 7), а затем получает отметку становления.<br><b>Д. Холодные мерцающие звёзды стали символом стремлений вашего народа к недосягаемым высотам.</b> Если знамение — <star>, каждый персонаж получает черту «хитрый». Каждый персонаж, на стороне легенды карты которого нет отметки становления [iv], навсегда увеличивает <dexterity> на 1 (не более чем до 7), а затем получает отметку становления.</p><p>Затем завершите текущее испытание и текущую эру. См. с. 204, чтобы <era3>начать эру 3</era3>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<mediator>"},{"label":"ii","image":"<bond>"},{"label":"iii","image":"<coral>"},{"label":"iv","image":"<growth>"}]},{"id":"outcomes-823","code":"823","description":{"en":"","ru":"<p><i><b>Зима вступила в свои права, не дав посевам на ваших полях взойти. Похоже, эта затея была обречена на провал с самого начала. Вашему народу теперь нужно было срочно найти припасы на зиму, чтобы выжить.</b></i></p><p>Завершите текущее испытание.</p><p>Затем уберите <population><population><population> и добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю о пересохших полях, включив в неё отметку расколотой земли и отметку <sun>.</p>"},"repeatable":false,"marks":[{"label":"","image":"<brokenearth>"}]},{"id":"outcomes-824","code":"824","description":{"en":"","ru":"<p><i><b>Ваш народ создал жизненно важную опорную точку в долине. Через много лет она может дать вашим потомкам шанс на процветание.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем добавьте <population><population><population><population>. Добавьте карты «Период затишья» (ИЯ01) и «Тлеющие угли» (ИЯ05) к грядущим испытаниям (даже если вы завершали ранее испытание «Тлеющие угли»). Добавьте к целям карту «Пройдите по следам тайн» (ЦA11).</p>"},"repeatable":false},{"id":"outcomes-830","code":"830","description":{"en":"","ru":"<p><i><b>Два чудища, исполненные ненависти, сверлили друг друга взглядами, готовясь превратить долину в поле для сражения. </b></i></p><p>Выберите 2 случайных чудищ с активными логовами в долине. Оба становятся бодрствующими. Добавьте к целям карты «Узрите великую битву» (ЦЯ16) и «Склоните чашу весов» (ЦЯ17).</p>"},"repeatable":false},{"id":"outcomes-831","code":"831","description":{"en":"","ru":"<p><i><b>Под светом Скитальца чудище впало в оцепенение. Вы легко смогли подойти к нему.</b></i></p><p>Получите <minor_boost> к <conviction>. Продолжите встречу.</p>"},"repeatable":false},{"id":"outcomes-832","code":"832","description":{"en":"","ru":"<p><i><b>Далёкая луна хранила свои секреты. Ходили слухи, что обнаруженная вами лунная кровь несла в себе проклятие, неподвластное разумению смертных.</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о лунной завесе, включив в неё отметку <moon> и отметку тайны.</p>"},"repeatable":false,"marks":[{"label":"","image":"<mystery>"}]},{"id":"outcomes-833","code":"833","description":{"en":"","ru":"<p><i><b>Время шло, и древние распри переросли в жестокий конфликт.</b></i></p><p>Уберите <population><population>. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Изгоните тех, кто отказывается забыть прошлые обиды. </b>Уберите <population>. На стене первобытной пещеры изобразите историю о кровавых днях, включив в неё отметку битвы [i] и отметку раскола [iii].<br><b>Б. Попытайтесь примирить конфликтующие стороны. </b>Добавьте <unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о непростых истинах, включив в неё отметку посредника [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<mediator>"},{"label":"iii","image":"<schism>"}]},{"id":"outcomes-838","code":"838","description":{"en":"","ru":"<p><i><b>По поселениям поползли слухи: пророк предсказал ужасную катастрофу — нашествие чудовищной гнили, прогрызающей корни Сплетения и превращающей их в песок. Великие заросли поддерживали ваш народ, поэтому их гибель должна была стать концом привычного уклада жизни. Пророк утверждал, что Сплетение должно получить причитающуюся ему жертву, чтобы, как и прежде, давать ресурсы вашему народу.</b></i></p><p>Если на стене первобытной пещеры есть отметка Сплетения [ii], заключённая в отметку погибели [i], добавьте 4 <lore>. В противном случае добавьте карты «Соберите образцы листвы» (ЦЖ04) и «Изучите природу заражения» (ЦЖ05) к целям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<doom>"},{"label":"ii","image":"<tangle>"}]},{"id":"outcomes-839","code":"839","description":{"en":"","ru":"<p><i><b>Отмщение — это яд с горьким привкусом, однако ваши люди слишком хорошо изучили его вкус. В тени поселений враждебные группы неустанно сводили друг с другом счёты.</b></i></p><p>Добавьте карту «Беспрестанное насилие» (ПР06) в колоду пути, если возможно. В противном случае уберите <population>.</p>"},"repeatable":false},{"id":"outcomes-841","code":"841","description":{"en":"","ru":"<p><i><b>С вершины зубчатого склона вы смотрели вниз на землю огня и пепла. Из глубин дрожащей горы поднимался дым — словно чёрный змей, пожирающий небо. Что же могло выжить в этой пустоши?</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Отправьтесь в знакомую землю огня и пепла. </b>Если на стене первобытной пещеры есть отметка Вулканических пустошей [ii], переместите своего персонажа на любой участок Вулканических пустошей, затем добавьте <lore><lore><lore>.<br><b>Б. Исследуйте огненную землю.</b> Если у вас есть хотя бы одна неразмещённая основа местности, на стене первобытной пещеры изобразите историю о затронутых пламенем землях, включив в неё отметку открытия [i], отметку <sun> и отметку Вулканических пустошей [ii]. Добавьте карту «Изучите зловещее предзнаменование» (ЦЕ03) к целям. Затем расширьте долину, пройдя описанные ниже этапы.<br><b>Этап 1. </b>Добавьте новую основу местности в долину. Поместите её по соседству с участком местности со своим персонажем, если возможно. Границы основы должны соседствовать с как можно большим количеством границ уже размещённых основ. Если есть несколько возможных позиций, выберите одну случайным образом.<br><b>Этап 2. </b>Положите все неразмещённые участки Вулканических пустошей, кроме начального, в мешочек и перемешайте. Затем по одному вытащите 3 участка и поместите их неисследованной стороной вверх в ячейки новой основы по направлению с севера на юг и с востока на запад.<br><b>Этап 3.</b> Если есть хотя бы 1 неиспользованная накладка геотермальных источников, выберите случайный участок Вулканических пустошей и поместите туда накладку геотермальных источников активной стороной вверх. Бросьте <1d6>, чтобы поместить накладку в соответствующий район: [1-2] А, [3-4] Б, [5-6] В.<br><b>Этап 4.</b> Если на стене первобытной пещеры есть отметка ЧД4 [iii], переместите логово этого чудища на случайный участок Вулканических пустошей без накладки. В противном случае это чудище появляется в долине: поместите его логово на случайный участок Вулканических пустошей без накладки.<br><b>Этап 5.</b> Добавьте карты ПВ01–ПВ03 в колоду пути, если возможно.<br><b>В. Проследите за тем, как поток лавы покрывает пеплом другой регион.</b> Если у вас нет неразмещённых основ местности, поместите случайный участок Вулканических пустошей рядом со своим участком (не в ячейку основы местности), а затем поместите своего персонажа на него. До конца текущего испытания считайте, что этот участок относится к региону Вулканических пустошей (см. правила дополнения «Пища и притчи», с. 8). Завершив испытание, верните в коробку этот участок местности вместе с жетонами и накладками на нём. Персонажи, которые находились на убранном участке, умирают.</p><p>В конце любого дня можете завершить текущее испытание.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<discovery>"},{"label":"ii","image":"<volcanic_wastes>"},{"label":"iii","image":"<bh4>"}]},{"id":"outcomes-843","code":"843","description":{"en":"","ru":"<p><i><b>Вы приблизились к зловещему пылающему дереву.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><i><b>Вокруг дерева поднялась стена дыма. Чем ближе вы подходили, тем сильнее она затмевала ваши чувства.</b></i></p><p><b>Защитник. </b>Один из персонажей в походе должен провести проверку <awareness>, чтобы проложить путь вперёд. +2 за каждый предмет для <i>исследования </i>у этого персонажа и +2, если он <i>сосредоточенный</i>.<br><b>≥10:</b>  Вы нашли путь сквозь клубящиеся тени. Продолжите поход.<br><b>1-9:</b>  Вы сбились с пути и, едва не задохнувшись, выбрались наружу. Получите <major_disease>. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Из завесы дыма внезапно поднялось дерево, и его пылающая листва озарила небо над вами. Вокруг посыпались горящие листья, и вам пришлось уклоняться от них, чтобы не обжечься.</b></i></p><p><b>Группа.</b> Все персонажи в походе должны провести проверку <dexterity>, чтобы подойти к дереву. +2, если персонаж <i>удачливый</i>, и +4, если в журнале записан хотя бы 1 секрет этого чудища.<br><b>≥11:</b>  Вы прорвались сквозь обжигающие листья и добрались до подножия дерева. Продолжите поход.<br><b>1-10:</b>  Вы сильно обожглись. Покиньте поход или получите <major_injury> и <minor_injury>. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><i><b>В дупле высоко на дереве что‑то поблёскивало в отсветах падающих листьев. Видимо, это было что‑то важное для чудища… </b></i></p><p><b>Защитник. </b>Один из персонажей в походе должен провести проверку <conviction>, чтобы дотянуться. +2, если у этого персонажа есть предмет с <fire>, +2, если у персонажа есть <stoneworking>, и +2, если он <i>изобретательный</i>.<br><b>≥12:</b>  Вы сунули руку в дупло и извлекли невообразимое сокровище — янтарную бусину, пульсирующую жаром. Вы быстро завернули её и спрятали в сумку. Завершите этот поход и достигните соответствующей цели.<br><b>1-11:</b>  Вас охватил страх, и вы отступили. Уменьшите все свои усиления дважды. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-845","code":"845","description":{"en":"","ru":"<p><i><b>Подобно дождю, падающему на раскалённые угли, ваши слова готовы были погасить разгоревшиеся страсти.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Уладьте разногласие уважительной речью. </b>Уберите <unrest><unrest><unrest>.<br><b>Б. Попросите других взглянуть на свою роль в этом конфликте. </b>Добавьте <unrest>. Верните в коробку карту «Открытая враждебность» (НО02).</p>"},"repeatable":false},{"id":"outcomes-846","code":"846","description":{"en":"","ru":"<p><i><b>Вы нашли следы гигантских существ, которые, вероятно, огромным стадом проходили через этот регион.</b></i></p><p>Поместите по 1 жетону тайны на каждый неисследованный участок в основе местности.</p>"},"repeatable":false},{"id":"outcomes-848","code":"848","description":{"en":"","ru":"<p><i><b>Выбравшись из завалов и отряхнувшись, хищник в панцире посмотрел на вас с настороженным любопытством.</b></i></p><p>Добавьте карту «Подружитесь с зубастиком» (ЦЖ16) к целям.</p>"},"repeatable":false},{"id":"outcomes-849","code":"849","description":{"en":"","ru":"<p><i><b>Разные, порой противоречивые трактовки недавних событий вызвали разногласия среди вашего народа. Разговоры у костра становились всё напряжённее…</b></i></p><p>Добавьте карту «Ворчание у костра» (НО01) в колоду ночи, если возможно. В противном случае добавьте <unrest>.</p>"},"repeatable":false},{"id":"outcomes-852","code":"852","description":{"en":"","ru":"<p><i><b>Защитник кометы снова приближался к поселению, и вы снова бросились ему наперерез. Однако на этот раз, похоже, он узнал вас и не стал мешкать, быстро направившись вам навстречу. Вокруг его тела сомкнулась коралловая броня, которую будет непросто пробить.</b></i></p><p>Проведите состязание, чтобы сразиться: ваша <might> против <conviction> кораллового защитника. +2 к вашему результату, если у вас есть предмет <i>лунной крови</i>. +3 к результату кораллового защитника за каждый соседний участок местности с активными коралловыми зарослями. <br><b>Успех. </b>Вы яростно оттеснили кораллового защитника, пробив его броню. Когда вы нанесли последний удар, доспехи рассыпались, оставив после себя лишь облако мерцающих спор. Но каким-то образом противнику удалось ускользнуть. Добавьте <major_boost> к <conviction>.<br><b>Провал.</b> Вы обрушили на кораллового защитника град ударов, но так и не смогли пробить его броню. Он ударил вас в ответ, и вы почувствовали, как у вас хрустнули кости. Получите <major_injury> и <minor_injury>.</p>"},"repeatable":false},{"id":"outcomes-857","code":"857","description":{"en":"","ru":"<p><i><b>Необычная коралловая активность сошла на нет, когда Скиталец исчез с небосвода на несколько месяцев. Какова бы ни была связь между ними, ваши люди не могли её осознать.</b></i></p><p>Завершите текущее испытание. </p><p>Добавьте <lore><lore>.</p>"},"repeatable":false},{"id":"outcomes-870","code":"870","description":{"en":"","ru":"<p><i><b>Поиски знамений среди обжигающего пепла и удушающего дыма оказались тщетными. Вы чувствовали себя неподготовленными к грядущему. Тем временем чудище становилось всё активнее по мере того, как дым сгущался…</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте карту «Извержение» (ИЕ04) к грядущим испытаниям. На стене первобытной пещеры изобразите историю об опалённых надеждах, включив в неё отметку ЧД4 [i] и отметку пламени [ii].</p><p>Затем разыграйте первое, что можете:<br><b>А. Пепельное чудище направилось к Вулканическим пустошам. </b>Если на стене первобытной пещеры есть отметка ЧД4 [i], переместите его логово на случайный участок Вулканических пустошей. Бросьте <1d6>, что бы поместить логово в соответствующий район: [1-2] А, [3-4] Б, [5-6] В.<br><b>Б. Пепельное чудище появилось в долине. </b>Подготовьте ЧД4, как описано в разделе «Появление чудища» в правилах игры на с. <rulebook>74</rulebook>. Поместите его логово на случайный участок Вулканических пустошей. Бросьте <1d6>, чтобы поместить логово в соответствующий район: [1-2] А, [3-4] Б, [5-6] В.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<bh4>"},{"label":"ii","image":"<blaze>"}]},{"id":"outcomes-871","code":"871","description":{"en":"","ru":"<p><i><b>Во сне ваш взор воспарил к небесам. Словно звезда, вы смотрели вниз и видели спящее чудище в его убежище. Тысячелетия проносились мимо, засыпая логово пылью веков.</b></i></p><p>Выберите случайное неразмещённое логово чудища и поместите его на любой участок местности, выбрав участок без накладки и с особенностью местности, соответствующей склонности этого чудища, если возможно. Бросьте <1d6>, чтобы поместить логово в соответствующий район: [1-2] А, [3-4] Б, [5-6] В. На стене первобытной пещеры изобразите историю о первозданной колыбели, включив в неё отметку чудища, чьё логово вы поместили, и отметку открытия. </p><p>Правила логов чудищ см. на с. 211–212. Затем верните в коробку карту «Безграничные сны» (НЯ02).</p>"},"repeatable":false,"marks":[{"label":"","image":"<discovery>"}]},{"id":"outcomes-875","code":"875","description":{"en":"","ru":"<p><i><b>Внезапно чудище стряхнуло с себя глубокое оцепенение. Повинуясь неведомому зову, существо понеслось вперёд, раскалывая землю на своём пути.</b></i></p><p>Поместите накладку расколотого отпечатка активной стороной вверх на каждый участок местности с жетоном следов. Для каждой помещённой накладки выбирайте район без накладки и с озером, болотом или рекой, если возможно. Правила расколотого отпечатка см. на с. 211.</p><p>Затем уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-878","code":"878","description":{"en":"","ru":"<p><i><b>Лишённый припасов и новых охотничьих угодий, ваш народ оказался в смертельной западне между голодом и надвигающимися холодами. Вам приходилось охотиться под падающим снегом, посылая некоторых людей своей общины на верную гибель в ледяных землях.</b></i></p><p>Завершите текущее испытание.</p><p>Уберите <population><population><population>. Добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю о лютой зиме, включив в неё отметку льда [i] и отметку ужаса [ii]. Добавьте карту «Тлеющие угли» (ИЯ05) к грядущим испытаниям (даже если вы завершали ранее это испытание).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<ice>"},{"label":"ii","image":"<harrowing>"}]},{"id":"outcomes-881","code":"881","description":{"en":"","ru":"<p><i><b>В вашем разуме возникла картина необъятного мерцающего моря. Серебристые воды сверкали и закручивались в звёздном свете. Из моря поднимались зазубренные клыки ледяного кристалла.</b></i></p><p>Добавьте <lore><lore>. Возьмите 2 случайных участка Звёздного моря и посмотрите на их исследованные стороны в течение 1 минуты, не показывая другим игрокам. Затем верните их в коробку. Можете рассказать остальным игрокам о том, что увидели. На стене первобытной пещеры изобразите историю о мерцающем море, включив в неё отметку лунной крови [ii] и отметку тайны [i].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<mystery>"},{"label":"ii","image":"<moonblood>"}]},{"id":"outcomes-882","code":"882","description":{"en":"","ru":"<p><i><b>Словно само время обернулось вспять вокруг чудища. Жилы и кожа натянулись на древние кости, и исполин восстал, обновлённый вашей жертвой. С изумлением и страхом вы взирали, как гигантское существо вышло из своего логова…</b></i></p><p>Добавьте <unrest><unrest><unrest>. Переверните неактивное логово чудища. На стене первобытной пещеры изобразите историю о возвращении древнего существа, включив в неё отметку этого чудища и отметку расколотой земли. Это чудище появляется в долине (см. раздел «Появление чудища» в правилах игры на с. <rulebook>74</rulebook>). Затем, если в долине есть хотя бы 2 активных логова, добавьте карту «Битва титанов» (ИЯ08) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"","image":"<brokenearth>"}]},{"id":"outcomes-883","code":"883","description":{"en":"","ru":"<p><i><b>Ярость чудища была страшна: оно сокрушало все преграды на своём пути и безжалостно давило каждого, кому не повезло оказаться у него под ногами.</b></i></p><p>За каждый участок местности с поселением, где есть жетон следов, бросьте <1d6>.+1, если значение нрава чудища не более 5. Разыграйте эффект по результату броска:<br><b>1-4:</b>  Чудище оставило после себя лишь разбитый кратер. Поселение становится руинами. Уберите <1d6><population>.<br><b>5:</b>  Чудище проломило заграждения на окраине поселения. Разрушьте 2 случайных сооружения в этом поселении. Уберите <population><population>.<br><b>6:</b>  Чудище снесло постройку и напугало жителей. Разрушьте 1 случайное сооружение в этом поселении. Добавьте <unrest>. </p><p>Затем уберите все жетоны следов этого чудища и назначьте ему инстинкт «Истребить» (ЧК18).</p>"},"repeatable":false},{"id":"outcomes-885","code":"885","description":{"en":"","ru":"<p><i><b>Чудище подобралось к семени и переплело свои щупальца с зелёными побегами. Казалось, чудище кормило другой организм, помогая ему расти! </b></i></p><p>Разыграйте первое, что можете:<br><b>А. Позвольте семени расцвести.</b> Если цель «Взрастите саженец» в игре и ещё не достигнута, достигните её немедленно.<br><b>Б. Беспомощно наблюдайте, как семя оттаивает. </b>Если цель «Разомкните круг» в игре и ещё не достигнута, уберите с неё все жетоны лунной крови.<br><b>В. Воодушевитесь дарами чудища. </b>Каждый персонаж получает <minor_boost> к <awareness>.</p><p>Затем уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20)</p>"},"repeatable":false},{"id":"outcomes-886","code":"886","description":{"en":"","ru":"<p><i><b>Вы знали, что можете прогнать чудище, используя его страх перед кораллом. Чудище обращалось в бегство всякий раз, когда сталкивалось с коралловыми побегами или когда те расцветали под светом кометы.</b></i></p><p>Завершите встречу. Разозлите чудище на 1. Чудище сбегает.</p>"},"repeatable":false},{"id":"outcomes-887","code":"887","description":{"en":"","ru":"<p><i><b>Вы вонзили оружие в пульсирующее сердце кораллового чудища. Существо содрогалось, пока смерть не поглотила его. Раздался мощный перезвон, и коралл по всей долине поблёк и умер.</b></i></p><p>Добавьте <population><population><population> и уберите <unrest><unrest><unrest>. Переверните коралловые заросли и логово кораллового чудища неактивной стороной вверх.</p><p>На стене первобытной пещеры изобразите историю о коралловом возмездии, включив в неё отметку этого чудища, отметку битвы [i], а также отметку коралла, заключённую в отметку окончания [ii]. Ваша община <b>выжила</b>.</p><p>Поздравляем! Вы завершили кампанию «Наскальной истории»! Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!</p><p>Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. <rulebook>97</rulebook> или раздел «Бесконечный режим» на с. <rulebook>102</rulebook>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":{"image":"<conclusion>","overlay":{"image":"<coral>","size":0.85,"x":3,"y":5,"rotate":0}}},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-888","code":"888","description":{"en":"","ru":"<p><i><b>Вы подавили бунт, но так и не устранили его первопричину.</b></i></p><p>Завершите текущее испытание.</p><p>Установите значение <unrest> на 4. Уберите <population><population><population>. На стене первобытной пещеры изобразите историю о рассыпанном пепле, включив в неё отметку битвы. Затем добавьте карту «Ворчание у костра» (НО01) в колоду ночи, если возможно.</p>"},"repeatable":false,"marks":[{"label":"","image":"<battle>"}]},{"id":"outcomes-889","code":"889","description":{"en":"","ru":"<p><i><b>С годами ваши люди обнаружили пути, ведущие вглубь долины, и невероятные чудеса открылись перед ними...</b></i></p><p>Разыграйте как можно больше из следующего:<br><b>А.</b> Добавьте карты ПР01–ПР04 и ПН01–ПН11 в колоду пути.<br><b>Б.</b> Если в долине есть хотя бы 1 участок Дивной долины, добавьте карты ПД01–ПД06 в колоду пути.<br><b>В.</b> Если в долине есть хотя бы 1 участок Поднебесной равнины, добавьте карты ПП01–ПП06 в колоду пути.<br><b>Г.</b> Если в долине есть хотя бы 1 участок Ураганных холмов, добавьте карты ПУ01–ПУ05 в колоду пути. <br><b>Д.</b> Если в долине есть хотя бы 1 участок Звёздного моря, добавьте карты ПЗ01–ПЗ03 в колоду пути.<br><b>Е.</b> Получите силы мантий МА01–МА04, если ещё этого не сделали (см. раздел «Силы мантий» на с. <rulebook>65</rulebook> правил). </p><p><i><b>Чем дольше вы находились в долине, тем больше чудес и ужасов её ночей вы начинали видеть. </b></i></p><p>Разыграйте как можно больше из следующего:<br><b>А.</b> Добавьте карты НН01–НН16 в колоду ночи.<br><b>Б.</b> Если в долине есть хотя бы 1 участок Дивной долины, добавьте карты НД01–НД03 в колоду ночи.<br><b>В. </b>Если в долине есть хотя бы 1 участок Поднебесной равнины, добавьте карты НП01–НП03 в колоду ночи. </p><p><i><b>Затем ваши люди нашли последний оплот могущественных ледников.</b></i></p><p>Пройдите описанные ниже этапы.<br><b>Этап 1. </b>Добавьте новую основу местности в долину. Эта основа должна быть помещена по соседству с самым северным участком местности и касаться как можно большего числа границ первой основы. <br><b>Этап 2. </b>Положите все неразмещённые участки местности начального региона в мешочек. По одному вытащите 3 участка и поместите их неисследованной стороной вверх в ячейки новой основы по направлению с севера на юг и с востока на запад.<br><b>Этап 3.</b> Поместите накладку ледникового купола (ОБ01a) на самый северный участок в только что помещённой основе местности.<br><b>Этап 4.</b> Бросьте <1d6> и поместите ледники на только что помещённых участках местности по результату броска: [1-2] один ледник в район А любого из участков местности без накладки, [3-4] один ледник в район Б любого из участков местности без накладки, [5] разыграйте результаты 1-2 и 3-4, [6] один ледник в район Б и один ледник в район В любого из участков местности без ледникового купола.</p><p><i><b>Дополнение «Природа зверя»</b></i></p><p>Если вы используете дополнение «Природа зверя», разыграйте как можно больше из следующего:<br><b>А. </b>Добавьте карты ПЖ01–ПЖ04 в колоду пути.<br><b>Б.</b> Если в долине есть хотя бы 1 участок Сплетения, добавьте карты ПС01–ПС06 в колоду пути. В противном случае добавьте карту «Найдите Сплетение» (ЦЖ01) к целям.<br><b>В.</b> Добавьте карты НЖ01–НЖ07 в колоду ночи.<br><b>Г. </b>Если в долине есть хотя бы 1 участок Сплетения, добавьте карты НС01–НС03 в колоду ночи.<br><b>Д.</b> Добавьте карту ДЛ15 в колоду добычи припасов в лесу.<br><b>Е.</b> Добавьте карту ДС15 в колоду добычи припасов в степи.<br><b>Ж. </b>Добавьте карту ГЖ01 в колоду спуска (даже если действие спуска ещё не доступно).<br><b>З.</b> Добавьте карту РД11 в колоду рыбалки.<br><b>И.</b> Если в долине есть хотя бы 1 участок Сплетения, добавьте карту «Под навесом» (ИЖ01) к грядущим испытаниям. </p><p><i><b>Дополнение «Пища и притчи»</b></i></p><p>Если вы используете дополнение «Пища и притчи», разыграйте как можно больше из следующего:<br><b>А. </b>Добавьте карты ПЕ01–ПЕ07 в колоду пути.<br><b>Б.</b> Если в долине есть хотя бы 1 участок Вулканических пустошей, добавьте карты ПВ01–ПВ03 в колоду пути.<br><b>В.</b> Добавьте карты НЕ01–НЕ10 в колоду ночи.<br><b>Г.</b> Добавьте карту «Пир на весь мир» (ИЕ01) к грядущим испытаниям.</p>"},"repeatable":false},{"id":"outcomes-890","code":"890","description":{"en":"","ru":"<p><i><b>Ваши усердные поиски раскрыли удивительную правду: послание предполагаемого пророка было искажено, но в нём содержалось зерно истины. Над долиной и правда нависало древнее зло, и вам предстояло встретиться с ним. Не с помощью пустых домыслов и тайных заговоров, что будоражили умы прежде, а с твёрдой уверенностью человека, прошедшего тяжкие испытания и познавшего истину.</b></i></p><p>В конце любого дня можете завершить текущее испытание. Затем разыграйте первое, что можете:<br><b>А. Послание говорило о гниении под самими вашими ногами.</b> Если на стене первобытной пещеры есть отметка расколотой земли [iii], заключённая в отметку погибели [ii], добавьте карту «Подземная зараза» (ИЖ03) к грядущим испытаниям.<br><b>Б. Сторонники пророка утверждали, что мир скоро навеки задохнётся в мертвенно-белом пепле. </b>Если на стене первобытной пещеры есть отметка пламени [iv] заключённая в отметку погибели [ii], добавьте карту «Жгучий пепел, сверкающие тайны» (ИЕ03) к грядущим испытаниям.<br><b>В. Пророк бормотал о всеобъемлющем единстве, которое должно было прийти в долину. </b>Добавьте к грядущим испытаниям карту «Час приготовлений» (ИВ03).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<coral>"},{"label":"ii","image":"<doom>"},{"label":"iii","image":"<brokenearth>"},{"label":"iv","image":"<blaze>"}]},{"id":"outcomes-891","code":"891","description":{"en":"","ru":"<p><i><b>Вы успешно перенесли своё поселение в новые земли, богатые дичью.</b></i></p><p>До конца текущего испытания не помещайте жетоны истощения при выполнении действий добычи припасов или рыбалки.</p>"},"repeatable":false},{"id":"outcomes-893","code":"893","description":{"en":"","ru":"<p><i><b>Хотя вам удалось немного сдержать натиск коралловых зарослей, но поднявшуюся при этом пыльную завесу невозможно было разогнать ни оружием, ни огнём. Из‑за неё растения вяли и умирали, а еда становилась всё более скудной.</b></i></p><p>Уберите <population><population>. Добавьте к грядущим испытаниям карту «Презрение земли» (ИВ06).</p>"},"repeatable":false},{"id":"outcomes-895","code":"895","description":{"en":"","ru":"<p><i><b>Через коралловые споры, наполнявшие воздух вокруг вас, чудище двигалось медленно, что позволяло вам с лёгкостью на него взбираться. В гребне на его спине вы обнаружили странный предмет. Вы могли бы достать его, использовав коралл, но чудище могло это заметить…</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Используйте коралл, чтобы достать предмет. </b>Сбросьте живой коралл из своего инвентаря или предмет коралла, чтобы завершить встречу. Разозлите чудище на 3. Чудище сбегает. Затем, если у персонажа, животного-компаньона или в сооружении-<i>хранилище </i>есть предмет со словом «симбиотический» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Симбиотическое яйцо» (ВЩ93).<br><b>Б. Не тревожьте чудище. </b>Продолжите встречу.</p>"},"repeatable":false},{"id":"outcomes-899","code":"899","description":{"en":"","ru":"<p><i><b>Вы скатились в странный омут, и вещество прилипло к вашей коже, когда вы начали тонуть. Холод распространился по всему телу — такой, будто вы стояли на улице в безлунную зимнюю ночь. Перед глазами поплыли маленькие размытые огоньки, похожие на звёзды. Вас швыряло в этом веществе неизвестно как долго. Затем холод и тьма охватили вас.</b></i></p><p>Добавьте отметку лунной крови на сторону легенды карты своего персонажа, затем верните в коробку эту карту. Создайте нового персонажа, как если бы ваш предыдущий персонаж умер. Добавьте карту «Облик на глубине» (ПЗ02) в колоду пути.</p>"},"repeatable":false,"marks":[{"label":"","image":"<moonblood>"}]},{"id":"outcomes-903","code":"903","description":{"en":"","ru":"<p><i><b>Разговоры переросли в ссоры, а те, в свою очередь, — в стычки. Чем больше нарастало напряжение, тем больше вы начинали бояться, что это может подтолкнуть некоторых людей вашей общины на крайние меры. </b></i></p><p>Добавьте карту «Знак опасности» (ПР03) в колоду пути, если возможно. В противном случае добавьте <unrest>.</p>"},"repeatable":false},{"id":"outcomes-907","code":"907","description":{"en":"","ru":"<p><i><b>Среди переливов ртутного моря вы заметили странное лицо на глубине. Сперва вы подумали, что это ваше отражение, но постепенно лик всплыл на поверхность. Это была человеческая фигура, покрытая затвердевшей лунной кровью. Вы вытащили тело на берег и освободили от оболочки. Фигура пошевелилась, закашлялась и смерила вас взглядом, в котором отражалась бесконечность ушедших эпох.</b></i></p><p>Возьмите из коробки карту молодого или пожилого персонажа (он не может быть легендой) с отметкой лунной крови [i]. На стене первобытной пещеры изобразите историю о замёрзшем, включив в неё отметку лунной крови [i] и отметку тайны [ii]. Верните в коробку карту «Облик на глубине» (ПЗ02). Затем выберите одно:<br><b>А. Взовите к мудрости древнего. </b>Выберите <conviction> или <awareness>. Можете заменить значение выбранной характеристики с карты своего персонажа на значение этой же характеристики с карты персонажа из коробки. Если сделали это, добавьте отметку становления [iii] на сторону легенды карты своего персонажа.<br><b>Б. Попросите древнего взять на себя вашу ношу.</b> Замените карту своего персонажа картой персонажа из коробки. Ваш предыдущий персонаж не будет использоваться до конца этого испытания. В конце испытания верните в коробку выбранную карту персонажа.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<moonblood>"},{"label":"ii","image":"<mystery>"},{"label":"iii","image":"<growth>"}]},{"id":"outcomes-908","code":"908","description":{"en":"","ru":"<p><i><b>Из‑за низко нависших над пропастями туманов показалась земля…</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Посмотрите на окружающую вас знакомую местность с новой точки зрения.</b> Если на стене первобытной пещеры есть отметка Дивной долины [i] или у вас нет непомещённых основ местности, добавьте <lore><lore><lore>. <br><b>Б. Попадите на землю чудес. </b>Если на стене первобытной пещеры нет отметки Дивной долины [i] и у вас есть хотя бы 1 неразмещённая основа местности, откройте новый регион. На стене первобытной пещеры изобразите историю о зелёной низине, включив в неё отметку Дивной долины [i] и отметку открытия [ii]. Затем расширьте долину, пройдя описанные ниже этапы.<br><b>Этап 1. </b>Добавьте новую основу местности в долину. Поместите её по соседству с участком местности со своим персонажем, если возможно. Границы основы должны соседствовать с как можно большим количеством границ уже размещённых основ. Если есть несколько возможных позиций, выберите одну случайным образом.<br><b>Этап 2. </b>Положите все неразмещённые участки Дивной долины, кроме начального, в мешочек и перемешайте. Затем по одному вытащите 3 участка и поместите их неисследованной стороной вверх в ячейки новой основы по направлению с севера на юг и с востока на запад.<br><b>Этап 3 (только для эры 1 и бесконечного режима).</b> Если в запасе есть хотя бы 1 непомещённая накладка ледника, бросьте <1d6> и поместите ледники по результату броска: [1-2] один ледник в район А одного из участков местности без накладки, [3-4] один ледник в район Б одного из участков местности без накладки, [5] разыграйте результаты 1-2 и 3-4, [6] бросьте <1d6> ещё раз и прочитайте один из исходов ниже, соответствующий результату броска.<br>[1-2] <outcome> 846, [3-5] <outcome> 134, [6] <outcome> 446.<br><b>Этап 4.</b> Замешайте карты ПД01–ПД06 в колоду пути и карты НД01–НД03 в колоду ночи, если возможно.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<verdantvale>"},{"label":"ii","image":"<discovery>"}]},{"id":"outcomes-913","code":"913","description":{"en":"","ru":"<p><i><b>Пока вы медленно плыли в ледяной жидкости, вам казалось, что весь мир перевернулся. Проследовав за пузырьками до поверхности, вы с жадностью глотнули воздух. Сотрясаясь от холода, пока жидкость стекала с тела, вы с трудом поднялись на ноги, когда добрались до берега. Море сверкающего серебра омывало ваши ступни. Над головой мерцали холодные звёзды — их рисунок показался вам знакомым. И, что удивительнее всего, вдалеке восходила голубовато‑зелёная луна, заполняя собой небо.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Поймите, что вы знаете это место, пусть оно и показалось необычным, когда вы его увидели воочию. </b>Если на стене первобытной пещеры есть отметка Звёздного моря [i], завершите это действие спуска. Получите все награды, которые вы присвоили. Переместите своего персонажа на любой участок Звёздного моря, выбрав участок с пещерой, если возможно. Затем добавьте <lore><lore><lore>.<br><b>Б. Осознайте, что это отличное место для исследования.</b> Если у вас есть хотя бы 1 неразмещённая основа местности, завершите это действие спуска. Получите все награды, которые вы присвоили. На стене первобытной пещеры изобразите историю о холодных следах, включив в неё отметку открытия [iii], отметку Звёздного моря [i] и отметку подземного мира [ii]. Наконец, подготовьте Звёздное море, как описано на с. 216.<br><b>В. Затаившись, словно ощутили ледяное дыхание ужаса за спиной, исследуйте местность.</b> Если у вас нет неразмещённых основ местности, поместите случайный участок Звёздного моря рядом с долиной, но без соприкосновения с ней. Переместите своего персонажа на этот участок. До конца текущего испытания считайте, что этот участок местности относится к региону Звёздного моря (см. с. 216) и что на нём есть пещера для спуска. В конце испытания верните в коробку этот участок местности вместе с жетонами и накладками этого участка. Персонажи, которые находились на убранном участке, умирают.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<starlitsea>"},{"label":"ii","image":"<underworld>"},{"label":"iii","image":"<discovery>"}]},{"id":"outcomes-914","code":"914","description":{"en":"","ru":"<p><i><b>Сеть ваших туннелей раскинулась под долиной. Путешествуя по ним, вы ненароком открыли дверь охотникам из теней. Жуткие членистоногие монстры, бродившие по мрачным глубинам, вырвались на поверхность в ваших поселениях, разрушая сооружения и утаскивая несчастных жителей под землю. Когда разведчики из ближайшего поселения прибыли, чтобы расследовать случившееся, они обнаружили лишь огромную воронку на месте поселения.</b></i></p><p>Завершите текущее испытание.</p><p>Каждое из ваших поселений со входом было поглощено землёй. Эти поселения становятся руинами. Уберите <population><population> за каждое поглощённое поселение. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Оставьте позади тех, кто ушёл в подземелья.</b> На стене первобытной пещеры изобразите историю о поглощённом царстве, включив в неё отметку расколотой земли [i], отметку ужаса [ii] и отметку табу [iii]. Уберите из долины все руины поселений, которые были поглощены в конце этого испытания. Запишите «Выполнять действие спуска» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет.<br><b>Б. Верните себе потерянные города.</b> Если на стене первобытной пещеры есть отметки зверобоя [iv] и охотника [v], добавьте <unrest><unrest><unrest><unrest> и уберите <population><population>. На стене первобытной пещеры изобразите историю о чудищах из тьмы, включив в неё отметку подземного мира [vi], отметку ужаса [ii] и отметку табу [iii]. Запишите «Выполнять действие спуска без предмета оружия» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет.<br><b>В. Совершите дерзкую спасательную вылазку под землю. </b>Если на стене первобытной пещеры есть отметки открытия [vii] и тайны [viii], добавьте <population><population><population>. На стене первобытной пещеры изобразите историю о хранителях сокровенных знаний, включив в неё отметку подземного мира [vi], отметку тайны [viii] и отметку табу [iii]. Запишите «Выполнять действие спуска без „Карты“» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет.</p><p>Затем завершите текущую эру. См. с. 204, чтобы <era3>начать эру 3</era3>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<brokenearth>"},{"label":"ii","image":"<harrowing>"},{"label":"iii","image":"<taboo>"},{"label":"iv","image":"<beastslayer>"},{"label":"v","image":"<hunter>"},{"label":"vi","image":"<underworld>"},{"label":"vi","image":"<discovery>"},{"label":"viii","image":"<mystery>"}]},{"id":"outcomes-915","code":"915","description":{"en":"","ru":"<p><i><b>Мощный порыв ветра сбил вас с ног, и вы рухнули в затянутый туманом мир внизу. Падая сквозь пелену, вы заметили возможное спасение — тончайшую нить, свободно качающуюся на ветру. Вы потянулись к ней — и она обвилась вокруг вашей руки. Затем нечто начало тянуть вас вверх, прочь из горящих туманов. Когда вы наконец оказались на спине шагающего хребта, вашего спасителя нигде не было видно, но виток нити остался.</b></i></p><p>Получите 1 шёлк. Добавьте <lore><lore>. Добавьте к целям карту «Пройдите сквозь туман» (ЦЯ25).</p>"},"repeatable":false},{"id":"outcomes-916","code":"916","description":{"en":"","ru":"<p><i><b>Вы приблизились к высоким горам, заметив земли по ту сторону. Если вам удастся преодолеть это громадное каменное препятствие, вам откроется новый регион для исследования. </b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><b><i>Подниматься в горы было трудно даже в лучшие времена. Одному из вас пришлось разведать путь для всей группы. </i></b></p><p><b>Защитник, угроза. </b>Один из персонажей в походе должен провести проверку <might>, чтобы взобраться на гору. +2, если у него есть «Скальный крюк», +2, если у него есть «Верёвка», и +4, если у него есть отметка ледника [i].<br><b>≥9:</b>  Вы без труда вскарабкались по отвесной скале. Продолжите поход.<br><b>1-8:</b>  Начало выдалось тяжёлым — острые камни грозили изрезать вам руки. Поход окончился неудачно, если только любой персонаж в походе не получит <major_injury> или не потратит <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Ваша группа уверенно продвигалась вперёд по надёжной тропе. Но ваше настроение резко упало, когда на горизонте показалась буря, грозящая яростно обрушиться на склон горы.</b></i></p><p><b>Группа, погода. </b>Все персонажи в походе должны провести проверку <awareness>, чтобы найти укрытие. +2, если у персонажа есть <i>одежда</i>, +2, если у него есть <i>накидка</i>, +2, если у него есть предмет с <fire>, и +4, если у него есть отметка льда [ii]. <br><b>≥11:</b>  Вам удалось вовремя укрыться. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-10:</b>  Яростная буря обрушилась на склон и начала швырять вас о каменные выступы. Получите <major_injury>. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><i><b>Буря утихла, но склон горы оставался скользким и опасным.</b></i></p><p><b>Защитник, угроза.</b> Один из персонажей в походе должен провести проверку <dexterity>, чтобы найти безопасный путь вниз. +2, если у него есть предмет для <i>исследования</i>, и +4, если у него есть отметка прибытия [iii].<br><b>≥10:</b>  Вы ловко выбрались по безопасному маршруту. Завершите этот поход и достигните соответствующей цели.<br><b>1-9:</b>  Вы поскользнулись и начали падать. Получите <major_injury><major_injury>. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или не сбросит «Верёвку» либо «Скальный крюк», чтобы провести проверку ещё раз.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<glacier>"},{"label":"ii","image":"<ice>"},{"label":"iii","image":"<arrival>"}]},{"id":"outcomes-917","code":"917","description":{"en":"","ru":"<p><i><b>В прошлом чудище было защитником ваших людей в долине. Теперь вы пришли к великому зверю с последней просьбой: даровать выживание вашему народу.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><b><i>Вы подошли к логову чудища с дарами в руках. Если ваша с ним связь что‑то значила, это должно помочь.</i></b></p><p><b>Чудище, защитник. </b>Один из персонажей в походе должен провести проверку <awareness> и сбросить материал или предмет, чтобы сделать подношение. +2, если сброшенный материал — сокровище чудища, +2, если это редкий материал, +2, если это предмет, и +6, если это трофей. Также +2 за каждый секрет этого чудища, записанный в журнал.<br><b>≥12:</b>  Чудище медленно повернулось к вам. Продолжите поход.<br><b>1-11:</b>  Чудище, похоже, вас не заметило. Поход окончился неудачно, если только любой персонаж в походе не потратит <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Громадная голова чудища склонилась к вам. Вы содрогнулись пред его взором.</b></i></p><p><b>Чудище, группа. </b>Все персонажи в походе должны провести проверку <conviction>, чтобы выстоять. +2, если персонаж <i>неукротимый</i>, и +2 за каждый секрет этого чудища, записанный в журнал.<br><b>≥13:</b>  Вы держались стойко. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-12:</b>  Вы не выдержали взгляда чудища. Покиньте поход и сбегите. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><i><b>Чудище не реагировало. Как вы могли объясниться с этим существом? Вы протянули руку к его громадной голове и начали говорить, отчаянно надеясь, что оно поймёт вас.</b></i></p><p><b>Чудище, защитник. </b>Один из персонажей в походе должен провести проверку <awareness>, чтобы поговорить с чудищем. +2 за каждый секрет этого чудища, записанный в журнал.<br><b>≥14:</b>  Чудище отвернулось от вас и ушло в неизвестном направлении. Были ли ваши просьбы поняты этим существом? Завершите этот поход и достигните соответствующей цели.<br><b>1-13:</b>  Чудище, похоже, не поняло вас. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-918","code":"918","description":{"en":"","ru":"<p><i><b>Чудище возвышалось над горизонтом — то был зверь из старинных мифов, воскрешённый силой коралла. Пульсирующие коралловые щупальца оплетали его древние кости, и оно двигалось к вам с яростью, которую не усмирила бы и смерть.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><i><b>Вокруг чудища образовалась оболочка из спящего коралла, а под ней его тело приводили в движение живые щупальца. Вам предстояло расколоть эту оболочку, чтобы добраться до уязвимого нутра.</b></i></p><p><b>Чудище, защитник, коралл.</b> Один из персонажей в походе должен провести состязание, чтобы сразиться: его <might> против <dexterity> кораллового чудища. +2, если у этого персонажа есть <strike> или <stoneworking> (или +4, если у него есть предмет лунной крови с <strike> или <stoneworking>), и +2, если персонаж <i>хитрый</i>.<br><b>Успех. </b>С большим трудом, но вы вскрыли оболочку, обнажив бьющееся коралловое сердце в груди чудища. Продолжите поход. <br><b>Провал.</b> Живые коралловые щупальца выползали наружу и залечивали раны, а вы задыхались от спор, вырывающихся из трещин. Получите <minor_disease>. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy>, чтобы провести проверку ещё раз.</p><p><b><i>Разъярённое вашей атакой, чудище нанесло ответный удар. Земля вокруг вас содрогнулась и раскололась!</i></b></p><p><b>Чудище, коралл, группа. </b>Все персонажи в походе должны провести состязание, чтобы избежать урона: <dexterity> или <awareness> против <might> кораллового чудища. +2, если у персонажа есть <i>одежда</i>, +2, если у него есть «Талисман из лунной крови», и +2, если он <i>удачливый</i>.<br><b>Успех. </b>Вы успели укрыться от летящих обломков. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>Провал. </b>Камень ударил вас прямо в грудь и сбил с ног. Получите <major_injury> и <minor_injury>. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore><lore>, чтобы провести проверку ещё раз.</p><p><i><b>Когда звон в ушах стих, а пыль осела, судьба преподнесла вам ещё один шанс. Кто‑то из вас мог взбежать по вытянутой конечности чудища и ударить в трещину его панциря, чтобы пронзить бьющееся коралловое сердце!</b></i></p><p><b>Чудище, защитник, коралл.</b> Один из персонажей в походе должен провести состязание, чтобы пронзить сердце: его <dexterity> против <conviction> чудища. +2, если у этого персонажа есть <i>оружие лунной крови</i>, +4, если у персонажа есть <i>оружие-трофей</i>, и +2, если персонаж <i>мстительный</i>.<br><b>Успех.</b> Вы вонзили оружие в коралловое сердце и пронзили его! Завершите этот поход и достигните соответствующей цели.<br><b>Провал. </b>Чудище подкинуло вас в воздух, и вы упали с глухим треском. Сбросьте оружие, использованное в проверке. Получите <major_injury><major_injury>. Вернитесь к предыдущей вылазке, если только не потратите <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-919","code":"919","description":{"en":"","ru":"<p><b><i>Спокойные дни подошли к концу, на горизонте нависла неопределённость…</i></b></p><p>Завершите текущее испытание, затем добавьте  <population><population>.</p>"},"repeatable":false},{"id":"outcomes-924","code":"924","description":{"en":"","ru":"<p><i><b>Вы бросились к чудищу…</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><i><b>…и осознание содеянного внезапно нахлынуло на вас, когда над головой навис каменный лик чудища. Существо оказалось таким громадным, таким древним… Как вы вообще могли надеяться противостоять ему?</b></i></p><p><b>Чудище, защитник. </b>Один из персонажей в походе должен провести состязание, чтобы вести остальных за собой: его <conviction> против <awareness> чудища. +2, если этот персонаж <i>неукротимый</i>.<br><b>Успех.</b> Вы собрались с духом, и остальные двинулись за вами. Продолжите поход.<br><b>Провал. </b>Ваша решимость дала трещину. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Когда вы приблизились к чудищу, вокруг вас внезапно появился лес щупалец, мешающих двигаться вперёд. Вы должны были не дать им добраться до вас!</b></i></p><p><b>Чудище, группа, угроза. </b>Все персонажи в походе должны провести состязание, чтобы избежать урона: <dexterity> или <awareness> против <dexterity> чудища. +2, если у персонажа есть оружие, и +2, если он <i>осторожный</i>.<br><b>Успех.</b> Вы прорвались сквозь колючие заросли. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>Провал.</b> Вас изранили колючие побеги. Покиньте поход или получите <major_injury><major_injury> и <minor_injury>. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><i><b>Вы снова бросились к чудищу, и его массивная голова опустилась навстречу вам. Чудище вгрызлось в землю, и вас накрыло волной грязи. Вы прыгнули и обрушили удар на гигантскую голову.</b></i></p><p><b>Чудище, защитник.</b> Один из персонажей в походе должен провести состязание, чтобы сразиться с чудищем: его <dexterity> или <might> против <might> чудища. +2, если у этого персонажа есть <i>оружие</i>, и +4, если у персонажа есть <i>трофей</i>.<br><b>Успех.</b> Вы обрушили оружие с сокрушительным ударом, который ещё долго будут помнить. Завершите этот поход и достигните соответствующей цели.<br><b>Провал.</b> Ответный удар противника отбросил вас. Поход окончился неудачно, если только любой персонаж в походе не получит <major_injury>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-928","code":"928","description":{"en":"","ru":"<p><i><b>Место, в которое вы попали, оказалось странным и удивительным — оно было совсем не похоже на тот мир, что вы видели раньше…</b></i></p><p>Добавьте <lore><lore><lore>. Бросьте <1d6> и добавьте соответствующую цель: [1-3] «Отправьтесь за зубчатый край» (ЦЯ04), [4-6] «Отправьтесь в подземный мир» (ЦЯ05).</p>"},"repeatable":false},{"id":"outcomes-929","code":"929","description":{"en":"","ru":"<p><i><b>Во тьме глубинных корневых тоннелей вы не нашли ответа на вопрос, как спасти Сплетение. Среди вашего народа ходили верования, что Сплетение обречено и единственный выход — покинуть это место. Но кто‑то верил и в другой путь.</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest>. Все поселения в регионе Сплетения становятся руинами. За каждое такое поселение уберите <population><population>. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Найдите земли без заражения. </b>На стене первобытной пещеры изобразите историю о потерянном рае, включив в неё отметку исхода [i] и отметку Сплетения [ii]. Добавьте к грядущим испытаниям карту «Исход» (ИЯ09).<br><b>Б. Спасите умирающее Сплетение, чего бы это ни стоило вашему народу. </b>На стене первобытной пещеры изобразите историю о цене гнили, включив в неё отметку ужаса [iii] и отметку Сплетения [ii]. Уберите <1d6><population> и добавьте <unrest><unrest>. Затем добавьте карту «Глубоко захороненная надежда» (ИЖ04) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<exodus>"},{"label":"ii","image":"<tangle>"},{"label":"iii","image":"<harrowing>"}]},{"id":"outcomes-931","code":"931","description":{"en":"","ru":"<p><i><b>Ваш народ с тревогой наблюдал за передвижением Скитальца. И словно в ответ на это земля выгнулась и треснула, точно грязь, которую некий громадный зверь стряхнул со своего хребта. По поселениям стремительно разнеслись пожары. </b></i></p><p>Переверните все неактивные коралловые заросли. В каждом поселении разрушьте 1 случайное сооружение, если персонажи (один или несколько) на участке местности с этим поселением не сбросят 2 воды.</p>"},"repeatable":false},{"id":"outcomes-932","code":"932","description":{"en":"","ru":"<p><i><b>Ваши дары и приветствия были приняты, и новые друзья повели вас в своё поселение. Там вы обнаружили множество знакомых артефактов и сооружений. Сидя у костра, вы поняли: вы наконец‑то нашли своих давних сородичей. </b></i></p><p>Добавьте 6 <population>. Постройте новое поселение на самом удалённом от других поселений участке местности, на котором нет накладки, не тратя <energy>. Бросьте <1d6> три раза и постройте в этом поселении следующие сооружения по результатам бросков (повторяющиеся результаты перебрасывайте): [1-2] костровая яма (СР02), [3] дом исцеления (СР10), [4] сторожевая башня (СР19), [5] сад (СР20), [6] памятник небу (СР13).</p><p>На стене первобытной пещеры изобразите историю о воссоединении, включив в неё отметку посредника.</p>"},"repeatable":false,"marks":[{"label":"","image":"<mediator>"}]},{"id":"outcomes-934","code":"934","description":{"en":"","ru":"<p><i><b>Вы могли лишь наблюдать, как два титана сражались друг с другом, как они сминали леса и разбивали склоны гор в своей легендарной битве. В конце концов один одержал верх и низринул изломанное тело поверженного. На мгновение долина затихла, узрев нового владыку.</b></i></p><p>Проведите состязание <might> между двумя чудищами. Уберите 6 <population>, если отметка победившего чудища не заключена в отметку связи [i] на стене первобытной пещеры.</p><p>Затем на стене первобытной пещеры изобразите историю о разрушительной дуэли, включив в неё отметки обоих бодрствующих чудищ и отметку расколотой земли [ii].</p><p>Затем завершите текущее испытание. Переверните логово проигравшего чудища.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<bond>"},{"label":"ii","image":"<brokenearth>"}]},{"id":"outcomes-939","code":"939","description":{"en":"","ru":"<p><i><b>Когда ваша группа исследователей попыталась пересечь ледники, на вашем пути встали отвесные утёсы, ревущие ветра и леденящий холод. Чтобы выжить, вам понадобились выдержка, находчивость и подходящее снаряжение.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. <rulebook>60</rulebook>).</p><p><b><i>Вы подошли к огромной ледяной стене. Несмотря на холод, от одного её вида пот выступил у вас на затылке.</i></b></p><p><b>Группа, угроза.</b> Все персонажи в походе должны провести проверку <dexterity>, чтобы взобраться на стену. +2, если у персонажа есть «Скальный крюк», +2, если у персонажа есть «Верёвка», и +4, если у него есть <stoneworking>.<br><b>≥9:</b>  Вам удалось взобраться по ледяной стене, и вы оказались на замёрзшем плато. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-8:</b>  Лёд и земля под вами обрушились, и вы соскользнули вниз по стене, почувствовав боль. Получите <major_injury> и покиньте поход либо потратьте <energy><energy> или <lore><lore>, чтобы провести проверку ещё раз. Если все персонажи покинули поход, он окончился неудачно.</p><p><b><i>На вершине ледника вы увидели бескрайнюю равнину мёрзлой земли, испещрённой ледяными зубцами. Когда вы начали пробираться вперёд, над вами сгустились тучи и в воздухе зловеще закружились снежинки.</i></b></p><p><b>Группа, погода. </b>Все персонажи в походе должны провести проверку <might>, чтобы выдержать холод. +2, если у персонажа есть <i>одежда</i>, и +2, если он <i>неукротимый</i>.<br><b>≥9:</b>  Вы устояли перед пронизывающим ветром. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-8:</b>  Ваши конечности начали страшно неметь, и вы почувствовали, как силы покидают тело. Продолжать путь было безумием. Покиньте поход либо получите <major_disease> или потратьте <lore><lore>, чтобы провести проверку ещё раз. Если все персонажи покинули поход, он окончился неудачно.</p><p><b><i>Тучи рассеялись, но белизна ледника ослепила вас и лишила ориентира. Вы должны были найти путь и не сбиться с него. </i></b></p><p><b>Защитник, угроза.</b> Один из персонажей в походе должен провести проверку <awareness>, чтобы проложить маршрут через ледяное плато. +2 за каждый предмет для <i>исследования </i>у этого персонажа и +2, если он <i>сосредоточенный</i>.<br><b>≥10:</b>  Вам удалось пройти по леднику. Завершите этот поход и достигните соответствующей цели.<br><b>1-9:</b>  Ваша группа окончательно заблудилась среди однообразной безжизненной белизны. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-940","code":"940","description":{"en":"","ru":"<p><i><b>Ваши усилия по созданию великой цитадели не увенчались успехом. С годами ваши соплеменники окончательно уверовали в то, что стройке не будет конца. Незавершённые части города в итоге были заселены как есть, и продолжать строительство стало невозможно. Наконец, границы, которые вы наметили много лет назад, исчезли в буйных зарослях, и многие люди вашей общины разбрелись. Потомки, что остались здесь, жили среди руин былых мечтаний.</b></i></p><p>Завершите текущее испытание.</p><p>Уберите <population><population>. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Зацепитесь за призрачную славу несбывшегося. </b>Добавьте <unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о брошенной работе, включив в неё отметку расколотой земли [i] и отметку несчастья [ii]. Навсегда уменьшите <awareness> каждого персонажа на 1 (не может быть меньше 1) и увеличьте <conviction> на 2 (не более чем до 7). Затем добавьте отметку становления [iii] и отметку несчастья [ii] на сторону легенды карт всех персонажей.<br><b>Б. Позвольте честолюбию и неудачам исчезнуть из памяти.</b> На стене первобытной пещеры изобразите историю о забытом пути, включив в неё отметку расколотой земли [i] и отметку тайны [iv]. Когда ваши текущие персонажи станут легендами в конце эры, случайным образом выберите половину из них (округляя в меньшую сторону). Эти карты легенд становятся забытыми: верните их в коробку.</p><p>Затем завершите текущую эру. См. с. 204, чтобы <era3>начать эру 3</era3>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<brokenearth>"},{"label":"ii","image":"<misfortune>"},{"label":"iii","image":"<growth>"},{"label":"iv","image":"<mystery>"}]},{"id":"outcomes-948","code":"948","description":{"en":"","ru":"<p><i><b>Ходили слухи, что пророку довелось увидеть великое огненное чудище, извергающее пламя по всей земле и сжигающее вашу цивилизацию дотла за грех гордыни. Предупреждение пророка вашему народу было простым: великий огонь нужно насытить, пока он сам не возымел желаемое.</b></i></p><p>Добавьте карту «Запечатлейте знамения» (ЦЕ04) к целям.</p>"},"repeatable":false},{"id":"outcomes-966","code":"966","description":{"en":"","ru":"<p><i><b>Смерть, расползшаяся по долине, возвещала вечную зиму. Кости вашего народа, засыпанные пеплом, сохранились для тех веков, которым ещё предстояло наступить. Но вашу историю пересказать было более некому.</b></i></p><p>На стене первобытной пещеры изобразите историю о покрытом пеплом исходе, включив в неё отметку почерневшего неба [ii] и отметку ужаса [i]. Ваша община <b>исчезла</b>.</p><p>Такой конец хоть и далёк от счастливого, но он всё же может послужить уроком для народов, которые заселят эту долину в будущем. Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!</p><p>Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. <rulebook>97</rulebook> или раздел «Бесконечный режим» на с. <rulebook>102</rulebook>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<blackenedsky>"},{"label":"ii","image":"<harrowing>"},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-973","code":"973","description":{"en":"","ru":"<p><b><i>Вы заприметили странный огромный курган. Что это могло быть? Здание? Логово древнего существа? Могила?</i></b></p><p>Выберите случайное непомещённое логово чудища и поместите его неактивной стороной вверх на участок местности в своей основе местности или в соседней. Выбирайте неисследованный участок местности без накладок, если возможно. На стене первобытной пещеры изобразите историю о древней гробнице, включив в неё отметку чудища, чьё логово вы поместили, и отметку открытия. Правила логов чудищ см. на с. 211–212.</p>"},"repeatable":false,"marks":[{"label":"","image":"<discovery>"}]},{"id":"outcomes-975","code":"975","description":{"en":"","ru":"<p><i><b>Ярость небес обрушилась вниз, поджигая листву вокруг!</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Обуздайте силу огня.</b> Добавьте карту «Разведите огонь» (ЦA08) к целям.<br><b>Б. Потушите неконтролируемое пламя.</b> Если на стене первобытной пещеры есть отметка пламени, дважды уменьшите <fire> на своём участке местности. Затем добавьте <lore>.</p>"},"repeatable":false,"marks":[{"label":"","image":"<blaze>"}]},{"id":"outcomes-977","code":"977","description":{"en":"","ru":"<p><i><b>Ядовитый туман вокруг вас внезапно вспыхнул огненным столбом.</b></i></p><p>Проведите проверку <dexterity>, чтобы отскочить назад. +2, если вы <i>осторожный</i>, и +4, если у вас есть отметка пламени.<br><b>≥12:</b>  Вам удалось уклониться от сокрушительной мощи взрыва и выбраться лишь слегка обожжённым. Получите <minor_injury>.<br><b>6-11:</b>  Взрыв сбил вас с ног. Получите <major_injury>.<br><b>1-5:</b>  Вы получили сильные ожоги. Получите <major_injury><major_injury>. Сбросьте все свои предметы с <fire>.</p>"},"repeatable":false,"marks":[{"label":"","image":"<blaze>"}]},{"id":"outcomes-978","code":"978","description":{"en":"","ru":"<p><i><b>Вы устранили проблему, что расколола ваш народ, но в долине воцарился хаос. Хоть враждующие группы и согласились сложить оружие, кровь уже была пролита и мира добиться было сложно.</b></i></p><p>Завершите текущее испытание.</p><p>Установите значение <unrest> на 3. Уберите <population>. На стене первобытной пещеры изобразите историю о хрупком перемирии, включив в неё отметку осторожности [i] и отметку посредника [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":"<mediator>"}]},{"id":"outcomes-981","code":"981","description":{"en":"","ru":"<p><i><b>Из ртутного моря вы вытащили окаменевший кусок коралла, который явно не ожидали здесь выловить. Странно, но в этом регионе он вам нигде больше не встречался.</b></i></p><p>Получите 1 мёртвый коралл. Добавьте <lore><lore>.</p>"},"repeatable":false},{"id":"outcomes-982","code":"982","description":{"en":"","ru":"<p><i><b>Ослепительный свет заставил зажмуриться. Открыв глаза, вы обнаружили, что вы больше не в пещере. Ошеломление от происходящего переплеталось с необъяснимым чувством радости и воодушевления.</b></i></p><p>Получите <minor_injury>. Получите <major_boost> к каждой характеристике. Выберите другой участок местности в долине и переместите туда своего персонажа, если возможно. Затем разыграйте первое, что можете:<br><b>А. Почувствуйте, как к вам возвращается юношеская энергия. </b>Если ваш персонаж пожилой, сотрите или зачеркните отметку в клетке «Пожилой» на карте персонажа. Теперь ваш персонаж снова считается молодым.<br><b>Б. Приобретите мудрость, несвойственную возрасту. </b>Если ваш персонаж молодой, выберите одну из следующих черт и добавьте её на карту персонажа: «любознательный», «удачливый» или «мудрый».</p><p>Затем на стене первобытной пещеры изобразите историю о странной находке, включив в неё отметку тайны.</p><p>Наконец, верните в коробку карту «Загадка» (ПН07).</p>"},"repeatable":false,"marks":[{"label":"","image":"<mystery>"}]},{"id":"outcomes-983","code":"983","description":{"en":"","ru":"<p><i><b>В долине появилось огромное чудище, и теперь его присутствие невозможно было отрицать. Существо было настолько громадным, что ломало деревья, словно это были ветки, и оставляло отпечатки следов таких размеров, что их легко было спутать с высохшими озёрами. Однако воочию вы его не лицезрели. Что же это за существо, способное одной только поступью изменить мир вокруг?</b></i></p><p>Добавьте карту «Вторжение» (ИА04) к грядущим испытаниям. Затем совместно выберите один из следующих путей развития общины: <br><b>А. Поразмышляйте о природе загадочного существа.</b> Если есть чудище, чья отметка не запечатлена на стене первобытной пещеры, выберите одно из таких чудищ случайным образом. На стене первобытной пещеры изобразите историю о незримом гиганте, включив в неё отметку выбранного чудища и отметку тайны.<br><b>Б. Вспомните, что вы уже видели признаки существа, подходящего под это описание. </b>Добавьте <lore><lore><lore>.</p>"},"repeatable":false,"marks":[{"label":"","image":"<mystery>"}]},{"id":"outcomes-984","code":"984","description":{"en":"","ru":"<p><i><b>Вы вгляделись в засушливую землю высокой равнины. Здесь земля вздымалась к небу и обрушивалась в глубокие расселины вечного мрака.</b></i></p><p>Добавьте <lore><lore><lore>. Добавьте к целям карту «Отправьтесь за зубчатый край» (ЦЯ04).</p>"},"repeatable":false},{"id":"outcomes-986","code":"986","description":{"en":"","ru":"<p><i><b>В логове вы обнаружили массивную ледяную стену, испещрённую странными метками чудища. Вы пристально всмотрелись в них — и изображения ожили, разыгрывая перед вами множество сцен, борющихся за господство в вашем сознании. На миг одна из них прояснилась, открыв вам вариант будущего в водовороте возможностей.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Пигмент на стене перекрутился в гигантское облако, и вы отшатнулись. </b>Если <comet> или <sun>— текущее знамение, найдите карту цели ЦВ10. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описать её другим игрокам. Затем на стене первобытной пещеры изобразите историю о ненаступающем рассвете, включив в неё отметку ЧД3 [i], отметку подземного мира [ii] и отметку <comet>, заключённую в отметку пророчества [iii].<br><b>Б. Когда видение исчезло, в ушах у вас звенело от криков ярости, а ноздри наполнились запахом крови.</b> Если <star> или <cloud> — текущее знамение, найдите карту цели ЦЯ06. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описать её другим игрокам. Затем на стене первобытной пещеры изобразите историю о предсказанном расколе, включив в неё отметку ЧД3 [i] и отметку <star>, заключённую в отметку пророчества [iii].<br><b>В. Вас отбросило назад от извивающихся узоров — одно логово перетекало в другое.</b> Если <moon> — текущее знамение, найдите карту цели ЦЯ15. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описать её другим игрокам. Затем на стене первобытной пещеры изобразите историю о вековом хранилище, включив в неё отметку ЧД3 [i] и отметку <moon>, заключённую в отметку пророчества [iii].</p><p>В конце текущего испытания завершите текущую эру. См. с. 196, чтобы <era2>начать эру 2</era2>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<bh2>"},{"label":"ii","image":"<underworld>"},{"label":"iii","image":"<prophecy>"}]},{"id":"outcomes-988","code":"988","description":{"en":"","ru":"<p><i><b>Чрезмерное собирательство нарушило циклы роста, и с каждым поколением вам становилось всё труднее добывать пропитание. Теперь ваш народ встал перед трудным выбором... </b></i></p><p>Совместно выберите один из следующих путей развития общины:<br><b>А. Продолжите добывать припасы, как и прежде. </b>Уберите <population><population><population>. Для каждого из следующих регионов уберите следующие карты из соответствующих колод добычи припасов, если возможно:<br>1. Если в долине есть хотя бы 1 участок Дивной долины, уберите карту ДЛ09 из колоды добычи припасов в лесу.<br>2. Если в долине есть хотя бы 1 участок Поднебесной равнины, уберите карту ДС07 из колоды добычи припасов в степи.<br>3. Если в долине есть хотя бы 1 участок Ураганных холмов, уберите карту ДД04 из колоды добычи припасов в джунглях.<br>4. Если в долине есть хотя бы 1 участок Сплетения (и этот регион доступен), уберите карту ДП03 из колоды добычи припасов на полянах.<br><br><b>Б. Ограничьте сбор растений. </b>Запишите «Собирать 3 или более овоща в день» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет. Добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю об осторожном сборе, включив в неё отметку осторожности [i], отметку травничества [ii] и отметку табу [iii].<br><b>В. Переосмыслите старые запреты, касающиеся питания. </b>Если у вас есть табу на потребление мяса (рыбы или дичи), удалите это табу и добавьте <unrest><unrest><unrest>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":"<herbalism>"},{"label":"iii","image":"<taboo>"}]},{"id":"outcomes-990","code":"990","description":{"en":"","ru":"<p><i><b>Ваше внимание привлекло чёрное облако вдалеке. Оно клубилось на горизонте, за пределами досягаемости.</b></i></p><p>Если на стене первобытной пещеры есть отметка Вулканических пустошей, добавьте <lore>. В противном случае добавьте карту «Найдите луч света» (ЦЕ02) к целям.</p>"},"repeatable":false},{"id":"outcomes-992","code":"992","description":{"en":"","ru":"<p><i><b>Когда день обернулся ночью, казалось, что мир не проснулся. Всколыхнувшееся напряжение вырвалось наружу, и под исчезнувшим солнцем воцарился хаос.</b></i></p><p>Уберите <1d6> <population>. Каждый персонаж на участке местности с поселением получает <major_injury><major_injury>, если только он не <i>хитрый </i>или <i>мудрый</i>.</p>"},"repeatable":false},{"id":"outcomes-993","code":"993","description":{"en":"","ru":"<p><i><b>Вы сильно заболели. Утром вы услышали, как кашляют и другие...</b></i></p><p>Если на стене первобытной пещеры есть отметка чумы, добавьте <lore>. В противном случае добавьте карту «Мор» (ИЯ03) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"","image":"<plague>"}]},{"id":"outcomes-994","code":"994","description":{"en":"","ru":"<p><i><b>Воспевая деяния предков, ваши люди заслужили своё место среди легенд.</b></i></p><p>Уберите <unrest><unrest>. На стене первобытной пещеры изобразите историю о ткачах песен, включив в неё отметку песнопевца. Получите карту знаний «Легенды» (ЗБ15), если у вас её нет.</p>"},"repeatable":false,"marks":[{"label":"","image":"<songweaver>"}]},{"id":"outcomes-995","code":"995","description":{"en":"","ru":"<p><i><b>Чудище насытилось плодами долины, мало что оставив после себя...</b></i></p><p>До конца текущего испытания (или до конца события в бесконечном режиме) каждый персонаж может получать не более 1 овоща в день при выполнении действия добычи припасов.</p><p>Уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-996","code":"996","description":{"en":"","ru":"<p><i><b>Вы застряли в каменной лавине!</b></i></p><p>Проведите проверку <dexterity>, чтобы вырваться из груды камней. +2, если вы <i>хитрый</i>, и +2, если у вас есть <strike>.<br><b>≥11:</b>  Вы легко выскользнули из каменных зубьев. Без эффекта.<br><b>8-10:</b>  Вам пришлось вывихнуть себе руку, чтобы освободиться. Получите <minor_injury>.<br><b>1-7:</b>  Освобождение было утомительным и болезненным. Получите <minor_injury> и потеряйте <energy><energy>.</p>"},"repeatable":false},{"id":"outcomes-997","code":"997","description":{"en":"","ru":"<p><i><b>Когда вы проснулись на рассвете, пепельное чудище стояло перед вашим поселением, словно подзывая вас. Вы ощутили, как древняя связь с этим существом стала теперь важнее всего на свете.</b></i></p><p>Добавьте <lore><lore>. Поместите ЧД4 на соседний с поселением участок местности. Поместите <minor_boost> на карту цели «Изучите пепельное чудище».</p>"},"repeatable":false},{"id":"outcomes-998","code":"998","description":{"en":"","ru":"<p><i><b>Коралловый защитник приближался к поселению. Он будто вёл за собой коралл, споры которого густо висели в воздухе, угрожая поглотить это место. Вы собрались с духом, готовясь встретиться с тем, кто оказался во власти Скитальца. Защитник поднял руку — и щупальца живого коралла вырвались из земли, разрезая вашу плоть!</b></i></p><p>Проведите состязание: <dexterity> своего персонажа против <awareness> кораллового защитника. +2 к вашему результату, если у вас есть предмет <i>лунной крови</i>. +2 к результату кораллового защитника за каждый соседний с ним участок местности с активными коралловыми зарослями. <br><b>Успех.</b> Вы стремительно бросились к коралловому защитнику, избегая его хлестающих щупалец. Ваш удар оказался точным — коралловый защитник пошатнулся и исчез в густом тумане из спор. Добавьте <major_boost> к <might>.<br><b>Провал. </b>Коралловый защитник двигался быстро, избегая ваших ударов и нанося урон в ответ. Получите <major_injury>.</p>"},"repeatable":false},{"id":"outcomes-999","code":"999","description":{"en":"","ru":"<p><i><b>Свирепость чудища стихла, и оно тяжёлой поступью начало путь к своему логову, довольное тем, что показало свою мощь. </b></i></p><p>За каждый участок местности с поселением и жетоном следов уберите <population><population> и добавьте <unrest><unrest>. Каждый персонаж на участке местности с жетоном следов получает <minor_injury>.</p><p>Затем уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false}]'),F={version:B,lastUpdated:U,outcomes:L},o={en:{title:"OUTCOMES",searchButton:"Seek Outcome",enterNumber:"Enter code",noOutcome:"Outcome Unfound",repeatableTrue:"Repeatable",repeatableFalse:"Unique",thisOutcome:"This outcome is"},ru:{title:"Исходы",searchButton:"Проверить исход",enterNumber:"Введите код",noOutcome:"Исход не найден",repeatableTrue:"Повторяемый",repeatableFalse:"Уникальный",thisOutcome:"Этот исход"}};function D(){const{language:p}=z(),t=O(),m=S(),[y,g]=b.useState(!1),[a,c]=b.useState(null),[l,d]=b.useState(""),[s,j]=b.useState([]),{textSize:v=1,iconSize:h=1,lineHeight:_=1.45}=q(),w=async()=>F;b.useEffect(()=>{w().then(r=>{j(r.outcomes)})},[]),b.useEffect(()=>{const n=new URLSearchParams(t.search).get("code");if(n){const i=n.trim();d(i),s.length&&f(i)}},[t.search,s.length]);const f=b.useCallback(async(r=l,{replaceHistory:n=!0}={})=>{const i=r?.trim();if(i){g(!0);try{const u=s.find(A=>A.code===i);c(u||{isNotFound:!0,title:{en:o.en.noOutcome,ru:o.ru.noOutcome},description:{en:`<p class="not-found-message">No outcome found with code: <strong>${i}</strong></p>`,ru:`<p class="not-found-message">Исход с кодом <strong>${i}</strong> не найден</p>`}}),d(i);const x=t.search||"",k=`?code=${encodeURIComponent(i)}`;x!==k&&m({pathname:"/OUTCOMES",search:k},{replace:n})}catch(u){console.error("Error fetching outcomes:",u),c({isNotFound:!0,title:{en:"Error",ru:"Ошибка"},description:{en:'<p class="error-message">An error occurred while searching for the outcome.</p>',ru:'<p class="error-message">Произошла ошибка при поиске исхода.</p>'}})}finally{g(!1)}}},[l,s,t.search,m]);return e.jsxs(e.Fragment,{children:[e.jsx(M,{}),e.jsx(E,{title:o[p].title,children:e.jsxs("div",{className:"recipes-content",children:[e.jsxs("div",{className:"input-row",children:[e.jsx("input",{type:"number",className:"number-input",value:l,onChange:r=>d(r.target.value.trim()),placeholder:o[p].enterNumber}),e.jsx("button",{className:"craft-button",onClick:()=>f(l),disabled:y,children:o[p].searchButton})]}),a&&e.jsxs(N,{children:[a.title?e.jsx("h3",{children:o[p].noOutcome}):e.jsxs("div",{style:{fontSize:`${v}em`,lineHeight:_,"--et-icon-size":`${h}em`},children:[" ",e.jsxs("h3",{className:"h3-title",children:["Исход ",a.code]})," "]}),e.jsx(C,{text:a.description[p]}),e.jsx(R,{marks:a.marks})]})]})})]})}export{D as default};
